insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (388, 51, 31, 60, 'سورة الذاريات ٣١ – ٦٠', 'الذاريات: ففرّوا إلى الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 388) = $j$[{"lbl": "الآيات ٣١ – ٣٧", "q": "۞قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ ﴿٣١﴾ قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ ﴿٣٢﴾ لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَةٗ مِّن طِينٖ ﴿٣٣﴾ مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِينَ ﴿٣٤﴾ فَأَخۡرَجۡنَا مَن كَانَ فِيهَا مِنَ ٱلۡمُؤۡمِنِينَ ﴿٣٥﴾ فَمَا وَجَدۡنَا فِيهَا غَيۡرَ بَيۡتٖ مِّنَ ٱلۡمُسۡلِمِينَ ﴿٣٦﴾ وَتَرَكۡنَا فِيهَآ ءَايَةٗ لِّلَّذِينَ يَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٣٧﴾", "w": [["قال فما خطبكم أيها المرسلون", "ما شأنكم أيها المرسلون؟"], ["إلى قوم مجرمين", "إلى قوم كافرين فاعلين لأكبر الجرائم، وهي إتيان الفاحشة."], ["حجارة من طين", "طين مطبوخ بالنار."], ["مسوّمة", "معلّمة، على كل حجر اسم من يُرمى به."], ["للمسرفين", "المبالغين في الكفر والعصيان كإتيان الذكران."], ["غير بيت من المسلمين", "وهو بيت لوط ﵇ ومن معه من المؤمنين."], ["وتركنا فيها آية", "بعد إهلاكهم تركنا فيها علامة على إهلاكهم."], ["للذين يخافون العذاب الأليم", "عذاب الآخرة، فلا يفعلون فعلهم الشنيع."]], "m": "ما زال السياق في قصة إبراهيم مع ضيفه من الملائكة؛ إنه لاحظ بعد أن عرف أنهم سادات الملائكة أن مهمتهم لم تكن مقصورة على بشارته، بل هي أعظم، فلذا سألهم: فما شأنكم أيها المرسلون؟ فأجابوه: إنا أرسلنا ربنا عز وجل إلى قوم مجرمين على أنفسهم بالكفر وفعل الفاحشة، لنرسل عليهم حجارة من طين مطبوخ بالنار، معلّمة عند ربك للمسرفين، قد كُتب على كل حجر اسم من يُرمى به. فأخرجنا من تلك القرية، وهي سدوم، من كان فيها من المؤمنين، فما وجدنا فيها غير بيت من المسلمين، وهو بيت لوط ﵇، وما به سوى لوط وابنتيه، ومن الجائز أن يكون معهم بعض المؤمنين. وتركنا فيها علامة على إهلاكهم، وهي ماء أسود منتن كالبحيرة يُعرف الآن بالبحر الميت، للذين يخافون عذاب الآخرة من المؤمنين حتى لا يفعلوا فعل قوم لوط من الكفر وإتيان الفاحشة.", "h": ["جواز تشكّل الملائكة بصورة رجال من البشر.", "التنديد بالإجرام وفاعليه.", "جواز الإهلاك بالعذاب الخاص الذي لم يُعرف له نظير.", "تقرير حقيقة علمية، وهي أن كل مؤمن صادق الإيمان مسلم، وليس كل مسلم مؤمناً حتى يحسن إسلامه بانبنائه على أركان الإيمان الستة."], "k": "«وتركنا فيها آية للذين يخافون العذاب الأليم»… الآيات حولي كثيرة؛ فهل أقرؤها بقلب يخاف؟"}, {"lbl": "الآيات ٣٨ – ٤٦", "q": "وَفِي مُوسَىٰٓ إِذۡ أَرۡسَلۡنَٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَٰنٖ مُّبِينٖ ﴿٣٨﴾ فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَٰحِرٌ أَوۡ مَجۡنُونٞ ﴿٣٩﴾ فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّ وَهُوَ مُلِيمٞ ﴿٤٠﴾ وَفِي عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ ٱلرِّيحَ ٱلۡعَقِيمَ ﴿٤١﴾ مَا تَذَرُ مِن شَيۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِيمِ ﴿٤٢﴾ وَفِي ثَمُودَ إِذۡ قِيلَ لَهُمۡ تَمَتَّعُواْ حَتَّىٰ حِينٖ ﴿٤٣﴾ فَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ وَهُمۡ يَنظُرُونَ ﴿٤٤﴾ فَمَا ٱسۡتَطَٰعُواْ مِن قِيَامٖ وَمَا كَانُواْ مُنتَصِرِينَ ﴿٤٥﴾ وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿٤٦﴾", "w": [["وفي موسى إذ أرسلناه إلى فرعون", "فكذّبه وكفر، فأغرقناه ومن معه، آية كآية سدوم."], ["بسلطان مبين", "بحجة ظاهرة قوية، وهي اليد والعصا."], ["فتولّى بركنه", "أعرض عن الإيمان مع رجال قومه."], ["وقال ساحر أو مجنون", "قال فرعون في شأن موسى: ساحر أو مجنون."], ["فنبذناهم في اليم", "طرحناهم في البحر فغرقوا أجمعين."], ["وهو مليم", "آتٍ بما يُلام عليه، إذ عرّض جيشاً كاملاً للهلاك، زيادة على ادعائه الربوبية وتكذيبه لموسى وهارون."], ["وفي عاد", "وفي إهلاك عاد آية على قدرتنا وتدبيرنا."], ["الريح العقيم", "التي لا خير فيها، لأنها لا تحمل المطر ولا تلقّح الشجر، وهي الدبور."], ["ما تذر من شيء أتت عليه", "من نفس أو مال."], ["إلا جعلته كالرميم", "كالبالي المتفتّت."], ["وفي ثمود", "وفي إهلاك ثمود آية دالة على قدرة الله وكرهه للكفر والإجرام."], ["إذ قيل لهم تمتّعوا حتى حين", "بعد عقر الناقة: تمتّعوا إلى انقضاء آجالكم بعد ثلاثة أيام."], ["فأخذتهم الصاعقة", "بعد ثلاثة أيام من عقر الناقة."], ["فما استطاعوا من قيام", "ما قدروا على النهوض عند نزول العذاب بهم."], ["وقوم نوح من قبل", "وفي إهلاك قوم نوح بالطوفان آية، وأعظم آية."]], "m": "لما ذكر تعالى إهلاك قوم لوط وجعل في ذلك آية، ذكر هنا أربع آيات أخرى يهتدي بها أهل الإيمان الذين يخافون يوم الحساب: وفي موسى بن عمران إذ أرسلناه إلى فرعون ملك القبط بمصر بحجة قوية ظاهرة، فلم يستجب لدعوة الحق، فأعرض بجنده الذي يركن إليه، وقال في موسى: ساحر أو مجنون، فانتقمنا منه بعد الإصرار على الكفر والظلم، فطرحناهم في البحر فهلكوا بالغرق، وهو آتٍ بما يُلام عليه؛ وفي هذا الصنيع آية من أظهر الآيات. وفي عاد حيث أرسلنا إليهم أخاهم هوداً فدعاهم إلى عبادة الله وحده فكذّبوه، إذ أرسلنا عليهم الريح العقيم التي لا تحمل مطراً ولا تلقّح شجراً، ما تذر من شيء مرّت به من أنفس أو أموال إلا جعلته كالرميم البالي المتفتت، وفي هذا الإهلاك آية من أعظم الآيات الدالة على قدرة الله الموجبة لعبادته، والمستلزمة لقدرته على البعث والجزاء. وفي ثمود إذ أرسلنا إليهم أخاهم صالحاً فكذّبوه وطالبوه بآية، فأعطاهم الله الناقة فعقروها استخفافاً وتكذيباً، إذ قيل لهم: تمتعوا إلى انقضاء الأجل الذي حُدّد لهلاككم، فبدل أن يؤمنوا عتوا عن أمر ربهم متكبرين، فأخذتهم صاعقة العذاب وهم ينظرون بأعينهم الموت يتخطّفهم، فما استطاعوا من قيام من مجالسهم وهم جاثمون على الرُّكب، وما كانوا منتصرين. وفي قوم نوح من قبل، إذ كذّبوه وأصرّوا على الشرك فأهلكناهم بالطوفان وأنجينا المؤمنين، آية من أعظم الآيات الدالة على وجود الله وربوبيته وألوهيته، والمستلزمة لقدرته على البعث والجزاء الذي يصرّ الملاحدة على إنكاره ليواصلوا فسقهم وفجورهم بلا تأنيب ضمير ولا خوف.", "h": ["تقرير كل من التوحيد والنبوة والبعث، لما في الآيات من دلائل على ذلك.", "قوة الله تعالى فوق كل قوة، إذ كل قوة في الأرض هو الذي خلقها ووهبها.", "اتهام المبطلين لأهل الحق دفعاً للحق وعدم قبول له يكاد يكون سنة بشرية في كل زمان.", "من عوامل الهلاك العتوّ عن أمر الله، أي عدم الإذعان لقبوله، والفسق عن طاعته وطاعة رسله."], "k": "«فعتوا عن أمر ربهم»… قد يبدأ الهلاك بتكبّر صغير على أمر واحد؛ فهل في نفسي أمر أتكبّر عنه؟"}, {"lbl": "الآيات ٤٧ – ٥١", "q": "وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدٖ وَإِنَّا لَمُوسِعُونَ ﴿٤٧﴾ وَٱلۡأَرۡضَ فَرَشۡنَٰهَا فَنِعۡمَ ٱلۡمَٰهِدُونَ ﴿٤٨﴾ وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٤٩﴾ فَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ ﴿٥٠﴾ وَلَا تَجۡعَلُواْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ ﴿٥١﴾", "w": [["والسماء بنيناها بأيد", "وبنينا السماء بقوة ظاهرة في رفعها وإحكام بنائها."], ["وإنا لموسعون", "لقادرون على البناء والتوسعة."], ["والأرض فرشناها", "مهّدناها فجعلناها كالمهاد، أي الفراش."], ["فنعم الماهدون", "نحن، أثنى الله تعالى على نفسه بفعله الخيري."], ["ومن كل شيء خلقنا زوجين", "وخلقنا من كل شيء صنفين: ذكراً وأنثى، خيراً وشراً."], ["لعلكم تذكّرون", "تذكرون أن خالق الأزواج كلها إله فرد فلا يُعبد معه غيره."], ["ففرّوا إلى الله", "إلى التوبة بطاعته وعدم معصيته."], ["إني لكم منه نذير مبين", "إني، وأنا رسول الله إليكم، نذير منه بيّن النذارة، أخوّفكم عذابه."], ["ولا تجعلوا مع الله إلهاً آخر", "لا تعبدوا مع الله معبوداً آخر، إذ لا معبود بحق إلا هو."]], "m": "ما زال السياق في عرض مظاهر القدرة الإلهية الموجبة له تعالى الربوبية لكل شيء والألوهية على كل عباده: والسماء بنيناها بأيد، فهذا أكبر مظهر من مظاهر القدرة الإلهية: بناء السماء وإحكام ذلك البناء وارتفاعه وما تعلّق به من كواكب ونجوم وشمس وقمر، تمّ هذا الخلق بقوة الله التي لا توازيها قوة، وإنا لقادرون على توسعته أكثر مما هو عليه لسعة قدرتنا. ومظهر ثانٍ: والأرض فرشها بساطاً ومهّدها مهاداً، فنعم الماهد الله تعالى لها، إذ غيره لا يقدر على ذلك. وثالث: ومن كل شيء خلقنا زوجين، وهذا لفظ عام يعمّ سائر المخلوقات، وأنها كلها أزواج وليس فيها فرد قط، والذوات كالصفات: فالسماء يقابلها الأرض، والحر يقابله البرد، والذكر يقابله الأنثى، والبر يقابله البحر، والخير يقابله الشر، والمعروف يقابله المنكر؛ خلقنا ذلك رجاء أن تذكروا فتعلموا أن خالق هذه الأزواج هو الله الفرد الصمد الواحد الأحد، فتعبدوه وحده. ففرّوا إلى الله: بعد أن تبيّن لكم أيها الناس أنه لا إله غير الله فاهربوا إليه بالإيمان به وطاعته، بفعل فرائضه وترك نواهيه، إني لكم منه نذير من عقاب شديد، ونذارتي بيّنة لا شك فيها، وأنصح لكم ألا تجعلوا مع الله معبوداً غيره، إذ الشرك يحبط أعمالكم ويحرّم عليكم الجنة.", "h": ["تقرير التوحيد والبعث بمظاهر القدرة الإلهية التي لا يعجزها شيء، ومظاهر العلم والحكمة المتجلية في كل شيء.", "ظاهرة الزوجية في الكون، في الذرة، انبهر لها العقل الإنساني، وهي مما سبق إليه القرآن الكريم وقرّره في غير موضع منه: «سبحان الذي خلق الأزواج كلها مما تنبت الأرض ومن أنفسهم ومما لا يعلمون»، فدلّ هذا قطعاً أن القرآن وحي الله، وأن من أوحي به إليه، وهو محمد بن عبد الله، لن يكون إلا رسول الله ﷺ.", "التحذير من الشرك، فإنه ذنب عظيم لا يُغفر إلا بالتوبة الصحيحة النصوح."], "k": "«ففرّوا إلى الله»… كل ما أخافه أهرب منه، إلا الله فأهرب إليه؛ فإلى أين أفرّ أنا حين أضيق؟"}, {"lbl": "الآيات ٥٢ – ٦٠", "q": "كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُواْ سَاحِرٌ أَوۡ مَجۡنُونٌ ﴿٥٢﴾ أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ ﴿٥٣﴾ فَتَوَلَّ عَنۡهُمۡ فَمَآ أَنتَ بِمَلُومٖ ﴿٥٤﴾ وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ ﴿٥٥﴾ وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ ﴿٥٦﴾ مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقٖ وَمَآ أُرِيدُ أَن يُطۡعِمُونِ ﴿٥٧﴾ إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ ﴿٥٨﴾ فَإِنَّ لِلَّذِينَ ظَلَمُواْ ذَنُوبٗا مِّثۡلَ ذَنُوبِ أَصۡحَٰبِهِمۡ فَلَا يَسۡتَعۡجِلُونِ ﴿٥٩﴾ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن يَوۡمِهِمُ ٱلَّذِي يُوعَدُونَ ﴿٦٠﴾", "w": [["كذلك ما أتى الذين من قبلهم من رسول", "الأمر كذلك: ما أتى الذين من قبل قومك يا محمد من رسول إلا قالوا ساحر أو مجنون."], ["أتواصوا به بل هم قوم طاغون", "هل أوصت كل أمة التي بعدها بهذا القول؟ لا، بل جمعهم عليه الطغيان."], ["فتولّ عنهم فما أنت بملوم", "أعرض عنهم يا رسولنا، فما أنت بملوم لأنك بلّغتهم."], ["وذكّر فإن الذكرى تنفع المؤمنين", "عِظ بالقرآن يا رسولنا، فإن التذكير ينفع من علم الله أنه يؤمن."], ["وما خلقت الجن والإنس إلا ليعبدون", "خلقتهم لأجل أن يعبدوني، فمن عبدني أكرمته، ومن ترك عبادتي أهنته."], ["ما أريد منهم من رزق", "لا لي ولا لأنفسهم ولا لغيرهم."], ["وما أريد أن يطعمون", "لا أريد منهم ما يريد أرباب العبيد من عبيدهم، فالله هو الذي يرزقهم."], ["ذو القوة المتين", "صاحب القوة الشديد الذي لا يعجزه شيء."], ["ذَنوباً مثل ذَنوب أصحابهم", "نصيباً من العذاب مثل نصيب أصحابهم الذين مضوا."], ["فلا يستعجلون", "فلا يطالبوني بالعذاب، فإن له موعداً لا يُخلفونه."], ["من يومهم الذي يوعدون", "يوم القيامة."]], "m": "بعد عرض تلك الأدلة المقررة للتوحيد والبعث والمستلزمة للرسالة المحمدية، والمشركون ما زالوا مصرّين على الكفر، قال تعالى مسلّياً رسوله: الأمر كذلك؛ ما أتى الذين من قبل قومك من رسول إلا قالوا فيه: ساحر أو مجنون، كما قال قومك لك اليوم. أتواصوا به، كل أمة توصي التي بعدها؟ لم يتواصوا به، وإنما جمعهم على هذا القول الطغيان، فإن الطاغي من شأنه أن ينكر ويكذّب ويتّهم بأبعد التهم. فأعرض عنهم يا رسولنا ولا تلتفت إلى أقوالهم، فما أنت بملوم، لأنك بلّغت رسالتك وأدّيت أمانتك، ولا يمنعك هذا الإعراض أن تعظ بالقرآن، فإن الذكرى تنفع من علم الله أنهم يؤمنون، كما تنفع المؤمنين حالياً بزيادة إيمانهم وصبرهم على الطاعة. وما خلقت الجن والإنس للهو ولا للعب، وإنما خلقتهما ليعبدوني بالإذعان لي والتسليم لأمري ونهيي، وليس شأني معهم كشأن السادة مالكي العبيد الذين يستعبدونهم بالقيام بحاجاتهم: هذا يجمع المال وهذا يُعدّ الطعام، بل خلقتهم ليوحّدوني في عبادتي، إذ عبادتهم لي مع عبادة غيري لا أقبلها منهم. إن الله هو الرزاق ذو القوة المتين، قرّر به غناه عن خلقه، وأنه ليس في حاجة إلى أحد، لملكه المطلق وقدرته التي لا يعجزها شيء. فإن للذين ظلموا من المشركين نصيباً من العذاب مثل نصيب أصحابهم من عاد وثمود وغيرهم، وعبّر بالذَّنوب، وهي الدلو الملأى بالماء، عن العذاب لأنه يُصبّ عليهم كما يُصبّ الماء من الدلو، ولأن الدلاء تأتي واحداً بعد واحد، فكذلك الهلاك يتم لأمة بعد أمة، فلا حاجة بهم إلى استعجاله فإنه آتٍ في وقته المحدد لا محالة. فويل للذين كفروا بالله ولقائه ورسوله من يومهم الذي يوعدون، وهو يوم القيامة، والويل وادٍ في جهنم يسيل بصديد أهل النار.", "h": ["بيان سنة بشرية، وهي التكذيب والاتهام بالباطل وقلب الحقائق لكل من جاءهم يدعوهم إلى خلاف مألوفهم وما اعتادوه من باطل وشر، فيدفعون بالقول، فإذا أعياهم ذلك دفعوا بالفعل، وهي الحرب والقتال.", "بيان أن طغيان النفس يتولّد عنه كل شر.", "مشروعية التذكير، وأنه ينتفع به من أراد الله إيمانه ممن لم يؤمن، ويزداد به إيمان المؤمنين.", "بيان علّة خلق الإنس والجن، وهي عبادة الله وحده.", "بيان غنى الله تعالى عن خلقه، وعدم احتياجه إليهم بحال من الأحوال.", "توعّد الرب تبارك وتعالى الكافرين، وأن نصيبهم من العذاب نازل بهم لا محالة."], "k": "«وما خلقت الجن والإنس إلا ليعبدون»… هذا سبب وجودي كله؛ فكم من يومي يذهب فيما خُلقت له؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 388;
insert into public.tdb_cards(topic, i, body) select 388, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣١ – ٣٧", "q": "۞قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ ﴿٣١﴾ قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ ﴿٣٢﴾ لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَةٗ مِّن طِينٖ ﴿٣٣﴾ مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِينَ ﴿٣٤﴾ فَأَخۡرَجۡنَا مَن كَانَ فِيهَا مِنَ ٱلۡمُؤۡمِنِينَ ﴿٣٥﴾ فَمَا وَجَدۡنَا فِيهَا غَيۡرَ بَيۡتٖ مِّنَ ٱلۡمُسۡلِمِينَ ﴿٣٦﴾ وَتَرَكۡنَا فِيهَآ ءَايَةٗ لِّلَّذِينَ يَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٣٧﴾", "w": [["قال فما خطبكم أيها المرسلون", "ما شأنكم أيها المرسلون؟"], ["إلى قوم مجرمين", "إلى قوم كافرين فاعلين لأكبر الجرائم، وهي إتيان الفاحشة."], ["حجارة من طين", "طين مطبوخ بالنار."], ["مسوّمة", "معلّمة، على كل حجر اسم من يُرمى به."], ["للمسرفين", "المبالغين في الكفر والعصيان كإتيان الذكران."], ["غير بيت من المسلمين", "وهو بيت لوط ﵇ ومن معه من المؤمنين."], ["وتركنا فيها آية", "بعد إهلاكهم تركنا فيها علامة على إهلاكهم."], ["للذين يخافون العذاب الأليم", "عذاب الآخرة، فلا يفعلون فعلهم الشنيع."]], "m": "ما زال السياق في قصة إبراهيم مع ضيفه من الملائكة؛ إنه لاحظ بعد أن عرف أنهم سادات الملائكة أن مهمتهم لم تكن مقصورة على بشارته، بل هي أعظم، فلذا سألهم: فما شأنكم أيها المرسلون؟ فأجابوه: إنا أرسلنا ربنا عز وجل إلى قوم مجرمين على أنفسهم بالكفر وفعل الفاحشة، لنرسل عليهم حجارة من طين مطبوخ بالنار، معلّمة عند ربك للمسرفين، قد كُتب على كل حجر اسم من يُرمى به. فأخرجنا من تلك القرية، وهي سدوم، من كان فيها من المؤمنين، فما وجدنا فيها غير بيت من المسلمين، وهو بيت لوط ﵇، وما به سوى لوط وابنتيه، ومن الجائز أن يكون معهم بعض المؤمنين. وتركنا فيها علامة على إهلاكهم، وهي ماء أسود منتن كالبحيرة يُعرف الآن بالبحر الميت، للذين يخافون عذاب الآخرة من المؤمنين حتى لا يفعلوا فعل قوم لوط من الكفر وإتيان الفاحشة.", "h": ["جواز تشكّل الملائكة بصورة رجال من البشر.", "التنديد بالإجرام وفاعليه.", "جواز الإهلاك بالعذاب الخاص الذي لم يُعرف له نظير.", "تقرير حقيقة علمية، وهي أن كل مؤمن صادق الإيمان مسلم، وليس كل مسلم مؤمناً حتى يحسن إسلامه بانبنائه على أركان الإيمان الستة."], "k": "«وتركنا فيها آية للذين يخافون العذاب الأليم»… الآيات حولي كثيرة؛ فهل أقرؤها بقلب يخاف؟"}, {"lbl": "الآيات ٣٨ – ٤٦", "q": "وَفِي مُوسَىٰٓ إِذۡ أَرۡسَلۡنَٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَٰنٖ مُّبِينٖ ﴿٣٨﴾ فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَٰحِرٌ أَوۡ مَجۡنُونٞ ﴿٣٩﴾ فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّ وَهُوَ مُلِيمٞ ﴿٤٠﴾ وَفِي عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ ٱلرِّيحَ ٱلۡعَقِيمَ ﴿٤١﴾ مَا تَذَرُ مِن شَيۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِيمِ ﴿٤٢﴾ وَفِي ثَمُودَ إِذۡ قِيلَ لَهُمۡ تَمَتَّعُواْ حَتَّىٰ حِينٖ ﴿٤٣﴾ فَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ وَهُمۡ يَنظُرُونَ ﴿٤٤﴾ فَمَا ٱسۡتَطَٰعُواْ مِن قِيَامٖ وَمَا كَانُواْ مُنتَصِرِينَ ﴿٤٥﴾ وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿٤٦﴾", "w": [["وفي موسى إذ أرسلناه إلى فرعون", "فكذّبه وكفر، فأغرقناه ومن معه، آية كآية سدوم."], ["بسلطان مبين", "بحجة ظاهرة قوية، وهي اليد والعصا."], ["فتولّى بركنه", "أعرض عن الإيمان مع رجال قومه."], ["وقال ساحر أو مجنون", "قال فرعون في شأن موسى: ساحر أو مجنون."], ["فنبذناهم في اليم", "طرحناهم في البحر فغرقوا أجمعين."], ["وهو مليم", "آتٍ بما يُلام عليه، إذ عرّض جيشاً كاملاً للهلاك، زيادة على ادعائه الربوبية وتكذيبه لموسى وهارون."], ["وفي عاد", "وفي إهلاك عاد آية على قدرتنا وتدبيرنا."], ["الريح العقيم", "التي لا خير فيها، لأنها لا تحمل المطر ولا تلقّح الشجر، وهي الدبور."], ["ما تذر من شيء أتت عليه", "من نفس أو مال."], ["إلا جعلته كالرميم", "كالبالي المتفتّت."], ["وفي ثمود", "وفي إهلاك ثمود آية دالة على قدرة الله وكرهه للكفر والإجرام."], ["إذ قيل لهم تمتّعوا حتى حين", "بعد عقر الناقة: تمتّعوا إلى انقضاء آجالكم بعد ثلاثة أيام."], ["فأخذتهم الصاعقة", "بعد ثلاثة أيام من عقر الناقة."], ["فما استطاعوا من قيام", "ما قدروا على النهوض عند نزول العذاب بهم."], ["وقوم نوح من قبل", "وفي إهلاك قوم نوح بالطوفان آية، وأعظم آية."]], "m": "لما ذكر تعالى إهلاك قوم لوط وجعل في ذلك آية، ذكر هنا أربع آيات أخرى يهتدي بها أهل الإيمان الذين يخافون يوم الحساب: وفي موسى بن عمران إذ أرسلناه إلى فرعون ملك القبط بمصر بحجة قوية ظاهرة، فلم يستجب لدعوة الحق، فأعرض بجنده الذي يركن إليه، وقال في موسى: ساحر أو مجنون، فانتقمنا منه بعد الإصرار على الكفر والظلم، فطرحناهم في البحر فهلكوا بالغرق، وهو آتٍ بما يُلام عليه؛ وفي هذا الصنيع آية من أظهر الآيات. وفي عاد حيث أرسلنا إليهم أخاهم هوداً فدعاهم إلى عبادة الله وحده فكذّبوه، إذ أرسلنا عليهم الريح العقيم التي لا تحمل مطراً ولا تلقّح شجراً، ما تذر من شيء مرّت به من أنفس أو أموال إلا جعلته كالرميم البالي المتفتت، وفي هذا الإهلاك آية من أعظم الآيات الدالة على قدرة الله الموجبة لعبادته، والمستلزمة لقدرته على البعث والجزاء. وفي ثمود إذ أرسلنا إليهم أخاهم صالحاً فكذّبوه وطالبوه بآية، فأعطاهم الله الناقة فعقروها استخفافاً وتكذيباً، إذ قيل لهم: تمتعوا إلى انقضاء الأجل الذي حُدّد لهلاككم، فبدل أن يؤمنوا عتوا عن أمر ربهم متكبرين، فأخذتهم صاعقة العذاب وهم ينظرون بأعينهم الموت يتخطّفهم، فما استطاعوا من قيام من مجالسهم وهم جاثمون على الرُّكب، وما كانوا منتصرين. وفي قوم نوح من قبل، إذ كذّبوه وأصرّوا على الشرك فأهلكناهم بالطوفان وأنجينا المؤمنين، آية من أعظم الآيات الدالة على وجود الله وربوبيته وألوهيته، والمستلزمة لقدرته على البعث والجزاء الذي يصرّ الملاحدة على إنكاره ليواصلوا فسقهم وفجورهم بلا تأنيب ضمير ولا خوف.", "h": ["تقرير كل من التوحيد والنبوة والبعث، لما في الآيات من دلائل على ذلك.", "قوة الله تعالى فوق كل قوة، إذ كل قوة في الأرض هو الذي خلقها ووهبها.", "اتهام المبطلين لأهل الحق دفعاً للحق وعدم قبول له يكاد يكون سنة بشرية في كل زمان.", "من عوامل الهلاك العتوّ عن أمر الله، أي عدم الإذعان لقبوله، والفسق عن طاعته وطاعة رسله."], "k": "«فعتوا عن أمر ربهم»… قد يبدأ الهلاك بتكبّر صغير على أمر واحد؛ فهل في نفسي أمر أتكبّر عنه؟"}, {"lbl": "الآيات ٤٧ – ٥١", "q": "وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدٖ وَإِنَّا لَمُوسِعُونَ ﴿٤٧﴾ وَٱلۡأَرۡضَ فَرَشۡنَٰهَا فَنِعۡمَ ٱلۡمَٰهِدُونَ ﴿٤٨﴾ وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٤٩﴾ فَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ ﴿٥٠﴾ وَلَا تَجۡعَلُواْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ ﴿٥١﴾", "w": [["والسماء بنيناها بأيد", "وبنينا السماء بقوة ظاهرة في رفعها وإحكام بنائها."], ["وإنا لموسعون", "لقادرون على البناء والتوسعة."], ["والأرض فرشناها", "مهّدناها فجعلناها كالمهاد، أي الفراش."], ["فنعم الماهدون", "نحن، أثنى الله تعالى على نفسه بفعله الخيري."], ["ومن كل شيء خلقنا زوجين", "وخلقنا من كل شيء صنفين: ذكراً وأنثى، خيراً وشراً."], ["لعلكم تذكّرون", "تذكرون أن خالق الأزواج كلها إله فرد فلا يُعبد معه غيره."], ["ففرّوا إلى الله", "إلى التوبة بطاعته وعدم معصيته."], ["إني لكم منه نذير مبين", "إني، وأنا رسول الله إليكم، نذير منه بيّن النذارة، أخوّفكم عذابه."], ["ولا تجعلوا مع الله إلهاً آخر", "لا تعبدوا مع الله معبوداً آخر، إذ لا معبود بحق إلا هو."]], "m": "ما زال السياق في عرض مظاهر القدرة الإلهية الموجبة له تعالى الربوبية لكل شيء والألوهية على كل عباده: والسماء بنيناها بأيد، فهذا أكبر مظهر من مظاهر القدرة الإلهية: بناء السماء وإحكام ذلك البناء وارتفاعه وما تعلّق به من كواكب ونجوم وشمس وقمر، تمّ هذا الخلق بقوة الله التي لا توازيها قوة، وإنا لقادرون على توسعته أكثر مما هو عليه لسعة قدرتنا. ومظهر ثانٍ: والأرض فرشها بساطاً ومهّدها مهاداً، فنعم الماهد الله تعالى لها، إذ غيره لا يقدر على ذلك. وثالث: ومن كل شيء خلقنا زوجين، وهذا لفظ عام يعمّ سائر المخلوقات، وأنها كلها أزواج وليس فيها فرد قط، والذوات كالصفات: فالسماء يقابلها الأرض، والحر يقابله البرد، والذكر يقابله الأنثى، والبر يقابله البحر، والخير يقابله الشر، والمعروف يقابله المنكر؛ خلقنا ذلك رجاء أن تذكروا فتعلموا أن خالق هذه الأزواج هو الله الفرد الصمد الواحد الأحد، فتعبدوه وحده. ففرّوا إلى الله: بعد أن تبيّن لكم أيها الناس أنه لا إله غير الله فاهربوا إليه بالإيمان به وطاعته، بفعل فرائضه وترك نواهيه، إني لكم منه نذير من عقاب شديد، ونذارتي بيّنة لا شك فيها، وأنصح لكم ألا تجعلوا مع الله معبوداً غيره، إذ الشرك يحبط أعمالكم ويحرّم عليكم الجنة.", "h": ["تقرير التوحيد والبعث بمظاهر القدرة الإلهية التي لا يعجزها شيء، ومظاهر العلم والحكمة المتجلية في كل شيء.", "ظاهرة الزوجية في الكون، في الذرة، انبهر لها العقل الإنساني، وهي مما سبق إليه القرآن الكريم وقرّره في غير موضع منه: «سبحان الذي خلق الأزواج كلها مما تنبت الأرض ومن أنفسهم ومما لا يعلمون»، فدلّ هذا قطعاً أن القرآن وحي الله، وأن من أوحي به إليه، وهو محمد بن عبد الله، لن يكون إلا رسول الله ﷺ.", "التحذير من الشرك، فإنه ذنب عظيم لا يُغفر إلا بالتوبة الصحيحة النصوح."], "k": "«ففرّوا إلى الله»… كل ما أخافه أهرب منه، إلا الله فأهرب إليه؛ فإلى أين أفرّ أنا حين أضيق؟"}, {"lbl": "الآيات ٥٢ – ٦٠", "q": "كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُواْ سَاحِرٌ أَوۡ مَجۡنُونٌ ﴿٥٢﴾ أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ ﴿٥٣﴾ فَتَوَلَّ عَنۡهُمۡ فَمَآ أَنتَ بِمَلُومٖ ﴿٥٤﴾ وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ ﴿٥٥﴾ وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ ﴿٥٦﴾ مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقٖ وَمَآ أُرِيدُ أَن يُطۡعِمُونِ ﴿٥٧﴾ إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ ﴿٥٨﴾ فَإِنَّ لِلَّذِينَ ظَلَمُواْ ذَنُوبٗا مِّثۡلَ ذَنُوبِ أَصۡحَٰبِهِمۡ فَلَا يَسۡتَعۡجِلُونِ ﴿٥٩﴾ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن يَوۡمِهِمُ ٱلَّذِي يُوعَدُونَ ﴿٦٠﴾", "w": [["كذلك ما أتى الذين من قبلهم من رسول", "الأمر كذلك: ما أتى الذين من قبل قومك يا محمد من رسول إلا قالوا ساحر أو مجنون."], ["أتواصوا به بل هم قوم طاغون", "هل أوصت كل أمة التي بعدها بهذا القول؟ لا، بل جمعهم عليه الطغيان."], ["فتولّ عنهم فما أنت بملوم", "أعرض عنهم يا رسولنا، فما أنت بملوم لأنك بلّغتهم."], ["وذكّر فإن الذكرى تنفع المؤمنين", "عِظ بالقرآن يا رسولنا، فإن التذكير ينفع من علم الله أنه يؤمن."], ["وما خلقت الجن والإنس إلا ليعبدون", "خلقتهم لأجل أن يعبدوني، فمن عبدني أكرمته، ومن ترك عبادتي أهنته."], ["ما أريد منهم من رزق", "لا لي ولا لأنفسهم ولا لغيرهم."], ["وما أريد أن يطعمون", "لا أريد منهم ما يريد أرباب العبيد من عبيدهم، فالله هو الذي يرزقهم."], ["ذو القوة المتين", "صاحب القوة الشديد الذي لا يعجزه شيء."], ["ذَنوباً مثل ذَنوب أصحابهم", "نصيباً من العذاب مثل نصيب أصحابهم الذين مضوا."], ["فلا يستعجلون", "فلا يطالبوني بالعذاب، فإن له موعداً لا يُخلفونه."], ["من يومهم الذي يوعدون", "يوم القيامة."]], "m": "بعد عرض تلك الأدلة المقررة للتوحيد والبعث والمستلزمة للرسالة المحمدية، والمشركون ما زالوا مصرّين على الكفر، قال تعالى مسلّياً رسوله: الأمر كذلك؛ ما أتى الذين من قبل قومك من رسول إلا قالوا فيه: ساحر أو مجنون، كما قال قومك لك اليوم. أتواصوا به، كل أمة توصي التي بعدها؟ لم يتواصوا به، وإنما جمعهم على هذا القول الطغيان، فإن الطاغي من شأنه أن ينكر ويكذّب ويتّهم بأبعد التهم. فأعرض عنهم يا رسولنا ولا تلتفت إلى أقوالهم، فما أنت بملوم، لأنك بلّغت رسالتك وأدّيت أمانتك، ولا يمنعك هذا الإعراض أن تعظ بالقرآن، فإن الذكرى تنفع من علم الله أنهم يؤمنون، كما تنفع المؤمنين حالياً بزيادة إيمانهم وصبرهم على الطاعة. وما خلقت الجن والإنس للهو ولا للعب، وإنما خلقتهما ليعبدوني بالإذعان لي والتسليم لأمري ونهيي، وليس شأني معهم كشأن السادة مالكي العبيد الذين يستعبدونهم بالقيام بحاجاتهم: هذا يجمع المال وهذا يُعدّ الطعام، بل خلقتهم ليوحّدوني في عبادتي، إذ عبادتهم لي مع عبادة غيري لا أقبلها منهم. إن الله هو الرزاق ذو القوة المتين، قرّر به غناه عن خلقه، وأنه ليس في حاجة إلى أحد، لملكه المطلق وقدرته التي لا يعجزها شيء. فإن للذين ظلموا من المشركين نصيباً من العذاب مثل نصيب أصحابهم من عاد وثمود وغيرهم، وعبّر بالذَّنوب، وهي الدلو الملأى بالماء، عن العذاب لأنه يُصبّ عليهم كما يُصبّ الماء من الدلو، ولأن الدلاء تأتي واحداً بعد واحد، فكذلك الهلاك يتم لأمة بعد أمة، فلا حاجة بهم إلى استعجاله فإنه آتٍ في وقته المحدد لا محالة. فويل للذين كفروا بالله ولقائه ورسوله من يومهم الذي يوعدون، وهو يوم القيامة، والويل وادٍ في جهنم يسيل بصديد أهل النار.", "h": ["بيان سنة بشرية، وهي التكذيب والاتهام بالباطل وقلب الحقائق لكل من جاءهم يدعوهم إلى خلاف مألوفهم وما اعتادوه من باطل وشر، فيدفعون بالقول، فإذا أعياهم ذلك دفعوا بالفعل، وهي الحرب والقتال.", "بيان أن طغيان النفس يتولّد عنه كل شر.", "مشروعية التذكير، وأنه ينتفع به من أراد الله إيمانه ممن لم يؤمن، ويزداد به إيمان المؤمنين.", "بيان علّة خلق الإنس والجن، وهي عبادة الله وحده.", "بيان غنى الله تعالى عن خلقه، وعدم احتياجه إليهم بحال من الأحوال.", "توعّد الرب تبارك وتعالى الكافرين، وأن نصيبهم من العذاب نازل بهم لا محالة."], "k": "«وما خلقت الجن والإنس إلا ليعبدون»… هذا سبب وجودي كله؛ فكم من يومي يذهب فيما خُلقت له؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (389, 52, 1, 28, 'سورة الطور ١ – ٢٨', 'الطور: إنا كنا قبل في أهلنا مشفقين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 389) = $j$[{"lbl": "الآيات ١ – ١٦", "q": "وَٱلطُّورِ ﴿١﴾ وَكِتَٰبٖ مَّسۡطُورٖ ﴿٢﴾ فِي رَقّٖ مَّنشُورٖ ﴿٣﴾ وَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ ﴿٤﴾ وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ ﴿٥﴾ وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ ﴿٦﴾ إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٞ ﴿٧﴾ مَّا لَهُۥ مِن دَافِعٖ ﴿٨﴾ يَوۡمَ تَمُورُ ٱلسَّمَآءُ مَوۡرٗا ﴿٩﴾ وَتَسِيرُ ٱلۡجِبَالُ سَيۡرٗا ﴿١٠﴾ فَوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١١﴾ ٱلَّذِينَ هُمۡ فِي خَوۡضٖ يَلۡعَبُونَ ﴿١٢﴾ يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا ﴿١٣﴾ هَٰذِهِ ٱلنَّارُ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ ﴿١٤﴾ أَفَسِحۡرٌ هَٰذَآ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ ﴿١٥﴾ ٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ﴿١٦﴾", "w": [["والطور", "الجبل الذي كلّم الله عز وجل عليه موسى ﵇."], ["وكتاب مسطور", "وكتاب مكتوب."], ["في رقّ منشور", "في جلد رقيق أو ورق منشور."], ["والبيت المعمور", "بيت في السماء معمور بالملائكة، يدخله كل يوم سبعون ألف ملك لا يعودون إليه أبداً."], ["والسقف المرفوع", "السماء التي هي كالسقف المرفوع للأرض."], ["والبحر المسجور", "المملوء المجموع ماؤه بعضه في بعض."], ["يوم تمور السماء موراً", "تتحرك وتدور."], ["في خوض يلعبون", "في باطل يلعبون، أي يتشاغلون بكفرهم."], ["يوم يُدَعّون إلى نار جهنم دعّاً", "يُدفعون إليها بعنف دفعاً."], ["أفسحر هذا", "أسحر هذا العذاب الذي ترون، كما كنتم تقولون في القرآن؟"], ["أم أنتم لا تبصرون", "أم عدمتم الأبصار فأنتم لا تبصرون؟"], ["اصلوها", "اصطلوا بحرّها."], ["فاصبروا أو لا تصبروا", "صبركم وعدمه عليكم سواء."]], "m": "هذه خمسة أشياء عظام أقسم الله تعالى بها، وبالتتبّع لما يقسم الله به يُرى أنه إنما يقسم بالشيء لكونه مظهراً من مظاهر القدرة الإلهية كالسماء، أو لكونه معظّماً نحو «لعمرك» إذ هو إقسام بحياة النبي ﷺ، أو لكونه ذا فائدة للإنسان كالتين والزيتون. والطور جبل كلّم الله عليه موسى، وهو مكان مقدّس. وكتاب مسطور في ورق أو جلد رقيق، وهو التوراة أو القرآن، والإقسام به لما فيه من حرمة وقدسية عند الله. والبيت المعمور بيت في السماء تغشاه الملائكة كل يوم وتعمره بالعبادة، وهو بحيال الكعبة بحيث لو وقع لوقع فوقها. والسقف المرفوع وهو السماء، وهي كالسقف للأرض، ومثلها البحر المسجور أي المملوء بكميات المياه الهائلة، فإنه مظهر من مظاهر القدرة والعلم والحكمة الإلهية. وجواب هذا القسم الضخم: إن عذاب ربك يا رسولنا لواقع، ما له من دافع يدفعه أبداً، وإن له وقتاً محدداً يقع فيه، وعلامات تدل عليه: يوم تتحرك السماء بشدة وتدور، وتسير الجبال سيراً فتكون كالهباء المنبث، فويل يومئذ للمكذبين، والويل وادٍ في جهنم مملوء بقيح وصديد أهل النار، والمكذبون هم الكافرون بالله وبما جاءت به رسله من أركان الإيمان وقواعد الإسلام، الذين هم في باطلهم وكفرهم يتشاغلون به عن الإيمان الحق والعمل الصالح المزكّي للنفس. يوم يُدفعون بشدة وعنف إلى جهنم، ويقال لهم توبيخاً: هذه النار التي كنتم بها تكذبون، أفسحر هذا العذاب الذي أنتم فيه الآن أم أنتم لا تبصرون؟ اصلوها فاصبروا على عذابها أو لا تصبروا، صبركم وعدمه عليكم سواء، إنما تُجزون ما كنتم تعملون في الدنيا من الشرك والمعاصي.", "h": ["تقرير البعث والجزاء.", "لله تعالى أن يقسم بما يشاء من خلقه، وليس للعبد أن يقسم بغير الله تعالى.", "عرض سريع لأهوال القيامة وأحوال المكذبين فيها.", "تقرير قاعدة: الجزاء من جنس العمل."], "k": "«الذين هم في خوض يلعبون»… قد أنشغل بالكلام الفارغ ساعات؛ فهل هذا لعب يُحسب عليّ؟"}, {"lbl": "الآيات ١٧ – ٢٠", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَنَعِيمٖ ﴿١٧﴾ فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ ﴿١٨﴾ كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٩﴾ مُتَّكِـِٔينَ عَلَىٰ سُرُرٖ مَّصۡفُوفَةٖۖ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ ﴿٢٠﴾", "w": [["إن المتقين", "الذين اتقوا ربهم فعبدوه وحده بما شرع لهم، فأدّوا الفرائض واجتنبوا النواهي."], ["فاكهين", "متلذّذين بأكل الفواكه الكثيرة التي آتاهم ربهم."], ["ووقاهم ربهم عذاب الجحيم", "وحفظهم من عذاب النار."], ["على سرر مصفوفة", "بعضها إلى جنب بعض."], ["وزوّجناهم بحور عين", "قرنّاهم بنساء عظام الأعين حسانها."]], "m": "لما ذكر تعالى حال أهل النار ذكر حال أهل الجنة، وهذا أسلوب الترغيب والترهيب الذي امتاز به القرآن الكريم: إن الذين اتقوا في الدنيا الشرك والمعاصي في بساتين ونعيم مقيم يحوي كل ما لذّ وطاب مما تشتهيه الأنفس وتلذّه الأعين، متلذّذين بأكل الفواكه الكثيرة الموصوفة بأنها لا مقطوعة ولا ممنوعة، ووقاهم ربهم عذاب النار. ويقال لهم: كلوا واشربوا هنيئاً بسبب ما كنتم تعملونه من أعمال البر والإصلاح بعد الفرائض واجتناب الشرك والمعاصي، وهم في نعيمهم متكئون على سرر قد صُفّ بعضها إلى جنب بعض، وزوّجناهم بحور عين؛ والحور جمع حوراء، وهي التي يغلب بياض عينها على سوادها، والعين جمع عيناء، وهي الواسعة العينين.", "h": ["فضل التقوى وكرامة أهلها.", "بيان منّة الله وفضله على أهل الإيمان والتقوى، وهم أولياء الله تعالى.", "مشروعية الدعاء بكلمة «هنيئاً» لمن أكل أو شرب، اقتداءً بأهل الجنة.", "الإيمان والأعمال الصالحة سبب في دخول الجنة وليست ثمناً لها، لأن الجنة أغلى من عمل الإنسان، وإنما العمل الصالح يزكّي النفس فيؤهّل صاحبها لدخول الجنة، فالباء في قوله «بما كنتم تعملون» سببية وليست للعوض كما في قولك: بعتك الدار بألف مثلاً."], "k": "«كلوا واشربوا هنيئاً بما كنتم تعملون»… عملي سبب لا ثمن؛ فلأُكثر من السبب وأرجُ الفضل."}, {"lbl": "الآيات ٢١ – ٢٨", "q": "وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءٖۚ كُلُّ ٱمۡرِيِٕۭ بِمَا كَسَبَ رَهِينٞ ﴿٢١﴾ وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ وَلَحۡمٖ مِّمَّا يَشۡتَهُونَ ﴿٢٢﴾ يَتَنَٰزَعُونَ فِيهَا كَأۡسٗا لَّا لَغۡوٞ فِيهَا وَلَا تَأۡثِيمٞ ﴿٢٣﴾ ۞وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَانٞ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤٞ مَّكۡنُونٞ ﴿٢٤﴾ وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ﴿٢٥﴾ قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ ﴿٢٦﴾ فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ ﴿٢٧﴾ إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ ﴿٢٨﴾", "w": [["والذين آمنوا", "حق الإيمان المستلزم للإسلام والإحسان."], ["واتّبعتهم ذريتهم بإيمان", "كامل مستوفٍ لشرائطه، ومنها الإسلام."], ["ألحقنا بهم ذريتهم", "وإن لم يعملوا عملهم بل قصّروا في ذلك."], ["وما ألتناهم من عملهم من شيء", "وما نقصناهم من أجور أعمالهم شيئاً."], ["كل امرئ بما كسب رهين", "كل إنسان مرهون، أي محبوس بكسبه الباطل."], ["يتنازعون فيها كأساً", "يتعاطون بينهم في الجنة كأساً من خمر."], ["لا لغو فيها ولا تأثيم", "لا يقع لهم بسبب شربها لغو، وهو كل كلام لا خير فيه، ولا إثم."], ["ويطوف عليهم غلمان", "ويدور بهم خدم لهم."], ["كأنهم لؤلؤ مكنون", "مصون."], ["وأقبل بعضهم على بعض يتساءلون", "يسأل بعضهم بعضاً عما كانوا عليه في الدنيا وما وصلوا إليه في الآخرة."], ["قالوا إنا كنا قبل في أهلنا مشفقين", "قالوا مشيرين إلى علّة سعادتهم: كنا في الدنيا بين أهلنا وأولادنا خائفين من عذاب الله."], ["فمنّ الله علينا", "بالمغفرة."], ["ووقانا عذاب السموم", "وحفظنا من عذاب النار التي يدخل حرّها في مسامّ الجسم."], ["إنا كنا من قبل ندعوه", "في الدنيا نعبده موحّدين له."], ["إنه هو البرّ الرحيم", "المحسن الصادق في وعده، الرحيم العظيم الرحمة."]], "m": "ما زال السياق في ذكر إفضال الله تعالى وإنعامه على أوليائه في الجنة: والذين آمنوا حق الإيمان، الذي هو عقد بالجنان وقول باللسان وعمل بالأركان، واتّبعتهم ذريتهم بإيمان كامل صحيح، إلا أنهم لم يبلغوا من الأعمال الصالحة ما بلغه آباؤهم، ألحقنا بهم ذريتهم لتقرّ بذلك أعينهم وتكمل سعادتهم باجتماعهم مع ذريتهم، وما نقصنا الآباء من عملهم الصالح من شيء، بل وفّيناهموه كاملاً، ورفعنا إليهم أبناءهم بفضل منا ورحمة. كل امرئ بما كسب رهين: كل نفس عنده يوم القيامة مرتهنة بعملها تُجزى به، إلا أنه تعالى تفضّل على أولئك الآباء فرفع إلى درجاتهم أبناءهم تفضّلاً وإحساناً. وأمددناهم بفاكهة ولحم مما يشتهون، هذا طعامهم، أما الشراب فإنهم يتعاطون في الجنة كأساً من خمر لا تسبّب هذياناً من الكلام، وليس في شربها إثم، ويطوف عليهم خدم لهم كأنهم في جمالهم وحسن منظرهم لؤلؤ مكنون في أصدافه. وأقبل بعضهم على بعض يتساءلون عما كان لهم في الدنيا وما انتهوا إليه من هذا النعيم المقيم، وقالوا مشيرين إلى سببه: إنا كنا في الدنيا في أهلنا خائفين من عذاب ربنا، فمنّ الله علينا بدخول الجنة ووقانا عذاب النار الذي ينفذ إلى المسام، إنا كنا من قبل ندعوه ونتضرع إليه أن يجيرنا من النار ويدخلنا الجنة، إنه هو البرّ بأوليائه، الرحيم بعباده المؤمنين.", "h": ["وصف كامل لأهل الجنة، وهو تقرير في نفس الوقت للبعث والجزاء بذكر ما يكون فيه.", "فضل الإيمان وكرامة أهله عند الله، بإلحاق الأبناء قليلي العمل الصالح بآبائهم الكثيري العمل.", "تقرير قاعدة أن المرء يوم القيامة يكون رهين كسبه، لا يفكّه إلا الله عز وجل، فمن استطاع أن يفكّ رقبته فليفعل، وذلك بالإيمان والإسلام والإحسان.", "فضيلة الإشفاق في الدنيا من عذاب الآخرة.", "فضل الدعاء والتضرّع إلى الله تعالى."], "k": "«إنا كنا قبل في أهلنا مشفقين»… الخوف في بيتي اليوم أمان غداً؛ فهل أخاف وأنا بين أهلي؟"}]$j$::jsonb then 0 else 1 end;
