insert into public.tdb_cards(topic, i, body) select 389, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٦", "q": "وَٱلطُّورِ ﴿١﴾ وَكِتَٰبٖ مَّسۡطُورٖ ﴿٢﴾ فِي رَقّٖ مَّنشُورٖ ﴿٣﴾ وَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ ﴿٤﴾ وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ ﴿٥﴾ وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ ﴿٦﴾ إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٞ ﴿٧﴾ مَّا لَهُۥ مِن دَافِعٖ ﴿٨﴾ يَوۡمَ تَمُورُ ٱلسَّمَآءُ مَوۡرٗا ﴿٩﴾ وَتَسِيرُ ٱلۡجِبَالُ سَيۡرٗا ﴿١٠﴾ فَوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١١﴾ ٱلَّذِينَ هُمۡ فِي خَوۡضٖ يَلۡعَبُونَ ﴿١٢﴾ يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا ﴿١٣﴾ هَٰذِهِ ٱلنَّارُ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ ﴿١٤﴾ أَفَسِحۡرٌ هَٰذَآ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ ﴿١٥﴾ ٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ﴿١٦﴾", "w": [["والطور", "الجبل الذي كلّم الله عز وجل عليه موسى ﵇."], ["وكتاب مسطور", "وكتاب مكتوب."], ["في رقّ منشور", "في جلد رقيق أو ورق منشور."], ["والبيت المعمور", "بيت في السماء معمور بالملائكة، يدخله كل يوم سبعون ألف ملك لا يعودون إليه أبداً."], ["والسقف المرفوع", "السماء التي هي كالسقف المرفوع للأرض."], ["والبحر المسجور", "المملوء المجموع ماؤه بعضه في بعض."], ["يوم تمور السماء موراً", "تتحرك وتدور."], ["في خوض يلعبون", "في باطل يلعبون، أي يتشاغلون بكفرهم."], ["يوم يُدَعّون إلى نار جهنم دعّاً", "يُدفعون إليها بعنف دفعاً."], ["أفسحر هذا", "أسحر هذا العذاب الذي ترون، كما كنتم تقولون في القرآن؟"], ["أم أنتم لا تبصرون", "أم عدمتم الأبصار فأنتم لا تبصرون؟"], ["اصلوها", "اصطلوا بحرّها."], ["فاصبروا أو لا تصبروا", "صبركم وعدمه عليكم سواء."]], "m": "هذه خمسة أشياء عظام أقسم الله تعالى بها، وبالتتبّع لما يقسم الله به يُرى أنه إنما يقسم بالشيء لكونه مظهراً من مظاهر القدرة الإلهية كالسماء، أو لكونه معظّماً نحو «لعمرك» إذ هو إقسام بحياة النبي ﷺ، أو لكونه ذا فائدة للإنسان كالتين والزيتون. والطور جبل كلّم الله عليه موسى، وهو مكان مقدّس. وكتاب مسطور في ورق أو جلد رقيق، وهو التوراة أو القرآن، والإقسام به لما فيه من حرمة وقدسية عند الله. والبيت المعمور بيت في السماء تغشاه الملائكة كل يوم وتعمره بالعبادة، وهو بحيال الكعبة بحيث لو وقع لوقع فوقها. والسقف المرفوع وهو السماء، وهي كالسقف للأرض، ومثلها البحر المسجور أي المملوء بكميات المياه الهائلة، فإنه مظهر من مظاهر القدرة والعلم والحكمة الإلهية. وجواب هذا القسم الضخم: إن عذاب ربك يا رسولنا لواقع، ما له من دافع يدفعه أبداً، وإن له وقتاً محدداً يقع فيه، وعلامات تدل عليه: يوم تتحرك السماء بشدة وتدور، وتسير الجبال سيراً فتكون كالهباء المنبث، فويل يومئذ للمكذبين، والويل وادٍ في جهنم مملوء بقيح وصديد أهل النار، والمكذبون هم الكافرون بالله وبما جاءت به رسله من أركان الإيمان وقواعد الإسلام، الذين هم في باطلهم وكفرهم يتشاغلون به عن الإيمان الحق والعمل الصالح المزكّي للنفس. يوم يُدفعون بشدة وعنف إلى جهنم، ويقال لهم توبيخاً: هذه النار التي كنتم بها تكذبون، أفسحر هذا العذاب الذي أنتم فيه الآن أم أنتم لا تبصرون؟ اصلوها فاصبروا على عذابها أو لا تصبروا، صبركم وعدمه عليكم سواء، إنما تُجزون ما كنتم تعملون في الدنيا من الشرك والمعاصي.", "h": ["تقرير البعث والجزاء.", "لله تعالى أن يقسم بما يشاء من خلقه، وليس للعبد أن يقسم بغير الله تعالى.", "عرض سريع لأهوال القيامة وأحوال المكذبين فيها.", "تقرير قاعدة: الجزاء من جنس العمل."], "k": "«الذين هم في خوض يلعبون»… قد أنشغل بالكلام الفارغ ساعات؛ فهل هذا لعب يُحسب عليّ؟"}, {"lbl": "الآيات ١٧ – ٢٠", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَنَعِيمٖ ﴿١٧﴾ فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ ﴿١٨﴾ كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٩﴾ مُتَّكِـِٔينَ عَلَىٰ سُرُرٖ مَّصۡفُوفَةٖۖ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ ﴿٢٠﴾", "w": [["إن المتقين", "الذين اتقوا ربهم فعبدوه وحده بما شرع لهم، فأدّوا الفرائض واجتنبوا النواهي."], ["فاكهين", "متلذّذين بأكل الفواكه الكثيرة التي آتاهم ربهم."], ["ووقاهم ربهم عذاب الجحيم", "وحفظهم من عذاب النار."], ["على سرر مصفوفة", "بعضها إلى جنب بعض."], ["وزوّجناهم بحور عين", "قرنّاهم بنساء عظام الأعين حسانها."]], "m": "لما ذكر تعالى حال أهل النار ذكر حال أهل الجنة، وهذا أسلوب الترغيب والترهيب الذي امتاز به القرآن الكريم: إن الذين اتقوا في الدنيا الشرك والمعاصي في بساتين ونعيم مقيم يحوي كل ما لذّ وطاب مما تشتهيه الأنفس وتلذّه الأعين، متلذّذين بأكل الفواكه الكثيرة الموصوفة بأنها لا مقطوعة ولا ممنوعة، ووقاهم ربهم عذاب النار. ويقال لهم: كلوا واشربوا هنيئاً بسبب ما كنتم تعملونه من أعمال البر والإصلاح بعد الفرائض واجتناب الشرك والمعاصي، وهم في نعيمهم متكئون على سرر قد صُفّ بعضها إلى جنب بعض، وزوّجناهم بحور عين؛ والحور جمع حوراء، وهي التي يغلب بياض عينها على سوادها، والعين جمع عيناء، وهي الواسعة العينين.", "h": ["فضل التقوى وكرامة أهلها.", "بيان منّة الله وفضله على أهل الإيمان والتقوى، وهم أولياء الله تعالى.", "مشروعية الدعاء بكلمة «هنيئاً» لمن أكل أو شرب، اقتداءً بأهل الجنة.", "الإيمان والأعمال الصالحة سبب في دخول الجنة وليست ثمناً لها، لأن الجنة أغلى من عمل الإنسان، وإنما العمل الصالح يزكّي النفس فيؤهّل صاحبها لدخول الجنة، فالباء في قوله «بما كنتم تعملون» سببية وليست للعوض كما في قولك: بعتك الدار بألف مثلاً."], "k": "«كلوا واشربوا هنيئاً بما كنتم تعملون»… عملي سبب لا ثمن؛ فلأُكثر من السبب وأرجُ الفضل."}, {"lbl": "الآيات ٢١ – ٢٨", "q": "وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءٖۚ كُلُّ ٱمۡرِيِٕۭ بِمَا كَسَبَ رَهِينٞ ﴿٢١﴾ وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ وَلَحۡمٖ مِّمَّا يَشۡتَهُونَ ﴿٢٢﴾ يَتَنَٰزَعُونَ فِيهَا كَأۡسٗا لَّا لَغۡوٞ فِيهَا وَلَا تَأۡثِيمٞ ﴿٢٣﴾ ۞وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَانٞ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤٞ مَّكۡنُونٞ ﴿٢٤﴾ وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ﴿٢٥﴾ قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ ﴿٢٦﴾ فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ ﴿٢٧﴾ إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ ﴿٢٨﴾", "w": [["والذين آمنوا", "حق الإيمان المستلزم للإسلام والإحسان."], ["واتّبعتهم ذريتهم بإيمان", "كامل مستوفٍ لشرائطه، ومنها الإسلام."], ["ألحقنا بهم ذريتهم", "وإن لم يعملوا عملهم بل قصّروا في ذلك."], ["وما ألتناهم من عملهم من شيء", "وما نقصناهم من أجور أعمالهم شيئاً."], ["كل امرئ بما كسب رهين", "كل إنسان مرهون، أي محبوس بكسبه الباطل."], ["يتنازعون فيها كأساً", "يتعاطون بينهم في الجنة كأساً من خمر."], ["لا لغو فيها ولا تأثيم", "لا يقع لهم بسبب شربها لغو، وهو كل كلام لا خير فيه، ولا إثم."], ["ويطوف عليهم غلمان", "ويدور بهم خدم لهم."], ["كأنهم لؤلؤ مكنون", "مصون."], ["وأقبل بعضهم على بعض يتساءلون", "يسأل بعضهم بعضاً عما كانوا عليه في الدنيا وما وصلوا إليه في الآخرة."], ["قالوا إنا كنا قبل في أهلنا مشفقين", "قالوا مشيرين إلى علّة سعادتهم: كنا في الدنيا بين أهلنا وأولادنا خائفين من عذاب الله."], ["فمنّ الله علينا", "بالمغفرة."], ["ووقانا عذاب السموم", "وحفظنا من عذاب النار التي يدخل حرّها في مسامّ الجسم."], ["إنا كنا من قبل ندعوه", "في الدنيا نعبده موحّدين له."], ["إنه هو البرّ الرحيم", "المحسن الصادق في وعده، الرحيم العظيم الرحمة."]], "m": "ما زال السياق في ذكر إفضال الله تعالى وإنعامه على أوليائه في الجنة: والذين آمنوا حق الإيمان، الذي هو عقد بالجنان وقول باللسان وعمل بالأركان، واتّبعتهم ذريتهم بإيمان كامل صحيح، إلا أنهم لم يبلغوا من الأعمال الصالحة ما بلغه آباؤهم، ألحقنا بهم ذريتهم لتقرّ بذلك أعينهم وتكمل سعادتهم باجتماعهم مع ذريتهم، وما نقصنا الآباء من عملهم الصالح من شيء، بل وفّيناهموه كاملاً، ورفعنا إليهم أبناءهم بفضل منا ورحمة. كل امرئ بما كسب رهين: كل نفس عنده يوم القيامة مرتهنة بعملها تُجزى به، إلا أنه تعالى تفضّل على أولئك الآباء فرفع إلى درجاتهم أبناءهم تفضّلاً وإحساناً. وأمددناهم بفاكهة ولحم مما يشتهون، هذا طعامهم، أما الشراب فإنهم يتعاطون في الجنة كأساً من خمر لا تسبّب هذياناً من الكلام، وليس في شربها إثم، ويطوف عليهم خدم لهم كأنهم في جمالهم وحسن منظرهم لؤلؤ مكنون في أصدافه. وأقبل بعضهم على بعض يتساءلون عما كان لهم في الدنيا وما انتهوا إليه من هذا النعيم المقيم، وقالوا مشيرين إلى سببه: إنا كنا في الدنيا في أهلنا خائفين من عذاب ربنا، فمنّ الله علينا بدخول الجنة ووقانا عذاب النار الذي ينفذ إلى المسام، إنا كنا من قبل ندعوه ونتضرع إليه أن يجيرنا من النار ويدخلنا الجنة، إنه هو البرّ بأوليائه، الرحيم بعباده المؤمنين.", "h": ["وصف كامل لأهل الجنة، وهو تقرير في نفس الوقت للبعث والجزاء بذكر ما يكون فيه.", "فضل الإيمان وكرامة أهله عند الله، بإلحاق الأبناء قليلي العمل الصالح بآبائهم الكثيري العمل.", "تقرير قاعدة أن المرء يوم القيامة يكون رهين كسبه، لا يفكّه إلا الله عز وجل، فمن استطاع أن يفكّ رقبته فليفعل، وذلك بالإيمان والإسلام والإحسان.", "فضيلة الإشفاق في الدنيا من عذاب الآخرة.", "فضل الدعاء والتضرّع إلى الله تعالى."], "k": "«إنا كنا قبل في أهلنا مشفقين»… الخوف في بيتي اليوم أمان غداً؛ فهل أخاف وأنا بين أهلي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (390, 52, 29, 49, 'سورة الطور ٢٩ – ٤٩', 'الطور: أم خلقوا من غير شيء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 390) = $j$[{"lbl": "الآيات ٢٩ – ٣٤", "q": "فَذَكِّرۡ فَمَآ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنٖ وَلَا مَجۡنُونٍ ﴿٢٩﴾ أَمۡ يَقُولُونَ شَاعِرٞ نَّتَرَبَّصُ بِهِۦ رَيۡبَ ٱلۡمَنُونِ ﴿٣٠﴾ قُلۡ تَرَبَّصُواْ فَإِنِّي مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِينَ ﴿٣١﴾ أَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمٞ طَاغُونَ ﴿٣٢﴾ أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ ﴿٣٣﴾ فَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ ﴿٣٤﴾", "w": [["فذكّر فما أنت بنعمة ربك", "فذكّر بالقرآن وعِظ من أُرسلت إليهم، فلست بنعمة ربك عليك بالعقل وكمال الخلق والوحي إليك…"], ["بكاهن ولا مجنون", "بمتعاطٍ للكهانة تخبر عن الغيب بواسطة رئيّ من الجن، ولا أنت بمجنون."], ["نتربّص به ريب المنون", "ننتظر به حوادث الدهر من موت وغيره."], ["أم تأمرهم أحلامهم بهذا", "أتأمرهم عقولهم بهذا، وهو قولهم إنك كاهن ومجنون؟ لم تأمرهم عقولهم به."], ["أم هم قوم طاغون", "بل هم قوم طاغون متجاوزون لكل حد."], ["أم يقولون تقوّله", "اختلق القرآن وكذبه من تلقاء نفسه."], ["فليأتوا بحديث مثله", "فليأتوا بقرآن مثله يختلقونه بأنفسهم."], ["إن كانوا صادقين", "في أن محمداً ﷺ اختلق القرآن."]], "m": "بعد ذلك العرض لأحوال أهل النار وأهل الجنة قال تعالى لرسوله: فذكّر قومك ومن تصل إليهم كلمتك من سائر الناس بالقرآن وما يحمل من وعد ووعيد وما يدعو إليه من هدى، فما أنت، بما أولاك ربك من رجاحة العقل وكمال الخلق وكرم الفعال وشرف النبوة، بكاهن تقول الغيب بواسطة رئيّ من الجن، ولا مجنون تخلط القول. بل يقولون: هو شاعر كالنابغة وزهير، ننتظر به حوادث الدهر حتى يهلك كما هلك من قبله من الشعراء، ولا ندخل معه في خصومة وجدل قد يغلبنا. قل: تربّصوا، فإني معكم من المتربّصين. أم تأمرهم عقولهم بهذا؟ والاستفهام للنفي والتوبيخ، بل هم قوم طاغون، طغيانهم هو الذي يأمرهم بما يقولون ويفعلون من الباطل والشر والفساد. أم يقولون تقوّله؟ قولهم هذا لم يصدر عن عقولهم بل عن كفرهم وتكذيبهم، والدليل تحدّي الله لهم بالإتيان بحديث مثله وعجزهم عن ذلك، فهم لا يعتقدون أن الرسول تقوّل القرآن من عنده، وإنما لما لم يؤمنوا به لا بد أن يقولوا كلمة يدفعون بها عن أنفسهم، فليأتوا بحديث مثله إن كانوا صادقين.", "h": ["وجوب التذكير والوعظ والإرشاد على أهل العلم بالكتاب والسنة، لأنهم خلفاء الرسول ﷺ.", "ذمّ الكهانة بل حرمتها، لأنها من أعمال الشياطين، والكاهن من يقول بالغيب.", "ذمّ الطغيان، فإنه منبع كل شر ومصدر كل فتنة وضلال.", "حرمة الكذب مطلقاً، وعلى الله ورسوله بخاصة، لما ينشأ عنه من فساد الدين والدنيا."], "k": "«أم تأمرهم أحلامهم بهذا»… أحياناً يأمرني هواي وأظنه عقلي؛ فمن الذي يأمرني حقاً؟"}, {"lbl": "الآيات ٣٥ – ٤٣", "q": "أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ ﴿٣٥﴾ أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ ﴿٣٦﴾ أَمۡ عِندَهُمۡ خَزَآئِنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۜيۡطِرُونَ ﴿٣٧﴾ أَمۡ لَهُمۡ سُلَّمٞ يَسۡتَمِعُونَ فِيهِۖ فَلۡيَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَٰنٖ مُّبِينٍ ﴿٣٨﴾ أَمۡ لَهُ ٱلۡبَنَٰتُ وَلَكُمُ ٱلۡبَنُونَ ﴿٣٩﴾ أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ ﴿٤٠﴾ أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ ﴿٤١﴾ أَمۡ يُرِيدُونَ كَيۡدٗاۖ فَٱلَّذِينَ كَفَرُواْ هُمُ ٱلۡمَكِيدُونَ ﴿٤٢﴾ أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ ﴿٤٣﴾", "w": [["أم خُلقوا من غير شيء", "من غير خالق خلقهم؟ وهذا باطل."], ["أم هم الخالقون", "لأنفسهم؟ وهذا محال، إذ الشيء لا يسبق وجوده."], ["أم خلقوا السماوات والأرض", "لم يخلقوهما، لأن العجز عن خلق أنفسهم دالّ على عجزهم عن خلق غيرهم."], ["بل لا يوقنون", "لا يوقنون أن الله خلقهم وخلق السماوات والأرض كما يقولون، إذ لو كانوا موقنين لما عبدوا غير الله، ولآمنوا برسوله ﷺ."], ["أم عندهم خزائن ربك", "من الرزق والنبوة وغيرهما، فيخصّوا من شاؤوا بذلك؟"], ["أم هم المسيطرون", "المتسلطون الغالبون، فيتصرفون كيف شاؤوا؟"], ["أم لهم سُلّم يستمعون فيه", "ألهم مرقى إلى السماء يرقون فيه فيسمعون كلام الملائكة فيأتون به ويعارضون الرسول؟"], ["فليأت مستمعهم بسلطان مبين", "بحجة بيّنة تدل على صدقه، وليس لهم في ذلك كله شيء."], ["أم له البنات ولكم البنون", "أله تعالى البنات ولكم البنون؟ إن أقوالكم كلها من هذا النوع، لا واقع لها أبداً، إنها افتراءات."], ["أم تسألهم أجراً", "على إبلاغ دعوتك؟"], ["فهم من مغرم مثقلون", "فهم من فداحة الغرم مغتمّون متعبون، فكرهوا ما تقول؟"], ["أم عندهم الغيب فهم يكتبون", "علم الغيب، فهم يكتبون منه لينازعوك ويجادلوك به؟"], ["أم يريدون كيداً", "مكراً وخديعة بك وبالدين."], ["فالذين كفروا هم المكيدون", "فالكافرون هم المكيدون المغلوبون."], ["أم لهم إله غير الله", "ألهم معبود غير الله؟ والجواب: لا."], ["سبحان الله عما يشركون", "تنزّه الله عما يشركون به من أصنام وأوثان."]], "m": "بعد أن أمر تعالى رسوله بالتذكير، أخذ يلقّنه الحجج، فيذكر له باطلهم موبّخاً إياهم به، ثم يدمغه بالحق في أسلوب قرآني عجيب: أم خُلقوا من غير خالق أم هم الخالقون لأنفسهم؟ والجواب: لا هذا ولا ذاك؛ إذ الأول باطل، فما هناك شيء وُجد بغير موجد، والثاني محال، إذ المخلوق لا يوجد قبل أن يُخلق، فكيف يخلقون أنفسهم وهم لم يُخلقوا بعد؟ وروى البخاري عن جبير بن مطعم أنه لما قدم على رسول الله ﷺ بعد بدر في فداء الأسرى سمعه يقرأ في المغرب بسورة الطور، قال: فلما بلغ هذه الآية «أم خُلقوا من غير شيء أم هم الخالقون» كاد قلبي يطير؛ سمعها وهو مشرك فكانت سبباً في إسلامه، فلو فتح القوم قلوبهم للقرآن لأنارها. أم خلقوا السماوات والأرض؟ لا، إذ العاجز عن خلق نفسه هو عن خلق السماوات والأرض أعجز. بل لا يوقنون؛ فقولهم إذا سُئلوا من خلقهم: الله، لم يكن عن يقين، إذ لو كان عن يقين لما عبدوا الأصنام ولا أنكروا البعث ولا كذّبوا بنبوة محمد ﷺ. أم عندهم خزائن ربك من الأرزاق والفضائل فيخصّوا من شاؤوا ويحرموا من شاؤوا؟ ليس لهم ذلك، فلمَ ينكرون على الله ما آتى رسوله؟ أم هم الغالبون المتسلطون فيتصرفون كيف شاؤوا في الملك؟ لا. أم لهم مرقى يرقون فيه إلى السماء فيستمعون إلى الملائكة ما ينازعون به رسولنا؟ فليأت مستمعهم بحجة واضحة، ومن أين له ذلك وقد حُجبت الشياطين عن ذلك؟ أم له البنات ولكم البنون؟ إن نسبتهم البنات لله كافية في ردّ كل ما يقولون. أم تسألهم يا رسولنا أجراً على البلاغ فهم لذلك مغتمّون متعبون؟ أم عندهم علم الغيب فهم منهمكون في كتابته لينازعوك؟ أم يريدون بك وبدينك كيداً ليقتلوك ويبطلوا دينك؟ فالذين كفروا هم المكيدون، ولم يمضِ على نزول هذه الآيات زمن طويل حتى هلك أولئك الكائدون ونصر الله رسوله وأعزّ دينه. أم لهم معبود غير الله؟ والحال أنه لا إله إلا الله، فسبحان الله وتقدّس عما يشركون به من أصنام لا تسمع ولا تبصر فضلاً عن أن تضر أو تنفع.", "h": ["تقرير التوحيد بذكر دلائله.", "تقرير النبوة المحمدية.", "تسفيه أحلام المشركين.", "عدم مشروعية أخذ أجر على إبلاغ الدعوة.", "لا يعلم الغيب إلا الله.", "صدق القرآن في أخباره آية أنه وحي الله وكلامه صدقاً وحقاً؛ إنه لم يمضِ إلا قليل من الوقت، خمسة عشر عاماً، حتى ظهر مصداق قول الله تعالى: «فالذين كفروا هم المكيدون»."], "k": "«أم خُلقوا من غير شيء أم هم الخالقون»… سؤال واحد هزّ قلب جبير فأسلم؛ فماذا يفعل بقلبي أنا؟"}, {"lbl": "الآيات ٤٤ – ٤٩", "q": "وَإِن يَرَوۡاْ كِسۡفٗا مِّنَ ٱلسَّمَآءِ سَاقِطٗا يَقُولُواْ سَحَابٞ مَّرۡكُومٞ ﴿٤٤﴾ فَذَرۡهُمۡ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي فِيهِ يُصۡعَقُونَ ﴿٤٥﴾ يَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ ﴿٤٦﴾ وَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابٗا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٤٧﴾ وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَقُومُ ﴿٤٨﴾ وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ ﴿٤٩﴾", "w": [["وإن يروا كسفاً من السماء ساقطاً", "وإن ير هؤلاء المشركون قطعة من السماء تسقط…"], ["يقولوا سحاب مركوم", "يقولوا في القطعة: سحاب متراكم يمطرنا، ولا يؤمنوا."], ["فذرهم حتى يلاقوا يومهم الذي فيه يُصعقون", "فاتركهم يجاحدون ويعاندون حتى يلاقوا يومهم الذي فيه يُصعقون، وهو يوم موتهم."], ["يوم لا يغني عنهم كيدهم شيئاً", "يوم لا يغني عنهم مكرهم بك شيئاً من العذاب، ولا هم ينصرون."], ["وإن للذين ظلموا عذاباً دون ذلك", "وإن لهؤلاء المشركين الظلمة عذاباً في الدنيا دون عذاب يوم القيامة، وهو القحط سبع سنين."], ["ولكن أكثرهم لا يعلمون", "أن العذاب نازل بهم في الدنيا قبل يوم القيامة."], ["واصبر لحكم ربك", "بإمهالهم، ولا يضق صدرك بكفرهم وعنادهم وعدم تعجيل العذاب لهم."], ["فإنك بأعيننا", "بمرأى منا، نراك ونحفظك من كيدهم ومكرهم."], ["وسبّح بحمد ربك حين تقوم", "واستعن على الصبر بالتسبيح، وهو الصلوات الخمس والذكر بعدها، والضراعة والدعاء صباح مساء."]], "m": "يذكر تعالى من عناد المشركين أنهم لو رأوا العذاب نازلاً من السماء في صورة قطعة كبيرة منها لما أذعنوا ولا آمنوا، بل قالوا: سحاب مركوم الآن يسقي ديارنا فترتوي أراضينا وبهائمنا. فلما كان الأمر هكذا فذرهم يا رسولنا في عنادهم وكفرهم حتى يلاقوا يومهم الذي فيه يُصعقون أي يموتون، يوم لا يغني عنهم كيدهم شيئاً ولا يجدون من ينصرهم، وذلك يوم القيامة. وإن للذين ظلموا أنفسهم بالكفر والشرك والمعاصي عذاباً دون عذاب يوم القيامة، وهو ما أصابهم به من سني القحط والمجاعة، وما أنزله بهم من هزيمة في بدر حيث قُتل صناديدهم وذلّوا، ولكن أكثرهم لا يعلمون ذلك، ولو علموا لما أصرّوا على العناد. واصبر لحكم ربك وقضائه بتأخير العذاب عن هؤلاء المشركين، ولا تخف ولا تحزن، فإنك بمرأى منا نراك ونحفظك، وجُمع لفظ العين على «أعين» مراعاةً لنون العظمة. وسبّح بحمد ربك، أي قل: سبحان الله وبحمده، حين تقوم من نومك ومن مجلسك، ومن الليل فسبّحه بصلاة المغرب والعشاء والتهجد، وإدبار النجوم، أي بعد طلوع الفجر، فسبّح بصلاة الصبح وغيرها.", "h": ["بيان عناد كفار قريش ومكابرتهم في الحق ومجاحدتهم فيه.", "تسلية الرسول ﷺ، وهي للدعاة بعده أيضاً.", "تقرير وخامة عاقبة الظلم في الدنيا قبل الآخرة.", "وجوب الصبر على قضاء الرب وعدم الجزع.", "مشروعية التسبيح عند القيام من النوم بنحو: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير."], "k": "«فإنك بأعيننا»… حين يضيق صدري أتذكّر أنه يراني ويحفظني؛ فهل يكفيني هذا لأصبر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 390;
insert into public.tdb_cards(topic, i, body) select 390, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٩ – ٣٤", "q": "فَذَكِّرۡ فَمَآ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنٖ وَلَا مَجۡنُونٍ ﴿٢٩﴾ أَمۡ يَقُولُونَ شَاعِرٞ نَّتَرَبَّصُ بِهِۦ رَيۡبَ ٱلۡمَنُونِ ﴿٣٠﴾ قُلۡ تَرَبَّصُواْ فَإِنِّي مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِينَ ﴿٣١﴾ أَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمٞ طَاغُونَ ﴿٣٢﴾ أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ ﴿٣٣﴾ فَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ ﴿٣٤﴾", "w": [["فذكّر فما أنت بنعمة ربك", "فذكّر بالقرآن وعِظ من أُرسلت إليهم، فلست بنعمة ربك عليك بالعقل وكمال الخلق والوحي إليك…"], ["بكاهن ولا مجنون", "بمتعاطٍ للكهانة تخبر عن الغيب بواسطة رئيّ من الجن، ولا أنت بمجنون."], ["نتربّص به ريب المنون", "ننتظر به حوادث الدهر من موت وغيره."], ["أم تأمرهم أحلامهم بهذا", "أتأمرهم عقولهم بهذا، وهو قولهم إنك كاهن ومجنون؟ لم تأمرهم عقولهم به."], ["أم هم قوم طاغون", "بل هم قوم طاغون متجاوزون لكل حد."], ["أم يقولون تقوّله", "اختلق القرآن وكذبه من تلقاء نفسه."], ["فليأتوا بحديث مثله", "فليأتوا بقرآن مثله يختلقونه بأنفسهم."], ["إن كانوا صادقين", "في أن محمداً ﷺ اختلق القرآن."]], "m": "بعد ذلك العرض لأحوال أهل النار وأهل الجنة قال تعالى لرسوله: فذكّر قومك ومن تصل إليهم كلمتك من سائر الناس بالقرآن وما يحمل من وعد ووعيد وما يدعو إليه من هدى، فما أنت، بما أولاك ربك من رجاحة العقل وكمال الخلق وكرم الفعال وشرف النبوة، بكاهن تقول الغيب بواسطة رئيّ من الجن، ولا مجنون تخلط القول. بل يقولون: هو شاعر كالنابغة وزهير، ننتظر به حوادث الدهر حتى يهلك كما هلك من قبله من الشعراء، ولا ندخل معه في خصومة وجدل قد يغلبنا. قل: تربّصوا، فإني معكم من المتربّصين. أم تأمرهم عقولهم بهذا؟ والاستفهام للنفي والتوبيخ، بل هم قوم طاغون، طغيانهم هو الذي يأمرهم بما يقولون ويفعلون من الباطل والشر والفساد. أم يقولون تقوّله؟ قولهم هذا لم يصدر عن عقولهم بل عن كفرهم وتكذيبهم، والدليل تحدّي الله لهم بالإتيان بحديث مثله وعجزهم عن ذلك، فهم لا يعتقدون أن الرسول تقوّل القرآن من عنده، وإنما لما لم يؤمنوا به لا بد أن يقولوا كلمة يدفعون بها عن أنفسهم، فليأتوا بحديث مثله إن كانوا صادقين.", "h": ["وجوب التذكير والوعظ والإرشاد على أهل العلم بالكتاب والسنة، لأنهم خلفاء الرسول ﷺ.", "ذمّ الكهانة بل حرمتها، لأنها من أعمال الشياطين، والكاهن من يقول بالغيب.", "ذمّ الطغيان، فإنه منبع كل شر ومصدر كل فتنة وضلال.", "حرمة الكذب مطلقاً، وعلى الله ورسوله بخاصة، لما ينشأ عنه من فساد الدين والدنيا."], "k": "«أم تأمرهم أحلامهم بهذا»… أحياناً يأمرني هواي وأظنه عقلي؛ فمن الذي يأمرني حقاً؟"}, {"lbl": "الآيات ٣٥ – ٤٣", "q": "أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ ﴿٣٥﴾ أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ ﴿٣٦﴾ أَمۡ عِندَهُمۡ خَزَآئِنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۜيۡطِرُونَ ﴿٣٧﴾ أَمۡ لَهُمۡ سُلَّمٞ يَسۡتَمِعُونَ فِيهِۖ فَلۡيَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَٰنٖ مُّبِينٍ ﴿٣٨﴾ أَمۡ لَهُ ٱلۡبَنَٰتُ وَلَكُمُ ٱلۡبَنُونَ ﴿٣٩﴾ أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ ﴿٤٠﴾ أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ ﴿٤١﴾ أَمۡ يُرِيدُونَ كَيۡدٗاۖ فَٱلَّذِينَ كَفَرُواْ هُمُ ٱلۡمَكِيدُونَ ﴿٤٢﴾ أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ ﴿٤٣﴾", "w": [["أم خُلقوا من غير شيء", "من غير خالق خلقهم؟ وهذا باطل."], ["أم هم الخالقون", "لأنفسهم؟ وهذا محال، إذ الشيء لا يسبق وجوده."], ["أم خلقوا السماوات والأرض", "لم يخلقوهما، لأن العجز عن خلق أنفسهم دالّ على عجزهم عن خلق غيرهم."], ["بل لا يوقنون", "لا يوقنون أن الله خلقهم وخلق السماوات والأرض كما يقولون، إذ لو كانوا موقنين لما عبدوا غير الله، ولآمنوا برسوله ﷺ."], ["أم عندهم خزائن ربك", "من الرزق والنبوة وغيرهما، فيخصّوا من شاؤوا بذلك؟"], ["أم هم المسيطرون", "المتسلطون الغالبون، فيتصرفون كيف شاؤوا؟"], ["أم لهم سُلّم يستمعون فيه", "ألهم مرقى إلى السماء يرقون فيه فيسمعون كلام الملائكة فيأتون به ويعارضون الرسول؟"], ["فليأت مستمعهم بسلطان مبين", "بحجة بيّنة تدل على صدقه، وليس لهم في ذلك كله شيء."], ["أم له البنات ولكم البنون", "أله تعالى البنات ولكم البنون؟ إن أقوالكم كلها من هذا النوع، لا واقع لها أبداً، إنها افتراءات."], ["أم تسألهم أجراً", "على إبلاغ دعوتك؟"], ["فهم من مغرم مثقلون", "فهم من فداحة الغرم مغتمّون متعبون، فكرهوا ما تقول؟"], ["أم عندهم الغيب فهم يكتبون", "علم الغيب، فهم يكتبون منه لينازعوك ويجادلوك به؟"], ["أم يريدون كيداً", "مكراً وخديعة بك وبالدين."], ["فالذين كفروا هم المكيدون", "فالكافرون هم المكيدون المغلوبون."], ["أم لهم إله غير الله", "ألهم معبود غير الله؟ والجواب: لا."], ["سبحان الله عما يشركون", "تنزّه الله عما يشركون به من أصنام وأوثان."]], "m": "بعد أن أمر تعالى رسوله بالتذكير، أخذ يلقّنه الحجج، فيذكر له باطلهم موبّخاً إياهم به، ثم يدمغه بالحق في أسلوب قرآني عجيب: أم خُلقوا من غير خالق أم هم الخالقون لأنفسهم؟ والجواب: لا هذا ولا ذاك؛ إذ الأول باطل، فما هناك شيء وُجد بغير موجد، والثاني محال، إذ المخلوق لا يوجد قبل أن يُخلق، فكيف يخلقون أنفسهم وهم لم يُخلقوا بعد؟ وروى البخاري عن جبير بن مطعم أنه لما قدم على رسول الله ﷺ بعد بدر في فداء الأسرى سمعه يقرأ في المغرب بسورة الطور، قال: فلما بلغ هذه الآية «أم خُلقوا من غير شيء أم هم الخالقون» كاد قلبي يطير؛ سمعها وهو مشرك فكانت سبباً في إسلامه، فلو فتح القوم قلوبهم للقرآن لأنارها. أم خلقوا السماوات والأرض؟ لا، إذ العاجز عن خلق نفسه هو عن خلق السماوات والأرض أعجز. بل لا يوقنون؛ فقولهم إذا سُئلوا من خلقهم: الله، لم يكن عن يقين، إذ لو كان عن يقين لما عبدوا الأصنام ولا أنكروا البعث ولا كذّبوا بنبوة محمد ﷺ. أم عندهم خزائن ربك من الأرزاق والفضائل فيخصّوا من شاؤوا ويحرموا من شاؤوا؟ ليس لهم ذلك، فلمَ ينكرون على الله ما آتى رسوله؟ أم هم الغالبون المتسلطون فيتصرفون كيف شاؤوا في الملك؟ لا. أم لهم مرقى يرقون فيه إلى السماء فيستمعون إلى الملائكة ما ينازعون به رسولنا؟ فليأت مستمعهم بحجة واضحة، ومن أين له ذلك وقد حُجبت الشياطين عن ذلك؟ أم له البنات ولكم البنون؟ إن نسبتهم البنات لله كافية في ردّ كل ما يقولون. أم تسألهم يا رسولنا أجراً على البلاغ فهم لذلك مغتمّون متعبون؟ أم عندهم علم الغيب فهم منهمكون في كتابته لينازعوك؟ أم يريدون بك وبدينك كيداً ليقتلوك ويبطلوا دينك؟ فالذين كفروا هم المكيدون، ولم يمضِ على نزول هذه الآيات زمن طويل حتى هلك أولئك الكائدون ونصر الله رسوله وأعزّ دينه. أم لهم معبود غير الله؟ والحال أنه لا إله إلا الله، فسبحان الله وتقدّس عما يشركون به من أصنام لا تسمع ولا تبصر فضلاً عن أن تضر أو تنفع.", "h": ["تقرير التوحيد بذكر دلائله.", "تقرير النبوة المحمدية.", "تسفيه أحلام المشركين.", "عدم مشروعية أخذ أجر على إبلاغ الدعوة.", "لا يعلم الغيب إلا الله.", "صدق القرآن في أخباره آية أنه وحي الله وكلامه صدقاً وحقاً؛ إنه لم يمضِ إلا قليل من الوقت، خمسة عشر عاماً، حتى ظهر مصداق قول الله تعالى: «فالذين كفروا هم المكيدون»."], "k": "«أم خُلقوا من غير شيء أم هم الخالقون»… سؤال واحد هزّ قلب جبير فأسلم؛ فماذا يفعل بقلبي أنا؟"}, {"lbl": "الآيات ٤٤ – ٤٩", "q": "وَإِن يَرَوۡاْ كِسۡفٗا مِّنَ ٱلسَّمَآءِ سَاقِطٗا يَقُولُواْ سَحَابٞ مَّرۡكُومٞ ﴿٤٤﴾ فَذَرۡهُمۡ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي فِيهِ يُصۡعَقُونَ ﴿٤٥﴾ يَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ ﴿٤٦﴾ وَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابٗا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٤٧﴾ وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَقُومُ ﴿٤٨﴾ وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ ﴿٤٩﴾", "w": [["وإن يروا كسفاً من السماء ساقطاً", "وإن ير هؤلاء المشركون قطعة من السماء تسقط…"], ["يقولوا سحاب مركوم", "يقولوا في القطعة: سحاب متراكم يمطرنا، ولا يؤمنوا."], ["فذرهم حتى يلاقوا يومهم الذي فيه يُصعقون", "فاتركهم يجاحدون ويعاندون حتى يلاقوا يومهم الذي فيه يُصعقون، وهو يوم موتهم."], ["يوم لا يغني عنهم كيدهم شيئاً", "يوم لا يغني عنهم مكرهم بك شيئاً من العذاب، ولا هم ينصرون."], ["وإن للذين ظلموا عذاباً دون ذلك", "وإن لهؤلاء المشركين الظلمة عذاباً في الدنيا دون عذاب يوم القيامة، وهو القحط سبع سنين."], ["ولكن أكثرهم لا يعلمون", "أن العذاب نازل بهم في الدنيا قبل يوم القيامة."], ["واصبر لحكم ربك", "بإمهالهم، ولا يضق صدرك بكفرهم وعنادهم وعدم تعجيل العذاب لهم."], ["فإنك بأعيننا", "بمرأى منا، نراك ونحفظك من كيدهم ومكرهم."], ["وسبّح بحمد ربك حين تقوم", "واستعن على الصبر بالتسبيح، وهو الصلوات الخمس والذكر بعدها، والضراعة والدعاء صباح مساء."]], "m": "يذكر تعالى من عناد المشركين أنهم لو رأوا العذاب نازلاً من السماء في صورة قطعة كبيرة منها لما أذعنوا ولا آمنوا، بل قالوا: سحاب مركوم الآن يسقي ديارنا فترتوي أراضينا وبهائمنا. فلما كان الأمر هكذا فذرهم يا رسولنا في عنادهم وكفرهم حتى يلاقوا يومهم الذي فيه يُصعقون أي يموتون، يوم لا يغني عنهم كيدهم شيئاً ولا يجدون من ينصرهم، وذلك يوم القيامة. وإن للذين ظلموا أنفسهم بالكفر والشرك والمعاصي عذاباً دون عذاب يوم القيامة، وهو ما أصابهم به من سني القحط والمجاعة، وما أنزله بهم من هزيمة في بدر حيث قُتل صناديدهم وذلّوا، ولكن أكثرهم لا يعلمون ذلك، ولو علموا لما أصرّوا على العناد. واصبر لحكم ربك وقضائه بتأخير العذاب عن هؤلاء المشركين، ولا تخف ولا تحزن، فإنك بمرأى منا نراك ونحفظك، وجُمع لفظ العين على «أعين» مراعاةً لنون العظمة. وسبّح بحمد ربك، أي قل: سبحان الله وبحمده، حين تقوم من نومك ومن مجلسك، ومن الليل فسبّحه بصلاة المغرب والعشاء والتهجد، وإدبار النجوم، أي بعد طلوع الفجر، فسبّح بصلاة الصبح وغيرها.", "h": ["بيان عناد كفار قريش ومكابرتهم في الحق ومجاحدتهم فيه.", "تسلية الرسول ﷺ، وهي للدعاة بعده أيضاً.", "تقرير وخامة عاقبة الظلم في الدنيا قبل الآخرة.", "وجوب الصبر على قضاء الرب وعدم الجزع.", "مشروعية التسبيح عند القيام من النوم بنحو: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير."], "k": "«فإنك بأعيننا»… حين يضيق صدري أتذكّر أنه يراني ويحفظني؛ فهل يكفيني هذا لأصبر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (391, 53, 1, 26, 'سورة النجم ١ – ٢٦', 'النجم: وما ينطق عن الهوى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 391) = $j$[{"lbl": "الآيات ١ – ١٨", "q": "وَٱلنَّجۡمِ إِذَا هَوَىٰ ﴿١﴾ مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ ﴿٢﴾ وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ ﴿٣﴾ إِنۡ هُوَ إِلَّا وَحۡيٞ يُوحَىٰ ﴿٤﴾ عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ ﴿٥﴾ ذُو مِرَّةٖ فَٱسۡتَوَىٰ ﴿٦﴾ وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ ﴿٧﴾ ثُمَّ دَنَا فَتَدَلَّىٰ ﴿٨﴾ فَكَانَ قَابَ قَوۡسَيۡنِ أَوۡ أَدۡنَىٰ ﴿٩﴾ فَأَوۡحَىٰٓ إِلَىٰ عَبۡدِهِۦ مَآ أَوۡحَىٰ ﴿١٠﴾ مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰٓ ﴿١١﴾ أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ ﴿١٢﴾ وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ ﴿١٣﴾ عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ ﴿١٤﴾ عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ ﴿١٥﴾ إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ ﴿١٦﴾ مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ ﴿١٧﴾ لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ ﴿١٨﴾", "w": [["والنجم إذا هوى", "والثريا إذا غابت بعد طلوعها."], ["ما ضلّ صاحبكم", "ما ضلّ محمد ﷺ عن طريق الهدى."], ["وما غوى", "وما لابس الغيّ، وهو جهل من اعتقاد فاسد."], ["وما ينطق عن الهوى", "ما يقوله عن الله تعالى لم يصدر فيه عن هوى نفسه."], ["إن هو إلا وحي يوحى", "ما هو إلا وحي إلهي يوحى إليه."], ["علّمه شديد القوى", "علّمه ملك شديد القوى، وهو جبريل ﵇."], ["ذو مِرّة", "ذو سلامة في جسمه وعقله، فكان بذلك ذا قوة شديدة."], ["فاستوى وهو بالأفق الأعلى", "استقر بأفق الشمس عند مطلعها على صورته التي خلقه الله عليها، فرآه النبي ﷺ وقد سدّ الأفق إلى المغرب، وكان النبي ﷺ هو الذي طلب من جبريل أن يريه نفسه في صورته."], ["ثم دنا فتدلّى", "قرب منه فتدلّى، أي زاد في القرب."], ["فكان قاب قوسين أو أدنى", "فكان في القرب مقدار قوسين أو أقرب."], ["فأوحى إلى عبده ما أوحى", "فأوحى الله تعالى إلى عبده جبريل ما أوحاه جبريل إلى محمد ﷺ."], ["ما كذب الفؤاد ما رأى", "ما كذب فؤاد النبي ما رأى ببصره من صورة جبريل."], ["أفتمارونه على ما يرى", "أفتجادلونه أيها المشركون على ما يرى من صورة جبريل؟"], ["ولقد رآه نزلة أخرى", "رآه على صورته مرة أخرى، وذلك في السماء ليلة أُسري به."], ["عند سدرة المنتهى", "وهي شجرة نبق عن يمين العرش لا يتجاوزها أحد من الملائكة."], ["عندها جنة المأوى", "تأوي إليها الملائكة وأرواح الشهداء والمتقين أولياء الله."], ["إذ يغشى السدرة ما يغشى", "من نور الله تعالى ما يغشى."], ["ما زاغ البصر وما طغى", "ما مال بصر محمد يميناً ولا شمالاً، ولا ارتفع عن الحد الذي حُدّد له."], ["لقد رأى من آيات ربه الكبرى", "رأى جبريل في صورته، ورأى رفرفاً أخضر سدّ الأفق."]], "m": "يقرّر تعالى بهذه الآيات نبوة محمد عبده ورسوله ﷺ؛ فقد أقسم بالنجم إذا هوى، وهو نجم الثريا إذا غاب في الأفق، على أنه ما ضلّ محمد صاحب قريش الذي صاحبته ما يزيد على أربعين سنة، فهي صحبة كاملة، ما ضلّ عن طريق الهدى وهم يعرفون هذا، وما غوى أية غواية، ما لابسه جهل في قول ولا عمل. وما ينطق بالقرآن وغيره مما يقوله ويدعو إليه عن هوى نفسه كما قد يقع من غيره من البشر، ما هو إلا وحي يوحى إليه، علّمه إياه ملك شديد القوى ذو سلامة عقل وبدن، فكان بذلك قوياً روحياً وعقلياً وذاتياً، وهو جبريل ﵇. فاستقر جبريل وهو بالأفق الأعلى، ثم قرب شيئاً فشيئاً حتى كان من الرسول ﷺ قدر قوسين أو أدنى، والقوس آلة الرمي المعروفة. فأوحى الله تعالى إلى جبريل ما أوحى إلى نبيه محمد ﷺ. ما كذب فؤاد محمد ﷺ ما رآه ببصره، وهو جبريل في صورته التي خلقه الله عليها ذات الستمائة جناح. أفتجادلونه وتغالبونه أيها المشركون على ما يرى ببصره؟ ولقد رآه مرة أخرى عند سدرة المنتهى ليلة أُسري به ﷺ، وهي شجرة النبق، وُصفت بأن أوراقها كآذان الفيلة وأن ثمرها كقلال هجر، فلما غشيها من أمر الله ما غشيها تغيّرت، فما أحد من خلق الله يقدر أن ينعتها من حسنها، وسميت سدرة المنتهى لانتهاء علم كل عالم من الخلق إليها، أو لكونها لا يتجاوزها أحد من الملائكة. عندها الجنة التي تأوي إليها الملائكة وأرواح الشهداء والمتقين، إذ يغشى السدرة ما يغشى من نور الله تعالى. ما مال بصر محمد يميناً ولا شمالاً ولا ارتفع فوق الحد الذي حُدّد له. لقد رأى جبريل في خلقه الذي يكون فيه في السماء، ورأى رفرفاً أخضر قد سدّ الأفق، ورأى من عجائب خلق الله ومظاهر قدرته وعلمه ما لا سبيل إلى إدراكه والحديث عنه.", "h": ["تقرير النبوة لمحمد ﷺ وإثباتها بما لا مجال للشك والجدال فيه.", "تنزيه الرسول ﷺ عن القول بالهوى، أو صدور شيء من أفعاله أو أقواله من اتباع الهوى.", "وصف جبريل ﵇.", "إثبات رؤية النبي ﷺ لجبريل على صورته التي يكون في السماء عليها مرتين.", "تقرير حادثة الإسراء والمعراج وإثباتها للنبي ﷺ."], "k": "«وما ينطق عن الهوى»… كلامه ﷺ وحي، وكلامي أنا كثيراً ما يكون هوى؛ فهل أزن كلامي قبل أن أقوله؟"}, {"lbl": "الآيات ١٩ – ٢٦", "q": "أَفَرَءَيۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ ﴿١٩﴾ وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ ﴿٢٠﴾ أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ ﴿٢١﴾ تِلۡكَ إِذٗا قِسۡمَةٞ ضِيزَىٰٓ ﴿٢٢﴾ إِنۡ هِيَ إِلَّآ أَسۡمَآءٞ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ ﴿٢٣﴾ أَمۡ لِلۡإِنسَٰنِ مَا تَمَنَّىٰ ﴿٢٤﴾ فَلِلَّهِ ٱلۡأٓخِرَةُ وَٱلۡأُولَىٰ ﴿٢٥﴾ ۞وَكَم مِّن مَّلَكٖ فِي ٱلسَّمَٰوَٰتِ لَا تُغۡنِي شَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ ﴿٢٦﴾", "w": [["أفرأيتم اللات والعزى", "أخبروني عن أصنامكم التي اشتققتم لها أسماء من أسماء الله وأنّثتموها."], ["ومناة الثالثة الأخرى", "وجعلتموها بنات لله، افتراءً على الله وكذباً عليه."], ["ألكم الذكر وله الأنثى", "أتزعمون أن لكم الذكر الذي ترضونه لأنفسكم، ولله الأنثى التي لا ترضونها لأنفسكم؟"], ["تلك إذاً قسمة ضيزى", "قسمتكم هذه إذاً جائرة غير عادلة، ناقصة غير تامة."], ["إن هي إلا أسماء سمّيتموها أنتم وآباؤكم", "ما اللات والعزى ومناة إلا أسماء سمّيتموها بها أنتم وآباؤكم."], ["ما أنزل الله بها من سلطان", "لم ينزل الله تعالى وحياً يأذن في عبادتها."], ["إن يتّبعون إلا الظن", "ما يتّبع المشركون في عبادة أصنامهم إلا الظن والخرص والكذب."], ["وما تهوى الأنفس", "وما يتّبعون إلا ما تهواه نفوسهم وتميل إليه شهواتهم."], ["أم للإنسان ما تمنّى", "بل أللإنسان ما تمنّى؟ والجواب: لا، ليس له كل ما يتمنّى."], ["فلله الآخرة والأولى", "الآخرة والأولى كلاهما لله، يهب منهما ما يشاء لمن يشاء."], ["وكم من ملك في السماوات", "وكثير من الملائكة في السماوات."], ["لا تغني شفاعتهم شيئاً", "لو أرادوا أن يشفعوا لأحد، حتى يكون الله قد أذن لهم ورضي للمشفوع له."]], "m": "بعد أن ذكر تعالى مظاهر قدرته وعظمته في الملكوت الأعلى: جبريل وسدرة المنتهى وما غشيها من نور الله، وما أرى رسوله من الآيات الكبرى، خاطب المشركين بقوله: أفرأيتم اللات والعزى ومناة الثالثة الأخرى؟ أعميتم فرأيتم هذه الأصنام أهلاً لأن تُسوّى بمن له ملكوت السماوات والأرض على حقارتها ودناءتها، وازددتم عمى فاشتققتم لها من أسماء الله أسماء: فمن العزيز العزى، ومن الله اللات، وجعلتموها بنات لله افتراء عليه؟ أخبروني: ألكم الذكر لأنكم تحبون الذكران وترضونهم لأنفسكم، وله الأنثى لأنكم تكرهونها؟ تلك إذاً قسمة جائرة ناقصة، فكيف ترضونها لمن عبدتم الأصنام من أجل التوسل بها إليه؟ إن أصنامكم لا تعدو كونها أسماء لآلهة لا وجود لها ولا حقيقة في عالم الواقع، إذ لا إله إلا الله، أما اللات والعزى ومناة فلم تكن آلهة تحيي وتميت وتعطي وتمنع، ما هي إلا أسماء سمّيتموها أنتم وآباؤكم ما أنزل الله بها وحياً يأذن بعبادتها. ثم التفت جل جلاله في الخطاب عنهم فقال: إن يتّبعون في عبادة هذه الأصنام إلا الظن، فلا يقين لهم في صحة عبادتها، وما تهوى أنفسهم، ولقد جاءهم من ربهم الهدى فبيّن لهم الصراط السوي فأعرضوا عن الحق، وتعلّقوا بالأماني الكاذبة وأن أصنامهم تشفع لهم. أم للإنسان ما تمنّى؟ ليس له ما تمنّى، إذ لله الآخرة والأولى يعطي منهما ما يشاء ويمنع ما يشاء. وكم من ملك في السماوات لا يُعدّون كثرة لا تغني شفاعتهم شيئاً إلا من بعد أن يأذن الله لمن يشاء أن يشفع ويرضى عن المشفوع له، وإلا فلا شافع ولا شفاعة تنفع عند الله الملك الحق المبين.", "h": ["التنديد بالشرك والمشركين وتسفيه أحلامهم لعبادتهم أسماء لا مسمّيات لها في الخارج، إذ تسمية حجر إلهاً لن تجعله إلهاً.", "بيان أن المشركين في كل زمان ومكان ما يتّبعون في عبادة غير الله إلا أهواءهم.", "بيان أن الإنسان لا يُعطى بأمانيه، ولكن بعمله وصدقه وجدّه فيه.", "بيان أن الدنيا كالآخرة لله، فلا ينبغي أن يُطلب شيء منها إلا من الله مالكها.", "كل شفاعة تُرجى فهي لا تحقق شيئاً إلا بتوفّر شرطين: الأول أن يأذن الله للشافع في الشفاعة، والثاني أن يكون الله قد رضي للمشفوع له بالشفاعة."], "k": "«أم للإنسان ما تمنّى»… أتمنّى الجنة كثيراً؛ فهل يشبه عملي أمنيتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 391;
insert into public.tdb_cards(topic, i, body) select 391, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٨", "q": "وَٱلنَّجۡمِ إِذَا هَوَىٰ ﴿١﴾ مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ ﴿٢﴾ وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ ﴿٣﴾ إِنۡ هُوَ إِلَّا وَحۡيٞ يُوحَىٰ ﴿٤﴾ عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ ﴿٥﴾ ذُو مِرَّةٖ فَٱسۡتَوَىٰ ﴿٦﴾ وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ ﴿٧﴾ ثُمَّ دَنَا فَتَدَلَّىٰ ﴿٨﴾ فَكَانَ قَابَ قَوۡسَيۡنِ أَوۡ أَدۡنَىٰ ﴿٩﴾ فَأَوۡحَىٰٓ إِلَىٰ عَبۡدِهِۦ مَآ أَوۡحَىٰ ﴿١٠﴾ مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰٓ ﴿١١﴾ أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ ﴿١٢﴾ وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ ﴿١٣﴾ عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ ﴿١٤﴾ عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ ﴿١٥﴾ إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ ﴿١٦﴾ مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ ﴿١٧﴾ لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ ﴿١٨﴾", "w": [["والنجم إذا هوى", "والثريا إذا غابت بعد طلوعها."], ["ما ضلّ صاحبكم", "ما ضلّ محمد ﷺ عن طريق الهدى."], ["وما غوى", "وما لابس الغيّ، وهو جهل من اعتقاد فاسد."], ["وما ينطق عن الهوى", "ما يقوله عن الله تعالى لم يصدر فيه عن هوى نفسه."], ["إن هو إلا وحي يوحى", "ما هو إلا وحي إلهي يوحى إليه."], ["علّمه شديد القوى", "علّمه ملك شديد القوى، وهو جبريل ﵇."], ["ذو مِرّة", "ذو سلامة في جسمه وعقله، فكان بذلك ذا قوة شديدة."], ["فاستوى وهو بالأفق الأعلى", "استقر بأفق الشمس عند مطلعها على صورته التي خلقه الله عليها، فرآه النبي ﷺ وقد سدّ الأفق إلى المغرب، وكان النبي ﷺ هو الذي طلب من جبريل أن يريه نفسه في صورته."], ["ثم دنا فتدلّى", "قرب منه فتدلّى، أي زاد في القرب."], ["فكان قاب قوسين أو أدنى", "فكان في القرب مقدار قوسين أو أقرب."], ["فأوحى إلى عبده ما أوحى", "فأوحى الله تعالى إلى عبده جبريل ما أوحاه جبريل إلى محمد ﷺ."], ["ما كذب الفؤاد ما رأى", "ما كذب فؤاد النبي ما رأى ببصره من صورة جبريل."], ["أفتمارونه على ما يرى", "أفتجادلونه أيها المشركون على ما يرى من صورة جبريل؟"], ["ولقد رآه نزلة أخرى", "رآه على صورته مرة أخرى، وذلك في السماء ليلة أُسري به."], ["عند سدرة المنتهى", "وهي شجرة نبق عن يمين العرش لا يتجاوزها أحد من الملائكة."], ["عندها جنة المأوى", "تأوي إليها الملائكة وأرواح الشهداء والمتقين أولياء الله."], ["إذ يغشى السدرة ما يغشى", "من نور الله تعالى ما يغشى."], ["ما زاغ البصر وما طغى", "ما مال بصر محمد يميناً ولا شمالاً، ولا ارتفع عن الحد الذي حُدّد له."], ["لقد رأى من آيات ربه الكبرى", "رأى جبريل في صورته، ورأى رفرفاً أخضر سدّ الأفق."]], "m": "يقرّر تعالى بهذه الآيات نبوة محمد عبده ورسوله ﷺ؛ فقد أقسم بالنجم إذا هوى، وهو نجم الثريا إذا غاب في الأفق، على أنه ما ضلّ محمد صاحب قريش الذي صاحبته ما يزيد على أربعين سنة، فهي صحبة كاملة، ما ضلّ عن طريق الهدى وهم يعرفون هذا، وما غوى أية غواية، ما لابسه جهل في قول ولا عمل. وما ينطق بالقرآن وغيره مما يقوله ويدعو إليه عن هوى نفسه كما قد يقع من غيره من البشر، ما هو إلا وحي يوحى إليه، علّمه إياه ملك شديد القوى ذو سلامة عقل وبدن، فكان بذلك قوياً روحياً وعقلياً وذاتياً، وهو جبريل ﵇. فاستقر جبريل وهو بالأفق الأعلى، ثم قرب شيئاً فشيئاً حتى كان من الرسول ﷺ قدر قوسين أو أدنى، والقوس آلة الرمي المعروفة. فأوحى الله تعالى إلى جبريل ما أوحى إلى نبيه محمد ﷺ. ما كذب فؤاد محمد ﷺ ما رآه ببصره، وهو جبريل في صورته التي خلقه الله عليها ذات الستمائة جناح. أفتجادلونه وتغالبونه أيها المشركون على ما يرى ببصره؟ ولقد رآه مرة أخرى عند سدرة المنتهى ليلة أُسري به ﷺ، وهي شجرة النبق، وُصفت بأن أوراقها كآذان الفيلة وأن ثمرها كقلال هجر، فلما غشيها من أمر الله ما غشيها تغيّرت، فما أحد من خلق الله يقدر أن ينعتها من حسنها، وسميت سدرة المنتهى لانتهاء علم كل عالم من الخلق إليها، أو لكونها لا يتجاوزها أحد من الملائكة. عندها الجنة التي تأوي إليها الملائكة وأرواح الشهداء والمتقين، إذ يغشى السدرة ما يغشى من نور الله تعالى. ما مال بصر محمد يميناً ولا شمالاً ولا ارتفع فوق الحد الذي حُدّد له. لقد رأى جبريل في خلقه الذي يكون فيه في السماء، ورأى رفرفاً أخضر قد سدّ الأفق، ورأى من عجائب خلق الله ومظاهر قدرته وعلمه ما لا سبيل إلى إدراكه والحديث عنه.", "h": ["تقرير النبوة لمحمد ﷺ وإثباتها بما لا مجال للشك والجدال فيه.", "تنزيه الرسول ﷺ عن القول بالهوى، أو صدور شيء من أفعاله أو أقواله من اتباع الهوى.", "وصف جبريل ﵇.", "إثبات رؤية النبي ﷺ لجبريل على صورته التي يكون في السماء عليها مرتين.", "تقرير حادثة الإسراء والمعراج وإثباتها للنبي ﷺ."], "k": "«وما ينطق عن الهوى»… كلامه ﷺ وحي، وكلامي أنا كثيراً ما يكون هوى؛ فهل أزن كلامي قبل أن أقوله؟"}, {"lbl": "الآيات ١٩ – ٢٦", "q": "أَفَرَءَيۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ ﴿١٩﴾ وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ ﴿٢٠﴾ أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ ﴿٢١﴾ تِلۡكَ إِذٗا قِسۡمَةٞ ضِيزَىٰٓ ﴿٢٢﴾ إِنۡ هِيَ إِلَّآ أَسۡمَآءٞ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ ﴿٢٣﴾ أَمۡ لِلۡإِنسَٰنِ مَا تَمَنَّىٰ ﴿٢٤﴾ فَلِلَّهِ ٱلۡأٓخِرَةُ وَٱلۡأُولَىٰ ﴿٢٥﴾ ۞وَكَم مِّن مَّلَكٖ فِي ٱلسَّمَٰوَٰتِ لَا تُغۡنِي شَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ ﴿٢٦﴾", "w": [["أفرأيتم اللات والعزى", "أخبروني عن أصنامكم التي اشتققتم لها أسماء من أسماء الله وأنّثتموها."], ["ومناة الثالثة الأخرى", "وجعلتموها بنات لله، افتراءً على الله وكذباً عليه."], ["ألكم الذكر وله الأنثى", "أتزعمون أن لكم الذكر الذي ترضونه لأنفسكم، ولله الأنثى التي لا ترضونها لأنفسكم؟"], ["تلك إذاً قسمة ضيزى", "قسمتكم هذه إذاً جائرة غير عادلة، ناقصة غير تامة."], ["إن هي إلا أسماء سمّيتموها أنتم وآباؤكم", "ما اللات والعزى ومناة إلا أسماء سمّيتموها بها أنتم وآباؤكم."], ["ما أنزل الله بها من سلطان", "لم ينزل الله تعالى وحياً يأذن في عبادتها."], ["إن يتّبعون إلا الظن", "ما يتّبع المشركون في عبادة أصنامهم إلا الظن والخرص والكذب."], ["وما تهوى الأنفس", "وما يتّبعون إلا ما تهواه نفوسهم وتميل إليه شهواتهم."], ["أم للإنسان ما تمنّى", "بل أللإنسان ما تمنّى؟ والجواب: لا، ليس له كل ما يتمنّى."], ["فلله الآخرة والأولى", "الآخرة والأولى كلاهما لله، يهب منهما ما يشاء لمن يشاء."], ["وكم من ملك في السماوات", "وكثير من الملائكة في السماوات."], ["لا تغني شفاعتهم شيئاً", "لو أرادوا أن يشفعوا لأحد، حتى يكون الله قد أذن لهم ورضي للمشفوع له."]], "m": "بعد أن ذكر تعالى مظاهر قدرته وعظمته في الملكوت الأعلى: جبريل وسدرة المنتهى وما غشيها من نور الله، وما أرى رسوله من الآيات الكبرى، خاطب المشركين بقوله: أفرأيتم اللات والعزى ومناة الثالثة الأخرى؟ أعميتم فرأيتم هذه الأصنام أهلاً لأن تُسوّى بمن له ملكوت السماوات والأرض على حقارتها ودناءتها، وازددتم عمى فاشتققتم لها من أسماء الله أسماء: فمن العزيز العزى، ومن الله اللات، وجعلتموها بنات لله افتراء عليه؟ أخبروني: ألكم الذكر لأنكم تحبون الذكران وترضونهم لأنفسكم، وله الأنثى لأنكم تكرهونها؟ تلك إذاً قسمة جائرة ناقصة، فكيف ترضونها لمن عبدتم الأصنام من أجل التوسل بها إليه؟ إن أصنامكم لا تعدو كونها أسماء لآلهة لا وجود لها ولا حقيقة في عالم الواقع، إذ لا إله إلا الله، أما اللات والعزى ومناة فلم تكن آلهة تحيي وتميت وتعطي وتمنع، ما هي إلا أسماء سمّيتموها أنتم وآباؤكم ما أنزل الله بها وحياً يأذن بعبادتها. ثم التفت جل جلاله في الخطاب عنهم فقال: إن يتّبعون في عبادة هذه الأصنام إلا الظن، فلا يقين لهم في صحة عبادتها، وما تهوى أنفسهم، ولقد جاءهم من ربهم الهدى فبيّن لهم الصراط السوي فأعرضوا عن الحق، وتعلّقوا بالأماني الكاذبة وأن أصنامهم تشفع لهم. أم للإنسان ما تمنّى؟ ليس له ما تمنّى، إذ لله الآخرة والأولى يعطي منهما ما يشاء ويمنع ما يشاء. وكم من ملك في السماوات لا يُعدّون كثرة لا تغني شفاعتهم شيئاً إلا من بعد أن يأذن الله لمن يشاء أن يشفع ويرضى عن المشفوع له، وإلا فلا شافع ولا شفاعة تنفع عند الله الملك الحق المبين.", "h": ["التنديد بالشرك والمشركين وتسفيه أحلامهم لعبادتهم أسماء لا مسمّيات لها في الخارج، إذ تسمية حجر إلهاً لن تجعله إلهاً.", "بيان أن المشركين في كل زمان ومكان ما يتّبعون في عبادة غير الله إلا أهواءهم.", "بيان أن الإنسان لا يُعطى بأمانيه، ولكن بعمله وصدقه وجدّه فيه.", "بيان أن الدنيا كالآخرة لله، فلا ينبغي أن يُطلب شيء منها إلا من الله مالكها.", "كل شفاعة تُرجى فهي لا تحقق شيئاً إلا بتوفّر شرطين: الأول أن يأذن الله للشافع في الشفاعة، والثاني أن يكون الله قد رضي للمشفوع له بالشفاعة."], "k": "«أم للإنسان ما تمنّى»… أتمنّى الجنة كثيراً؛ فهل يشبه عملي أمنيتي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (392, 53, 27, 62, 'سورة النجم ٢٧ – ٦٢', 'النجم: وأن ليس للإنسان إلا ما سعى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 392) = $j$[{"lbl": "الآيات ٢٧ – ٣٠", "q": "إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ لَيُسَمُّونَ ٱلۡمَلَـٰٓئِكَةَ تَسۡمِيَةَ ٱلۡأُنثَىٰ ﴿٢٧﴾ وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـٔٗا ﴿٢٨﴾ فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ﴿٢٩﴾ ذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ ﴿٣٠﴾", "w": [["إن الذين لا يؤمنون بالآخرة", "لا يؤمنون بالبعث والحياة الآخرة."], ["ليسمّون الملائكة تسمية الأنثى", "ليطلقون على الملائكة أسماء الإناث، إذ قالوا: بنات الله."], ["وما لهم به من علم", "ليس لهم بذلك علم من كتاب ولا هدى من نبي."], ["إن يتّبعون إلا الظن", "في تسميتهم الملائكة إناثاً إلا مجرد الظن، والظن لا تقوم به حجة ولا يُعطى به حق."], ["فأعرض عن من تولّى عن ذكرنا", "أي عن القرآن وعبادتنا."], ["ولم يرد إلا الحياة الدنيا", "لم يرد من قوله ولا عمله إلا ما يحقق رغائبه من الدنيا."], ["ذلك مبلغهم من العلم", "ذلك الطلب للدنيا نهاية علمهم، إذ آثروا الدنيا على الآخرة."]], "m": "لما ندّد تعالى بالمشركين الذين جعلوا من الأصنام والأوهام والأماني آلهة وجادلوا دونها، ذكر علّة ذلك التخبط والضلال فقال: إن الذين لا يؤمنون بالآخرة، دار السعادة الحقة أو الشقاء، ليسمّون الملائكة تسمية الأنثى؛ فلو آمنوا بالآخرة لما سمّوا الملائكة بنات الله، لأن المؤمن بالآخرة يحاسب نفسه على كل قول وعمل له تبعة يخشى أن يؤخذ بها، بخلاف الذي لا يؤمن بالآخرة فإنه يقول ويفعل ما يشاء لعدم شعوره بالمسؤولية. وما لهم في ادعائهم أن الملائكة بنات الله أي علم يُعتدّ به، إن يتّبعون فيه إلا الظن، والظن أكذب الحديث، وإن الظن لا يغني من الحق شيئاً. وبناءً على هذا أمر الله رسوله أن يعرض عمّن تولّى منهم عن الحق بعد معرفته، وعن القرآن والإيمان والتوحيد والطاعة، ولم يرد بقوله وعمله واعتقاده إلا الحياة الدنيا، إذ هو لا يؤمن بالآخرة، فكل تفكيره في الدنيا وكل عمله لها، فيصبح بذلك أشبه بالآلة منه بالإنسان، فلذا يجب الإعراض عنه وتركه إلى أن يأذن الله فيه بشيء. ذلك الطلب للدنيا هو ما انتهى إليه علمهم، فلذا آثروها على الآخرة التي لم يعلموا عنها شيئاً. إن ربك هو أعلم بمن ضلّ عن سبيله، وهو أعلم بمن اهتدى، قضاءً وقدراً وواقعاً في الحياة الدنيا، وسيجزي كلاً بما عمل، فلا تأسَ يا رسولنا ولا تحزن، وفوّض الأمر إلينا.", "h": ["أكثر الأمراض مردّها إلى قلب لا يؤمن بالآخرة.", "أكثر الفساد في الأرض هو نتيجة الجهل وعدم العلم اليقيني.", "التحذير من الماديين، فإنهم شر وخطر، وواجب الإعراض عنهم لأنهم شر الخليقة."], "k": "«ولم يرد إلا الحياة الدنيا»… كم من همّي في يومي للدنيا، وكم للآخرة؟"}, {"lbl": "الآيتان ٣١ – ٣٢", "q": "وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ لِيَجۡزِيَ ٱلَّذِينَ أَسَـٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ بِٱلۡحُسۡنَى ﴿٣١﴾ ٱلَّذِينَ يَجۡتَنِبُونَ كَبَـٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةٞ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰٓ ﴿٣٢﴾", "w": [["ولله ما في السماوات وما في الأرض", "خلقاً وملكاً وتصرّفاً."], ["ليجزي الذين أساءوا بما عملوا", "ليعاقب الذين أساءوا بما عملوا من الشرك والمعاصي."], ["ويجزي الذين أحسنوا بالحسنى", "ويثيب الذين أحسنوا في إيمانهم وعملهم الصالح بالجنة."], ["الذين يجتنبون كبائر الإثم", "يتجنّبون كبائر الذنوب، وهي كل ذنب وُضع له حد، أو لُعن فاعله، أو تُوعّد عليه بالعذاب في الآخرة."], ["والفواحش إلا اللمم", "الذنوب القبيحة كالزنا واللواط وقذف المحصنات والبخل، واللمم صغائر الذنوب التي تُكفّر باجتناب كبائرها."], ["هو أعلم بكم إذ أنشأكم من الأرض", "خلق أباكم آدم من تراب الأرض."], ["وإذ أنتم أجنّة في بطون أمهاتكم", "وأنتم في أرحام أمهاتكم لم تولدوا بعد."], ["فلا تزكّوا أنفسكم", "فلا تمدحوها على سبيل الفخر والإعجاب."], ["هو أعلم بمن اتقى", "هو أعلم منكم بمن اتقى منكم وبمن فجر."]], "m": "ما زال السياق في تقرير ربوبيته تعالى المطلقة لكل شيء؛ إذ تقدم قوله «فلله الآخرة والأولى»، وهنا قال: ولله ما في السماوات وما في الأرض خلقاً وملكاً وتصرفاً وتدبيراً، فهو يهدي من يشاء ويضل من يشاء، هداية وإضلالاً تابعين لحكمة، يدل عليه قوله: ليجزي الذين أساءوا إلى أنفسهم بما عملوا من الشرك والمعاصي بجهنم، ويجزي الذين أحسنوا إلى أنفسهم فزكّوها وطهّروها بالإيمان والعمل الصالح بالحسنى التي هي الجنة. ثم بيّن وجه إحسان المحسنين: الذين يجتنبون كبائر الإثم، من كل ما وُعد فاعله بالنار أو بلعن أو إقامة حد أو غضب الرب، والفواحش من زنا ولواط وبخل، إلا اللمم فإنه يُتجاوز عنه، وهو ما ألمّ به المرء وتاب منه، أو فعله في الجاهلية ثم أسلم، وما كان من صغائر الذنوب كالنظرة والكلمة، وقد فُسّر بقول الرسول ﷺ: «إن الله كتب على ابن آدم حظه من الزنا، أدرك ذلك لا محالة؛ فزنا العينين النظر، وزنا اللسان المنطق، والنفس تتمنى وتشتهي، والفرج يصدّق ذلك أو يكذّبه». فمغفرة الله واسعة تشمل كل ذنب تاب منه فاعله. هو أعلم بكم إذ أنشأكم من الأرض وإذ أنتم أجنّة في بطون أمهاتكم؛ أعلم بضعفنا وغرائزنا وحاجاتنا منا بأنفسنا، ولذا تجاوز لنا عن اللمم الذي نُلمّ به بحكم العجز والضعف، فله الحمد والمنة. فلا تزكّوا أنفسكم: ينهى تعالى عباده عن تزكية المرء نفسه بادعاء الكمال والطهر، الأمر الذي يكون فخراً وإعجاباً، والإعجاب بالنفس محبط للعمل كالرياء، أي لا تشهدوا عليها بأنها زكية بريئة من الذنوب، هو أعلم بمن اتقى منكم ربه فأدّى الفرائض واجتنب المحرمات، فلا تمدحوا أنفسكم له، فإنه أعلم بكم من أنفسكم.", "h": ["تقرير ربوبية الله تعالى لكل شيء، وهي مستلزمة لألوهيته.", "تقرير حرية إرادة الله؛ يهدي من يشاء ويضل، ويعذّب من يشاء ويرحم.", "تقرير قاعدة: الجزاء من جنس العمل.", "تقرير قاعدة أن الصغائر تُكفّر باجتناب الكبائر.", "حرمة تزكية النفس، وهي مدحها والشهادة عليها بالخير والفضل والكمال والتفوق."], "k": "«فلا تزكّوا أنفسكم هو أعلم بمن اتقى»… حين أمدح نفسي أنسى ما يعلمه هو عني؛ فلأسكت وأستغفر."}, {"lbl": "الآيات ٣٣ – ٥٤", "q": "أَفَرَءَيۡتَ ٱلَّذِي تَوَلَّىٰ ﴿٣٣﴾ وَأَعۡطَىٰ قَلِيلٗا وَأَكۡدَىٰٓ ﴿٣٤﴾ أَعِندَهُۥ عِلۡمُ ٱلۡغَيۡبِ فَهُوَ يَرَىٰٓ ﴿٣٥﴾ أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِي صُحُفِ مُوسَىٰ ﴿٣٦﴾ وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ ﴿٣٧﴾ أَلَّا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰ ﴿٣٨﴾ وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ ﴿٣٩﴾ وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ ﴿٤٠﴾ ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ ﴿٤١﴾ وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ ﴿٤٢﴾ وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ ﴿٤٣﴾ وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡيَا ﴿٤٤﴾ وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ ﴿٤٥﴾ مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ ﴿٤٦﴾ وَأَنَّ عَلَيۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ ﴿٤٧﴾ وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ ﴿٤٨﴾ وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ ﴿٤٩﴾ وَأَنَّهُۥٓ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ ﴿٥٠﴾ وَثَمُودَاْ فَمَآ أَبۡقَىٰ ﴿٥١﴾ وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ ﴿٥٢﴾ وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ ﴿٥٣﴾ فَغَشَّىٰهَا مَا غَشَّىٰ ﴿٥٤﴾", "w": [["أفرأيت الذي تولّى", "عن الإسلام بعد ما قارب أن يدخل فيه."], ["وأعطى قليلاً وأكدى", "أعطى من زعم أنه يتحمّل عنه عذاب الآخرة ما وعده من المال ثم منع."], ["أعنده علم الغيب فهو يرى", "يعلم أن غيره يتحمّل عنه العذاب؟ والجواب: لا."], ["أم لم يُنبّأ بما في صحف موسى وإبراهيم الذي وفّى", "بل لم يُخبر بما ورد في الصحف، وهي التوراة وعشر صحف كانت لإبراهيم ﵇."], ["ألا تزر وازرة وزر أخرى", "لا تحمل نفس مذنبة ذنب غيرها."], ["وأن ليس للإنسان إلا ما سعى", "من خير وشر، وليس له ولا عليه من سعي غيره شيء."], ["وأن سعيه سوف يُرى", "يُبصَر يوم القيامة ويراه بنفسه."], ["ثم يُجزاه الجزاء الأوفى", "الأكمل التام الذي لا نقص فيه."], ["وأن إلى ربك المنتهى", "المرجع والمصير، إليه ينتهي أمر عباده بعد الموت."], ["وأنه هو أضحك وأبكى", "أفرح من شاء فأضحكه، وأحزن من شاء فأبكاه."], ["وأنه هو أمات وأحيا", "أمات في الدنيا وأحيا في الآخرة."], ["وأنه خلق الزوجين", "الصنفين: الذكر والأنثى."], ["من نطفة إذا تُمنى", "من منيّ إذا يُصبّ في الرحم."], ["وأن عليه النشأة الأخرى", "الخلقة الثانية للبعث والجزاء."], ["وأنه هو أغنى وأقنى", "أغنى بعض الناس بالكفاية، وأقنى بعضهم بالمال المقتنى المدّخر."], ["وأنه هو ربّ الشِّعرى", "خالقها ومالكها، وهي كوكب خلف الجوزاء عبده بعض العرب."], ["وأنه أهلك عاداً الأولى", "قوم هود ﵇."], ["وثمود فما أبقى", "أهلكها أيضاً فلم يُبقِ منهم أحداً، وهم قوم صالح."], ["وقوم نوح من قبل", "وأهلك قوم نوح من قبل عاد وثمود."], ["والمؤتفكة أهوى", "وقرى قوم لوط أسقطها بعد رفعها إلى السماء مقلوبة إلى الأرض، إذ الائتفاك الانقلاب."], ["فغشّاها ما غشّى", "من العذاب ما غشّى، حيث جعل عاليها سافلها وأمطر عليها حجارة من سجيل."]], "m": "إن هذه الآيات ترسم صورة لقرشي جاهل هو الوليد بن المغيرة؛ استمع إلى قراءة رسول الله ﷺ فهشّ لها، ودعاه الرسول فأوشك أن يسلم، فعلم به أحد المشركين فعيّره بترك دين آبائه، فاعتذر الوليد بأنه يخاف عذاب الله، فقال له ذلك المشرك، وكان فقيراً والوليد غنياً: أعطني كذا من المال وأنا أتحمّل عنك العذاب الذي تخافه، وعُد إلى دينك، فوافق الوليد وأعطاه ثم قطع عنه ما كان يعطيه. فأنزل الله فيه هذه الآيات تسلية لرسوله ﷺ وتعليماً وتحذيراً لكل من تبلغه: أفرأيت الذي تولّى عن الإسلام بعد أن قارب الدخول فيه، وأعطى قليلاً من المال للذي اتفق معه على أن يتحمل عنه العذاب، وأكدى أي قطع ومنع، كالذي يحفر بئراً فتصادفه كدية من الأرض الصلبة فيعجز وينقطع. أعنده علم الغيب فهو يرى أن المرء يمكنه أن يتحمّل عذاب غيره يوم القيامة؟ لا علم غيب عنده. أم لم يُخبر بما في صحف موسى، وهي التوراة، وإبراهيم الذي وفّى لربه في كل ما عهد به إليه من ذبح ولده وبناء البيت والهجرة والختان وغير ذلك من التكاليف الشاقة؟ ثم بيّن تعالى ما تضمنته تلك الصحف: ألّا تحمل نفس مذنبة ذنب نفس أخرى، وأن ليس للإنسان من ثواب يوم القيامة إلا ما سعى في تحصيله بنفسه، وهذا لا يتعارض مع قوله ﷺ في الصحيح: «إذا مات ابن آدم انقطع عمله إلا من ثلاث: ولد صالح يدعو له، أو صدقة جارية، أو علم ينتفع به»، إذ هذه الثلاثة من سعيه: الولد أنجبه ورباه، والصدقة أوقفها بنفسه، والعلم تعلّمه وبثّه في الناس. وأن عمله في الدنيا سوف يُرى علانية ويُجزى به الجزاء الأكمل. وأن إلى ربك المنتهى، إليه تصير أمور عباده بعد الموت فيحكم فيها. وأنه أضحك أهل الجنة وأبكى أهل النار، زيادة على من أفرح في الدنيا ومن أحزن. وأنه أمات عند نهاية الأجل وأحيا في القبر ويوم النشر، وأحيا بالإيمان وأمات بالكفر، وأمات بالقحط وأحيا بالمطر. وأنه خلق الزوجين الذكر والأنثى من سائر الحيوانات من نطفة إذا تُصبّ في الأرحام. وأن عليه النشأة الأخرى، فهو الذي يحيي الخلائق بعد موتهم. وأنه أغنى بعض الناس فسدّ حاجتهم، وأقنى آخرين فأعطاهم مالاً كثيراً. وأنه رب الشعرى، ذلك الكوكب الذي يطلع خلف الجوزاء، فالله خالقه ومسخّره، وقد عبده الجاهلون وهو مربوب. وأنه أهلك عاداً الأولى قوم هود، تلك الأمة القائلة: من أشد منا قوة، وثمود قوم صالح فما أبقى منهم أحداً، وقوم نوح من قبل، إنهم كانوا أظلم وأطغى، والمؤتفكة قرى قوم لوط رفعها إلى عنان السماء ثم أهوى بها إلى الأرض، فغشّاها من العذاب الأليم ما يعجز الوصف عنه. هذا هو الله رب العالمين الذي اتخذ الجهّال له أنداداً، العزيز المنتقم لأوليائه من أعدائه.", "h": ["تقرير ربوبية الله تعالى وإثبات ألوهيته بالبراهين والحجج التي لا تُردّ بحال.", "تقرير عدالة الله تعالى في حكمه وقضائه.", "مظاهر قدرة الله تعالى وعلمه وحكمته.", "تقرير حقيقة علمية، وهي أن العمل الذي يزكّي النفس أو يدنّسها هو ذاك الذي يباشره المرء بنفسه وباختياره وقصده ونيته.", "تحذير الظلمة والطغاة من أهل الكفر والشرك من أن يصيبهم ما أصاب غيرهم من الدمار."], "k": "«وأن ليس للإنسان إلا ما سعى»… لن يحمل عني أحد، ولن أنال إلا ما سعيت؛ فماذا أسعى اليوم؟"}, {"lbl": "الآيات ٥٥ – ٦٢", "q": "فَبِأَيِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ ﴿٥٥﴾ هَٰذَا نَذِيرٞ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰٓ ﴿٥٦﴾ أَزِفَتِ ٱلۡأٓزِفَةُ ﴿٥٧﴾ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ ﴿٥٨﴾ أَفَمِنۡ هَٰذَا ٱلۡحَدِيثِ تَعۡجَبُونَ ﴿٥٩﴾ وَتَضۡحَكُونَ وَلَا تَبۡكُونَ ﴿٦٠﴾ وَأَنتُمۡ سَٰمِدُونَ ﴿٦١﴾ فَٱسۡجُدُواْۤ لِلَّهِۤ وَٱعۡبُدُواْ۩ ﴿٦٢﴾", "w": [["فبأي آلاء ربك", "فبأي نعم ربك عليك وعلى غيرك أيها الإنسان…"], ["تتمارى", "تتشكك أو تكذّب."], ["هذا نذير من النذر الأولى", "هذا النبي محمد ﷺ رسول مثل الرسل الأولى الذين أُرسلوا إلى أقوامهم."], ["أزفت الآزفة", "قربت القيامة، ووُصفت بالقرب لقربها فعلاً."], ["ليس لها من دون الله كاشفة", "ليس للقيامة من دون الله نفس كاشفة مظهرة لوقتها، إذ لا يجلّيها لوقتها إلا الله سبحانه."], ["أفمن هذا الحديث", "أي القرآن."], ["تعجبون وتضحكون", "تعجبون تكذيباً به، وتضحكون سخرية منه."], ["وأنتم سامدون", "لاهون مشتغلون بالباطل من القول كالغناء، والعمل كعبادة الأصنام."], ["فاسجدوا لله", "الذي خلقكم ورزقكم وكلأكم، ولا تسجدوا للأصنام."], ["واعبدوا", "ذلّوا لله واخضعوا له تعظيماً ومحبة ورهبة، فإنه إلهكم الحق الذي لا إله لكم غيره."]], "m": "خاطب الله تعالى الإنسان فقال: بعد الذي عرضنا عليك في هذه السورة من مظاهر النعم والنقم، وكلها في الباطن نعم، فبأي نعم ربك تتشكك أو تكذّب، وكلها ثابتة أمامك لا تقدر على إنكارها؟ هذا نذير من النذر الأولى: يشير إلى ما في هذه السورة والقرآن كله من نذر، أو إلى النبي محمد ﷺ، وكلا الأمرين حق: القرآن نذير ومحمد نذير من النذر الأولى التي سبقته، وهم الرسل، ألا فاحذروا أيها الناس عاقبة إعراضكم. أزفت الآزفة: يخبر تعالى أن القيامة قد آن أوانها وحضرت ساعتها، إنها لقريبة جداً، ليس لها من دون الله نفس كاشفة تظهرها، بل تبقى مستورة لحكمة إلهية حتى تفاجأ بها البشرية. ثم قال توبيخاً للمشركين: أفمن هذا الحديث الإلهي، وهو القرآن، تعجبون؟ وتضحكون كأن قلوبكم أصابها الموات، ولا تبكون على أنفسكم وقد بعتموها للشيطان، وأنتم ساهون لاهون تغنّون وتلعبون. أنقذوا أنفسكم فاسجدوا لله، فإنه لا نجاة لكم من العذاب الأليم إلا بالاطّراح بين يديه إسلاماً له وخضوعاً، تعبدونه بتوحيده في عبادته، وتسلمون له قلوبكم ووجوهكم، فلا يكون لكم غير الله معبوداً تعظّمونه وتحبونه وتتقربون إليه بفعل محابّه وترك مكارهه.", "h": ["بيان قرب الساعة، وخفاء ساعتها عن كل خلق الله حتى تأتي بغتة.", "ذم الضحك مع الانغماس في الشهوات.", "الترغيب في البكاء من خشية الله.", "كراهية الغناء واللهو واللعب.", "مشروعية السجود عند تلاوة هذه الآية لمن يتلوها ولمن يستمع لها، وهي من عزائم السجدات في القرآن الكريم، ومن خصائص هذه السجدة أن المشركين سجدوها مع رسول الله ﷺ حول الكعبة كما في الصحيح."], "k": "«وتضحكون ولا تبكون»… أضحك كثيراً، فمتى بكيت آخر مرة من خشية الله؟"}]$j$::jsonb then 0 else 1 end;
