insert into public.tdb_cards(topic, i, body) select 392, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٧ – ٣٠", "q": "إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ لَيُسَمُّونَ ٱلۡمَلَـٰٓئِكَةَ تَسۡمِيَةَ ٱلۡأُنثَىٰ ﴿٢٧﴾ وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـٔٗا ﴿٢٨﴾ فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ﴿٢٩﴾ ذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ ﴿٣٠﴾", "w": [["إن الذين لا يؤمنون بالآخرة", "لا يؤمنون بالبعث والحياة الآخرة."], ["ليسمّون الملائكة تسمية الأنثى", "ليطلقون على الملائكة أسماء الإناث، إذ قالوا: بنات الله."], ["وما لهم به من علم", "ليس لهم بذلك علم من كتاب ولا هدى من نبي."], ["إن يتّبعون إلا الظن", "في تسميتهم الملائكة إناثاً إلا مجرد الظن، والظن لا تقوم به حجة ولا يُعطى به حق."], ["فأعرض عن من تولّى عن ذكرنا", "أي عن القرآن وعبادتنا."], ["ولم يرد إلا الحياة الدنيا", "لم يرد من قوله ولا عمله إلا ما يحقق رغائبه من الدنيا."], ["ذلك مبلغهم من العلم", "ذلك الطلب للدنيا نهاية علمهم، إذ آثروا الدنيا على الآخرة."]], "m": "لما ندّد تعالى بالمشركين الذين جعلوا من الأصنام والأوهام والأماني آلهة وجادلوا دونها، ذكر علّة ذلك التخبط والضلال فقال: إن الذين لا يؤمنون بالآخرة، دار السعادة الحقة أو الشقاء، ليسمّون الملائكة تسمية الأنثى؛ فلو آمنوا بالآخرة لما سمّوا الملائكة بنات الله، لأن المؤمن بالآخرة يحاسب نفسه على كل قول وعمل له تبعة يخشى أن يؤخذ بها، بخلاف الذي لا يؤمن بالآخرة فإنه يقول ويفعل ما يشاء لعدم شعوره بالمسؤولية. وما لهم في ادعائهم أن الملائكة بنات الله أي علم يُعتدّ به، إن يتّبعون فيه إلا الظن، والظن أكذب الحديث، وإن الظن لا يغني من الحق شيئاً. وبناءً على هذا أمر الله رسوله أن يعرض عمّن تولّى منهم عن الحق بعد معرفته، وعن القرآن والإيمان والتوحيد والطاعة، ولم يرد بقوله وعمله واعتقاده إلا الحياة الدنيا، إذ هو لا يؤمن بالآخرة، فكل تفكيره في الدنيا وكل عمله لها، فيصبح بذلك أشبه بالآلة منه بالإنسان، فلذا يجب الإعراض عنه وتركه إلى أن يأذن الله فيه بشيء. ذلك الطلب للدنيا هو ما انتهى إليه علمهم، فلذا آثروها على الآخرة التي لم يعلموا عنها شيئاً. إن ربك هو أعلم بمن ضلّ عن سبيله، وهو أعلم بمن اهتدى، قضاءً وقدراً وواقعاً في الحياة الدنيا، وسيجزي كلاً بما عمل، فلا تأسَ يا رسولنا ولا تحزن، وفوّض الأمر إلينا.", "h": ["أكثر الأمراض مردّها إلى قلب لا يؤمن بالآخرة.", "أكثر الفساد في الأرض هو نتيجة الجهل وعدم العلم اليقيني.", "التحذير من الماديين، فإنهم شر وخطر، وواجب الإعراض عنهم لأنهم شر الخليقة."], "k": "«ولم يرد إلا الحياة الدنيا»… كم من همّي في يومي للدنيا، وكم للآخرة؟"}, {"lbl": "الآيتان ٣١ – ٣٢", "q": "وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ لِيَجۡزِيَ ٱلَّذِينَ أَسَـٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ بِٱلۡحُسۡنَى ﴿٣١﴾ ٱلَّذِينَ يَجۡتَنِبُونَ كَبَـٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةٞ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰٓ ﴿٣٢﴾", "w": [["ولله ما في السماوات وما في الأرض", "خلقاً وملكاً وتصرّفاً."], ["ليجزي الذين أساءوا بما عملوا", "ليعاقب الذين أساءوا بما عملوا من الشرك والمعاصي."], ["ويجزي الذين أحسنوا بالحسنى", "ويثيب الذين أحسنوا في إيمانهم وعملهم الصالح بالجنة."], ["الذين يجتنبون كبائر الإثم", "يتجنّبون كبائر الذنوب، وهي كل ذنب وُضع له حد، أو لُعن فاعله، أو تُوعّد عليه بالعذاب في الآخرة."], ["والفواحش إلا اللمم", "الذنوب القبيحة كالزنا واللواط وقذف المحصنات والبخل، واللمم صغائر الذنوب التي تُكفّر باجتناب كبائرها."], ["هو أعلم بكم إذ أنشأكم من الأرض", "خلق أباكم آدم من تراب الأرض."], ["وإذ أنتم أجنّة في بطون أمهاتكم", "وأنتم في أرحام أمهاتكم لم تولدوا بعد."], ["فلا تزكّوا أنفسكم", "فلا تمدحوها على سبيل الفخر والإعجاب."], ["هو أعلم بمن اتقى", "هو أعلم منكم بمن اتقى منكم وبمن فجر."]], "m": "ما زال السياق في تقرير ربوبيته تعالى المطلقة لكل شيء؛ إذ تقدم قوله «فلله الآخرة والأولى»، وهنا قال: ولله ما في السماوات وما في الأرض خلقاً وملكاً وتصرفاً وتدبيراً، فهو يهدي من يشاء ويضل من يشاء، هداية وإضلالاً تابعين لحكمة، يدل عليه قوله: ليجزي الذين أساءوا إلى أنفسهم بما عملوا من الشرك والمعاصي بجهنم، ويجزي الذين أحسنوا إلى أنفسهم فزكّوها وطهّروها بالإيمان والعمل الصالح بالحسنى التي هي الجنة. ثم بيّن وجه إحسان المحسنين: الذين يجتنبون كبائر الإثم، من كل ما وُعد فاعله بالنار أو بلعن أو إقامة حد أو غضب الرب، والفواحش من زنا ولواط وبخل، إلا اللمم فإنه يُتجاوز عنه، وهو ما ألمّ به المرء وتاب منه، أو فعله في الجاهلية ثم أسلم، وما كان من صغائر الذنوب كالنظرة والكلمة، وقد فُسّر بقول الرسول ﷺ: «إن الله كتب على ابن آدم حظه من الزنا، أدرك ذلك لا محالة؛ فزنا العينين النظر، وزنا اللسان المنطق، والنفس تتمنى وتشتهي، والفرج يصدّق ذلك أو يكذّبه». فمغفرة الله واسعة تشمل كل ذنب تاب منه فاعله. هو أعلم بكم إذ أنشأكم من الأرض وإذ أنتم أجنّة في بطون أمهاتكم؛ أعلم بضعفنا وغرائزنا وحاجاتنا منا بأنفسنا، ولذا تجاوز لنا عن اللمم الذي نُلمّ به بحكم العجز والضعف، فله الحمد والمنة. فلا تزكّوا أنفسكم: ينهى تعالى عباده عن تزكية المرء نفسه بادعاء الكمال والطهر، الأمر الذي يكون فخراً وإعجاباً، والإعجاب بالنفس محبط للعمل كالرياء، أي لا تشهدوا عليها بأنها زكية بريئة من الذنوب، هو أعلم بمن اتقى منكم ربه فأدّى الفرائض واجتنب المحرمات، فلا تمدحوا أنفسكم له، فإنه أعلم بكم من أنفسكم.", "h": ["تقرير ربوبية الله تعالى لكل شيء، وهي مستلزمة لألوهيته.", "تقرير حرية إرادة الله؛ يهدي من يشاء ويضل، ويعذّب من يشاء ويرحم.", "تقرير قاعدة: الجزاء من جنس العمل.", "تقرير قاعدة أن الصغائر تُكفّر باجتناب الكبائر.", "حرمة تزكية النفس، وهي مدحها والشهادة عليها بالخير والفضل والكمال والتفوق."], "k": "«فلا تزكّوا أنفسكم هو أعلم بمن اتقى»… حين أمدح نفسي أنسى ما يعلمه هو عني؛ فلأسكت وأستغفر."}, {"lbl": "الآيات ٣٣ – ٥٤", "q": "أَفَرَءَيۡتَ ٱلَّذِي تَوَلَّىٰ ﴿٣٣﴾ وَأَعۡطَىٰ قَلِيلٗا وَأَكۡدَىٰٓ ﴿٣٤﴾ أَعِندَهُۥ عِلۡمُ ٱلۡغَيۡبِ فَهُوَ يَرَىٰٓ ﴿٣٥﴾ أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِي صُحُفِ مُوسَىٰ ﴿٣٦﴾ وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ ﴿٣٧﴾ أَلَّا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰ ﴿٣٨﴾ وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ ﴿٣٩﴾ وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ ﴿٤٠﴾ ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ ﴿٤١﴾ وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ ﴿٤٢﴾ وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ ﴿٤٣﴾ وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡيَا ﴿٤٤﴾ وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ ﴿٤٥﴾ مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ ﴿٤٦﴾ وَأَنَّ عَلَيۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ ﴿٤٧﴾ وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ ﴿٤٨﴾ وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ ﴿٤٩﴾ وَأَنَّهُۥٓ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ ﴿٥٠﴾ وَثَمُودَاْ فَمَآ أَبۡقَىٰ ﴿٥١﴾ وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ ﴿٥٢﴾ وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ ﴿٥٣﴾ فَغَشَّىٰهَا مَا غَشَّىٰ ﴿٥٤﴾", "w": [["أفرأيت الذي تولّى", "عن الإسلام بعد ما قارب أن يدخل فيه."], ["وأعطى قليلاً وأكدى", "أعطى من زعم أنه يتحمّل عنه عذاب الآخرة ما وعده من المال ثم منع."], ["أعنده علم الغيب فهو يرى", "يعلم أن غيره يتحمّل عنه العذاب؟ والجواب: لا."], ["أم لم يُنبّأ بما في صحف موسى وإبراهيم الذي وفّى", "بل لم يُخبر بما ورد في الصحف، وهي التوراة وعشر صحف كانت لإبراهيم ﵇."], ["ألا تزر وازرة وزر أخرى", "لا تحمل نفس مذنبة ذنب غيرها."], ["وأن ليس للإنسان إلا ما سعى", "من خير وشر، وليس له ولا عليه من سعي غيره شيء."], ["وأن سعيه سوف يُرى", "يُبصَر يوم القيامة ويراه بنفسه."], ["ثم يُجزاه الجزاء الأوفى", "الأكمل التام الذي لا نقص فيه."], ["وأن إلى ربك المنتهى", "المرجع والمصير، إليه ينتهي أمر عباده بعد الموت."], ["وأنه هو أضحك وأبكى", "أفرح من شاء فأضحكه، وأحزن من شاء فأبكاه."], ["وأنه هو أمات وأحيا", "أمات في الدنيا وأحيا في الآخرة."], ["وأنه خلق الزوجين", "الصنفين: الذكر والأنثى."], ["من نطفة إذا تُمنى", "من منيّ إذا يُصبّ في الرحم."], ["وأن عليه النشأة الأخرى", "الخلقة الثانية للبعث والجزاء."], ["وأنه هو أغنى وأقنى", "أغنى بعض الناس بالكفاية، وأقنى بعضهم بالمال المقتنى المدّخر."], ["وأنه هو ربّ الشِّعرى", "خالقها ومالكها، وهي كوكب خلف الجوزاء عبده بعض العرب."], ["وأنه أهلك عاداً الأولى", "قوم هود ﵇."], ["وثمود فما أبقى", "أهلكها أيضاً فلم يُبقِ منهم أحداً، وهم قوم صالح."], ["وقوم نوح من قبل", "وأهلك قوم نوح من قبل عاد وثمود."], ["والمؤتفكة أهوى", "وقرى قوم لوط أسقطها بعد رفعها إلى السماء مقلوبة إلى الأرض، إذ الائتفاك الانقلاب."], ["فغشّاها ما غشّى", "من العذاب ما غشّى، حيث جعل عاليها سافلها وأمطر عليها حجارة من سجيل."]], "m": "إن هذه الآيات ترسم صورة لقرشي جاهل هو الوليد بن المغيرة؛ استمع إلى قراءة رسول الله ﷺ فهشّ لها، ودعاه الرسول فأوشك أن يسلم، فعلم به أحد المشركين فعيّره بترك دين آبائه، فاعتذر الوليد بأنه يخاف عذاب الله، فقال له ذلك المشرك، وكان فقيراً والوليد غنياً: أعطني كذا من المال وأنا أتحمّل عنك العذاب الذي تخافه، وعُد إلى دينك، فوافق الوليد وأعطاه ثم قطع عنه ما كان يعطيه. فأنزل الله فيه هذه الآيات تسلية لرسوله ﷺ وتعليماً وتحذيراً لكل من تبلغه: أفرأيت الذي تولّى عن الإسلام بعد أن قارب الدخول فيه، وأعطى قليلاً من المال للذي اتفق معه على أن يتحمل عنه العذاب، وأكدى أي قطع ومنع، كالذي يحفر بئراً فتصادفه كدية من الأرض الصلبة فيعجز وينقطع. أعنده علم الغيب فهو يرى أن المرء يمكنه أن يتحمّل عذاب غيره يوم القيامة؟ لا علم غيب عنده. أم لم يُخبر بما في صحف موسى، وهي التوراة، وإبراهيم الذي وفّى لربه في كل ما عهد به إليه من ذبح ولده وبناء البيت والهجرة والختان وغير ذلك من التكاليف الشاقة؟ ثم بيّن تعالى ما تضمنته تلك الصحف: ألّا تحمل نفس مذنبة ذنب نفس أخرى، وأن ليس للإنسان من ثواب يوم القيامة إلا ما سعى في تحصيله بنفسه، وهذا لا يتعارض مع قوله ﷺ في الصحيح: «إذا مات ابن آدم انقطع عمله إلا من ثلاث: ولد صالح يدعو له، أو صدقة جارية، أو علم ينتفع به»، إذ هذه الثلاثة من سعيه: الولد أنجبه ورباه، والصدقة أوقفها بنفسه، والعلم تعلّمه وبثّه في الناس. وأن عمله في الدنيا سوف يُرى علانية ويُجزى به الجزاء الأكمل. وأن إلى ربك المنتهى، إليه تصير أمور عباده بعد الموت فيحكم فيها. وأنه أضحك أهل الجنة وأبكى أهل النار، زيادة على من أفرح في الدنيا ومن أحزن. وأنه أمات عند نهاية الأجل وأحيا في القبر ويوم النشر، وأحيا بالإيمان وأمات بالكفر، وأمات بالقحط وأحيا بالمطر. وأنه خلق الزوجين الذكر والأنثى من سائر الحيوانات من نطفة إذا تُصبّ في الأرحام. وأن عليه النشأة الأخرى، فهو الذي يحيي الخلائق بعد موتهم. وأنه أغنى بعض الناس فسدّ حاجتهم، وأقنى آخرين فأعطاهم مالاً كثيراً. وأنه رب الشعرى، ذلك الكوكب الذي يطلع خلف الجوزاء، فالله خالقه ومسخّره، وقد عبده الجاهلون وهو مربوب. وأنه أهلك عاداً الأولى قوم هود، تلك الأمة القائلة: من أشد منا قوة، وثمود قوم صالح فما أبقى منهم أحداً، وقوم نوح من قبل، إنهم كانوا أظلم وأطغى، والمؤتفكة قرى قوم لوط رفعها إلى عنان السماء ثم أهوى بها إلى الأرض، فغشّاها من العذاب الأليم ما يعجز الوصف عنه. هذا هو الله رب العالمين الذي اتخذ الجهّال له أنداداً، العزيز المنتقم لأوليائه من أعدائه.", "h": ["تقرير ربوبية الله تعالى وإثبات ألوهيته بالبراهين والحجج التي لا تُردّ بحال.", "تقرير عدالة الله تعالى في حكمه وقضائه.", "مظاهر قدرة الله تعالى وعلمه وحكمته.", "تقرير حقيقة علمية، وهي أن العمل الذي يزكّي النفس أو يدنّسها هو ذاك الذي يباشره المرء بنفسه وباختياره وقصده ونيته.", "تحذير الظلمة والطغاة من أهل الكفر والشرك من أن يصيبهم ما أصاب غيرهم من الدمار."], "k": "«وأن ليس للإنسان إلا ما سعى»… لن يحمل عني أحد، ولن أنال إلا ما سعيت؛ فماذا أسعى اليوم؟"}, {"lbl": "الآيات ٥٥ – ٦٢", "q": "فَبِأَيِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ ﴿٥٥﴾ هَٰذَا نَذِيرٞ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰٓ ﴿٥٦﴾ أَزِفَتِ ٱلۡأٓزِفَةُ ﴿٥٧﴾ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ ﴿٥٨﴾ أَفَمِنۡ هَٰذَا ٱلۡحَدِيثِ تَعۡجَبُونَ ﴿٥٩﴾ وَتَضۡحَكُونَ وَلَا تَبۡكُونَ ﴿٦٠﴾ وَأَنتُمۡ سَٰمِدُونَ ﴿٦١﴾ فَٱسۡجُدُواْۤ لِلَّهِۤ وَٱعۡبُدُواْ۩ ﴿٦٢﴾", "w": [["فبأي آلاء ربك", "فبأي نعم ربك عليك وعلى غيرك أيها الإنسان…"], ["تتمارى", "تتشكك أو تكذّب."], ["هذا نذير من النذر الأولى", "هذا النبي محمد ﷺ رسول مثل الرسل الأولى الذين أُرسلوا إلى أقوامهم."], ["أزفت الآزفة", "قربت القيامة، ووُصفت بالقرب لقربها فعلاً."], ["ليس لها من دون الله كاشفة", "ليس للقيامة من دون الله نفس كاشفة مظهرة لوقتها، إذ لا يجلّيها لوقتها إلا الله سبحانه."], ["أفمن هذا الحديث", "أي القرآن."], ["تعجبون وتضحكون", "تعجبون تكذيباً به، وتضحكون سخرية منه."], ["وأنتم سامدون", "لاهون مشتغلون بالباطل من القول كالغناء، والعمل كعبادة الأصنام."], ["فاسجدوا لله", "الذي خلقكم ورزقكم وكلأكم، ولا تسجدوا للأصنام."], ["واعبدوا", "ذلّوا لله واخضعوا له تعظيماً ومحبة ورهبة، فإنه إلهكم الحق الذي لا إله لكم غيره."]], "m": "خاطب الله تعالى الإنسان فقال: بعد الذي عرضنا عليك في هذه السورة من مظاهر النعم والنقم، وكلها في الباطن نعم، فبأي نعم ربك تتشكك أو تكذّب، وكلها ثابتة أمامك لا تقدر على إنكارها؟ هذا نذير من النذر الأولى: يشير إلى ما في هذه السورة والقرآن كله من نذر، أو إلى النبي محمد ﷺ، وكلا الأمرين حق: القرآن نذير ومحمد نذير من النذر الأولى التي سبقته، وهم الرسل، ألا فاحذروا أيها الناس عاقبة إعراضكم. أزفت الآزفة: يخبر تعالى أن القيامة قد آن أوانها وحضرت ساعتها، إنها لقريبة جداً، ليس لها من دون الله نفس كاشفة تظهرها، بل تبقى مستورة لحكمة إلهية حتى تفاجأ بها البشرية. ثم قال توبيخاً للمشركين: أفمن هذا الحديث الإلهي، وهو القرآن، تعجبون؟ وتضحكون كأن قلوبكم أصابها الموات، ولا تبكون على أنفسكم وقد بعتموها للشيطان، وأنتم ساهون لاهون تغنّون وتلعبون. أنقذوا أنفسكم فاسجدوا لله، فإنه لا نجاة لكم من العذاب الأليم إلا بالاطّراح بين يديه إسلاماً له وخضوعاً، تعبدونه بتوحيده في عبادته، وتسلمون له قلوبكم ووجوهكم، فلا يكون لكم غير الله معبوداً تعظّمونه وتحبونه وتتقربون إليه بفعل محابّه وترك مكارهه.", "h": ["بيان قرب الساعة، وخفاء ساعتها عن كل خلق الله حتى تأتي بغتة.", "ذم الضحك مع الانغماس في الشهوات.", "الترغيب في البكاء من خشية الله.", "كراهية الغناء واللهو واللعب.", "مشروعية السجود عند تلاوة هذه الآية لمن يتلوها ولمن يستمع لها، وهي من عزائم السجدات في القرآن الكريم، ومن خصائص هذه السجدة أن المشركين سجدوها مع رسول الله ﷺ حول الكعبة كما في الصحيح."], "k": "«وتضحكون ولا تبكون»… أضحك كثيراً، فمتى بكيت آخر مرة من خشية الله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (393, 54, 1, 22, 'سورة القمر ١ – ٢٢', 'القمر: ولقد يسّرنا القرآن للذكر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 393) = $j$[{"lbl": "الآيات ١ – ٨", "q": "ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ ﴿١﴾ وَإِن يَرَوۡاْ ءَايَةٗ يُعۡرِضُواْ وَيَقُولُواْ سِحۡرٞ مُّسۡتَمِرّٞ ﴿٢﴾ وَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرٖ مُّسۡتَقِرّٞ ﴿٣﴾ وَلَقَدۡ جَآءَهُم مِّنَ ٱلۡأَنۢبَآءِ مَا فِيهِ مُزۡدَجَرٌ ﴿٤﴾ حِكۡمَةُۢ بَٰلِغَةٞۖ فَمَا تُغۡنِ ٱلنُّذُرُ ﴿٥﴾ فَتَوَلَّ عَنۡهُمۡۘ يَوۡمَ يَدۡعُ ٱلدَّاعِ إِلَىٰ شَيۡءٖ نُّكُرٍ ﴿٦﴾ خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادٞ مُّنتَشِرٞ ﴿٧﴾ مُّهۡطِعِينَ إِلَى ٱلدَّاعِۖ يَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرٞ ﴿٨﴾", "w": [["اقتربت الساعة وانشقّ القمر", "قربت القيامة، وانفلق القمر فلقتين على جبل أبي قبيس."], ["وإن يروا آية يُعرضوا", "وإن ير كفار قريش معجزة يعرضوا عنها ولا يلتفتوا إليها."], ["ويقولوا سحر مستمر", "هذا سحر قوي من المِرّة، أو دائم."], ["وكل أمر مستقر", "وكل من الخير أو الشر مستقر بأهله في الجنة أو في النار."], ["ولقد جاءهم من الأنباء", "من أنباء الأمم السالفة مما قصّه القرآن."], ["ما فيه مزدجر", "جاءهم من الأخبار ما يزجرهم عن التكذيب."], ["حكمة بالغة", "الذي جاءهم من الأنباء حكمة تامة."], ["فما تُغنِ النذر", "عن قوم كذّبوا واتبعوا أهواءهم لا تغني شيئاً."], ["فتولّ عنهم", "لذلك فأعرض عنهم."], ["يوم يدعُ الداعِ إلى شيء نُكُر", "يدعو الداعي إلى موقف القيامة."], ["مهطعين إلى الداعِ", "مسرعين إلى نداء الداعي."], ["هذا يوم عسر", "صعب شديد."]], "m": "يخبر تعالى أن ساعة نهاية الدنيا وفنائها وقيام القيامة قد اقتربت، وأن القمر قد انشق معجزة للنبي ﷺ، وبعثة النبي ﷺ علامة من علامات الساعة. وكان انشقاق القمر بمكة، حيث طالبت قريش النبي ﷺ بمعجزة تدل على نبوته، فسأل الله تعالى انشقاق القمر فانشق فلقتين على جبل أبي قبيس، فلقة فوق الجبل وفلقة وراءه، فشاهدته قريش ولم تؤمن، وهو معنى قوله: وإن يروا آية يعرضوا ويقولوا سحر قوي شديد. وكذّبوا رسولنا وما جاءهم به من التوحيد والوحي، واتبعوا في هذا التكذيب أهواءهم لا عقولهم. وكل أمر من خير أو شر مستقر بصاحبه إما في الجنة أو النار. ولقد جاءهم في القرآن من أخبار الأمم السابقة وكيف أهلكها الله بتكذيبها رسلها ما فيه زاجر عن التكذيب والمعاصي، حكمة بالغة تامة، والحكمة القول الذي يمنع صاحبه من التردّي والهلاك. فما تغني النذر عن قوم كذّبوا بالحق لما جاءهم واتبعوا أهواءهم، إذاً فتولّ عنهم يا رسولنا واتركهم إلى حكم الله فيهم. واذكر يوم يدعو الداعي إلى موقف القيامة، خاشعة أبصارهم وكل أجسامهم، وإنما ذُكرت الأبصار لأنها أدلّ على الخشوع، يخرجون من القبور كأنهم جراد منتشر في كثرتهم وتفرقهم، مسرعين إلى داعي الله إلى ساحة الموقف، يومئذ يقول الكافرون: هذا يوم عسر، وهو كذلك عليهم، ولكنه على المؤمنين يسير، كما قال تعالى: «فذلك يومئذ يوم عسير على الكافرين غير يسير».", "h": ["تقرير عقيدة البعث والجزاء.", "ذكر بعض علامات الساعة، كبعثة النبي ﷺ وانشقاق القمر معجزة له ﷺ.", "التنديد باتباع الهوى، والتحذير منه فإنه مهلك.", "عدم جدوى النذر لمن يتنكّر لعقله ويتبع هواه."], "k": "«ولقد جاءهم من الأنباء ما فيه مزدجر»… قصص الهالكين بين يديّ؛ فهل زجرتني عن شيء؟"}, {"lbl": "الآيات ٩ – ١٧", "q": "۞كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ فَكَذَّبُواْ عَبۡدَنَا وَقَالُواْ مَجۡنُونٞ وَٱزۡدُجِرَ ﴿٩﴾ فَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبٞ فَٱنتَصِرۡ ﴿١٠﴾ فَفَتَحۡنَآ أَبۡوَٰبَ ٱلسَّمَآءِ بِمَآءٖ مُّنۡهَمِرٖ ﴿١١﴾ وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونٗا فَٱلۡتَقَى ٱلۡمَآءُ عَلَىٰٓ أَمۡرٖ قَدۡ قُدِرَ ﴿١٢﴾ وَحَمَلۡنَٰهُ عَلَىٰ ذَاتِ أَلۡوَٰحٖ وَدُسُرٖ ﴿١٣﴾ تَجۡرِي بِأَعۡيُنِنَا جَزَآءٗ لِّمَن كَانَ كُفِرَ ﴿١٤﴾ وَلَقَد تَّرَكۡنَٰهَآ ءَايَةٗ فَهَلۡ مِن مُّدَّكِرٖ ﴿١٥﴾ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿١٦﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿١٧﴾", "w": [["فكذّبوا عبدنا وقالوا مجنون", "كذّبوا نوحاً عبد الله ورسوله وقالوا: هو مجنون."], ["وازدُجر", "انتهروه وزجروه بالسب والشتم."], ["فدعا ربه أني مغلوب فانتصر", "فسأل ربه قائلاً: رب إني مغلوب فانتصر لي."], ["بماء منهمر", "منصبّ انصباباً شديداً."], ["وفجّرنا الأرض عيوناً", "تنبع نبعاً."], ["فالتقى الماء", "ماء السماء وماء الأرض."], ["على أمر قد قُدر", "قُدّر في الأزل ليغرقوا به فيهلكوا."], ["وحملناه على ذات ألواح ودُسُر", "حملنا نوحاً على سفينة ذات ألواح ودسر، وهو ما تُدسر به الألواح من مسامير وغيرها."], ["تجري بأعيننا", "بمرأى منا، أي محفوظة بحفظنا لها."], ["جزاءً لمن كان كُفر", "أغرقناهم انتصاراً لمن كان كُفر، وهو نوح، كفروا نبوته وكماله."], ["ولقد تركناها آية", "تركنا إغراقنا لهم على الصورة التي تمّت عليها آية لمن يعتبر بها، حيث شاع خبرها واستمر إلى اليوم."], ["فهل من مدّكر", "معتبر ومتّعظ بها."], ["فكيف كان عذابي ونذر", "ألم يكن واقعاً موقعه؟"], ["ولقد يسّرنا القرآن للذكر", "سهّلناه للحفظ، وهيّأناه للتذكير."]], "m": "يخبر تعالى مسلّياً رسوله مخوّفاً قومه: كذّبت قبل قريش قوم نوح، وهو أول رسول أُرسل إلى قوم مشركين؛ كذّبوه في دعوة التوحيد والرسالة، ولم يكتفوا بتكذيبه فقالوا: هو مجنون، وانتهروه وزجروه ببذيء القول وسيئ الفعل، فدعا نوح ربه: إني مغلوب فانتصر لي يا ربي، فاستجاب الله له ففتح أبواب السماء بماء منصبّ انصباباً شديداً، وفجّر الأرض عيوناً نابعة، فالتقى الماء النازل من السماء والنابع من الأرض على أمر قدّره الله في الأزل وقضى بأن يهلكهم بماء الطوفان. وحملناه على سفينة ذات ألواح ودسر تجري وهي حاملة لعوالم شتى بمرأى منا محفوظة بحفظنا، وأغرقناهم انتصاراً لعبدنا نوح وجزاءً له على صبره مع طول الزمن، فقد أقام فيهم ألف سنة إلا خمسين عاماً. ولقد تركنا تلك الفعلة آية للاعتبار لمن يعتبر بها، حيث شاع خبرها واستمر إلى اليوم، فهل من معتبر متّعظ؟ فكيف كان عذابي وإنذاري؟ ألم يكن واقعاً موقعه؟ بلى. ولقد سهّلنا القرآن للحفظ وهيّأناه للتذكر، فهل من متّعظ به حافظ له؟ والاستفهام للأمر، أي فاتّعظوا به واحفظوه.", "h": ["تسلية الرسول ﷺ.", "تحذير قريش من الاستمرار في الكفر والمعاندة.", "تقرير حادثة الطوفان التي لا ينكرها إلا سفيه لم يحترم عقله.", "فضل الله على هذه الأمة بتسهيل القرآن للحفظ والتذكر."], "k": "«ولقد يسّرنا القرآن للذكر فهل من مدّكر»… سهّله لي، فكم آية حفظت هذا الشهر؟"}, {"lbl": "الآيات ١٨ – ٢٢", "q": "كَذَّبَتۡ عَادٞ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿١٨﴾ إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِي يَوۡمِ نَحۡسٖ مُّسۡتَمِرّٖ ﴿١٩﴾ تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٖ مُّنقَعِرٖ ﴿٢٠﴾ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿٢١﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿٢٢﴾", "w": [["كذّبت عاد", "كذّبت نبيها هوداً ﵇ فلم تؤمن به ولا بما جاء به."], ["فكيف كان عذابي ونذر", "كيف كان عذابي الذي أنزلته بهم، وإنذاري لهم؟ كان أشد ما يكون."], ["إنا أرسلنا عليهم ريحاً صرصراً", "ريحاً عاتية ذات صوت شديد."], ["في يوم نحس مستمر", "في يوم شؤم مستمر دائم الشؤم."], ["تنزع الناس", "تقتلعهم من الحفر التي اندسّوا فيها وتصرعهم فتدقّ رقابهم."], ["كأنهم أعجاز نخل منقعر", "منفصلة أجسامهم كأنهم أصول نخل منقلع ساقط على الأرض."], ["ولقد يسّرنا القرآن للذكر", "سهّلنا القرآن للحفظ والتذكير والتذكر به."], ["فهل من مدّكر", "تذكّروا يا عباد الله بالقرآن، فإن منزله سهّله للتذكير."]], "m": "هذا القصص الثاني في هذه السورة يذكر بإيجاز تسلية لرسول الله ﷺ وتهديداً لقومه المكذبين وذكرى للمؤمنين: كذّبت عاد قوم هود رسول الله هوداً ﵇، وكفروا بما جاءهم به من التوحيد والشرع، وقالوا: ائتنا بما تعدنا إن كنت من الصادقين، فأرسل تعالى عليهم ريحاً صرصراً ذات صوت شديد في يوم نحس مستمر بشدته وشؤمه عليهم مدة سبع ليال وثمانية أيام، تنزع تلك الريح الناس وقد دخلوا حفراً تحصّنوا بها، فتنزعهم منها وتصرعهم فتدقّ رقابهم فتنفصل عن أجسادهم، فيصيرون لطول أجسامهم كأنهم أعجاز نخل منقلع ساقط على الأرض. فكيف كان عذابي ونذر؟ الاستفهام للتهويل، أي كان كأشد ما يكون العذاب والإنذار. ولقد سهّلنا القرآن وهيّأناه بفضل منا ورحمة للحفظ، ولولا هذا التسهيل ما حفظه أحد، وهيّأناه للتذكر به، فهل من متذكر؟ والاستفهام للأمر، كأنما قال: فاحفظوه وتذكّروا به.", "h": ["بيان عقوبة المكذبين لرسل الله، وما نزل بهم من العذاب في الدنيا قبل الآخرة.", "بيان أن قوة الإنسان مهما كانت هي أمام قوة الله تعالى لا شيء، ولا تردّ عذاب الله بحال.", "بيان تسهيل الله تعالى كتابه للناس ليحفظوه ويتذكروا به ويعملوا بما جاء فيه ليكملوا ويسعدوا."], "k": "«ولولا هذا التسهيل ما حفظه أحد»… فما عذري إن لم أحفظ منه شيئاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 393;
insert into public.tdb_cards(topic, i, body) select 393, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٨", "q": "ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ ﴿١﴾ وَإِن يَرَوۡاْ ءَايَةٗ يُعۡرِضُواْ وَيَقُولُواْ سِحۡرٞ مُّسۡتَمِرّٞ ﴿٢﴾ وَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرٖ مُّسۡتَقِرّٞ ﴿٣﴾ وَلَقَدۡ جَآءَهُم مِّنَ ٱلۡأَنۢبَآءِ مَا فِيهِ مُزۡدَجَرٌ ﴿٤﴾ حِكۡمَةُۢ بَٰلِغَةٞۖ فَمَا تُغۡنِ ٱلنُّذُرُ ﴿٥﴾ فَتَوَلَّ عَنۡهُمۡۘ يَوۡمَ يَدۡعُ ٱلدَّاعِ إِلَىٰ شَيۡءٖ نُّكُرٍ ﴿٦﴾ خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادٞ مُّنتَشِرٞ ﴿٧﴾ مُّهۡطِعِينَ إِلَى ٱلدَّاعِۖ يَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرٞ ﴿٨﴾", "w": [["اقتربت الساعة وانشقّ القمر", "قربت القيامة، وانفلق القمر فلقتين على جبل أبي قبيس."], ["وإن يروا آية يُعرضوا", "وإن ير كفار قريش معجزة يعرضوا عنها ولا يلتفتوا إليها."], ["ويقولوا سحر مستمر", "هذا سحر قوي من المِرّة، أو دائم."], ["وكل أمر مستقر", "وكل من الخير أو الشر مستقر بأهله في الجنة أو في النار."], ["ولقد جاءهم من الأنباء", "من أنباء الأمم السالفة مما قصّه القرآن."], ["ما فيه مزدجر", "جاءهم من الأخبار ما يزجرهم عن التكذيب."], ["حكمة بالغة", "الذي جاءهم من الأنباء حكمة تامة."], ["فما تُغنِ النذر", "عن قوم كذّبوا واتبعوا أهواءهم لا تغني شيئاً."], ["فتولّ عنهم", "لذلك فأعرض عنهم."], ["يوم يدعُ الداعِ إلى شيء نُكُر", "يدعو الداعي إلى موقف القيامة."], ["مهطعين إلى الداعِ", "مسرعين إلى نداء الداعي."], ["هذا يوم عسر", "صعب شديد."]], "m": "يخبر تعالى أن ساعة نهاية الدنيا وفنائها وقيام القيامة قد اقتربت، وأن القمر قد انشق معجزة للنبي ﷺ، وبعثة النبي ﷺ علامة من علامات الساعة. وكان انشقاق القمر بمكة، حيث طالبت قريش النبي ﷺ بمعجزة تدل على نبوته، فسأل الله تعالى انشقاق القمر فانشق فلقتين على جبل أبي قبيس، فلقة فوق الجبل وفلقة وراءه، فشاهدته قريش ولم تؤمن، وهو معنى قوله: وإن يروا آية يعرضوا ويقولوا سحر قوي شديد. وكذّبوا رسولنا وما جاءهم به من التوحيد والوحي، واتبعوا في هذا التكذيب أهواءهم لا عقولهم. وكل أمر من خير أو شر مستقر بصاحبه إما في الجنة أو النار. ولقد جاءهم في القرآن من أخبار الأمم السابقة وكيف أهلكها الله بتكذيبها رسلها ما فيه زاجر عن التكذيب والمعاصي، حكمة بالغة تامة، والحكمة القول الذي يمنع صاحبه من التردّي والهلاك. فما تغني النذر عن قوم كذّبوا بالحق لما جاءهم واتبعوا أهواءهم، إذاً فتولّ عنهم يا رسولنا واتركهم إلى حكم الله فيهم. واذكر يوم يدعو الداعي إلى موقف القيامة، خاشعة أبصارهم وكل أجسامهم، وإنما ذُكرت الأبصار لأنها أدلّ على الخشوع، يخرجون من القبور كأنهم جراد منتشر في كثرتهم وتفرقهم، مسرعين إلى داعي الله إلى ساحة الموقف، يومئذ يقول الكافرون: هذا يوم عسر، وهو كذلك عليهم، ولكنه على المؤمنين يسير، كما قال تعالى: «فذلك يومئذ يوم عسير على الكافرين غير يسير».", "h": ["تقرير عقيدة البعث والجزاء.", "ذكر بعض علامات الساعة، كبعثة النبي ﷺ وانشقاق القمر معجزة له ﷺ.", "التنديد باتباع الهوى، والتحذير منه فإنه مهلك.", "عدم جدوى النذر لمن يتنكّر لعقله ويتبع هواه."], "k": "«ولقد جاءهم من الأنباء ما فيه مزدجر»… قصص الهالكين بين يديّ؛ فهل زجرتني عن شيء؟"}, {"lbl": "الآيات ٩ – ١٧", "q": "۞كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ فَكَذَّبُواْ عَبۡدَنَا وَقَالُواْ مَجۡنُونٞ وَٱزۡدُجِرَ ﴿٩﴾ فَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبٞ فَٱنتَصِرۡ ﴿١٠﴾ فَفَتَحۡنَآ أَبۡوَٰبَ ٱلسَّمَآءِ بِمَآءٖ مُّنۡهَمِرٖ ﴿١١﴾ وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونٗا فَٱلۡتَقَى ٱلۡمَآءُ عَلَىٰٓ أَمۡرٖ قَدۡ قُدِرَ ﴿١٢﴾ وَحَمَلۡنَٰهُ عَلَىٰ ذَاتِ أَلۡوَٰحٖ وَدُسُرٖ ﴿١٣﴾ تَجۡرِي بِأَعۡيُنِنَا جَزَآءٗ لِّمَن كَانَ كُفِرَ ﴿١٤﴾ وَلَقَد تَّرَكۡنَٰهَآ ءَايَةٗ فَهَلۡ مِن مُّدَّكِرٖ ﴿١٥﴾ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿١٦﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿١٧﴾", "w": [["فكذّبوا عبدنا وقالوا مجنون", "كذّبوا نوحاً عبد الله ورسوله وقالوا: هو مجنون."], ["وازدُجر", "انتهروه وزجروه بالسب والشتم."], ["فدعا ربه أني مغلوب فانتصر", "فسأل ربه قائلاً: رب إني مغلوب فانتصر لي."], ["بماء منهمر", "منصبّ انصباباً شديداً."], ["وفجّرنا الأرض عيوناً", "تنبع نبعاً."], ["فالتقى الماء", "ماء السماء وماء الأرض."], ["على أمر قد قُدر", "قُدّر في الأزل ليغرقوا به فيهلكوا."], ["وحملناه على ذات ألواح ودُسُر", "حملنا نوحاً على سفينة ذات ألواح ودسر، وهو ما تُدسر به الألواح من مسامير وغيرها."], ["تجري بأعيننا", "بمرأى منا، أي محفوظة بحفظنا لها."], ["جزاءً لمن كان كُفر", "أغرقناهم انتصاراً لمن كان كُفر، وهو نوح، كفروا نبوته وكماله."], ["ولقد تركناها آية", "تركنا إغراقنا لهم على الصورة التي تمّت عليها آية لمن يعتبر بها، حيث شاع خبرها واستمر إلى اليوم."], ["فهل من مدّكر", "معتبر ومتّعظ بها."], ["فكيف كان عذابي ونذر", "ألم يكن واقعاً موقعه؟"], ["ولقد يسّرنا القرآن للذكر", "سهّلناه للحفظ، وهيّأناه للتذكير."]], "m": "يخبر تعالى مسلّياً رسوله مخوّفاً قومه: كذّبت قبل قريش قوم نوح، وهو أول رسول أُرسل إلى قوم مشركين؛ كذّبوه في دعوة التوحيد والرسالة، ولم يكتفوا بتكذيبه فقالوا: هو مجنون، وانتهروه وزجروه ببذيء القول وسيئ الفعل، فدعا نوح ربه: إني مغلوب فانتصر لي يا ربي، فاستجاب الله له ففتح أبواب السماء بماء منصبّ انصباباً شديداً، وفجّر الأرض عيوناً نابعة، فالتقى الماء النازل من السماء والنابع من الأرض على أمر قدّره الله في الأزل وقضى بأن يهلكهم بماء الطوفان. وحملناه على سفينة ذات ألواح ودسر تجري وهي حاملة لعوالم شتى بمرأى منا محفوظة بحفظنا، وأغرقناهم انتصاراً لعبدنا نوح وجزاءً له على صبره مع طول الزمن، فقد أقام فيهم ألف سنة إلا خمسين عاماً. ولقد تركنا تلك الفعلة آية للاعتبار لمن يعتبر بها، حيث شاع خبرها واستمر إلى اليوم، فهل من معتبر متّعظ؟ فكيف كان عذابي وإنذاري؟ ألم يكن واقعاً موقعه؟ بلى. ولقد سهّلنا القرآن للحفظ وهيّأناه للتذكر، فهل من متّعظ به حافظ له؟ والاستفهام للأمر، أي فاتّعظوا به واحفظوه.", "h": ["تسلية الرسول ﷺ.", "تحذير قريش من الاستمرار في الكفر والمعاندة.", "تقرير حادثة الطوفان التي لا ينكرها إلا سفيه لم يحترم عقله.", "فضل الله على هذه الأمة بتسهيل القرآن للحفظ والتذكر."], "k": "«ولقد يسّرنا القرآن للذكر فهل من مدّكر»… سهّله لي، فكم آية حفظت هذا الشهر؟"}, {"lbl": "الآيات ١٨ – ٢٢", "q": "كَذَّبَتۡ عَادٞ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿١٨﴾ إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِي يَوۡمِ نَحۡسٖ مُّسۡتَمِرّٖ ﴿١٩﴾ تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٖ مُّنقَعِرٖ ﴿٢٠﴾ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿٢١﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿٢٢﴾", "w": [["كذّبت عاد", "كذّبت نبيها هوداً ﵇ فلم تؤمن به ولا بما جاء به."], ["فكيف كان عذابي ونذر", "كيف كان عذابي الذي أنزلته بهم، وإنذاري لهم؟ كان أشد ما يكون."], ["إنا أرسلنا عليهم ريحاً صرصراً", "ريحاً عاتية ذات صوت شديد."], ["في يوم نحس مستمر", "في يوم شؤم مستمر دائم الشؤم."], ["تنزع الناس", "تقتلعهم من الحفر التي اندسّوا فيها وتصرعهم فتدقّ رقابهم."], ["كأنهم أعجاز نخل منقعر", "منفصلة أجسامهم كأنهم أصول نخل منقلع ساقط على الأرض."], ["ولقد يسّرنا القرآن للذكر", "سهّلنا القرآن للحفظ والتذكير والتذكر به."], ["فهل من مدّكر", "تذكّروا يا عباد الله بالقرآن، فإن منزله سهّله للتذكير."]], "m": "هذا القصص الثاني في هذه السورة يذكر بإيجاز تسلية لرسول الله ﷺ وتهديداً لقومه المكذبين وذكرى للمؤمنين: كذّبت عاد قوم هود رسول الله هوداً ﵇، وكفروا بما جاءهم به من التوحيد والشرع، وقالوا: ائتنا بما تعدنا إن كنت من الصادقين، فأرسل تعالى عليهم ريحاً صرصراً ذات صوت شديد في يوم نحس مستمر بشدته وشؤمه عليهم مدة سبع ليال وثمانية أيام، تنزع تلك الريح الناس وقد دخلوا حفراً تحصّنوا بها، فتنزعهم منها وتصرعهم فتدقّ رقابهم فتنفصل عن أجسادهم، فيصيرون لطول أجسامهم كأنهم أعجاز نخل منقلع ساقط على الأرض. فكيف كان عذابي ونذر؟ الاستفهام للتهويل، أي كان كأشد ما يكون العذاب والإنذار. ولقد سهّلنا القرآن وهيّأناه بفضل منا ورحمة للحفظ، ولولا هذا التسهيل ما حفظه أحد، وهيّأناه للتذكر به، فهل من متذكر؟ والاستفهام للأمر، كأنما قال: فاحفظوه وتذكّروا به.", "h": ["بيان عقوبة المكذبين لرسل الله، وما نزل بهم من العذاب في الدنيا قبل الآخرة.", "بيان أن قوة الإنسان مهما كانت هي أمام قوة الله تعالى لا شيء، ولا تردّ عذاب الله بحال.", "بيان تسهيل الله تعالى كتابه للناس ليحفظوه ويتذكروا به ويعملوا بما جاء فيه ليكملوا ويسعدوا."], "k": "«ولولا هذا التسهيل ما حفظه أحد»… فما عذري إن لم أحفظ منه شيئاً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (394, 54, 23, 55, 'سورة القمر ٢٣ – ٥٥', 'القمر: إنا كل شيء خلقناه بقدر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 394) = $j$[{"lbl": "الآيات ٢٣ – ٣٢", "q": "كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ ﴿٢٣﴾ فَقَالُوٓاْ أَبَشَرٗا مِّنَّا وَٰحِدٗا نَّتَّبِعُهُۥٓ إِنَّآ إِذٗا لَّفِي ضَلَٰلٖ وَسُعُرٍ ﴿٢٤﴾ أَءُلۡقِيَ ٱلذِّكۡرُ عَلَيۡهِ مِنۢ بَيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرٞ ﴿٢٥﴾ سَيَعۡلَمُونَ غَدٗا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ ﴿٢٦﴾ إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةٗ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ ﴿٢٧﴾ وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبٖ مُّحۡتَضَرٞ ﴿٢٨﴾ فَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ ﴿٢٩﴾ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿٣٠﴾ إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ صَيۡحَةٗ وَٰحِدَةٗ فَكَانُواْ كَهَشِيمِ ٱلۡمُحۡتَظِرِ ﴿٣١﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿٣٢﴾", "w": [["كذّبت ثمود بالنذر", "بالرسل، لأن النذر جمع نذير، وهو الرسول هنا."], ["فقالوا أبشراً منا واحداً نتّبعه", "كيف نتّبع بشراً واحداً منا؟ إنكاراً منهم للإيمان بصالح."], ["إنا إذاً لفي ضلال وسُعُر", "إنا إذا اتبعناه فيما جاء به لفي ذهاب عن الصواب وجنون."], ["أأُلقي الذكر عليه من بيننا", "لم يوحَ إليه من بيننا أبداً، وإنما هو كذّاب أشر."], ["بل هو كذّاب أشر", "كذّاب فيما ادّعى أنه أُلقي إليه من الوحي، أشر متكبر."], ["سيعلمون غداً", "في الآخرة."], ["من الكذاب الأشر", "وهم المعذَّبون يوم القيامة بكفرهم وتكذيبهم."], ["إنا مرسلو الناقة فتنة لهم", "مخرجو الناقة من الصخر ومرسلوها لهم محنة."], ["فارتقبهم واصطبر", "انتظر وراقب ماذا يصنعون وما يُصنع بهم، واصبر على أذاهم."], ["ونبّئهم أن الماء قسمة بينهم", "ماء بئرهم مقسوم بينهم وبين الناقة، فيوم لها ويوم لهم."], ["كل شرب محتضر", "كل نصيب من الماء يحضره أصحابه المختصون به."], ["فنادوا صاحبهم فتعاطى فعقر", "ملّوا ذلك فنادوا صاحبهم قُدار بن سالف ليقتلها، فتناول السيف فعقر الناقة."], ["إنا أرسلنا عليهم صيحة واحدة", "هي صيحة جبريل فهلكوا."], ["فكانوا كهشيم المحتظر", "صاروا بعد هلاكهم وتمزّق أجسادهم كالعشب اليابس والعيدان الرقيقة التي يجعلها الرجل في حظيرة غنمه."]], "m": "هذا القصص الموجز الثالث، قصص ثمود قوم صالح: كذّبت ثمود بالنذر التي أنذرها نبيها صالح، وهي ألوان العذاب، كما كذّبته فيما جاء به من الرسالة، فقالوا: أبشراً منا واحداً نتّبعه؟ كيف يتم ذلك منا؟ إنا إذاً لفي ضلال وسعر، أي إنا إذا اتبعناه وهو واحد منا لا غير لفي بعد عن الصواب وذهاب عن كل رشد، وفي جنون أيضاً. وقالوا متعجبين: أأُلقي الذكر عليه من بيننا؟ بل هو كذّاب متكبّر. قال تعالى رداً عليهم: سيعلمون غداً، يوم ينزل بهم العذاب ويوم القيامة، من الكذاب الأشر: أصالح أم هم؟ لن يكونوا إلا هم. إنا مرسلو الناقة فتنة لهم كما طلبوا، إذ قالوا لصالح: إن كنت رسول الله حقاً فسله يخرج لنا من هذه الصخرة ناقة، فقام يصلي ويدعو حتى تمخّض الجبل وخرجت منه ناقة عُشراء آية في القوة والجمال، وقال لهم: هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسّوها بسوء. فارتقبهم وراقبهم من بُعد واصطبر على أذاهم، وأخبرهم بأمرنا أن الماء الذي يشربون منه مقسوم بينهم: للناقة يوم وللقبيلة يوم، كل نصيب يحضره صاحبه دون غيره. وطالت المدة فملّوا، فنادوا صاحبهم قُدار بن سالف عاقر الناقة، فتناول السيف وعقرها بضرب رجليها ثم ذبحها. فكيف كان عذابي وإنذاري؟ أما العذاب فقد كان أليماً، وأما الإنذار فقد كان صادقاً: إنا أرسلنا عليهم صيحة واحدة، هي صيحة جبريل ﵇، فانخلعت لها قلوبهم فأصبحوا في ديارهم جاثمين ممزّقين محطّمين كحطب الحظائر التي تُجعل للأغنام. ولقد يسّرنا القرآن للذكر فهل من مدّكر: يدعو الله تعالى هذه الأمة إلى كتابه قراءةً وحفظاً وتذكراً، فإنه مصدر كمالهم وسعادتهم، لا سيما وقد سهّله وهيّأه لذلك.", "h": ["بيان سنة الله في إهلاك المكذبين.", "بيان أن الآيات لا تستلزم الإيمان، وإلا فآية صالح من أعظم الآيات ولم يؤمن بها قوم ثمود.", "أشقى أمة الإسلام عقبة بن أبي مُعيط الذي وضع سلى الجزور على ظهر الرسول ﷺ وهو يصلي حول الكعبة، وعاقر ناقة صالح قُدار بن سالف، كما جاء في الحديث.", "دعوة الله إلى حفظ القرآن والتذكير به، فإنه مصدر الإلهام والكمال والإسعاد."], "k": "«إنا مرسلو الناقة فتنة لهم»… قد تكون النعمة التي بين يديّ هي اختباري؛ فكيف أعاملها؟"}, {"lbl": "الآيات ٣٣ – ٤٢", "q": "كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ ﴿٣٣﴾ إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ حَاصِبًا إِلَّآ ءَالَ لُوطٖۖ نَّجَّيۡنَٰهُم بِسَحَرٖ ﴿٣٤﴾ نِّعۡمَةٗ مِّنۡ عِندِنَاۚ كَذَٰلِكَ نَجۡزِي مَن شَكَرَ ﴿٣٥﴾ وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡاْ بِٱلنُّذُرِ ﴿٣٦﴾ وَلَقَدۡ رَٰوَدُوهُ عَن ضَيۡفِهِۦ فَطَمَسۡنَآ أَعۡيُنَهُمۡ فَذُوقُواْ عَذَابِي وَنُذُرِ ﴿٣٧﴾ وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابٞ مُّسۡتَقِرّٞ ﴿٣٨﴾ فَذُوقُواْ عَذَابِي وَنُذُرِ ﴿٣٩﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿٤٠﴾ وَلَقَدۡ جَآءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ ﴿٤١﴾ كَذَّبُواْ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذۡنَٰهُمۡ أَخۡذَ عَزِيزٖ مُّقۡتَدِرٍ ﴿٤٢﴾", "w": [["كذّبت قوم لوط بالنذر", "كذّبت قوم لوط بالنذر التي أنذرهم بها لوط وخوّفهم منها."], ["إنا أرسلنا عليهم حاصباً", "ريحاً ترميهم بالحصباء، وهي الحجارة الصغيرة."], ["إلا آل لوط نجّيناهم بسحر", "لوطاً وبنتيه، نجّاهم الله من العذاب حيث غادروا البلاد قبل نزول العذاب بها."], ["نعمة من عندنا", "إنعاماً منا عليهم ورحمة منا بهم."], ["كذلك نجزي من شكر", "مثل هذا الجزاء بالنجاة من الهلاك نجزي من شكرنا بالإيمان والطاعة."], ["ولقد أنذرهم بطشتنا", "أنذرهم لوط، أي خوّفهم أخذتنا إياهم بالعذاب."], ["فتماروا بالنذر", "فتجادلوا وكذّبوا بالنذر التي أنذرهم بها."], ["ولقد راودوه عن ضيفه", "أن يخلّي بينهم وبين ضيفه، وهم ملائكة، ليخبثوا بهم."], ["فطمسنا أعينهم", "ضربهم جبريل بجناحه فطمس أعينهم فكانت كباقي الوجه."], ["ولقد صبّحهم بكرة عذاب مستقر", "نزل بهم بكرة صباحاً عذاب مستقر لا يفارقهم أبداً: هلكوا به في الدنيا، ويصحبهم في البرزخ، ويلازمهم في جهنم."], ["ولقد يسّرنا القرآن للذكر", "سهّلناه للحفظ والتذكر به والعمل بما فيه."], ["فهل من مدّكر", "من متذكّر فيعمل بما فيه فينجو من النار ويسعد في الجنة."], ["ولقد جاء آل فرعون النذر", "جاءت قوم فرعون الإنذارات على لسان موسى وهارون ﵉."], ["كذّبوا بآياتنا كلها", "فلم يؤمنوا بل كذّبوا بآياتنا التسع التي آتيناها موسى."], ["فأخذناهم أخذ عزيز مقتدر", "أخذناهم بالعذاب، وهو الغرق، أخذ قوي مقتدر على كل شيء لا يعجزه شيء."]], "m": "ما زال السياق في ذكر موجز لقصص عدد من الأمم السابقة تسلية لرسول الله ﷺ، وإنذاراً لأهل الشرك والمعاصي في كل زمان ومكان: كذّبت قوم لوط، وهم أهل قرى سدوم وعمورة، رسولهم لوطاً ابن أخي إبراهيم ﵇، كذّبوا بالنذر التي أنذرهم بها وخوّفهم من عواقبها. فلما أصرّوا على الكفر وإتيان الفاحشة أرسلنا عليهم ريحاً تحمل الحصباء فأهلكناهم بعد قلب البلاد بجعل عاليها سافلها، إلا آل لوط ومن آمن معه من ابنتيه وغيرهما، نجّاهم الله بسحر، وهو آخر الليل، إنعاماً منا عليهم ورحمة بهم، وكهذا الإنجاء من العذاب نجزي من شكرنا فآمن بنا وعمل صالحاً. ولقد أنذرهم بطشتنا، فلم نأخذهم بظلم منا ولا بدون سابق إنذار، بل أخذناهم بظلمهم وبعد تكرّر إنذارهم، فكانوا إذا أُنذروا جادلوا فيه مستهزئين مكذّبين. ومن أعظم ظلمهم أنهم راودوا لوطاً عن ضيفه من الملائكة وهم في صورة بشر، فضربهم جبريل بجناحه فطمس أعينهم فأصبحت كسائر وجوههم لا مقلة ولا مكان للعين، وقلنا لهم: فذوقوا عذابي ونذر. أما باقي الأمة فقد صبّحهم عذاب دائم ملازم لا يفارقهم: ذاقوه في الدنيا موتاً، ويصحبهم برزخاً، ويلازمهم في جهنم. ولقد سهّلنا القرآن للحفظ والفهم والاتعاظ، فهل من متذكّر فيقبل على طاعة الله متجنّباً معاصيه فينجو ويسعد؟ ولقد جاء قوم فرعون من القبط النذر على لسان موسى وأخيه هارون، فكذّبوا بآيات الله كلها، وهي تسع آيات أولها العصا وآخرها انفلاق البحر، فأخذناهم أخذ عزيز غالب لا يُمانع في مراده، مقتدر لا يعجزه شيء، فأغرقناهم أجمعين.", "h": ["تقرير ربوبية الله تعالى وألوهيته، وتقرير التوحيد وإثبات النبوة لمحمد ﷺ؛ إذ أفعال الله العظيمة من إرسال الرسل وأخذ الظلمة الكافرين بأشد أنواع العقوبات دالّة على ربوبيته وألوهيته، وقصّ هذا القصص من أمّي لم يقرأ ولم يكتب دالّ على نبوة محمد ﷺ.", "بيان جزاء الشاكرين لله تعالى بالإيمان به وطاعته وطاعة رسله.", "مشروعية الضيافة وإكرام الضيف.", "تيسير القرآن وتسهيله للحفظ والاتعاظ والاعتبار."], "k": "«كذلك نجزي من شكر»… النجاة جزاء الشكر؛ فهل أشكر بلساني فقط أم بطاعتي؟"}, {"lbl": "الآيات ٤٣ – ٤٦", "q": "أَكُفَّارُكُمۡ خَيۡرٞ مِّنۡ أُوْلَـٰٓئِكُمۡ أَمۡ لَكُم بَرَآءَةٞ فِي ٱلزُّبُرِ ﴿٤٣﴾ أَمۡ يَقُولُونَ نَحۡنُ جَمِيعٞ مُّنتَصِرٞ ﴿٤٤﴾ سَيُهۡزَمُ ٱلۡجَمۡعُ وَيُوَلُّونَ ٱلدُّبُرَ ﴿٤٥﴾ بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ ﴿٤٦﴾", "w": [["أكفّاركم خير من أولئكم", "أكفّاركم يا قريش خير من أولئكم الكفار المذكورين من قوم نوح وعاد وثمود وقوم لوط وفرعون وملئه، فلذا هم آمنون؟"], ["أم لكم براءة في الزبر", "أم لكم يا كفار قريش براءة من العذاب في الكتب الإلهية؟"], ["أم يقولون نحن جميع منتصر", "أم يقول كفار قريش: نحن جمع منتصر على محمد وأصحابه؟"], ["سيُهزم الجمع ويولّون الدبر", "سيُهزم جمعهم ويولّون الدبر هاربين منهزمين."], ["بل الساعة موعدهم", "الساعة موعدهم بالعذاب، والمراد بالساعة يوم القيامة."], ["والساعة أدهى وأمرّ", "وعذاب الساعة وأهوالها أعظم بلية، وأشد مرارة من عذاب الدنيا قطعاً."]], "m": "يقول تعالى مبكّتاً مشركي قريش، وهم الذين إن يروا آية يعرضوا ويقولوا سحر مستمر: أكفّاركم يا قريش خير من كفار الأمم السابقة كعاد وثمود وقوم لوط وآل فرعون، فلذا هم آمنون من العذاب الذي نزل بأولئك، أم لكم براءة من العذاب جاءت في الكتب مسطورة؟ لا هذا ولا ذاك؛ ما كفّاركم بخير من أولئكم، وليس لكم براءة في الزبر، وإنما أنتم مُمهَلون، فإما أن تتوبوا وإما أن تؤخذوا. أم يقولون: نحن جمع منتصر على كل من يحاربنا ويريد أن يفرّق جمعنا؟ نعم قالوا هذا، ولكن سيُهزم الجمع ويولّون الدبر، وقد تم هذا في بدر بعد سنيّات ثلاث أو أربع، فهُزم جمعهم وولّوا الأدبار هاربين إلى مكة. بل الساعة التي ينكرونها ويكذّبون بها هي موعد عذابهم الحق، أما عذاب الدنيا فليس بشيء إذا قيس بعذاب الآخرة، والساعة أعظم بلية وأكبر داهية تصيب الإنسان، وعذابها أمرّ من عذاب الدنيا كله.", "h": ["بيان حقيقة يغفل عنها الناس، وهي أن الكفر كله واحد ومورد للهلاك.", "لا قيمة أبداً لقوة الإنسان إزاء قوة الله تعالى.", "صدق القرآن في إخباره بغيب لمّا يقع، ووقع كما أخبر، وهو آية أنه وحي الله وكلامه.", "القيامة موعد لقاء البشرية كافة، بحيث لا يتخلّف عنه أحد."], "k": "«أم لكم براءة في الزبر»… ليس عندي صك أمان؛ فلماذا أطمئن وأنا مقصّر؟"}, {"lbl": "الآيات ٤٧ – ٥٥", "q": "إِنَّ ٱلۡمُجۡرِمِينَ فِي ضَلَٰلٖ وَسُعُرٖ ﴿٤٧﴾ يَوۡمَ يُسۡحَبُونَ فِي ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُواْ مَسَّ سَقَرَ ﴿٤٨﴾ إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرٖ ﴿٤٩﴾ وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةٞ كَلَمۡحِۭ بِٱلۡبَصَرِ ﴿٥٠﴾ وَلَقَدۡ أَهۡلَكۡنَآ أَشۡيَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرٖ ﴿٥١﴾ وَكُلُّ شَيۡءٖ فَعَلُوهُ فِي ٱلزُّبُرِ ﴿٥٢﴾ وَكُلُّ صَغِيرٖ وَكَبِيرٖ مُّسۡتَطَرٌ ﴿٥٣﴾ إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَنَهَرٖ ﴿٥٤﴾ فِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكٖ مُّقۡتَدِرِۭ ﴿٥٥﴾", "w": [["إن المجرمين في ضلال وسُعُر", "الذين أجرموا على أنفسهم بالشرك والمعاصي في ضلال في الدنيا، ونار مستعرة في الآخرة."], ["ذوقوا مسّ سقر", "يوم يُسحبون في النار على وجوههم يقال لهم: ذوقوا مسّ سقر."], ["إنا كل شيء خلقناه بقدر", "خلقنا كل شيء بتقدير سابق لخلقنا له، وذلك بكتابته في اللوح المحفوظ قبل خلق السماوات والأرض، فهو يقع كما كُتب كمية وصورة وزماناً ومكاناً لا يتخلف في شيء."], ["وما أمرنا إلا واحدة", "وما أمرنا إذا أردنا خلق شيء إلا أمرة واحدة فيتم الشيء."], ["كلمح بالبصر", "بسرعة كلمح البصر، وهو النظر بعجلة."], ["ولقد أهلكنا أشياعكم", "أهلكنا أمثالكم أيها المشركون من الأمم السابقة."], ["فهل من مدّكر", "فاذكروا واتّعظوا، خيراً لكم من هذا الإعراض."], ["وكل شيء فعلوه في الزبر", "وكل ما فعله العباد مسجّل في كتب الحفظة من الملائكة."], ["وكل صغير وكبير مستطر", "وكل صغير وكبير من سائر الأعمال والأحداث مكتوب في اللوح المحفوظ."], ["إن المتقين في جنات ونهر", "إن الذين اتقوا ربهم فلم يشركوا به ولم يفسقوا عن أمره في جنات يشربون من أنهار الماء واللبن والخمر والعسل."], ["في مقعد صدق", "في مجلس حق لا لغو فيه ولا تأثيم."], ["عند مليك مقتدر", "عند مليك ذي ملك وسلطان، مقتدر على ما يشاء، وهو الله جل جلاله."]], "m": "يخبر تعالى تحذيراً وإنذاراً عن حال المجرمين الذين أجرموا على أنفسهم فأفسدوها بالشرك وغشيان الذنوب، بأنهم في ضلال في حياتهم الدنيا، وفي نار مستعرة متأجّجة يوم القيامة، يوم يُسحبون في النار على وجوههم، يقال لهم تهكّماً بهم: ذوقوا مسّ سقر، وسقر طبق من أطباق جهنم وباب من أبوابها. إنا كل شيء خلقناه بقدر: إعلام منه تعالى عن نظام الكون الذي خلقه، وهو أن كل حادث يحدث في هذا العالم قد سبق به علم الله وتقديره له، فحدّد ذاته وصفاته وأعماله ومآله إلى جنة أو إلى نار إن كان إنساناً أو جاناً، وليس هناك شيء يحدث بدون تقدير سابق له وعلم تام به قبل حدوثه. وما أمرنا إلا واحدة كلمح بالبصر: يخبر تعالى عن قدرته كما أخبر عن علمه، بأنه إذا أراد إيجاد شيء لم يزد على أمر واحد، وهو «كن»، فإذا بالمطلوب يكون كما أراد، بسرعة كسرعة لمح البصر. ولقد أهلكنا أمثالكم في الكفر والعصيان من الأمم السابقة، فهل من متّعظ قبل فوات الوقت؟ وكل شيء فعله أولئك المشركون في كتب الحفظة من الملائكة الكرام الكاتبين، وكل صغير وكبير من أعمالهم وأعمال غيرهم، بل كل حادثة في الأكوان، مسطّرة في اللوح المحفوظ كتاب المقادير. إن المتقين في جنات ونهر: هذا الإخبار يقابل الإخبار الأول أن المجرمين في ضلال وسعر؛ فالذين اتقوا ربهم فلم يشركوا به ولم يفسقوا عن أمره في بساتين ذات قصور وحور وأنهار وأشجار، جالسون في مقعد صدق، في مجلس حق لا لغو يُسمع فيه ولا تأثيم يلحق جالسه، عند مليك ذي ملك وسلطان، مقتدر على فعل كل ما يريده.", "h": ["بيان مصير المجرمين، وضمنه تخويف وتحذير من الإجرام الموبق للإنسان.", "تقرير عقيدة القضاء والقدر.", "تقرير أن أعمال العباد مدوّنة في كتب الكرام الكاتبين، لا يُترك منها شيء.", "تقرير أن كل صغيرة وكبيرة من أحداث الكون هي في كتاب المقادير، اللوح المحفوظ.", "بيان مصير المتقين، مع الترغيب في التقوى، إذ هي ملاك الأمر وجماع الخير.", "ذكر الجوار الكريم، وهو مجاورة الله رب العالمين في الملكوت الأعلى في دار السلام."], "k": "«وكل صغير وكبير مستطر»… حتى النظرة الصغيرة مكتوبة؛ فهل أنتبه لصغائري كما أنتبه لكبائري؟"}]$j$::jsonb then 0 else 1 end;
