insert into public.tdb_cards(topic, i, body) select 394, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٣ – ٣٢", "q": "كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ ﴿٢٣﴾ فَقَالُوٓاْ أَبَشَرٗا مِّنَّا وَٰحِدٗا نَّتَّبِعُهُۥٓ إِنَّآ إِذٗا لَّفِي ضَلَٰلٖ وَسُعُرٍ ﴿٢٤﴾ أَءُلۡقِيَ ٱلذِّكۡرُ عَلَيۡهِ مِنۢ بَيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرٞ ﴿٢٥﴾ سَيَعۡلَمُونَ غَدٗا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ ﴿٢٦﴾ إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةٗ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ ﴿٢٧﴾ وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبٖ مُّحۡتَضَرٞ ﴿٢٨﴾ فَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ ﴿٢٩﴾ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ﴿٣٠﴾ إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ صَيۡحَةٗ وَٰحِدَةٗ فَكَانُواْ كَهَشِيمِ ٱلۡمُحۡتَظِرِ ﴿٣١﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿٣٢﴾", "w": [["كذّبت ثمود بالنذر", "بالرسل، لأن النذر جمع نذير، وهو الرسول هنا."], ["فقالوا أبشراً منا واحداً نتّبعه", "كيف نتّبع بشراً واحداً منا؟ إنكاراً منهم للإيمان بصالح."], ["إنا إذاً لفي ضلال وسُعُر", "إنا إذا اتبعناه فيما جاء به لفي ذهاب عن الصواب وجنون."], ["أأُلقي الذكر عليه من بيننا", "لم يوحَ إليه من بيننا أبداً، وإنما هو كذّاب أشر."], ["بل هو كذّاب أشر", "كذّاب فيما ادّعى أنه أُلقي إليه من الوحي، أشر متكبر."], ["سيعلمون غداً", "في الآخرة."], ["من الكذاب الأشر", "وهم المعذَّبون يوم القيامة بكفرهم وتكذيبهم."], ["إنا مرسلو الناقة فتنة لهم", "مخرجو الناقة من الصخر ومرسلوها لهم محنة."], ["فارتقبهم واصطبر", "انتظر وراقب ماذا يصنعون وما يُصنع بهم، واصبر على أذاهم."], ["ونبّئهم أن الماء قسمة بينهم", "ماء بئرهم مقسوم بينهم وبين الناقة، فيوم لها ويوم لهم."], ["كل شرب محتضر", "كل نصيب من الماء يحضره أصحابه المختصون به."], ["فنادوا صاحبهم فتعاطى فعقر", "ملّوا ذلك فنادوا صاحبهم قُدار بن سالف ليقتلها، فتناول السيف فعقر الناقة."], ["إنا أرسلنا عليهم صيحة واحدة", "هي صيحة جبريل فهلكوا."], ["فكانوا كهشيم المحتظر", "صاروا بعد هلاكهم وتمزّق أجسادهم كالعشب اليابس والعيدان الرقيقة التي يجعلها الرجل في حظيرة غنمه."]], "m": "هذا القصص الموجز الثالث، قصص ثمود قوم صالح: كذّبت ثمود بالنذر التي أنذرها نبيها صالح، وهي ألوان العذاب، كما كذّبته فيما جاء به من الرسالة، فقالوا: أبشراً منا واحداً نتّبعه؟ كيف يتم ذلك منا؟ إنا إذاً لفي ضلال وسعر، أي إنا إذا اتبعناه وهو واحد منا لا غير لفي بعد عن الصواب وذهاب عن كل رشد، وفي جنون أيضاً. وقالوا متعجبين: أأُلقي الذكر عليه من بيننا؟ بل هو كذّاب متكبّر. قال تعالى رداً عليهم: سيعلمون غداً، يوم ينزل بهم العذاب ويوم القيامة، من الكذاب الأشر: أصالح أم هم؟ لن يكونوا إلا هم. إنا مرسلو الناقة فتنة لهم كما طلبوا، إذ قالوا لصالح: إن كنت رسول الله حقاً فسله يخرج لنا من هذه الصخرة ناقة، فقام يصلي ويدعو حتى تمخّض الجبل وخرجت منه ناقة عُشراء آية في القوة والجمال، وقال لهم: هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسّوها بسوء. فارتقبهم وراقبهم من بُعد واصطبر على أذاهم، وأخبرهم بأمرنا أن الماء الذي يشربون منه مقسوم بينهم: للناقة يوم وللقبيلة يوم، كل نصيب يحضره صاحبه دون غيره. وطالت المدة فملّوا، فنادوا صاحبهم قُدار بن سالف عاقر الناقة، فتناول السيف وعقرها بضرب رجليها ثم ذبحها. فكيف كان عذابي وإنذاري؟ أما العذاب فقد كان أليماً، وأما الإنذار فقد كان صادقاً: إنا أرسلنا عليهم صيحة واحدة، هي صيحة جبريل ﵇، فانخلعت لها قلوبهم فأصبحوا في ديارهم جاثمين ممزّقين محطّمين كحطب الحظائر التي تُجعل للأغنام. ولقد يسّرنا القرآن للذكر فهل من مدّكر: يدعو الله تعالى هذه الأمة إلى كتابه قراءةً وحفظاً وتذكراً، فإنه مصدر كمالهم وسعادتهم، لا سيما وقد سهّله وهيّأه لذلك.", "h": ["بيان سنة الله في إهلاك المكذبين.", "بيان أن الآيات لا تستلزم الإيمان، وإلا فآية صالح من أعظم الآيات ولم يؤمن بها قوم ثمود.", "أشقى أمة الإسلام عقبة بن أبي مُعيط الذي وضع سلى الجزور على ظهر الرسول ﷺ وهو يصلي حول الكعبة، وعاقر ناقة صالح قُدار بن سالف، كما جاء في الحديث.", "دعوة الله إلى حفظ القرآن والتذكير به، فإنه مصدر الإلهام والكمال والإسعاد."], "k": "«إنا مرسلو الناقة فتنة لهم»… قد تكون النعمة التي بين يديّ هي اختباري؛ فكيف أعاملها؟"}, {"lbl": "الآيات ٣٣ – ٤٢", "q": "كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ ﴿٣٣﴾ إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ حَاصِبًا إِلَّآ ءَالَ لُوطٖۖ نَّجَّيۡنَٰهُم بِسَحَرٖ ﴿٣٤﴾ نِّعۡمَةٗ مِّنۡ عِندِنَاۚ كَذَٰلِكَ نَجۡزِي مَن شَكَرَ ﴿٣٥﴾ وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡاْ بِٱلنُّذُرِ ﴿٣٦﴾ وَلَقَدۡ رَٰوَدُوهُ عَن ضَيۡفِهِۦ فَطَمَسۡنَآ أَعۡيُنَهُمۡ فَذُوقُواْ عَذَابِي وَنُذُرِ ﴿٣٧﴾ وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابٞ مُّسۡتَقِرّٞ ﴿٣٨﴾ فَذُوقُواْ عَذَابِي وَنُذُرِ ﴿٣٩﴾ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿٤٠﴾ وَلَقَدۡ جَآءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ ﴿٤١﴾ كَذَّبُواْ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذۡنَٰهُمۡ أَخۡذَ عَزِيزٖ مُّقۡتَدِرٍ ﴿٤٢﴾", "w": [["كذّبت قوم لوط بالنذر", "كذّبت قوم لوط بالنذر التي أنذرهم بها لوط وخوّفهم منها."], ["إنا أرسلنا عليهم حاصباً", "ريحاً ترميهم بالحصباء، وهي الحجارة الصغيرة."], ["إلا آل لوط نجّيناهم بسحر", "لوطاً وبنتيه، نجّاهم الله من العذاب حيث غادروا البلاد قبل نزول العذاب بها."], ["نعمة من عندنا", "إنعاماً منا عليهم ورحمة منا بهم."], ["كذلك نجزي من شكر", "مثل هذا الجزاء بالنجاة من الهلاك نجزي من شكرنا بالإيمان والطاعة."], ["ولقد أنذرهم بطشتنا", "أنذرهم لوط، أي خوّفهم أخذتنا إياهم بالعذاب."], ["فتماروا بالنذر", "فتجادلوا وكذّبوا بالنذر التي أنذرهم بها."], ["ولقد راودوه عن ضيفه", "أن يخلّي بينهم وبين ضيفه، وهم ملائكة، ليخبثوا بهم."], ["فطمسنا أعينهم", "ضربهم جبريل بجناحه فطمس أعينهم فكانت كباقي الوجه."], ["ولقد صبّحهم بكرة عذاب مستقر", "نزل بهم بكرة صباحاً عذاب مستقر لا يفارقهم أبداً: هلكوا به في الدنيا، ويصحبهم في البرزخ، ويلازمهم في جهنم."], ["ولقد يسّرنا القرآن للذكر", "سهّلناه للحفظ والتذكر به والعمل بما فيه."], ["فهل من مدّكر", "من متذكّر فيعمل بما فيه فينجو من النار ويسعد في الجنة."], ["ولقد جاء آل فرعون النذر", "جاءت قوم فرعون الإنذارات على لسان موسى وهارون ﵉."], ["كذّبوا بآياتنا كلها", "فلم يؤمنوا بل كذّبوا بآياتنا التسع التي آتيناها موسى."], ["فأخذناهم أخذ عزيز مقتدر", "أخذناهم بالعذاب، وهو الغرق، أخذ قوي مقتدر على كل شيء لا يعجزه شيء."]], "m": "ما زال السياق في ذكر موجز لقصص عدد من الأمم السابقة تسلية لرسول الله ﷺ، وإنذاراً لأهل الشرك والمعاصي في كل زمان ومكان: كذّبت قوم لوط، وهم أهل قرى سدوم وعمورة، رسولهم لوطاً ابن أخي إبراهيم ﵇، كذّبوا بالنذر التي أنذرهم بها وخوّفهم من عواقبها. فلما أصرّوا على الكفر وإتيان الفاحشة أرسلنا عليهم ريحاً تحمل الحصباء فأهلكناهم بعد قلب البلاد بجعل عاليها سافلها، إلا آل لوط ومن آمن معه من ابنتيه وغيرهما، نجّاهم الله بسحر، وهو آخر الليل، إنعاماً منا عليهم ورحمة بهم، وكهذا الإنجاء من العذاب نجزي من شكرنا فآمن بنا وعمل صالحاً. ولقد أنذرهم بطشتنا، فلم نأخذهم بظلم منا ولا بدون سابق إنذار، بل أخذناهم بظلمهم وبعد تكرّر إنذارهم، فكانوا إذا أُنذروا جادلوا فيه مستهزئين مكذّبين. ومن أعظم ظلمهم أنهم راودوا لوطاً عن ضيفه من الملائكة وهم في صورة بشر، فضربهم جبريل بجناحه فطمس أعينهم فأصبحت كسائر وجوههم لا مقلة ولا مكان للعين، وقلنا لهم: فذوقوا عذابي ونذر. أما باقي الأمة فقد صبّحهم عذاب دائم ملازم لا يفارقهم: ذاقوه في الدنيا موتاً، ويصحبهم برزخاً، ويلازمهم في جهنم. ولقد سهّلنا القرآن للحفظ والفهم والاتعاظ، فهل من متذكّر فيقبل على طاعة الله متجنّباً معاصيه فينجو ويسعد؟ ولقد جاء قوم فرعون من القبط النذر على لسان موسى وأخيه هارون، فكذّبوا بآيات الله كلها، وهي تسع آيات أولها العصا وآخرها انفلاق البحر، فأخذناهم أخذ عزيز غالب لا يُمانع في مراده، مقتدر لا يعجزه شيء، فأغرقناهم أجمعين.", "h": ["تقرير ربوبية الله تعالى وألوهيته، وتقرير التوحيد وإثبات النبوة لمحمد ﷺ؛ إذ أفعال الله العظيمة من إرسال الرسل وأخذ الظلمة الكافرين بأشد أنواع العقوبات دالّة على ربوبيته وألوهيته، وقصّ هذا القصص من أمّي لم يقرأ ولم يكتب دالّ على نبوة محمد ﷺ.", "بيان جزاء الشاكرين لله تعالى بالإيمان به وطاعته وطاعة رسله.", "مشروعية الضيافة وإكرام الضيف.", "تيسير القرآن وتسهيله للحفظ والاتعاظ والاعتبار."], "k": "«كذلك نجزي من شكر»… النجاة جزاء الشكر؛ فهل أشكر بلساني فقط أم بطاعتي؟"}, {"lbl": "الآيات ٤٣ – ٤٦", "q": "أَكُفَّارُكُمۡ خَيۡرٞ مِّنۡ أُوْلَـٰٓئِكُمۡ أَمۡ لَكُم بَرَآءَةٞ فِي ٱلزُّبُرِ ﴿٤٣﴾ أَمۡ يَقُولُونَ نَحۡنُ جَمِيعٞ مُّنتَصِرٞ ﴿٤٤﴾ سَيُهۡزَمُ ٱلۡجَمۡعُ وَيُوَلُّونَ ٱلدُّبُرَ ﴿٤٥﴾ بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ ﴿٤٦﴾", "w": [["أكفّاركم خير من أولئكم", "أكفّاركم يا قريش خير من أولئكم الكفار المذكورين من قوم نوح وعاد وثمود وقوم لوط وفرعون وملئه، فلذا هم آمنون؟"], ["أم لكم براءة في الزبر", "أم لكم يا كفار قريش براءة من العذاب في الكتب الإلهية؟"], ["أم يقولون نحن جميع منتصر", "أم يقول كفار قريش: نحن جمع منتصر على محمد وأصحابه؟"], ["سيُهزم الجمع ويولّون الدبر", "سيُهزم جمعهم ويولّون الدبر هاربين منهزمين."], ["بل الساعة موعدهم", "الساعة موعدهم بالعذاب، والمراد بالساعة يوم القيامة."], ["والساعة أدهى وأمرّ", "وعذاب الساعة وأهوالها أعظم بلية، وأشد مرارة من عذاب الدنيا قطعاً."]], "m": "يقول تعالى مبكّتاً مشركي قريش، وهم الذين إن يروا آية يعرضوا ويقولوا سحر مستمر: أكفّاركم يا قريش خير من كفار الأمم السابقة كعاد وثمود وقوم لوط وآل فرعون، فلذا هم آمنون من العذاب الذي نزل بأولئك، أم لكم براءة من العذاب جاءت في الكتب مسطورة؟ لا هذا ولا ذاك؛ ما كفّاركم بخير من أولئكم، وليس لكم براءة في الزبر، وإنما أنتم مُمهَلون، فإما أن تتوبوا وإما أن تؤخذوا. أم يقولون: نحن جمع منتصر على كل من يحاربنا ويريد أن يفرّق جمعنا؟ نعم قالوا هذا، ولكن سيُهزم الجمع ويولّون الدبر، وقد تم هذا في بدر بعد سنيّات ثلاث أو أربع، فهُزم جمعهم وولّوا الأدبار هاربين إلى مكة. بل الساعة التي ينكرونها ويكذّبون بها هي موعد عذابهم الحق، أما عذاب الدنيا فليس بشيء إذا قيس بعذاب الآخرة، والساعة أعظم بلية وأكبر داهية تصيب الإنسان، وعذابها أمرّ من عذاب الدنيا كله.", "h": ["بيان حقيقة يغفل عنها الناس، وهي أن الكفر كله واحد ومورد للهلاك.", "لا قيمة أبداً لقوة الإنسان إزاء قوة الله تعالى.", "صدق القرآن في إخباره بغيب لمّا يقع، ووقع كما أخبر، وهو آية أنه وحي الله وكلامه.", "القيامة موعد لقاء البشرية كافة، بحيث لا يتخلّف عنه أحد."], "k": "«أم لكم براءة في الزبر»… ليس عندي صك أمان؛ فلماذا أطمئن وأنا مقصّر؟"}, {"lbl": "الآيات ٤٧ – ٥٥", "q": "إِنَّ ٱلۡمُجۡرِمِينَ فِي ضَلَٰلٖ وَسُعُرٖ ﴿٤٧﴾ يَوۡمَ يُسۡحَبُونَ فِي ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُواْ مَسَّ سَقَرَ ﴿٤٨﴾ إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرٖ ﴿٤٩﴾ وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةٞ كَلَمۡحِۭ بِٱلۡبَصَرِ ﴿٥٠﴾ وَلَقَدۡ أَهۡلَكۡنَآ أَشۡيَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرٖ ﴿٥١﴾ وَكُلُّ شَيۡءٖ فَعَلُوهُ فِي ٱلزُّبُرِ ﴿٥٢﴾ وَكُلُّ صَغِيرٖ وَكَبِيرٖ مُّسۡتَطَرٌ ﴿٥٣﴾ إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَنَهَرٖ ﴿٥٤﴾ فِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكٖ مُّقۡتَدِرِۭ ﴿٥٥﴾", "w": [["إن المجرمين في ضلال وسُعُر", "الذين أجرموا على أنفسهم بالشرك والمعاصي في ضلال في الدنيا، ونار مستعرة في الآخرة."], ["ذوقوا مسّ سقر", "يوم يُسحبون في النار على وجوههم يقال لهم: ذوقوا مسّ سقر."], ["إنا كل شيء خلقناه بقدر", "خلقنا كل شيء بتقدير سابق لخلقنا له، وذلك بكتابته في اللوح المحفوظ قبل خلق السماوات والأرض، فهو يقع كما كُتب كمية وصورة وزماناً ومكاناً لا يتخلف في شيء."], ["وما أمرنا إلا واحدة", "وما أمرنا إذا أردنا خلق شيء إلا أمرة واحدة فيتم الشيء."], ["كلمح بالبصر", "بسرعة كلمح البصر، وهو النظر بعجلة."], ["ولقد أهلكنا أشياعكم", "أهلكنا أمثالكم أيها المشركون من الأمم السابقة."], ["فهل من مدّكر", "فاذكروا واتّعظوا، خيراً لكم من هذا الإعراض."], ["وكل شيء فعلوه في الزبر", "وكل ما فعله العباد مسجّل في كتب الحفظة من الملائكة."], ["وكل صغير وكبير مستطر", "وكل صغير وكبير من سائر الأعمال والأحداث مكتوب في اللوح المحفوظ."], ["إن المتقين في جنات ونهر", "إن الذين اتقوا ربهم فلم يشركوا به ولم يفسقوا عن أمره في جنات يشربون من أنهار الماء واللبن والخمر والعسل."], ["في مقعد صدق", "في مجلس حق لا لغو فيه ولا تأثيم."], ["عند مليك مقتدر", "عند مليك ذي ملك وسلطان، مقتدر على ما يشاء، وهو الله جل جلاله."]], "m": "يخبر تعالى تحذيراً وإنذاراً عن حال المجرمين الذين أجرموا على أنفسهم فأفسدوها بالشرك وغشيان الذنوب، بأنهم في ضلال في حياتهم الدنيا، وفي نار مستعرة متأجّجة يوم القيامة، يوم يُسحبون في النار على وجوههم، يقال لهم تهكّماً بهم: ذوقوا مسّ سقر، وسقر طبق من أطباق جهنم وباب من أبوابها. إنا كل شيء خلقناه بقدر: إعلام منه تعالى عن نظام الكون الذي خلقه، وهو أن كل حادث يحدث في هذا العالم قد سبق به علم الله وتقديره له، فحدّد ذاته وصفاته وأعماله ومآله إلى جنة أو إلى نار إن كان إنساناً أو جاناً، وليس هناك شيء يحدث بدون تقدير سابق له وعلم تام به قبل حدوثه. وما أمرنا إلا واحدة كلمح بالبصر: يخبر تعالى عن قدرته كما أخبر عن علمه، بأنه إذا أراد إيجاد شيء لم يزد على أمر واحد، وهو «كن»، فإذا بالمطلوب يكون كما أراد، بسرعة كسرعة لمح البصر. ولقد أهلكنا أمثالكم في الكفر والعصيان من الأمم السابقة، فهل من متّعظ قبل فوات الوقت؟ وكل شيء فعله أولئك المشركون في كتب الحفظة من الملائكة الكرام الكاتبين، وكل صغير وكبير من أعمالهم وأعمال غيرهم، بل كل حادثة في الأكوان، مسطّرة في اللوح المحفوظ كتاب المقادير. إن المتقين في جنات ونهر: هذا الإخبار يقابل الإخبار الأول أن المجرمين في ضلال وسعر؛ فالذين اتقوا ربهم فلم يشركوا به ولم يفسقوا عن أمره في بساتين ذات قصور وحور وأنهار وأشجار، جالسون في مقعد صدق، في مجلس حق لا لغو يُسمع فيه ولا تأثيم يلحق جالسه، عند مليك ذي ملك وسلطان، مقتدر على فعل كل ما يريده.", "h": ["بيان مصير المجرمين، وضمنه تخويف وتحذير من الإجرام الموبق للإنسان.", "تقرير عقيدة القضاء والقدر.", "تقرير أن أعمال العباد مدوّنة في كتب الكرام الكاتبين، لا يُترك منها شيء.", "تقرير أن كل صغيرة وكبيرة من أحداث الكون هي في كتاب المقادير، اللوح المحفوظ.", "بيان مصير المتقين، مع الترغيب في التقوى، إذ هي ملاك الأمر وجماع الخير.", "ذكر الجوار الكريم، وهو مجاورة الله رب العالمين في الملكوت الأعلى في دار السلام."], "k": "«وكل صغير وكبير مستطر»… حتى النظرة الصغيرة مكتوبة؛ فهل أنتبه لصغائري كما أنتبه لكبائري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (395, 55, 1, 25, 'سورة الرحمن ١ – ٢٥', 'الرحمن: فبأي آلاء ربكما تكذبان', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 395) = $j$[{"lbl": "الآيات ١ – ١٣", "q": "ٱلرَّحۡمَٰنُ ﴿١﴾ عَلَّمَ ٱلۡقُرۡءَانَ ﴿٢﴾ خَلَقَ ٱلۡإِنسَٰنَ ﴿٣﴾ عَلَّمَهُ ٱلۡبَيَانَ ﴿٤﴾ ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانٖ ﴿٥﴾ وَٱلنَّجۡمُ وَٱلشَّجَرُ يَسۡجُدَانِ ﴿٦﴾ وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلۡمِيزَانَ ﴿٧﴾ أَلَّا تَطۡغَوۡاْ فِي ٱلۡمِيزَانِ ﴿٨﴾ وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ ﴿٩﴾ وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ ﴿١٠﴾ فِيهَا فَٰكِهَةٞ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ ﴿١١﴾ وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّيۡحَانُ ﴿١٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿١٣﴾", "w": [["الرحمن", "اسم من أسماء الله تعالى."], ["علّم القرآن", "علّم من شاء من عباده القرآن."], ["خلق الإنسان", "آدم، كما خلق ذريته أيضاً."], ["علّمه البيان", "علّم آدم البيان، وهو النطق والإعراب عما في النفس بلغة من اللغات، كل هذا تعليم الله عز وجل."], ["الشمس والقمر بحسبان", "يجريان بحساب معلوم مقدّر في بروجهما ومنازلهما."], ["والنجم والشجر يسجدان", "النجم ما لا ساق له من النبات، والشجر ما له ساق، يسجدان: يخضعان لله تعالى بما يريد منهما في طواعية كالسجود من المكلفين."], ["والسماء رفعها", "فوق الأرض وأعلاها."], ["ووضع الميزان", "أثبت العدل بين العباد، أمر به وألهم صنع آلته."], ["ألا تطغوا في الميزان", "لأجل ألا تجوروا في الميزان، وهو ما يوزن به."], ["وأقيموا الوزن بالقسط", "بالعدل."], ["ولا تُخسروا الميزان", "لا تنقصوا الموزون الذي تزنونه، بل وفّوه."], ["والأرض وضعها للأنام", "أثبتها وخفضها كما رفع السماء، لحياة الأنام عليها، وهم الإنس والجن والحيوان وكل ذي روح."], ["فيها فاكهة والنخل ذات الأكمام", "في الأرض فاكهة، وهي كل ما يتفكّه به الإنسان، والنخل ذات الأكمام، وهي أوعية الطلع."], ["والحب ذو العصف", "وفي الأرض الحب من بُرّ وشعير، وعصفه تبنه."], ["والريحان", "أنواع الرياحين المشمومة ذات الريح الطيبة."], ["فبأي آلاء ربكما تكذّبان", "فبأي نعم ربكما يا معشر الجن والإنس تكذّبان، وهي كثيرة لا تُعدّ ولا تُحصى؟ والجواب: لا بشيء من نعمك ربنا نكذّب، فلك الحمد."]], "m": "يخبر تعالى أنه هو الرحمن الذي علّم نبيه محمداً ﷺ القرآن، لا كما يقول المبطلون: إنما يعلّمه بشر؛ الرحمن الذي وسعت رحمته كل شيء، وهي متجلّية فيما يعدّد من آلاء ونعم: منها خلقه الإنسان، آدم وذريته، وتعليمهم البيان، وهو النطق والإبانة عما في نفوسهم. الشمس والقمر بحسبان يجريان لإفادة الناس في معرفة أوقات عباداتهم وآجال ديونهم. والنجم غذاء بهائمكم، والشجر فيه فاكهتكم وبعض غذائكم، يسجدان خضوعاً لله بما أراد منهما، لا يعصيان كما يعصي الثقلان. والسماء رفعها عن الأرض ولم يلصقها بها، إنعاماً منه في رفعها وتزيينها بكواكبها وشمسها وقمرها. ووضع العدل، حيث أمر به وألهم وضع آلته وغرز في النفوس حبه والرغبة فيه، من أجل ألّا تجوروا في الميزان، وأقيموا الوزن بالعدل، ولا تنقصوه إذا وزنتم بل وفّوه؛ كل هذا إنعام وألوان من رحمات الرحمن. والأرض أثبتها وخفضها ودحاها لحياة الأنام، فيها فاكهة، والنخل ذات أوعية الطلع، والحب من بُرّ وشعير ذو التبن، والريحان؛ هذه أنواع الطعام للإنسان والحيوان: طعام وفاكهة وريحان، كلها مظاهر الرحمة التي أفاضها الرحمن، فبأي آلاء ربكما يا معشر الجن والإنس تكذّبان؟ لا بشيء من نعمك ربنا نكذّب، فلك الحمد.", "h": ["«الرحمن» مثل اسم «الله» لا يصح أن يُطلق على غير الرب تبارك وتعالى؛ فيقال: فلان عزيز أو رحيم أو عليم أو حكيم، ولكن لا يقال: رحمن، كما لا يقال: إله أو الإله أو الله.", "ورد في الصحيح في فضل تعلّم القرآن قوله ﷺ: «خيركم من تعلّم القرآن وعلّمه».", "وجوب إقامة العدل والتواصي به، ومراقبة الموازين لدى التجار وإصلاح فاسدها.", "وجوب شكر الله على آلائه.", "استحباب قول: «لا بشيء من آلائك ربنا نكذّب فلك الحمد» عند سماع قراءة «فبأي آلاء ربكما تكذّبان».", "مشروعية تعلّم علم الفلك لمعرفة القبلة ومواقيت الصلاة والصيام والحج."], "k": "«فبأي آلاء ربكما تكذّبان»… أعدّ ما في يومي من نعم، ثم أقول: لا بشيء من آلائك ربنا نكذّب."}, {"lbl": "الآيات ١٤ – ٢٥", "q": "خَلَقَ ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ كَٱلۡفَخَّارِ ﴿١٤﴾ وَخَلَقَ ٱلۡجَآنَّ مِن مَّارِجٖ مِّن نَّارٖ ﴿١٥﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿١٦﴾ رَبُّ ٱلۡمَشۡرِقَيۡنِ وَرَبُّ ٱلۡمَغۡرِبَيۡنِ ﴿١٧﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿١٨﴾ مَرَجَ ٱلۡبَحۡرَيۡنِ يَلۡتَقِيَانِ ﴿١٩﴾ بَيۡنَهُمَا بَرۡزَخٞ لَّا يَبۡغِيَانِ ﴿٢٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢١﴾ يَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ ﴿٢٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢٣﴾ وَلَهُ ٱلۡجَوَارِ ٱلۡمُنشَـَٔاتُ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ ﴿٢٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢٥﴾", "w": [["خلق الإنسان من صلصال كالفخار", "خلق آدم من طين يابس يُسمع له صلصلة كالفخار، وهو ما طُبخ من الطين."], ["وخلق الجانّ من مارج من نار", "خلق أبا الجن من لهب النار الخالص من الدخان، المختلط أحمر وأزرق وأصفر."], ["رب المشرقين ورب المغربين", "مشرق الشتاء ومشرق الصيف، أي مطلع الشمس فيهما، وكذا المغربين في الصيف والشتاء."], ["مرج البحرين يلتقيان", "أرسل البحرين العذب والملح يلتقيان في رأي العين."], ["بينهما برزخ لا يبغيان", "بينهما حاجز لا يبغي أحدهما على الآخر فيختلط به."], ["يخرج منهما اللؤلؤ والمرجان", "يخرج من مجموعهما الصادق بأحدهما، وهو الملح، اللؤلؤ والمرجان."], ["وله الجوار المنشآت في البحر كالأعلام", "السفن المحدثات في البحر كالجبال عِظماً وارتفاعاً."]], "m": "ما زال السياق في ذكر ما أفاض الرحمن جل جلاله من رحمته التي وسعت كل شيء: الرحمن، الذي تجاهله المبطلون وقالوا: وما الرحمن؟ هو الذي خلق آدم أول إنسان من طين ذي صلصلة وصوت كالفخار، وخلق الجان، وهو عالم كعالم الإنسان، خلق أصله من لهب النار المختلط، فبأي آلاء ربكما يا معشر الجن والإنس تكذّبان؟ إنها نعم تفوق عدّ الإنسان. من رب المشرقين ورب المغربين، من خلقهما وسخّرهما لفائدة الإنسان؟ إنه الرحمن، فبأي آلاء ربكما تكذّبان؟ الرحمن مرج البحرين الملح والعذب، أرسلهما على بعضهما كأنهما اختلطا، وجعل بينهما برزخاً حاجزاً فلا يختلط أحدهما بالثاني. يخرج من مجموع البحرين اللؤلؤ والمرجان، ولفائدة من خلقهما الرحمن؟ إنها لفائدة الإنسان، فهما نعمة من رحمات الرحمن. وللرحمن الجواري المنشآت المصنوعات في البحر، تظهر فيه كما تظهر الجبال في البر، لمصلحة الإنسان، فهي إذاً رحمة الرحمن ونعمته، فبأي آلاء ربكما يا معشر الإنس والجن تكذّبان؟ أقرّوا واعترفوا واشكروا الرحمن.", "h": ["بيان أصل خلق الإنسان والجان؛ فالأول من طين لازب ذي صلصال كالفخار، والثاني من مارج من نار، وأخبر الرسول ﷺ أن خلق الملائكة كان من نور.", "معرفة مطالع الشمس ومغاربها في الشتاء والصيف، وهما مطلعان ومغربان.", "معرفة صناعة اللؤلؤ والمرجان، والسفن التي هي في البحر كالجبال علواً وظهوراً.", "وجوب شكر الرحمن على إنعامه على الإنس والجان."], "k": "«بينهما برزخ لا يبغيان»… حدود رسمها الرحمن للبحرين فلا تُتجاوز؛ فهل أحفظ حدوده في نفسي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 395;
insert into public.tdb_cards(topic, i, body) select 395, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٣", "q": "ٱلرَّحۡمَٰنُ ﴿١﴾ عَلَّمَ ٱلۡقُرۡءَانَ ﴿٢﴾ خَلَقَ ٱلۡإِنسَٰنَ ﴿٣﴾ عَلَّمَهُ ٱلۡبَيَانَ ﴿٤﴾ ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانٖ ﴿٥﴾ وَٱلنَّجۡمُ وَٱلشَّجَرُ يَسۡجُدَانِ ﴿٦﴾ وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلۡمِيزَانَ ﴿٧﴾ أَلَّا تَطۡغَوۡاْ فِي ٱلۡمِيزَانِ ﴿٨﴾ وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ ﴿٩﴾ وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ ﴿١٠﴾ فِيهَا فَٰكِهَةٞ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ ﴿١١﴾ وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّيۡحَانُ ﴿١٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿١٣﴾", "w": [["الرحمن", "اسم من أسماء الله تعالى."], ["علّم القرآن", "علّم من شاء من عباده القرآن."], ["خلق الإنسان", "آدم، كما خلق ذريته أيضاً."], ["علّمه البيان", "علّم آدم البيان، وهو النطق والإعراب عما في النفس بلغة من اللغات، كل هذا تعليم الله عز وجل."], ["الشمس والقمر بحسبان", "يجريان بحساب معلوم مقدّر في بروجهما ومنازلهما."], ["والنجم والشجر يسجدان", "النجم ما لا ساق له من النبات، والشجر ما له ساق، يسجدان: يخضعان لله تعالى بما يريد منهما في طواعية كالسجود من المكلفين."], ["والسماء رفعها", "فوق الأرض وأعلاها."], ["ووضع الميزان", "أثبت العدل بين العباد، أمر به وألهم صنع آلته."], ["ألا تطغوا في الميزان", "لأجل ألا تجوروا في الميزان، وهو ما يوزن به."], ["وأقيموا الوزن بالقسط", "بالعدل."], ["ولا تُخسروا الميزان", "لا تنقصوا الموزون الذي تزنونه، بل وفّوه."], ["والأرض وضعها للأنام", "أثبتها وخفضها كما رفع السماء، لحياة الأنام عليها، وهم الإنس والجن والحيوان وكل ذي روح."], ["فيها فاكهة والنخل ذات الأكمام", "في الأرض فاكهة، وهي كل ما يتفكّه به الإنسان، والنخل ذات الأكمام، وهي أوعية الطلع."], ["والحب ذو العصف", "وفي الأرض الحب من بُرّ وشعير، وعصفه تبنه."], ["والريحان", "أنواع الرياحين المشمومة ذات الريح الطيبة."], ["فبأي آلاء ربكما تكذّبان", "فبأي نعم ربكما يا معشر الجن والإنس تكذّبان، وهي كثيرة لا تُعدّ ولا تُحصى؟ والجواب: لا بشيء من نعمك ربنا نكذّب، فلك الحمد."]], "m": "يخبر تعالى أنه هو الرحمن الذي علّم نبيه محمداً ﷺ القرآن، لا كما يقول المبطلون: إنما يعلّمه بشر؛ الرحمن الذي وسعت رحمته كل شيء، وهي متجلّية فيما يعدّد من آلاء ونعم: منها خلقه الإنسان، آدم وذريته، وتعليمهم البيان، وهو النطق والإبانة عما في نفوسهم. الشمس والقمر بحسبان يجريان لإفادة الناس في معرفة أوقات عباداتهم وآجال ديونهم. والنجم غذاء بهائمكم، والشجر فيه فاكهتكم وبعض غذائكم، يسجدان خضوعاً لله بما أراد منهما، لا يعصيان كما يعصي الثقلان. والسماء رفعها عن الأرض ولم يلصقها بها، إنعاماً منه في رفعها وتزيينها بكواكبها وشمسها وقمرها. ووضع العدل، حيث أمر به وألهم وضع آلته وغرز في النفوس حبه والرغبة فيه، من أجل ألّا تجوروا في الميزان، وأقيموا الوزن بالعدل، ولا تنقصوه إذا وزنتم بل وفّوه؛ كل هذا إنعام وألوان من رحمات الرحمن. والأرض أثبتها وخفضها ودحاها لحياة الأنام، فيها فاكهة، والنخل ذات أوعية الطلع، والحب من بُرّ وشعير ذو التبن، والريحان؛ هذه أنواع الطعام للإنسان والحيوان: طعام وفاكهة وريحان، كلها مظاهر الرحمة التي أفاضها الرحمن، فبأي آلاء ربكما يا معشر الجن والإنس تكذّبان؟ لا بشيء من نعمك ربنا نكذّب، فلك الحمد.", "h": ["«الرحمن» مثل اسم «الله» لا يصح أن يُطلق على غير الرب تبارك وتعالى؛ فيقال: فلان عزيز أو رحيم أو عليم أو حكيم، ولكن لا يقال: رحمن، كما لا يقال: إله أو الإله أو الله.", "ورد في الصحيح في فضل تعلّم القرآن قوله ﷺ: «خيركم من تعلّم القرآن وعلّمه».", "وجوب إقامة العدل والتواصي به، ومراقبة الموازين لدى التجار وإصلاح فاسدها.", "وجوب شكر الله على آلائه.", "استحباب قول: «لا بشيء من آلائك ربنا نكذّب فلك الحمد» عند سماع قراءة «فبأي آلاء ربكما تكذّبان».", "مشروعية تعلّم علم الفلك لمعرفة القبلة ومواقيت الصلاة والصيام والحج."], "k": "«فبأي آلاء ربكما تكذّبان»… أعدّ ما في يومي من نعم، ثم أقول: لا بشيء من آلائك ربنا نكذّب."}, {"lbl": "الآيات ١٤ – ٢٥", "q": "خَلَقَ ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ كَٱلۡفَخَّارِ ﴿١٤﴾ وَخَلَقَ ٱلۡجَآنَّ مِن مَّارِجٖ مِّن نَّارٖ ﴿١٥﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿١٦﴾ رَبُّ ٱلۡمَشۡرِقَيۡنِ وَرَبُّ ٱلۡمَغۡرِبَيۡنِ ﴿١٧﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿١٨﴾ مَرَجَ ٱلۡبَحۡرَيۡنِ يَلۡتَقِيَانِ ﴿١٩﴾ بَيۡنَهُمَا بَرۡزَخٞ لَّا يَبۡغِيَانِ ﴿٢٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢١﴾ يَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ ﴿٢٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢٣﴾ وَلَهُ ٱلۡجَوَارِ ٱلۡمُنشَـَٔاتُ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ ﴿٢٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢٥﴾", "w": [["خلق الإنسان من صلصال كالفخار", "خلق آدم من طين يابس يُسمع له صلصلة كالفخار، وهو ما طُبخ من الطين."], ["وخلق الجانّ من مارج من نار", "خلق أبا الجن من لهب النار الخالص من الدخان، المختلط أحمر وأزرق وأصفر."], ["رب المشرقين ورب المغربين", "مشرق الشتاء ومشرق الصيف، أي مطلع الشمس فيهما، وكذا المغربين في الصيف والشتاء."], ["مرج البحرين يلتقيان", "أرسل البحرين العذب والملح يلتقيان في رأي العين."], ["بينهما برزخ لا يبغيان", "بينهما حاجز لا يبغي أحدهما على الآخر فيختلط به."], ["يخرج منهما اللؤلؤ والمرجان", "يخرج من مجموعهما الصادق بأحدهما، وهو الملح، اللؤلؤ والمرجان."], ["وله الجوار المنشآت في البحر كالأعلام", "السفن المحدثات في البحر كالجبال عِظماً وارتفاعاً."]], "m": "ما زال السياق في ذكر ما أفاض الرحمن جل جلاله من رحمته التي وسعت كل شيء: الرحمن، الذي تجاهله المبطلون وقالوا: وما الرحمن؟ هو الذي خلق آدم أول إنسان من طين ذي صلصلة وصوت كالفخار، وخلق الجان، وهو عالم كعالم الإنسان، خلق أصله من لهب النار المختلط، فبأي آلاء ربكما يا معشر الجن والإنس تكذّبان؟ إنها نعم تفوق عدّ الإنسان. من رب المشرقين ورب المغربين، من خلقهما وسخّرهما لفائدة الإنسان؟ إنه الرحمن، فبأي آلاء ربكما تكذّبان؟ الرحمن مرج البحرين الملح والعذب، أرسلهما على بعضهما كأنهما اختلطا، وجعل بينهما برزخاً حاجزاً فلا يختلط أحدهما بالثاني. يخرج من مجموع البحرين اللؤلؤ والمرجان، ولفائدة من خلقهما الرحمن؟ إنها لفائدة الإنسان، فهما نعمة من رحمات الرحمن. وللرحمن الجواري المنشآت المصنوعات في البحر، تظهر فيه كما تظهر الجبال في البر، لمصلحة الإنسان، فهي إذاً رحمة الرحمن ونعمته، فبأي آلاء ربكما يا معشر الإنس والجن تكذّبان؟ أقرّوا واعترفوا واشكروا الرحمن.", "h": ["بيان أصل خلق الإنسان والجان؛ فالأول من طين لازب ذي صلصال كالفخار، والثاني من مارج من نار، وأخبر الرسول ﷺ أن خلق الملائكة كان من نور.", "معرفة مطالع الشمس ومغاربها في الشتاء والصيف، وهما مطلعان ومغربان.", "معرفة صناعة اللؤلؤ والمرجان، والسفن التي هي في البحر كالجبال علواً وظهوراً.", "وجوب شكر الرحمن على إنعامه على الإنس والجان."], "k": "«بينهما برزخ لا يبغيان»… حدود رسمها الرحمن للبحرين فلا تُتجاوز؛ فهل أحفظ حدوده في نفسي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (396, 55, 26, 45, 'سورة الرحمن ٢٦ – ٤٥', 'الرحمن: كل من عليها فان', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 396) = $j$[{"lbl": "الآيات ٢٦ – ٣٦", "q": "كُلُّ مَنۡ عَلَيۡهَا فَانٖ ﴿٢٦﴾ وَيَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ ﴿٢٧﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢٨﴾ يَسۡـَٔلُهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ كُلَّ يَوۡمٍ هُوَ فِي شَأۡنٖ ﴿٢٩﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٠﴾ سَنَفۡرُغُ لَكُمۡ أَيُّهَ ٱلثَّقَلَانِ ﴿٣١﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٢﴾ يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ أَن تَنفُذُواْ مِنۡ أَقۡطَارِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ فَٱنفُذُواْۚ لَا تَنفُذُونَ إِلَّا بِسُلۡطَٰنٖ ﴿٣٣﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٤﴾ يُرۡسَلُ عَلَيۡكُمَا شُوَاظٞ مِّن نَّارٖ وَنُحَاسٞ فَلَا تَنتَصِرَانِ ﴿٣٥﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٦﴾", "w": [["كل من عليها فان", "كل من على الأرض من إنسان وحيوان وجانّ فانٍ، أي هالك."], ["ويبقى وجه ربك", "ذاته ووجهه سبحانه وتعالى."], ["ذو الجلال والإكرام", "ذو العظمة، والإنعام على عباده عامة والمؤمنين بخاصة."], ["يسأله من في السماوات والأرض", "يسألونه حاجاتهم التي تتوقف عليها حياتهم من الرزق والقوة على العبادة والمغفرة للذنب."], ["كل يوم هو في شأن", "كل وقت هو في شأن، شؤون يبديها وفق تقديره لها، يرفع أقواماً ويضع آخرين."], ["سنفرغ لكم أيها الثقلان", "لحسابكم ومجازاتكم بعد انتهاء هذه الحياة الدنيا، ونجزي كلاً بما عمل."], ["إن استطعتم أن تنفذوا", "إن قدرتم على أن تخرجوا."], ["من أقطار السماوات والأرض", "من نواحي السماوات والأرض."], ["فانفذوا لا تنفذون إلا بسلطان", "فاخرجوا، لا تنفذون إلا بقوة، ولا قوة لكم، وهذا تعجيز."], ["يرسل عليكما شواظ من نار", "من لهب النار الخالص الذي لا دخان فيه."], ["ونحاس", "دخان لا لهب فيه، ولا يبعد أن يكون نحاساً مذاباً."], ["فلا تنتصران", "لا تمتنعان من السَّوق إلى المحشر."]], "m": "ما زال السياق في ذكر أيادي الرحمن الرحيم: كل من على الأرض من إنسان وجانّ وحيوان فانٍ هالك، ويبقى وجه ربك ذو الجلال والإكرام، حيّ لا يموت، والإنس والجن يموتون. فبأي آلاء ربكما تكذّبان: أبنعمة إيجادكما وإمدادكما بالأرزاق طوال الحياة، أم بنعمة إنهاء أتعابكما وتكاليفكما، أم بإهلاك أعدائكما وإدنائكما من النعيم المقيم؟ قولا خيراً لكما: لا بشيء من آلائك ربنا نكذّب، فلك الحمد. يسأله من في السماوات والأرض بلسان المقال أو الحال ما هم في حاجة إليه مما يحفظ وجودهم ويغفر ذنوبهم، كل يوم هو في شأن، لا يفرغ الدهر كله، يدبّر أمر السماء والأرض، يرفع أقواماً ويضع آخرين. سنفرغ لكم أيها الثقلان من الإنس والجن فنحاسبكما ونجزيكما، محسنكما بالإحسان، ومسيئكما بالسوء والخسران، وهذا يوم تقومان للرحمن حفاة عراة. يا معشر الجن والإنس، إن استطعتم أن تخرجوا من جوانب السماوات والأرض هاربين من قضائي وحكمي فاخرجوا، لا تنفذون إلا بقوة غالبة، ولا قوة لكم ولا سلطان؛ هكذا يتحدّاهما الرحمن وهم يُساقون إلى ساحة فصل القضاء، فبأي آلاء ربكما تكذّبان: أبنعمة إحيائكما بعد موتكما، أم بنعمة إكرام صلحائكما وإهانة فاسديكما، وهي العدالة التي لا تساويها نعمة؟ يرسل عليكما لهب النار الخالص من الدخان، ونحاس وهو دخان خالص، فلا تنتصران إن أردتما الفرار من عدالتي وعدم الإذعان لحكمي فيكما.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان جلال الله وعظمته وقوة سلطانه.", "عجز الخلائق أمام خالقها عز وجل.", "وجوب حمد الله تعالى وشكره على السراء والضراء."], "k": "«كل يوم هو في شأن»… كم من شأن غيّره في حياتي بين يوم وليلة؛ فلماذا أيأس من تغيير حالي؟"}, {"lbl": "الآيات ٣٧ – ٤٥", "q": "فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتۡ وَرۡدَةٗ كَٱلدِّهَانِ ﴿٣٧﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٨﴾ فَيَوۡمَئِذٖ لَّا يُسۡـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٞ وَلَا جَآنّٞ ﴿٣٩﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٠﴾ يُعۡرَفُ ٱلۡمُجۡرِمُونَ بِسِيمَٰهُمۡ فَيُؤۡخَذُ بِٱلنَّوَٰصِي وَٱلۡأَقۡدَامِ ﴿٤١﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٢﴾ هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي يُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ ﴿٤٣﴾ يَطُوفُونَ بَيۡنَهَا وَبَيۡنَ حَمِيمٍ ءَانٖ ﴿٤٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٥﴾", "w": [["فإذا انشقّت السماء", "انفتحت أبواباً لنزول الملائكة إلى الأرض لتسوق الخلائق إلى المحشر."], ["فكانت وردة كالدهان", "صارت السماء محمرّة احمرار الأديم أو الفرس الأحمر، وذابت فكانت كالدهان في صفائها وذوبانها."], ["فيومئذ لا يُسأل عن ذنبه إنس ولا جانّ", "يوم يخرجون من قبورهم لا يُسألون عن ذنوبهم لما لهم من علامات كاسوداد الوجوه وبياضها، ويُسألون عند الحساب."], ["يُعرف المجرمون بسيماهم", "بسواد الوجوه وزرقة العيون."], ["فيؤخذ بالنواصي والأقدام", "تُضمّ ناصية المجرم إلى قدميه ويؤخذ فيُلقى في جهنم."], ["هذه جهنم التي يكذّب بها المجرمون", "يقال لهم توبيخاً وتبكيتاً: هذه جهنم التي يكذّب بها المجرمون في الدنيا، الذين أجرموا على أنفسهم بالشرك والمعاصي."], ["يطوفون بينها وبين حميم آن", "يسعون متردّدين بينها وبين ماء حار قد انتهت حرارته إلى حد لا مزيد عليه، يُسقونه إذا عطشوا واستغاثوا."]], "m": "ما زال السياق في عرض أحوال القيامة وأهوال الموقف: فإذا انشقّت السماء، أي تفتّحت لنزول الملائكة فكانت أبواباً، بعد أن احمرّت وتغيّرت زرقتها لحمرة كحمرة الأديم الأحمر أو الوردة الحمراء، وذابت فكانت كالدهان، كما جاء وصفها في سورة المعارج: «يوم تكون السماء كالمهل»، وهو دُرديّ الزيت وعكره. فيومئذ يعظم الكرب ويشتد البلاء، ويخرج الناس من قبورهم لا يُسأل عن ذنبه إنسيّ ولا جنيّ، فبأي آلاء ربكما تكذّبان؟ يُعرف المجرمون باسوداد وجوههم وزرقة أعينهم، فيجمع الملك المكلّف بين ناصية المجرم من الإنس أو الجن وقدميه، ويأخذه فيرمي به في نار جهنم؛ فبأي آلاء ربكما تكذّبان: أبنعمة العدالة أم بنعمة إكرام المتقين الصالحين؟ ويقال لهم توبيخاً: هذه جهنم التي يكذّب بها المجرمون على أنفسهم بالشرك والمعاصي في الحياة الدنيا، يسعون متردّدين بينها وبين ماء حار اشتدّت حرارته فبلغت حداً لا مزيد عليه، يُسقونه إذا استغاثوا من العطش. فبأي آلاء ربكما تكذّبان؟ إن خزي المجرمين وتعذيبهم نعمة تقرّها الفطرة البشرية، ولا يقدّرها إلا من ذاق طعم الخوف والعذاب الذي ينزله المجرمون بالمتقين، فلذا كان تعذيبهم يوم القيامة نعمة، كما أن هذا العرض لأحوال يوم القيامة وأهوالها نعمة، إذ عليه آمن المؤمنون واتقى المتقون.", "h": ["بيان الانقلاب الكوني وخراب العالم للقيامة.", "يُبعث الناس من قبورهم ولهم علامات تميّزهم، فيُعرف السعيد والشقي.", "التنديد بالإجرام، وهو الشرك والظلم والمعاصي."], "k": "«يُعرف المجرمون بسيماهم»… الوجوه يومئذ تفضح ما خفي؛ فماذا سيظهر على وجهي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 396;
insert into public.tdb_cards(topic, i, body) select 396, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٦ – ٣٦", "q": "كُلُّ مَنۡ عَلَيۡهَا فَانٖ ﴿٢٦﴾ وَيَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ ﴿٢٧﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٢٨﴾ يَسۡـَٔلُهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ كُلَّ يَوۡمٍ هُوَ فِي شَأۡنٖ ﴿٢٩﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٠﴾ سَنَفۡرُغُ لَكُمۡ أَيُّهَ ٱلثَّقَلَانِ ﴿٣١﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٢﴾ يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ أَن تَنفُذُواْ مِنۡ أَقۡطَارِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ فَٱنفُذُواْۚ لَا تَنفُذُونَ إِلَّا بِسُلۡطَٰنٖ ﴿٣٣﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٤﴾ يُرۡسَلُ عَلَيۡكُمَا شُوَاظٞ مِّن نَّارٖ وَنُحَاسٞ فَلَا تَنتَصِرَانِ ﴿٣٥﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٦﴾", "w": [["كل من عليها فان", "كل من على الأرض من إنسان وحيوان وجانّ فانٍ، أي هالك."], ["ويبقى وجه ربك", "ذاته ووجهه سبحانه وتعالى."], ["ذو الجلال والإكرام", "ذو العظمة، والإنعام على عباده عامة والمؤمنين بخاصة."], ["يسأله من في السماوات والأرض", "يسألونه حاجاتهم التي تتوقف عليها حياتهم من الرزق والقوة على العبادة والمغفرة للذنب."], ["كل يوم هو في شأن", "كل وقت هو في شأن، شؤون يبديها وفق تقديره لها، يرفع أقواماً ويضع آخرين."], ["سنفرغ لكم أيها الثقلان", "لحسابكم ومجازاتكم بعد انتهاء هذه الحياة الدنيا، ونجزي كلاً بما عمل."], ["إن استطعتم أن تنفذوا", "إن قدرتم على أن تخرجوا."], ["من أقطار السماوات والأرض", "من نواحي السماوات والأرض."], ["فانفذوا لا تنفذون إلا بسلطان", "فاخرجوا، لا تنفذون إلا بقوة، ولا قوة لكم، وهذا تعجيز."], ["يرسل عليكما شواظ من نار", "من لهب النار الخالص الذي لا دخان فيه."], ["ونحاس", "دخان لا لهب فيه، ولا يبعد أن يكون نحاساً مذاباً."], ["فلا تنتصران", "لا تمتنعان من السَّوق إلى المحشر."]], "m": "ما زال السياق في ذكر أيادي الرحمن الرحيم: كل من على الأرض من إنسان وجانّ وحيوان فانٍ هالك، ويبقى وجه ربك ذو الجلال والإكرام، حيّ لا يموت، والإنس والجن يموتون. فبأي آلاء ربكما تكذّبان: أبنعمة إيجادكما وإمدادكما بالأرزاق طوال الحياة، أم بنعمة إنهاء أتعابكما وتكاليفكما، أم بإهلاك أعدائكما وإدنائكما من النعيم المقيم؟ قولا خيراً لكما: لا بشيء من آلائك ربنا نكذّب، فلك الحمد. يسأله من في السماوات والأرض بلسان المقال أو الحال ما هم في حاجة إليه مما يحفظ وجودهم ويغفر ذنوبهم، كل يوم هو في شأن، لا يفرغ الدهر كله، يدبّر أمر السماء والأرض، يرفع أقواماً ويضع آخرين. سنفرغ لكم أيها الثقلان من الإنس والجن فنحاسبكما ونجزيكما، محسنكما بالإحسان، ومسيئكما بالسوء والخسران، وهذا يوم تقومان للرحمن حفاة عراة. يا معشر الجن والإنس، إن استطعتم أن تخرجوا من جوانب السماوات والأرض هاربين من قضائي وحكمي فاخرجوا، لا تنفذون إلا بقوة غالبة، ولا قوة لكم ولا سلطان؛ هكذا يتحدّاهما الرحمن وهم يُساقون إلى ساحة فصل القضاء، فبأي آلاء ربكما تكذّبان: أبنعمة إحيائكما بعد موتكما، أم بنعمة إكرام صلحائكما وإهانة فاسديكما، وهي العدالة التي لا تساويها نعمة؟ يرسل عليكما لهب النار الخالص من الدخان، ونحاس وهو دخان خالص، فلا تنتصران إن أردتما الفرار من عدالتي وعدم الإذعان لحكمي فيكما.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان جلال الله وعظمته وقوة سلطانه.", "عجز الخلائق أمام خالقها عز وجل.", "وجوب حمد الله تعالى وشكره على السراء والضراء."], "k": "«كل يوم هو في شأن»… كم من شأن غيّره في حياتي بين يوم وليلة؛ فلماذا أيأس من تغيير حالي؟"}, {"lbl": "الآيات ٣٧ – ٤٥", "q": "فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتۡ وَرۡدَةٗ كَٱلدِّهَانِ ﴿٣٧﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٨﴾ فَيَوۡمَئِذٖ لَّا يُسۡـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٞ وَلَا جَآنّٞ ﴿٣٩﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٠﴾ يُعۡرَفُ ٱلۡمُجۡرِمُونَ بِسِيمَٰهُمۡ فَيُؤۡخَذُ بِٱلنَّوَٰصِي وَٱلۡأَقۡدَامِ ﴿٤١﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٢﴾ هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي يُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ ﴿٤٣﴾ يَطُوفُونَ بَيۡنَهَا وَبَيۡنَ حَمِيمٍ ءَانٖ ﴿٤٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٥﴾", "w": [["فإذا انشقّت السماء", "انفتحت أبواباً لنزول الملائكة إلى الأرض لتسوق الخلائق إلى المحشر."], ["فكانت وردة كالدهان", "صارت السماء محمرّة احمرار الأديم أو الفرس الأحمر، وذابت فكانت كالدهان في صفائها وذوبانها."], ["فيومئذ لا يُسأل عن ذنبه إنس ولا جانّ", "يوم يخرجون من قبورهم لا يُسألون عن ذنوبهم لما لهم من علامات كاسوداد الوجوه وبياضها، ويُسألون عند الحساب."], ["يُعرف المجرمون بسيماهم", "بسواد الوجوه وزرقة العيون."], ["فيؤخذ بالنواصي والأقدام", "تُضمّ ناصية المجرم إلى قدميه ويؤخذ فيُلقى في جهنم."], ["هذه جهنم التي يكذّب بها المجرمون", "يقال لهم توبيخاً وتبكيتاً: هذه جهنم التي يكذّب بها المجرمون في الدنيا، الذين أجرموا على أنفسهم بالشرك والمعاصي."], ["يطوفون بينها وبين حميم آن", "يسعون متردّدين بينها وبين ماء حار قد انتهت حرارته إلى حد لا مزيد عليه، يُسقونه إذا عطشوا واستغاثوا."]], "m": "ما زال السياق في عرض أحوال القيامة وأهوال الموقف: فإذا انشقّت السماء، أي تفتّحت لنزول الملائكة فكانت أبواباً، بعد أن احمرّت وتغيّرت زرقتها لحمرة كحمرة الأديم الأحمر أو الوردة الحمراء، وذابت فكانت كالدهان، كما جاء وصفها في سورة المعارج: «يوم تكون السماء كالمهل»، وهو دُرديّ الزيت وعكره. فيومئذ يعظم الكرب ويشتد البلاء، ويخرج الناس من قبورهم لا يُسأل عن ذنبه إنسيّ ولا جنيّ، فبأي آلاء ربكما تكذّبان؟ يُعرف المجرمون باسوداد وجوههم وزرقة أعينهم، فيجمع الملك المكلّف بين ناصية المجرم من الإنس أو الجن وقدميه، ويأخذه فيرمي به في نار جهنم؛ فبأي آلاء ربكما تكذّبان: أبنعمة العدالة أم بنعمة إكرام المتقين الصالحين؟ ويقال لهم توبيخاً: هذه جهنم التي يكذّب بها المجرمون على أنفسهم بالشرك والمعاصي في الحياة الدنيا، يسعون متردّدين بينها وبين ماء حار اشتدّت حرارته فبلغت حداً لا مزيد عليه، يُسقونه إذا استغاثوا من العطش. فبأي آلاء ربكما تكذّبان؟ إن خزي المجرمين وتعذيبهم نعمة تقرّها الفطرة البشرية، ولا يقدّرها إلا من ذاق طعم الخوف والعذاب الذي ينزله المجرمون بالمتقين، فلذا كان تعذيبهم يوم القيامة نعمة، كما أن هذا العرض لأحوال يوم القيامة وأهوالها نعمة، إذ عليه آمن المؤمنون واتقى المتقون.", "h": ["بيان الانقلاب الكوني وخراب العالم للقيامة.", "يُبعث الناس من قبورهم ولهم علامات تميّزهم، فيُعرف السعيد والشقي.", "التنديد بالإجرام، وهو الشرك والظلم والمعاصي."], "k": "«يُعرف المجرمون بسيماهم»… الوجوه يومئذ تفضح ما خفي؛ فماذا سيظهر على وجهي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (397, 55, 46, 78, 'سورة الرحمن ٤٦ – ٧٨', 'الرحمن: هل جزاء الإحسان إلا الإحسان', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 397) = $j$[{"lbl": "الآيات ٤٦ – ٦١", "q": "وَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ ﴿٤٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٧﴾ ذَوَاتَآ أَفۡنَانٖ ﴿٤٨﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٩﴾ فِيهِمَا عَيۡنَانِ تَجۡرِيَانِ ﴿٥٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥١﴾ فِيهِمَا مِن كُلِّ فَٰكِهَةٖ زَوۡجَانِ ﴿٥٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٣﴾ مُتَّكِـِٔينَ عَلَىٰ فُرُشِۭ بَطَآئِنُهَا مِنۡ إِسۡتَبۡرَقٖۚ وَجَنَى ٱلۡجَنَّتَيۡنِ دَانٖ ﴿٥٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٥﴾ فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرۡفِ لَمۡ يَطۡمِثۡهُنَّ إِنسٞ قَبۡلَهُمۡ وَلَا جَآنّٞ ﴿٥٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٧﴾ كَأَنَّهُنَّ ٱلۡيَاقُوتُ وَٱلۡمَرۡجَانُ ﴿٥٨﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٩﴾ هَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ ﴿٦٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦١﴾", "w": [["ولمن خاف مقام ربه جنتان", "ولمن خاف الوقوف بين يدي الله في عرصات القيامة فآمن واتقى جنتان."], ["ذواتا أفنان", "ذواتا أغصان من شأنها أن تورق وتثمر وتمدّ الظل."], ["فيهما من كل فاكهة زوجان", "من كل ما يُتفكّه به من أنواع الفواكه صنفان."], ["بطائنها من إستبرق", "بطائن الفرش من إستبرق، وهو ما غلظ من الديباج، والظهائر من السندس، وهو ما رقّ منه."], ["وجنى الجنتين دان", "وما يُجنى من ثمار الجنة قريب التناول يناله القائم والقاعد والمضطجع."], ["فيهن قاصرات الطرف", "قاصرات النظر بأعينهن على أزواجهن فقط."], ["لم يطمثهن إنس قبلهم ولا جانّ", "لم يمسّهن قبل أزواجهن إنس ولا جانّ."], ["كأنهن الياقوت والمرجان", "كأنهن في جمالهن الياقوت في صفائه، والمرجان في بياضه."], ["هل جزاء الإحسان إلا الإحسان", "ما جزاء الإحسان بالطاعة إلا الإحسان بالنعيم."]], "m": "ما زال السياق في تعداد النعم: ولمن خاف الوقوف بين يدي ربه يوم القيامة فأطاعه بأداء الفرائض واجتناب المحرمات جنتان، أي بستانان، فبأي آلاء ربكما تكذّبان: أبإثابة أحدكم الذي إذا همّ بالمعصية ذكر قيامه بين يدي ربه فتركها؟ ذواتا أفنان، ولأشجارهما أغصان تورق وتثمر وتمدّ الظلال. فيهما عينان تجريان بالماء العذب الزلال خلال تلك القصور والأشجار. فيهما من كل فاكهة صنفان، فلا يُكتفى بصنف واحد إتماماً للنعيم. متكئين على فرش بطائنها من إستبرق، وهو الغليظ من الديباج، أما الظواهر فهي السندس، وثمار الجنتين قريبة التناول يتناولها المتقي وهو مضطجع أو قاعد أو قائم، لا شوك فيها ولا بُعد. وفي الجنتين نساء من الحور العين قاصرات الطرف على أزواجهن، فلا تنظر إلا إلى زوجها، وتقول له: وعزة ربي وجلاله ما أرى في الجنة شيئاً أحسن منك، فالحمد لله الذي جعلك زوجي وجعلني زوجك. لم يمسّهن قبل أزواجهن إنس ولا جانّ، كأنهن الياقوت في صفائهن والمرجان في بياضهن. هل جزاء الإحسان في الإيمان والطاعات إلا الإحسان إليه بمثل هذا النعيم العظيم؟ فبأي آلاء ربكما تكذّبان يا معشر الإنس والجان؟ فقولا: لا بشيء من آلاء ربنا نكذّب، فلك الحمد.", "h": ["فضل الخوف من الله تعالى، وذلك كأن تعرض للعبد المعصية فيتركها خوفاً من الله تعالى.", "فضل نساء أهل الجنة في حبهن لأزواجهن، بحيث لا ينظرن إلا إليهم.", "بيان أن أفضل النساء في الدنيا تلك التي تقصر نظرها على زوجها فتحبه ولا تحب غيره.", "بيان أن الجن المتقين يدخلون الجنة ولهم أزواج كما للإنس سواءً بسواء.", "الإشادة بالإحسان وبيان جزائه، والإحسان هو إخلاص العبادة لله والإتيان بها على الوجه الذي شُرع أداؤها عليه، مع الإحسان إلى الخلق بكفّ الأذى عنهم وبذل الفضل لمن احتاجه منهم."], "k": "«ولمن خاف مقام ربه جنتان»… كل معصية أتركها خوفاً منه خطوة إلى الجنتين؛ فماذا أترك اليوم؟"}, {"lbl": "الآيات ٦٢ – ٧٨", "q": "وَمِن دُونِهِمَا جَنَّتَانِ ﴿٦٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٣﴾ مُدۡهَآمَّتَانِ ﴿٦٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٥﴾ فِيهِمَا عَيۡنَانِ نَضَّاخَتَانِ ﴿٦٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٧﴾ فِيهِمَا فَٰكِهَةٞ وَنَخۡلٞ وَرُمَّانٞ ﴿٦٨﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٩﴾ فِيهِنَّ خَيۡرَٰتٌ حِسَانٞ ﴿٧٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧١﴾ حُورٞ مَّقۡصُورَٰتٞ فِي ٱلۡخِيَامِ ﴿٧٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧٣﴾ لَمۡ يَطۡمِثۡهُنَّ إِنسٞ قَبۡلَهُمۡ وَلَا جَآنّٞ ﴿٧٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧٥﴾ مُتَّكِـِٔينَ عَلَىٰ رَفۡرَفٍ خُضۡرٖ وَعَبۡقَرِيٍّ حِسَانٖ ﴿٧٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧٧﴾ تَبَٰرَكَ ٱسۡمُ رَبِّكَ ذِي ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ ﴿٧٨﴾", "w": [["ومن دونهما جنتان", "ومن دون تينك الجنتين جنتان أخريان لمن خاف مقام ربه."], ["مُدهامّتان", "مسودّتان من شدة خضرتهما."], ["فيهما عينان نضّاختان", "فوّارتان دائماً وأبداً بالماء العذب الزلال."], ["فيهن خيرات حسان", "في الجنات نساء خيّرات الأخلاق، حسان الوجوه."], ["حور", "بيض، والواحدة حوراء."], ["مقصورات في الخيام", "مستورات محبوسات على أزواجهن في الخيام، والخيمة من درّ مجوّف مضافة إلى القصور، طول الواحدة ستون ميلاً."], ["لم يطمثهن إنس قبلهم ولا جانّ", "لم يمسّهن قبل أزواجهن في الجنة أحد."], ["متكئين على رفرف خضر", "على وسائد أو بُسط خضر."], ["وعبقريّ حسان", "طنافس، وهي بُسط لها خمل رقيق."], ["تبارك اسم ربك", "تقدّس وكثرت بركة اسم ربك الرحمن."], ["ذي الجلال والإكرام", "ذي العظمة، والإكرام لأوليائه، والإحسان إلى عباده."]], "m": "ما زال السياق في ذكر إنعام الله تعالى وإفضاله على عباده: ومن دون تينك الجنتين جنتان أخريان؛ تلك لمن خاف مقام ربه من السابقين، وهاتان لمن خاف مقام ربه من أصحاب اليمين، وقد يكون العكس، والله أعلم بأي الجنتين أفضل. مدهامّتان: مخضرّتان إلى حد الاسوداد، فإن الأخضر إذا اشتدّت خضرته ضرب إلى السواد. فيهما عينان فوّارتان بالماء دائماً وأبداً. فيهما فاكهة ونخل ورمان؛ لفظ الفاكهة قد يعمّ النخل والرمان، وذكرهما لمزيد فضيلة، كذكر الصلاة الوسطى بعد ذكر الصلوات في قوله: «حافظوا على الصلوات والصلاة الوسطى». فيهن خيرات الأخلاق حسان الوجوه، حور بيض يغلب بياض أعينهن سوادها، وهو من جمال النساء، محبوسات في الخيام لا ينظرن إلى غير أزواجهن، والخيمة من درّة مجوّفة مضافة إلى قصورهم. لم يمسّهن إنس ولا جانّ من قبل أزواجهن في الجنة، متكئين على وسائد أو بُسط خضر، وعلى طنافس ذات خمل دقيق، فبأي آلاء ربكما تكذّبان: بنعم الدنيا أم بنعم البرزخ أم بنعم الآخرة؟ لا بشيء من آلاء ربنا نكذّب. تبارك اسم ربك، أي تقدّس وكثرت بركات اسم ربك الرحمن، ذي العظمة والإكرام لأوليائه وصالحي عباده.", "h": ["بيان أن نعيم الآخرة أعظم وأجلّ من نعم الدنيا.", "فضيلة التمر والرمان.", "فضل المرأة المقصورة في بيتها، وذمّ الولّاجة الخرّاجة، كما قال ابن عباس رضي الله عنهما.", "بيان أن الجن يدخلون الجنة ويسعدون فيها.", "البركة تُنال ببسم الله الرحمن الرحيم."], "k": "«تبارك اسم ربك»… البركة في اسمه؛ فهل أبدأ أعمالي كلها بـ«بسم الله»؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 397;
insert into public.tdb_cards(topic, i, body) select 397, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٦ – ٦١", "q": "وَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ ﴿٤٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٧﴾ ذَوَاتَآ أَفۡنَانٖ ﴿٤٨﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٤٩﴾ فِيهِمَا عَيۡنَانِ تَجۡرِيَانِ ﴿٥٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥١﴾ فِيهِمَا مِن كُلِّ فَٰكِهَةٖ زَوۡجَانِ ﴿٥٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٣﴾ مُتَّكِـِٔينَ عَلَىٰ فُرُشِۭ بَطَآئِنُهَا مِنۡ إِسۡتَبۡرَقٖۚ وَجَنَى ٱلۡجَنَّتَيۡنِ دَانٖ ﴿٥٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٥﴾ فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرۡفِ لَمۡ يَطۡمِثۡهُنَّ إِنسٞ قَبۡلَهُمۡ وَلَا جَآنّٞ ﴿٥٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٧﴾ كَأَنَّهُنَّ ٱلۡيَاقُوتُ وَٱلۡمَرۡجَانُ ﴿٥٨﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٥٩﴾ هَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ ﴿٦٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦١﴾", "w": [["ولمن خاف مقام ربه جنتان", "ولمن خاف الوقوف بين يدي الله في عرصات القيامة فآمن واتقى جنتان."], ["ذواتا أفنان", "ذواتا أغصان من شأنها أن تورق وتثمر وتمدّ الظل."], ["فيهما من كل فاكهة زوجان", "من كل ما يُتفكّه به من أنواع الفواكه صنفان."], ["بطائنها من إستبرق", "بطائن الفرش من إستبرق، وهو ما غلظ من الديباج، والظهائر من السندس، وهو ما رقّ منه."], ["وجنى الجنتين دان", "وما يُجنى من ثمار الجنة قريب التناول يناله القائم والقاعد والمضطجع."], ["فيهن قاصرات الطرف", "قاصرات النظر بأعينهن على أزواجهن فقط."], ["لم يطمثهن إنس قبلهم ولا جانّ", "لم يمسّهن قبل أزواجهن إنس ولا جانّ."], ["كأنهن الياقوت والمرجان", "كأنهن في جمالهن الياقوت في صفائه، والمرجان في بياضه."], ["هل جزاء الإحسان إلا الإحسان", "ما جزاء الإحسان بالطاعة إلا الإحسان بالنعيم."]], "m": "ما زال السياق في تعداد النعم: ولمن خاف الوقوف بين يدي ربه يوم القيامة فأطاعه بأداء الفرائض واجتناب المحرمات جنتان، أي بستانان، فبأي آلاء ربكما تكذّبان: أبإثابة أحدكم الذي إذا همّ بالمعصية ذكر قيامه بين يدي ربه فتركها؟ ذواتا أفنان، ولأشجارهما أغصان تورق وتثمر وتمدّ الظلال. فيهما عينان تجريان بالماء العذب الزلال خلال تلك القصور والأشجار. فيهما من كل فاكهة صنفان، فلا يُكتفى بصنف واحد إتماماً للنعيم. متكئين على فرش بطائنها من إستبرق، وهو الغليظ من الديباج، أما الظواهر فهي السندس، وثمار الجنتين قريبة التناول يتناولها المتقي وهو مضطجع أو قاعد أو قائم، لا شوك فيها ولا بُعد. وفي الجنتين نساء من الحور العين قاصرات الطرف على أزواجهن، فلا تنظر إلا إلى زوجها، وتقول له: وعزة ربي وجلاله ما أرى في الجنة شيئاً أحسن منك، فالحمد لله الذي جعلك زوجي وجعلني زوجك. لم يمسّهن قبل أزواجهن إنس ولا جانّ، كأنهن الياقوت في صفائهن والمرجان في بياضهن. هل جزاء الإحسان في الإيمان والطاعات إلا الإحسان إليه بمثل هذا النعيم العظيم؟ فبأي آلاء ربكما تكذّبان يا معشر الإنس والجان؟ فقولا: لا بشيء من آلاء ربنا نكذّب، فلك الحمد.", "h": ["فضل الخوف من الله تعالى، وذلك كأن تعرض للعبد المعصية فيتركها خوفاً من الله تعالى.", "فضل نساء أهل الجنة في حبهن لأزواجهن، بحيث لا ينظرن إلا إليهم.", "بيان أن أفضل النساء في الدنيا تلك التي تقصر نظرها على زوجها فتحبه ولا تحب غيره.", "بيان أن الجن المتقين يدخلون الجنة ولهم أزواج كما للإنس سواءً بسواء.", "الإشادة بالإحسان وبيان جزائه، والإحسان هو إخلاص العبادة لله والإتيان بها على الوجه الذي شُرع أداؤها عليه، مع الإحسان إلى الخلق بكفّ الأذى عنهم وبذل الفضل لمن احتاجه منهم."], "k": "«ولمن خاف مقام ربه جنتان»… كل معصية أتركها خوفاً منه خطوة إلى الجنتين؛ فماذا أترك اليوم؟"}, {"lbl": "الآيات ٦٢ – ٧٨", "q": "وَمِن دُونِهِمَا جَنَّتَانِ ﴿٦٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٣﴾ مُدۡهَآمَّتَانِ ﴿٦٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٥﴾ فِيهِمَا عَيۡنَانِ نَضَّاخَتَانِ ﴿٦٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٧﴾ فِيهِمَا فَٰكِهَةٞ وَنَخۡلٞ وَرُمَّانٞ ﴿٦٨﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٦٩﴾ فِيهِنَّ خَيۡرَٰتٌ حِسَانٞ ﴿٧٠﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧١﴾ حُورٞ مَّقۡصُورَٰتٞ فِي ٱلۡخِيَامِ ﴿٧٢﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧٣﴾ لَمۡ يَطۡمِثۡهُنَّ إِنسٞ قَبۡلَهُمۡ وَلَا جَآنّٞ ﴿٧٤﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧٥﴾ مُتَّكِـِٔينَ عَلَىٰ رَفۡرَفٍ خُضۡرٖ وَعَبۡقَرِيٍّ حِسَانٖ ﴿٧٦﴾ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٧٧﴾ تَبَٰرَكَ ٱسۡمُ رَبِّكَ ذِي ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ ﴿٧٨﴾", "w": [["ومن دونهما جنتان", "ومن دون تينك الجنتين جنتان أخريان لمن خاف مقام ربه."], ["مُدهامّتان", "مسودّتان من شدة خضرتهما."], ["فيهما عينان نضّاختان", "فوّارتان دائماً وأبداً بالماء العذب الزلال."], ["فيهن خيرات حسان", "في الجنات نساء خيّرات الأخلاق، حسان الوجوه."], ["حور", "بيض، والواحدة حوراء."], ["مقصورات في الخيام", "مستورات محبوسات على أزواجهن في الخيام، والخيمة من درّ مجوّف مضافة إلى القصور، طول الواحدة ستون ميلاً."], ["لم يطمثهن إنس قبلهم ولا جانّ", "لم يمسّهن قبل أزواجهن في الجنة أحد."], ["متكئين على رفرف خضر", "على وسائد أو بُسط خضر."], ["وعبقريّ حسان", "طنافس، وهي بُسط لها خمل رقيق."], ["تبارك اسم ربك", "تقدّس وكثرت بركة اسم ربك الرحمن."], ["ذي الجلال والإكرام", "ذي العظمة، والإكرام لأوليائه، والإحسان إلى عباده."]], "m": "ما زال السياق في ذكر إنعام الله تعالى وإفضاله على عباده: ومن دون تينك الجنتين جنتان أخريان؛ تلك لمن خاف مقام ربه من السابقين، وهاتان لمن خاف مقام ربه من أصحاب اليمين، وقد يكون العكس، والله أعلم بأي الجنتين أفضل. مدهامّتان: مخضرّتان إلى حد الاسوداد، فإن الأخضر إذا اشتدّت خضرته ضرب إلى السواد. فيهما عينان فوّارتان بالماء دائماً وأبداً. فيهما فاكهة ونخل ورمان؛ لفظ الفاكهة قد يعمّ النخل والرمان، وذكرهما لمزيد فضيلة، كذكر الصلاة الوسطى بعد ذكر الصلوات في قوله: «حافظوا على الصلوات والصلاة الوسطى». فيهن خيرات الأخلاق حسان الوجوه، حور بيض يغلب بياض أعينهن سوادها، وهو من جمال النساء، محبوسات في الخيام لا ينظرن إلى غير أزواجهن، والخيمة من درّة مجوّفة مضافة إلى قصورهم. لم يمسّهن إنس ولا جانّ من قبل أزواجهن في الجنة، متكئين على وسائد أو بُسط خضر، وعلى طنافس ذات خمل دقيق، فبأي آلاء ربكما تكذّبان: بنعم الدنيا أم بنعم البرزخ أم بنعم الآخرة؟ لا بشيء من آلاء ربنا نكذّب. تبارك اسم ربك، أي تقدّس وكثرت بركات اسم ربك الرحمن، ذي العظمة والإكرام لأوليائه وصالحي عباده.", "h": ["بيان أن نعيم الآخرة أعظم وأجلّ من نعم الدنيا.", "فضيلة التمر والرمان.", "فضل المرأة المقصورة في بيتها، وذمّ الولّاجة الخرّاجة، كما قال ابن عباس رضي الله عنهما.", "بيان أن الجن يدخلون الجنة ويسعدون فيها.", "البركة تُنال ببسم الله الرحمن الرحيم."], "k": "«تبارك اسم ربك»… البركة في اسمه؛ فهل أبدأ أعمالي كلها بـ«بسم الله»؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (398, 56, 1, 40, 'سورة الواقعة ١ – ٤٠', 'الواقعة: والسابقون السابقون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 398) = $j$[{"lbl": "الآيات ١ – ١٢", "q": "إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ ﴿١﴾ لَيۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ ﴿٢﴾ خَافِضَةٞ رَّافِعَةٌ ﴿٣﴾ إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجّٗا ﴿٤﴾ وَبُسَّتِ ٱلۡجِبَالُ بَسّٗا ﴿٥﴾ فَكَانَتۡ هَبَآءٗ مُّنۢبَثّٗا ﴿٦﴾ وَكُنتُمۡ أَزۡوَٰجٗا ثَلَٰثَةٗ ﴿٧﴾ فَأَصۡحَٰبُ ٱلۡمَيۡمَنَةِ مَآ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ ﴿٨﴾ وَأَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ مَآ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ ﴿٩﴾ وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ ﴿١٠﴾ أُوْلَـٰٓئِكَ ٱلۡمُقَرَّبُونَ ﴿١١﴾ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿١٢﴾", "w": [["إذا وقعت الواقعة", "قامت القيامة، وقيل لها الواقعة لأنها واقعة لا محالة."], ["ليس لوقعتها كاذبة", "ليس هناك نفس تكذّب بها فتنفيها كما نفتها في الدنيا."], ["خافضة رافعة", "مظهرة لخفض أقوام بدخولهم النار، ولرفع آخرين بدخولهم الجنة."], ["إذا رُجّت الأرض رجّاً", "حُرّكت حركة شديدة."], ["وبُسّت الجبال بسّاً", "فُتّتت تفتيتاً."], ["فكانت هباءً منبثّاً", "غباراً منتشراً."], ["وكنتم أزواجاً ثلاثة", "أصنافاً ثلاثة."], ["فأصحاب الميمنة ما أصحاب الميمنة", "الذين يؤتون كتبهم بأيمانهم، وفيه تعظيم لشأنهم بدخولهم الجنة."], ["وأصحاب المشأمة ما أصحاب المشأمة", "أصحاب الشمال الذين يؤتون كتبهم بشمائلهم، وفيه تحقير لشأنهم بدخولهم النار."], ["والسابقون السابقون", "الذين سبقوا إلى الإيمان والطاعة، وفيه تعظيم لشأنهم."], ["أولئك المقرّبون", "الذين يقرّبهم الله منه يوم القيامة."], ["في جنات النعيم", "في بساتين النعيم الدائم."]], "m": "هذا في تقرير البعث والجزاء الذي كذّب به المشركون وأنكروه في إصرار وعناد: إذا قامت القيامة، ليس لوقعتها نفس تكذّب بها، إذ يؤمن بها الجميع، خافضة لأقوام مظهرة لحالهم بأنهم أهل النار، رافعة لآخرين مظهرة لحالهم بأنهم من أهل الجنة. إذا حُرّكت الأرض حركة شديدة، وفُتّتت الجبال تفتيتاً فكانت غباراً منتشراً، وكنتم أيها الناس أنواعاً ثلاثة: أصحاب اليمين، وأصحاب الشمال، والمقرّبون. فأصحاب الميمنة الذين يؤتون كتبهم بأيمانهم، شأنهم عظيم، وذلك بدخولهم الجنة دار النعيم. وأصحاب المشأمة الذين يؤتون كتبهم بشمائلهم، شأنهم حقير، وذلك بدخولهم النار. والسابقون إلى الإيمان والطاعة في أول ظهور الدعوة السابقون، هذا تعظيم لشأنهم وإعلان عن فوزهم وكرامتهم في جنات النعيم، وهي بساتين ذات نعيم دائم.", "h": ["تقرير البعث والجزاء في الآخرة.", "الإيمان والتقوى يرفعان، والشرك والمعاصي يضعان ويخفضان.", "السابقون إلى الطاعات لهم فضل الأسبقية في كل زمان ومكان.", "اليساريون هم أشقياء الدنيا والآخرة، لأنهم عندما أخذ غيرهم ذات اليمين طالبين الإيمان والاستقامة أخذوا هم ذات الشمال طالبين الكفر والفسوق."], "k": "«خافضة رافعة»… يومها يرتفع من كان منسياً ويُخفض من كان مرفوعاً؛ فبماذا أرتفع أنا؟"}, {"lbl": "الآيات ١٣ – ٢٦", "q": "ثُلَّةٞ مِّنَ ٱلۡأَوَّلِينَ ﴿١٣﴾ وَقَلِيلٞ مِّنَ ٱلۡأٓخِرِينَ ﴿١٤﴾ عَلَىٰ سُرُرٖ مَّوۡضُونَةٖ ﴿١٥﴾ مُّتَّكِـِٔينَ عَلَيۡهَا مُتَقَٰبِلِينَ ﴿١٦﴾ يَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ ﴿١٧﴾ بِأَكۡوَابٖ وَأَبَارِيقَ وَكَأۡسٖ مِّن مَّعِينٖ ﴿١٨﴾ لَّا يُصَدَّعُونَ عَنۡهَا وَلَا يُنزِفُونَ ﴿١٩﴾ وَفَٰكِهَةٖ مِّمَّا يَتَخَيَّرُونَ ﴿٢٠﴾ وَلَحۡمِ طَيۡرٖ مِّمَّا يَشۡتَهُونَ ﴿٢١﴾ وَحُورٌ عِينٞ ﴿٢٢﴾ كَأَمۡثَٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ ﴿٢٣﴾ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ﴿٢٤﴾ لَا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا تَأۡثِيمًا ﴿٢٥﴾ إِلَّا قِيلٗا سَلَٰمٗا سَلَٰمٗا ﴿٢٦﴾", "w": [["ثلّة من الأولين", "جماعة من الأمم الماضية."], ["وقليل من الآخرين", "من أمة محمد ﷺ، هؤلاء هم السابقون."], ["على سرر موضونة", "منسوجة مشبّكة بالذهب والجواهر."], ["ولدان مخلّدون", "على شكل الأولاد، لا يهرمون، فيخدمونهم أبداً."], ["بأكواب وأباريق", "أكواب: أقداح لا عرى لها، وأباريق: لها عرى وخراطيم."], ["وكأس من معين", "وإناء لشرب الخمر من نهر جارٍ لا ينقطع."], ["لا يُصدّعون عنها", "لا يحصل لهم من شربها صداع."], ["ولا يُنزفون", "ولا تذهب عقولهم."], ["وفاكهة مما يتخيّرون", "يختارون منها ما يروق لهم ويعجبهم، وإن كانت كلها معجبة."], ["وحور عين", "نساء بيض واسعات الأعين، شديدات سواد العيون وبياضها."], ["كأمثال اللؤلؤ المكنون", "في جمالهن وصفائهن كاللؤلؤ المصون."], ["لا يسمعون فيها لغواً ولا تأثيماً", "لا يسمعون في الجنة فاحش الكلام وما لا خير فيه، ولا ما يوقع في الإثم."], ["إلا قيلاً سلاماً سلاماً", "لا يسمعون إلا السلام من الملائكة ومن بعضهم على بعض."]], "m": "ما زال السياق في بيان أحوال الناس إذا قامت القيامة، وهنا يقول في السابقين: إنهم ثلة من الأولين، من الأمم الماضية الذين سبقوا إلى الإسلام مع أنبيائهم، وقليل من الآخرين، من هذه الأمة، وهم الذين سبقوا إلى الإيمان والهجرة والجهاد. ثم يذكر نعيمهم: إنهم على سرر منسوجة مشبّكة بالذهب والجواهر، متكئين عليها متقابلين، لا ينظر أحدهم إلى قفا الآخر بل إلى وجهه، يطوف عليهم للخدمة غلمان مخلّدون لا يكبرون فيهرمون ولا يتغيّرون، بأكواب لا عرى لها، وأباريق لها عرى وخراطيم، وكأس من نهر الخمر الجاري لا ينضب، لا يصيبهم صداع من شربها ولا تذهب عقولهم، بخلاف خمر الدنيا. ويطوف عليهم الغلمان بفاكهة مما يختارون، ولحم طير مما تشتهيه أنفسهم، ولهم في الجنة حور عين، والحَوَر أن يكون بياض العين أكثر من سوادها، وهو ضرب من الجمال، كأمثال اللؤلؤ المصون في صدفه، يريد أنهن جميلات مصونات غير مبتذلات. جزاهم ربهم ذلك جزاء بما كانوا يعملون من الصالحات بعد الإيمان والتوحيد وترك المعاصي. ومن إتمام النعيم أنهم لا يسمعون في الجنة ما يكدّر صفو نعيمهم من قول بذيء، فلا يسمعون فيها كلاماً فاحشاً ولا ما يؤثم قائله وسامعه، إلا قولاً سلاماً سلاماً: سلام الرب تعالى عليهم، وهو أكبر نعيمهم، وسلام الملائكة عليهم، وسلام بعضهم على بعض.", "h": ["تقرير البعث والجزاء بذكر أحوال الدار الآخرة.", "بيان شيء من نعيم أهل الجنة، وخاصة السابقين منهم.", "بيان أن السابقين يكونون من سائر الأمم المسلمة.", "بيان فضل خمر الجنة على خمر الدنيا المحرّمة.", "تقرير قاعدة أن الجزاء من جنس العمل."], "k": "«إلا قيلاً سلاماً سلاماً»… في الجنة لا يُسمع إلا السلام؛ فهل يسمع الناس مني اليوم ما يشبه ذلك؟"}, {"lbl": "الآيات ٢٧ – ٤٠", "q": "وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ أَصۡحَٰبُ ٱلۡيَمِينِ ﴿٢٧﴾ فِي سِدۡرٖ مَّخۡضُودٖ ﴿٢٨﴾ وَطَلۡحٖ مَّنضُودٖ ﴿٢٩﴾ وَظِلّٖ مَّمۡدُودٖ ﴿٣٠﴾ وَمَآءٖ مَّسۡكُوبٖ ﴿٣١﴾ وَفَٰكِهَةٖ كَثِيرَةٖ ﴿٣٢﴾ لَّا مَقۡطُوعَةٖ وَلَا مَمۡنُوعَةٖ ﴿٣٣﴾ وَفُرُشٖ مَّرۡفُوعَةٍ ﴿٣٤﴾ إِنَّآ أَنشَأۡنَٰهُنَّ إِنشَآءٗ ﴿٣٥﴾ فَجَعَلۡنَٰهُنَّ أَبۡكَارًا ﴿٣٦﴾ عُرُبًا أَتۡرَابٗا ﴿٣٧﴾ لِّأَصۡحَٰبِ ٱلۡيَمِينِ ﴿٣٨﴾ ثُلَّةٞ مِّنَ ٱلۡأَوَّلِينَ ﴿٣٩﴾ وَثُلَّةٞ مِّنَ ٱلۡأٓخِرِينَ ﴿٤٠﴾", "w": [["وأصحاب اليمين ما أصحاب اليمين", "هذا شروع في ذكر الصنف الثاني من الأصناف الثلاثة وما أُعدّ لهم."], ["في سدر مخضود", "في شجر السدر، وثمره النبق، مخضود: لا شوك فيه."], ["وطلح منضود", "شجر موز منضود الحمل من أعلاه إلى أسفله."], ["وظل ممدود", "دائم، إذ لا شمس تنسخه، وإن في الجنة شجرة يسير الراكب في ظلها مائة سنة لا يقطعها."], ["وماء مسكوب", "مصبوب لا يحتاج المتنعّم أن يصبّه بيده، بل هو سائل في غير أخدود."], ["لا مقطوعة ولا ممنوعة", "غير مقطوعة في زمن، ولا ممنوعة بثمن."], ["وفرش مرفوعة", "على السرر العالية الرفيعة."], ["إنا أنشأناهن إنشاءً", "أي الحور العين، ومنهن من كانت في الدنيا عجوزاً فأنشأها ربها إنشاءً جديداً."], ["فجعلناهن أبكاراً", "الواحدة بكر، وهي العذراء."], ["عُرُباً", "الواحدة عَروب، وهي المتحبّبة إلى زوجها."], ["أتراباً", "مستويات في السن، الواحدة يقال لها ترب."], ["لأصحاب اليمين", "وهم الذين يؤخذ بهم في عرصات القيامة ذات اليمين، وهم أهل الإيمان والعمل الصالح في الدنيا."], ["ثلّة من الأولين", "من الأمم السابقة."], ["وثلّة من الآخرين", "من أمة محمد ﷺ."]], "m": "ما زال السياق في عرض أحوال الآخرة وذكر ما لكل صنف من أصناف الناس الثلاثة: وأصحاب اليمين، وهم الذين إذا وقفوا في عرصات القيامة أُخذ بهم ذات اليمين، وهم أهل الإيمان والتقوى في الدنيا، ما أصحاب اليمين؟ تفخيم لشأنهم وإعلان عن كرامتهم، ثم بيّن ذلك: إنهم في هذا النعيم الدائم المقيم، يتفكّهون بالنبق الذي هو أحلى من العسل وأنعم من الزبد، شجره مخضود لا شوك به، ويتفكّهون بالطلح وهو الموز، والماء المصبوب الجاري، والفاكهة الكثيرة التي لا تنقطع بالفصول الزمانية كما هي الحال في فاكهة الدنيا، يوجد منها في الصيف ما لا يوجد في الشتاء، وفرش مرفوعة عالية علوّ الدرجات التي هي فيها. إنا أنشأناهن إنشاءً: يعني الحور العين؛ منهن من أنشأهن الله إنشاءً لم يسبق لهن خلق، ومنهن نساء الدنيا، فقد كانت فيهن السوداء والعجوز، فيعيد تعالى إنشاءهن فيجعلهن من بين الحور العين كأنهن اللؤلؤ المكنون، فجعلناهن أبكاراً عذارى، عُرُباً متحبّبات إلى أزواجهن، أتراباً متساويات في السن، أنشأهن لأجل أصحاب اليمين. وأصحاب اليمين ثلة من الأمم الماضية، وثلة من هذه الأمة المسلمة.", "h": ["بيان إكرام الله وإنعامه على المؤمنين المتقين.", "بيان أن العجوز في الدنيا إذا دخلت الجنة تصير شابة حسناء حوراء عَروباً.", "تقرير أن ثمن الجنة الإيمان والتقوى، فلا دخل للحسب ولا للنسب."], "k": "«لا مقطوعة ولا ممنوعة»… نعيم الدنيا ينقطع أو يُمنع، ونعيمه هناك لا؛ فعلى أيهما أتحسّر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 398;
insert into public.tdb_cards(topic, i, body) select 398, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٢", "q": "إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ ﴿١﴾ لَيۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ ﴿٢﴾ خَافِضَةٞ رَّافِعَةٌ ﴿٣﴾ إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجّٗا ﴿٤﴾ وَبُسَّتِ ٱلۡجِبَالُ بَسّٗا ﴿٥﴾ فَكَانَتۡ هَبَآءٗ مُّنۢبَثّٗا ﴿٦﴾ وَكُنتُمۡ أَزۡوَٰجٗا ثَلَٰثَةٗ ﴿٧﴾ فَأَصۡحَٰبُ ٱلۡمَيۡمَنَةِ مَآ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ ﴿٨﴾ وَأَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ مَآ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ ﴿٩﴾ وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ ﴿١٠﴾ أُوْلَـٰٓئِكَ ٱلۡمُقَرَّبُونَ ﴿١١﴾ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿١٢﴾", "w": [["إذا وقعت الواقعة", "قامت القيامة، وقيل لها الواقعة لأنها واقعة لا محالة."], ["ليس لوقعتها كاذبة", "ليس هناك نفس تكذّب بها فتنفيها كما نفتها في الدنيا."], ["خافضة رافعة", "مظهرة لخفض أقوام بدخولهم النار، ولرفع آخرين بدخولهم الجنة."], ["إذا رُجّت الأرض رجّاً", "حُرّكت حركة شديدة."], ["وبُسّت الجبال بسّاً", "فُتّتت تفتيتاً."], ["فكانت هباءً منبثّاً", "غباراً منتشراً."], ["وكنتم أزواجاً ثلاثة", "أصنافاً ثلاثة."], ["فأصحاب الميمنة ما أصحاب الميمنة", "الذين يؤتون كتبهم بأيمانهم، وفيه تعظيم لشأنهم بدخولهم الجنة."], ["وأصحاب المشأمة ما أصحاب المشأمة", "أصحاب الشمال الذين يؤتون كتبهم بشمائلهم، وفيه تحقير لشأنهم بدخولهم النار."], ["والسابقون السابقون", "الذين سبقوا إلى الإيمان والطاعة، وفيه تعظيم لشأنهم."], ["أولئك المقرّبون", "الذين يقرّبهم الله منه يوم القيامة."], ["في جنات النعيم", "في بساتين النعيم الدائم."]], "m": "هذا في تقرير البعث والجزاء الذي كذّب به المشركون وأنكروه في إصرار وعناد: إذا قامت القيامة، ليس لوقعتها نفس تكذّب بها، إذ يؤمن بها الجميع، خافضة لأقوام مظهرة لحالهم بأنهم أهل النار، رافعة لآخرين مظهرة لحالهم بأنهم من أهل الجنة. إذا حُرّكت الأرض حركة شديدة، وفُتّتت الجبال تفتيتاً فكانت غباراً منتشراً، وكنتم أيها الناس أنواعاً ثلاثة: أصحاب اليمين، وأصحاب الشمال، والمقرّبون. فأصحاب الميمنة الذين يؤتون كتبهم بأيمانهم، شأنهم عظيم، وذلك بدخولهم الجنة دار النعيم. وأصحاب المشأمة الذين يؤتون كتبهم بشمائلهم، شأنهم حقير، وذلك بدخولهم النار. والسابقون إلى الإيمان والطاعة في أول ظهور الدعوة السابقون، هذا تعظيم لشأنهم وإعلان عن فوزهم وكرامتهم في جنات النعيم، وهي بساتين ذات نعيم دائم.", "h": ["تقرير البعث والجزاء في الآخرة.", "الإيمان والتقوى يرفعان، والشرك والمعاصي يضعان ويخفضان.", "السابقون إلى الطاعات لهم فضل الأسبقية في كل زمان ومكان.", "اليساريون هم أشقياء الدنيا والآخرة، لأنهم عندما أخذ غيرهم ذات اليمين طالبين الإيمان والاستقامة أخذوا هم ذات الشمال طالبين الكفر والفسوق."], "k": "«خافضة رافعة»… يومها يرتفع من كان منسياً ويُخفض من كان مرفوعاً؛ فبماذا أرتفع أنا؟"}, {"lbl": "الآيات ١٣ – ٢٦", "q": "ثُلَّةٞ مِّنَ ٱلۡأَوَّلِينَ ﴿١٣﴾ وَقَلِيلٞ مِّنَ ٱلۡأٓخِرِينَ ﴿١٤﴾ عَلَىٰ سُرُرٖ مَّوۡضُونَةٖ ﴿١٥﴾ مُّتَّكِـِٔينَ عَلَيۡهَا مُتَقَٰبِلِينَ ﴿١٦﴾ يَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ ﴿١٧﴾ بِأَكۡوَابٖ وَأَبَارِيقَ وَكَأۡسٖ مِّن مَّعِينٖ ﴿١٨﴾ لَّا يُصَدَّعُونَ عَنۡهَا وَلَا يُنزِفُونَ ﴿١٩﴾ وَفَٰكِهَةٖ مِّمَّا يَتَخَيَّرُونَ ﴿٢٠﴾ وَلَحۡمِ طَيۡرٖ مِّمَّا يَشۡتَهُونَ ﴿٢١﴾ وَحُورٌ عِينٞ ﴿٢٢﴾ كَأَمۡثَٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ ﴿٢٣﴾ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ﴿٢٤﴾ لَا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا تَأۡثِيمًا ﴿٢٥﴾ إِلَّا قِيلٗا سَلَٰمٗا سَلَٰمٗا ﴿٢٦﴾", "w": [["ثلّة من الأولين", "جماعة من الأمم الماضية."], ["وقليل من الآخرين", "من أمة محمد ﷺ، هؤلاء هم السابقون."], ["على سرر موضونة", "منسوجة مشبّكة بالذهب والجواهر."], ["ولدان مخلّدون", "على شكل الأولاد، لا يهرمون، فيخدمونهم أبداً."], ["بأكواب وأباريق", "أكواب: أقداح لا عرى لها، وأباريق: لها عرى وخراطيم."], ["وكأس من معين", "وإناء لشرب الخمر من نهر جارٍ لا ينقطع."], ["لا يُصدّعون عنها", "لا يحصل لهم من شربها صداع."], ["ولا يُنزفون", "ولا تذهب عقولهم."], ["وفاكهة مما يتخيّرون", "يختارون منها ما يروق لهم ويعجبهم، وإن كانت كلها معجبة."], ["وحور عين", "نساء بيض واسعات الأعين، شديدات سواد العيون وبياضها."], ["كأمثال اللؤلؤ المكنون", "في جمالهن وصفائهن كاللؤلؤ المصون."], ["لا يسمعون فيها لغواً ولا تأثيماً", "لا يسمعون في الجنة فاحش الكلام وما لا خير فيه، ولا ما يوقع في الإثم."], ["إلا قيلاً سلاماً سلاماً", "لا يسمعون إلا السلام من الملائكة ومن بعضهم على بعض."]], "m": "ما زال السياق في بيان أحوال الناس إذا قامت القيامة، وهنا يقول في السابقين: إنهم ثلة من الأولين، من الأمم الماضية الذين سبقوا إلى الإسلام مع أنبيائهم، وقليل من الآخرين، من هذه الأمة، وهم الذين سبقوا إلى الإيمان والهجرة والجهاد. ثم يذكر نعيمهم: إنهم على سرر منسوجة مشبّكة بالذهب والجواهر، متكئين عليها متقابلين، لا ينظر أحدهم إلى قفا الآخر بل إلى وجهه، يطوف عليهم للخدمة غلمان مخلّدون لا يكبرون فيهرمون ولا يتغيّرون، بأكواب لا عرى لها، وأباريق لها عرى وخراطيم، وكأس من نهر الخمر الجاري لا ينضب، لا يصيبهم صداع من شربها ولا تذهب عقولهم، بخلاف خمر الدنيا. ويطوف عليهم الغلمان بفاكهة مما يختارون، ولحم طير مما تشتهيه أنفسهم، ولهم في الجنة حور عين، والحَوَر أن يكون بياض العين أكثر من سوادها، وهو ضرب من الجمال، كأمثال اللؤلؤ المصون في صدفه، يريد أنهن جميلات مصونات غير مبتذلات. جزاهم ربهم ذلك جزاء بما كانوا يعملون من الصالحات بعد الإيمان والتوحيد وترك المعاصي. ومن إتمام النعيم أنهم لا يسمعون في الجنة ما يكدّر صفو نعيمهم من قول بذيء، فلا يسمعون فيها كلاماً فاحشاً ولا ما يؤثم قائله وسامعه، إلا قولاً سلاماً سلاماً: سلام الرب تعالى عليهم، وهو أكبر نعيمهم، وسلام الملائكة عليهم، وسلام بعضهم على بعض.", "h": ["تقرير البعث والجزاء بذكر أحوال الدار الآخرة.", "بيان شيء من نعيم أهل الجنة، وخاصة السابقين منهم.", "بيان أن السابقين يكونون من سائر الأمم المسلمة.", "بيان فضل خمر الجنة على خمر الدنيا المحرّمة.", "تقرير قاعدة أن الجزاء من جنس العمل."], "k": "«إلا قيلاً سلاماً سلاماً»… في الجنة لا يُسمع إلا السلام؛ فهل يسمع الناس مني اليوم ما يشبه ذلك؟"}, {"lbl": "الآيات ٢٧ – ٤٠", "q": "وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ أَصۡحَٰبُ ٱلۡيَمِينِ ﴿٢٧﴾ فِي سِدۡرٖ مَّخۡضُودٖ ﴿٢٨﴾ وَطَلۡحٖ مَّنضُودٖ ﴿٢٩﴾ وَظِلّٖ مَّمۡدُودٖ ﴿٣٠﴾ وَمَآءٖ مَّسۡكُوبٖ ﴿٣١﴾ وَفَٰكِهَةٖ كَثِيرَةٖ ﴿٣٢﴾ لَّا مَقۡطُوعَةٖ وَلَا مَمۡنُوعَةٖ ﴿٣٣﴾ وَفُرُشٖ مَّرۡفُوعَةٍ ﴿٣٤﴾ إِنَّآ أَنشَأۡنَٰهُنَّ إِنشَآءٗ ﴿٣٥﴾ فَجَعَلۡنَٰهُنَّ أَبۡكَارًا ﴿٣٦﴾ عُرُبًا أَتۡرَابٗا ﴿٣٧﴾ لِّأَصۡحَٰبِ ٱلۡيَمِينِ ﴿٣٨﴾ ثُلَّةٞ مِّنَ ٱلۡأَوَّلِينَ ﴿٣٩﴾ وَثُلَّةٞ مِّنَ ٱلۡأٓخِرِينَ ﴿٤٠﴾", "w": [["وأصحاب اليمين ما أصحاب اليمين", "هذا شروع في ذكر الصنف الثاني من الأصناف الثلاثة وما أُعدّ لهم."], ["في سدر مخضود", "في شجر السدر، وثمره النبق، مخضود: لا شوك فيه."], ["وطلح منضود", "شجر موز منضود الحمل من أعلاه إلى أسفله."], ["وظل ممدود", "دائم، إذ لا شمس تنسخه، وإن في الجنة شجرة يسير الراكب في ظلها مائة سنة لا يقطعها."], ["وماء مسكوب", "مصبوب لا يحتاج المتنعّم أن يصبّه بيده، بل هو سائل في غير أخدود."], ["لا مقطوعة ولا ممنوعة", "غير مقطوعة في زمن، ولا ممنوعة بثمن."], ["وفرش مرفوعة", "على السرر العالية الرفيعة."], ["إنا أنشأناهن إنشاءً", "أي الحور العين، ومنهن من كانت في الدنيا عجوزاً فأنشأها ربها إنشاءً جديداً."], ["فجعلناهن أبكاراً", "الواحدة بكر، وهي العذراء."], ["عُرُباً", "الواحدة عَروب، وهي المتحبّبة إلى زوجها."], ["أتراباً", "مستويات في السن، الواحدة يقال لها ترب."], ["لأصحاب اليمين", "وهم الذين يؤخذ بهم في عرصات القيامة ذات اليمين، وهم أهل الإيمان والعمل الصالح في الدنيا."], ["ثلّة من الأولين", "من الأمم السابقة."], ["وثلّة من الآخرين", "من أمة محمد ﷺ."]], "m": "ما زال السياق في عرض أحوال الآخرة وذكر ما لكل صنف من أصناف الناس الثلاثة: وأصحاب اليمين، وهم الذين إذا وقفوا في عرصات القيامة أُخذ بهم ذات اليمين، وهم أهل الإيمان والتقوى في الدنيا، ما أصحاب اليمين؟ تفخيم لشأنهم وإعلان عن كرامتهم، ثم بيّن ذلك: إنهم في هذا النعيم الدائم المقيم، يتفكّهون بالنبق الذي هو أحلى من العسل وأنعم من الزبد، شجره مخضود لا شوك به، ويتفكّهون بالطلح وهو الموز، والماء المصبوب الجاري، والفاكهة الكثيرة التي لا تنقطع بالفصول الزمانية كما هي الحال في فاكهة الدنيا، يوجد منها في الصيف ما لا يوجد في الشتاء، وفرش مرفوعة عالية علوّ الدرجات التي هي فيها. إنا أنشأناهن إنشاءً: يعني الحور العين؛ منهن من أنشأهن الله إنشاءً لم يسبق لهن خلق، ومنهن نساء الدنيا، فقد كانت فيهن السوداء والعجوز، فيعيد تعالى إنشاءهن فيجعلهن من بين الحور العين كأنهن اللؤلؤ المكنون، فجعلناهن أبكاراً عذارى، عُرُباً متحبّبات إلى أزواجهن، أتراباً متساويات في السن، أنشأهن لأجل أصحاب اليمين. وأصحاب اليمين ثلة من الأمم الماضية، وثلة من هذه الأمة المسلمة.", "h": ["بيان إكرام الله وإنعامه على المؤمنين المتقين.", "بيان أن العجوز في الدنيا إذا دخلت الجنة تصير شابة حسناء حوراء عَروباً.", "تقرير أن ثمن الجنة الإيمان والتقوى، فلا دخل للحسب ولا للنسب."], "k": "«لا مقطوعة ولا ممنوعة»… نعيم الدنيا ينقطع أو يُمنع، ونعيمه هناك لا؛ فعلى أيهما أتحسّر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (399, 56, 41, 74, 'سورة الواقعة ٤١ – ٧٤', 'الواقعة: أفرأيتم ما تحرثون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 399) = $j$[{"lbl": "الآيات ٤١ – ٥٦", "q": "وَأَصۡحَٰبُ ٱلشِّمَالِ مَآ أَصۡحَٰبُ ٱلشِّمَالِ ﴿٤١﴾ فِي سَمُومٖ وَحَمِيمٖ ﴿٤٢﴾ وَظِلّٖ مِّن يَحۡمُومٖ ﴿٤٣﴾ لَّا بَارِدٖ وَلَا كَرِيمٍ ﴿٤٤﴾ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُتۡرَفِينَ ﴿٤٥﴾ وَكَانُواْ يُصِرُّونَ عَلَى ٱلۡحِنثِ ٱلۡعَظِيمِ ﴿٤٦﴾ وَكَانُواْ يَقُولُونَ أَئِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ ﴿٤٧﴾ أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ ﴿٤٨﴾ قُلۡ إِنَّ ٱلۡأَوَّلِينَ وَٱلۡأٓخِرِينَ ﴿٤٩﴾ لَمَجۡمُوعُونَ إِلَىٰ مِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ ﴿٥٠﴾ ثُمَّ إِنَّكُمۡ أَيُّهَا ٱلضَّآلُّونَ ٱلۡمُكَذِّبُونَ ﴿٥١﴾ لَأٓكِلُونَ مِن شَجَرٖ مِّن زَقُّومٖ ﴿٥٢﴾ فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ ﴿٥٣﴾ فَشَٰرِبُونَ عَلَيۡهِ مِنَ ٱلۡحَمِيمِ ﴿٥٤﴾ فَشَٰرِبُونَ شُرۡبَ ٱلۡهِيمِ ﴿٥٥﴾ هَٰذَا نُزُلُهُمۡ يَوۡمَ ٱلدِّينِ ﴿٥٦﴾", "w": [["وأصحاب الشمال", "الذين يؤخذ بهم ذات الشمال في الموقف يوم القيامة، وهم أهل الشرك والمعاصي في الدنيا."], ["في سَموم", "في ريح حارة تنفذ في مسامّ الجسد."], ["وحميم", "ماء حار شديد الحرارة."], ["وظل من يحموم", "ظل من دخان أسود شديد السواد."], ["لا بارد ولا كريم", "لا بارد كغيره من الظلال، ولا كريم حسن المنظر."], ["إنهم كانوا قبل ذلك مترفين", "كانوا في الدنيا منعّمين لا ينهضون بالتكاليف الشرعية ولا يتعبون في طاعة الله ورسوله."], ["يصرّون على الحِنث العظيم", "على الذنب العظيم، وهو الشرك."], ["وكانوا يقولون أئذا متنا", "كانوا ينكرون البعث الآخر."], ["لمجموعون إلى ميقات يوم معلوم", "لوقت يوم معلوم، وهو يوم القيامة."], ["أيها الضالون المكذّبون", "الضالون عن طريق الهدى، المكذّبون بالبعث."], ["من شجر من زقّوم", "من أخبث الشجر، المرّ في غاية الكراهة والبشاعة."], ["فشاربون شرب الهيم", "شاربون شرب الإبل العطاش."], ["هذا نُزُلهم يوم الدين", "هذا ما أُعدّ لهم من قِرى يوم الجزاء والحساب."]], "m": "ما زال السياق في بيان أحوال الأصناف الثلاثة التي انقسمت البشرية إليها عند خروجها من قبورها، وذكر هنا حال أصحاب الشمال: ما أصحاب الشمال؟ تنديد بحالهم وإعلان عن سوء عاقبتهم: إنهم في ريح حارة تنفذ في مسامّ الجسم، وحميم وهو ماء حار شديد الحرارة هذا شرابهم، وظل من دخان أسود شديد السواد، لا بارد كغيره من الظلال ولا حسن. ثم ذكر علّة جزائهم: إنهم كانوا في الدنيا منعّمين لا يصلّون ولا يصومون ولا يجاهدون، وكانوا يصرّون على الإثم العظيم، الشرك وكبائر الإثم والفواحش، وكانوا يقولون منكرين للبعث: أئذا متنا وكنا تراباً وعظاماً أئنا لمبعوثون أحياء كما كنا في الدنيا؟ أوَآباؤنا الأولون أيضاً؟ والاستفهام للاستبعاد والإنكار. فأمر تعالى رسوله ﷺ أن يرد عليهم: إن الأولين والآخرين، أنتم وآباؤكم من عهد آدم ومن ذريتكم إلى نهاية حياة الإنسان، لمجموعون لوقت يوم معلوم عند الله محدد باليوم والساعة، ثم إنكم أيها الضالون عن سبيل الهدى المكذّبون بالبعث لداخلون جهنم، لآكلون من شجر من زقوم، وهو شر ثمر وأخبث ما يؤكل مرارة، فمالئون منه بطونكم لما يصيبكم من الجوع الشديد، فشاربون عليه من الماء الحار الشديد الحرارة مكثرين منه كما تكثر الإبل التي أصابها داء الهيام. هذا الذي ذكرنا من طعامهم وشرابهم هو نزلهم يوم الدين، وأصل النُّزُل ما يُعدّ للضيف النازل من قِرى.", "h": ["أصحاب الشمال يدخل فيهم كل كافر وُجد على وجه الأرض، فإنهم في التقسيم ثلث الناس، وفي الواقع هم أضعاف أضعاف السابقين وأصحاب اليمين، لأن أكثر الناس لا يؤمنون.", "التنديد بالترف والتنعّم في هذه الحياة الدنيا، فإنه يقود إلى ترك التكاليف الشرعية، فيهلك صاحبه لذلك، لا لكون طعامه وافراً وشرابه لذيذاً.", "تقرير عقيدة البعث والجزاء بما لا مزيد عليه من العرض والوصف لحال الناس."], "k": "«إنهم كانوا قبل ذلك مترفين»… ليس العيب في النعمة بل في أن تُنسيني الطاعة؛ فهل أنستني شيئاً؟"}, {"lbl": "الآيات ٥٧ – ٧٤", "q": "نَحۡنُ خَلَقۡنَٰكُمۡ فَلَوۡلَا تُصَدِّقُونَ ﴿٥٧﴾ أَفَرَءَيۡتُم مَّا تُمۡنُونَ ﴿٥٨﴾ ءَأَنتُمۡ تَخۡلُقُونَهُۥٓ أَمۡ نَحۡنُ ٱلۡخَٰلِقُونَ ﴿٥٩﴾ نَحۡنُ قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِينَ ﴿٦٠﴾ عَلَىٰٓ أَن نُّبَدِّلَ أَمۡثَٰلَكُمۡ وَنُنشِئَكُمۡ فِي مَا لَا تَعۡلَمُونَ ﴿٦١﴾ وَلَقَدۡ عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ ﴿٦٢﴾ أَفَرَءَيۡتُم مَّا تَحۡرُثُونَ ﴿٦٣﴾ ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّـٰرِعُونَ ﴿٦٤﴾ لَوۡ نَشَآءُ لَجَعَلۡنَٰهُ حُطَٰمٗا فَظَلۡتُمۡ تَفَكَّهُونَ ﴿٦٥﴾ إِنَّا لَمُغۡرَمُونَ ﴿٦٦﴾ بَلۡ نَحۡنُ مَحۡرُومُونَ ﴿٦٧﴾ أَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ ﴿٦٨﴾ ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ ﴿٦٩﴾ لَوۡ نَشَآءُ جَعَلۡنَٰهُ أُجَاجٗا فَلَوۡلَا تَشۡكُرُونَ ﴿٧٠﴾ أَفَرَءَيۡتُمُ ٱلنَّارَ ٱلَّتِي تُورُونَ ﴿٧١﴾ ءَأَنتُمۡ أَنشَأۡتُمۡ شَجَرَتَهَآ أَمۡ نَحۡنُ ٱلۡمُنشِـُٔونَ ﴿٧٢﴾ نَحۡنُ جَعَلۡنَٰهَا تَذۡكِرَةٗ وَمَتَٰعٗا لِّلۡمُقۡوِينَ ﴿٧٣﴾ فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ ﴿٧٤﴾", "w": [["نحن خلقناكم", "أوجدناكم من العدم."], ["فلولا تصدّقون", "فهلّا تصدّقون بالبعث، إذ القادر على الإنشاء قادر على الإعادة بعد الفناء والبلى."], ["أفرأيتم ما تمنون", "الذي تصبّونه من المنيّ في أرحام نسائكم."], ["أأنتم تخلقونه", "بشراً، أم نحن الخالقون له؟"], ["نحن قدّرنا بينكم الموت", "قضينا به عليكم، وجعلنا لكل واحد أجلاً معيّناً لا يتعدّاه."], ["وما نحن بمسبوقين", "بعاجزين."], ["على أن نبدّل أمثالكم", "نبدّل ما أنتم عليه من الخلق والصور."], ["وننشئكم فيما لا تعلمون", "نوجدكم في صور لا تعلمونها، وهذا تهديد لهم بمسخهم."], ["ولقد علمتم النشأة الأولى", "علمتم خلقنا لكم كيف تمّ."], ["أفرأيتم ما تحرثون", "من إثارة الأرض بالمحراث وإلقاء البذر فيها."], ["أأنتم تزرعونه", "تنبتونه؟"], ["لو نشاء لجعلناه حطاماً", "لجعلنا الزرع يابساً بعد أن أصبح سنبلاً وقارب أن يُفرك، فتُحرمون منه."], ["فظلتم تفكّهون", "تتعجّبون في مجالسكم من الجائحة التي أصابت زرعكم."], ["إنا لمغرمون", "قائلين: إنا لمعذّبون بما أنفقناه على حرثه ورعايته."], ["بل نحن محرومون", "لسنا معذّبين به فقط، بل نحن محرومون من زرعنا، غير محظوظين."], ["أأنتم أنزلتموه من المزن", "من السحاب في السماء إلى الأرض؟"], ["لو نشاء جعلناه أجاجاً", "ملحاً مرّاً لا يمكن شربه."], ["فلولا تشكرون", "فهلّا تشكرون الله بالإيمان والطاعة."], ["أفرأيتم النار التي تورون", "التي تخرجونها من الشجر."], ["أأنتم أنشأتم شجرتها", "كالمرخ والعفار."], ["نحن جعلناها تذكرة", "تذكّر بنار جهنم."], ["ومتاعاً للمقوين", "بُلغة للمسافرين يتبلّغون بها في سفرهم."], ["فسبّح باسم ربك العظيم", "نزّه اسم ربك عما لا يليق به، ومن ذلك قولك: سبحان ربي العظيم."]], "m": "السياق هنا في تقرير عقيدة البعث والجزاء بذكر الأدلة العقلية: نحن خلقناكم وأنتم معترفون بذلك، فهلّا تصدّقون بالبعث، إذ القادر على الخلق الأول قادر على الإعادة؟ وهذه أدلة قدرتنا فتأمّلوها: أولاً: أخبرونا عما تصبّونه في أرحام نسائكم، أأنتم تخلقونه ولداً أم نحن الخالقون؟ والجواب: نحن، إذاً فالقادر على خلقكم بهذا الطريق قادر على خلقكم بطريق آخر. ثانياً: نحن قدّرنا بينكم الموت وقضينا به عليكم، فلا يستطيع أحد أن يمنعنا من إماتته في الوقت المحدد له. ثالثاً: وما نحن بعاجزين على أن نبدّل أمثالكم، بحيث نخلقكم في صور غير ما أنتم عليه، خلقاً ذميماً كالقردة والخنازير، فهل نعجز إذاً عن بعثكم بعد موتكم؟ ولقد علمتم النشأة الأولى كيف تمّت، فهلا تذكرون أن الذي خلقكم أول مرة قادر على خلقكم ثانية، مع أن الإعادة ليست بأصعب من الإنشاء من عدم. رابعاً: ما تحرثون من الأرض وتلقون فيها البذر، أأنتم تنبتونه أم نحن؟ نحن الزارعون، فالقادر على إنبات الزرع قادر على إنباتكم في قبوركم على نحو إنبات الزرع، وعَجْب الذَّنَب هو النواة التي تنبتون منها. خامساً: لو نشاء لجعلنا ذلك الزرع بعد نضرته حطاماً يابساً، فظلتم تتعجّبون تقولون: إنا لمعذّبون بما أنفقنا، بل نحن محرومون لا حظ لنا. سادساً: الماء الذي تشربون وحياتكم متوقفة عليه، أأنتم أنزلتموه من السحاب أم نحن؟ نحن، ولو نشاء لجعلناه ملحاً مرّاً، فهلّا تشكرون هذا الإحسان بالإيمان والطاعة؟ سابعاً: النار التي توقدونها، أأنتم أنشأتم شجرتها أم نحن؟ فالذي يوجد النار في الشجر قادر على أن يبعثكم أحياء ليحاسبكم. نحن جعلناها تذكرة تذكّركم بنار الآخرة، ومتاعاً للمسافرين يتبلّغون بها. ثم بعد إقامة الحجة أمر تعالى رسوله أن يسبّح ربه، أي ينزّهه عن العبث اللازم لخلق الحياة الدنيا على هذا النظام الدقيق ثم إفنائها ولا شيء وراء ذلك، إذ البعث والحياة الآخرة هي الغاية من هذه الحياة الدنيا.", "h": ["تقرير عقيدة البعث والجزاء.", "إقامة الأدلة والبراهين العديدة على صحة البعث وإمكانه عقلاً.", "بيان منن الله تعالى على عباده في طعامهم وشرابهم.", "وجوب شكر الله تعالى على إفضاله وإنعامه.", "في النار التي توقدها عبرة وعظة للمتقين.", "وجوب تسبيح الله وتنزيهه عما لا يليق بجلاله وكماله من العبث والشريك."], "k": "«أفرأيتم الماء الذي تشربون»… أشرب كل يوم ولا أفكّر من أنزله؛ فلأشكره مع كل شربة."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 399;
insert into public.tdb_cards(topic, i, body) select 399, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٥٦", "q": "وَأَصۡحَٰبُ ٱلشِّمَالِ مَآ أَصۡحَٰبُ ٱلشِّمَالِ ﴿٤١﴾ فِي سَمُومٖ وَحَمِيمٖ ﴿٤٢﴾ وَظِلّٖ مِّن يَحۡمُومٖ ﴿٤٣﴾ لَّا بَارِدٖ وَلَا كَرِيمٍ ﴿٤٤﴾ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُتۡرَفِينَ ﴿٤٥﴾ وَكَانُواْ يُصِرُّونَ عَلَى ٱلۡحِنثِ ٱلۡعَظِيمِ ﴿٤٦﴾ وَكَانُواْ يَقُولُونَ أَئِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ ﴿٤٧﴾ أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ ﴿٤٨﴾ قُلۡ إِنَّ ٱلۡأَوَّلِينَ وَٱلۡأٓخِرِينَ ﴿٤٩﴾ لَمَجۡمُوعُونَ إِلَىٰ مِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ ﴿٥٠﴾ ثُمَّ إِنَّكُمۡ أَيُّهَا ٱلضَّآلُّونَ ٱلۡمُكَذِّبُونَ ﴿٥١﴾ لَأٓكِلُونَ مِن شَجَرٖ مِّن زَقُّومٖ ﴿٥٢﴾ فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ ﴿٥٣﴾ فَشَٰرِبُونَ عَلَيۡهِ مِنَ ٱلۡحَمِيمِ ﴿٥٤﴾ فَشَٰرِبُونَ شُرۡبَ ٱلۡهِيمِ ﴿٥٥﴾ هَٰذَا نُزُلُهُمۡ يَوۡمَ ٱلدِّينِ ﴿٥٦﴾", "w": [["وأصحاب الشمال", "الذين يؤخذ بهم ذات الشمال في الموقف يوم القيامة، وهم أهل الشرك والمعاصي في الدنيا."], ["في سَموم", "في ريح حارة تنفذ في مسامّ الجسد."], ["وحميم", "ماء حار شديد الحرارة."], ["وظل من يحموم", "ظل من دخان أسود شديد السواد."], ["لا بارد ولا كريم", "لا بارد كغيره من الظلال، ولا كريم حسن المنظر."], ["إنهم كانوا قبل ذلك مترفين", "كانوا في الدنيا منعّمين لا ينهضون بالتكاليف الشرعية ولا يتعبون في طاعة الله ورسوله."], ["يصرّون على الحِنث العظيم", "على الذنب العظيم، وهو الشرك."], ["وكانوا يقولون أئذا متنا", "كانوا ينكرون البعث الآخر."], ["لمجموعون إلى ميقات يوم معلوم", "لوقت يوم معلوم، وهو يوم القيامة."], ["أيها الضالون المكذّبون", "الضالون عن طريق الهدى، المكذّبون بالبعث."], ["من شجر من زقّوم", "من أخبث الشجر، المرّ في غاية الكراهة والبشاعة."], ["فشاربون شرب الهيم", "شاربون شرب الإبل العطاش."], ["هذا نُزُلهم يوم الدين", "هذا ما أُعدّ لهم من قِرى يوم الجزاء والحساب."]], "m": "ما زال السياق في بيان أحوال الأصناف الثلاثة التي انقسمت البشرية إليها عند خروجها من قبورها، وذكر هنا حال أصحاب الشمال: ما أصحاب الشمال؟ تنديد بحالهم وإعلان عن سوء عاقبتهم: إنهم في ريح حارة تنفذ في مسامّ الجسم، وحميم وهو ماء حار شديد الحرارة هذا شرابهم، وظل من دخان أسود شديد السواد، لا بارد كغيره من الظلال ولا حسن. ثم ذكر علّة جزائهم: إنهم كانوا في الدنيا منعّمين لا يصلّون ولا يصومون ولا يجاهدون، وكانوا يصرّون على الإثم العظيم، الشرك وكبائر الإثم والفواحش، وكانوا يقولون منكرين للبعث: أئذا متنا وكنا تراباً وعظاماً أئنا لمبعوثون أحياء كما كنا في الدنيا؟ أوَآباؤنا الأولون أيضاً؟ والاستفهام للاستبعاد والإنكار. فأمر تعالى رسوله ﷺ أن يرد عليهم: إن الأولين والآخرين، أنتم وآباؤكم من عهد آدم ومن ذريتكم إلى نهاية حياة الإنسان، لمجموعون لوقت يوم معلوم عند الله محدد باليوم والساعة، ثم إنكم أيها الضالون عن سبيل الهدى المكذّبون بالبعث لداخلون جهنم، لآكلون من شجر من زقوم، وهو شر ثمر وأخبث ما يؤكل مرارة، فمالئون منه بطونكم لما يصيبكم من الجوع الشديد، فشاربون عليه من الماء الحار الشديد الحرارة مكثرين منه كما تكثر الإبل التي أصابها داء الهيام. هذا الذي ذكرنا من طعامهم وشرابهم هو نزلهم يوم الدين، وأصل النُّزُل ما يُعدّ للضيف النازل من قِرى.", "h": ["أصحاب الشمال يدخل فيهم كل كافر وُجد على وجه الأرض، فإنهم في التقسيم ثلث الناس، وفي الواقع هم أضعاف أضعاف السابقين وأصحاب اليمين، لأن أكثر الناس لا يؤمنون.", "التنديد بالترف والتنعّم في هذه الحياة الدنيا، فإنه يقود إلى ترك التكاليف الشرعية، فيهلك صاحبه لذلك، لا لكون طعامه وافراً وشرابه لذيذاً.", "تقرير عقيدة البعث والجزاء بما لا مزيد عليه من العرض والوصف لحال الناس."], "k": "«إنهم كانوا قبل ذلك مترفين»… ليس العيب في النعمة بل في أن تُنسيني الطاعة؛ فهل أنستني شيئاً؟"}, {"lbl": "الآيات ٥٧ – ٧٤", "q": "نَحۡنُ خَلَقۡنَٰكُمۡ فَلَوۡلَا تُصَدِّقُونَ ﴿٥٧﴾ أَفَرَءَيۡتُم مَّا تُمۡنُونَ ﴿٥٨﴾ ءَأَنتُمۡ تَخۡلُقُونَهُۥٓ أَمۡ نَحۡنُ ٱلۡخَٰلِقُونَ ﴿٥٩﴾ نَحۡنُ قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِينَ ﴿٦٠﴾ عَلَىٰٓ أَن نُّبَدِّلَ أَمۡثَٰلَكُمۡ وَنُنشِئَكُمۡ فِي مَا لَا تَعۡلَمُونَ ﴿٦١﴾ وَلَقَدۡ عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ ﴿٦٢﴾ أَفَرَءَيۡتُم مَّا تَحۡرُثُونَ ﴿٦٣﴾ ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّـٰرِعُونَ ﴿٦٤﴾ لَوۡ نَشَآءُ لَجَعَلۡنَٰهُ حُطَٰمٗا فَظَلۡتُمۡ تَفَكَّهُونَ ﴿٦٥﴾ إِنَّا لَمُغۡرَمُونَ ﴿٦٦﴾ بَلۡ نَحۡنُ مَحۡرُومُونَ ﴿٦٧﴾ أَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ ﴿٦٨﴾ ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ ﴿٦٩﴾ لَوۡ نَشَآءُ جَعَلۡنَٰهُ أُجَاجٗا فَلَوۡلَا تَشۡكُرُونَ ﴿٧٠﴾ أَفَرَءَيۡتُمُ ٱلنَّارَ ٱلَّتِي تُورُونَ ﴿٧١﴾ ءَأَنتُمۡ أَنشَأۡتُمۡ شَجَرَتَهَآ أَمۡ نَحۡنُ ٱلۡمُنشِـُٔونَ ﴿٧٢﴾ نَحۡنُ جَعَلۡنَٰهَا تَذۡكِرَةٗ وَمَتَٰعٗا لِّلۡمُقۡوِينَ ﴿٧٣﴾ فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ ﴿٧٤﴾", "w": [["نحن خلقناكم", "أوجدناكم من العدم."], ["فلولا تصدّقون", "فهلّا تصدّقون بالبعث، إذ القادر على الإنشاء قادر على الإعادة بعد الفناء والبلى."], ["أفرأيتم ما تمنون", "الذي تصبّونه من المنيّ في أرحام نسائكم."], ["أأنتم تخلقونه", "بشراً، أم نحن الخالقون له؟"], ["نحن قدّرنا بينكم الموت", "قضينا به عليكم، وجعلنا لكل واحد أجلاً معيّناً لا يتعدّاه."], ["وما نحن بمسبوقين", "بعاجزين."], ["على أن نبدّل أمثالكم", "نبدّل ما أنتم عليه من الخلق والصور."], ["وننشئكم فيما لا تعلمون", "نوجدكم في صور لا تعلمونها، وهذا تهديد لهم بمسخهم."], ["ولقد علمتم النشأة الأولى", "علمتم خلقنا لكم كيف تمّ."], ["أفرأيتم ما تحرثون", "من إثارة الأرض بالمحراث وإلقاء البذر فيها."], ["أأنتم تزرعونه", "تنبتونه؟"], ["لو نشاء لجعلناه حطاماً", "لجعلنا الزرع يابساً بعد أن أصبح سنبلاً وقارب أن يُفرك، فتُحرمون منه."], ["فظلتم تفكّهون", "تتعجّبون في مجالسكم من الجائحة التي أصابت زرعكم."], ["إنا لمغرمون", "قائلين: إنا لمعذّبون بما أنفقناه على حرثه ورعايته."], ["بل نحن محرومون", "لسنا معذّبين به فقط، بل نحن محرومون من زرعنا، غير محظوظين."], ["أأنتم أنزلتموه من المزن", "من السحاب في السماء إلى الأرض؟"], ["لو نشاء جعلناه أجاجاً", "ملحاً مرّاً لا يمكن شربه."], ["فلولا تشكرون", "فهلّا تشكرون الله بالإيمان والطاعة."], ["أفرأيتم النار التي تورون", "التي تخرجونها من الشجر."], ["أأنتم أنشأتم شجرتها", "كالمرخ والعفار."], ["نحن جعلناها تذكرة", "تذكّر بنار جهنم."], ["ومتاعاً للمقوين", "بُلغة للمسافرين يتبلّغون بها في سفرهم."], ["فسبّح باسم ربك العظيم", "نزّه اسم ربك عما لا يليق به، ومن ذلك قولك: سبحان ربي العظيم."]], "m": "السياق هنا في تقرير عقيدة البعث والجزاء بذكر الأدلة العقلية: نحن خلقناكم وأنتم معترفون بذلك، فهلّا تصدّقون بالبعث، إذ القادر على الخلق الأول قادر على الإعادة؟ وهذه أدلة قدرتنا فتأمّلوها: أولاً: أخبرونا عما تصبّونه في أرحام نسائكم، أأنتم تخلقونه ولداً أم نحن الخالقون؟ والجواب: نحن، إذاً فالقادر على خلقكم بهذا الطريق قادر على خلقكم بطريق آخر. ثانياً: نحن قدّرنا بينكم الموت وقضينا به عليكم، فلا يستطيع أحد أن يمنعنا من إماتته في الوقت المحدد له. ثالثاً: وما نحن بعاجزين على أن نبدّل أمثالكم، بحيث نخلقكم في صور غير ما أنتم عليه، خلقاً ذميماً كالقردة والخنازير، فهل نعجز إذاً عن بعثكم بعد موتكم؟ ولقد علمتم النشأة الأولى كيف تمّت، فهلا تذكرون أن الذي خلقكم أول مرة قادر على خلقكم ثانية، مع أن الإعادة ليست بأصعب من الإنشاء من عدم. رابعاً: ما تحرثون من الأرض وتلقون فيها البذر، أأنتم تنبتونه أم نحن؟ نحن الزارعون، فالقادر على إنبات الزرع قادر على إنباتكم في قبوركم على نحو إنبات الزرع، وعَجْب الذَّنَب هو النواة التي تنبتون منها. خامساً: لو نشاء لجعلنا ذلك الزرع بعد نضرته حطاماً يابساً، فظلتم تتعجّبون تقولون: إنا لمعذّبون بما أنفقنا، بل نحن محرومون لا حظ لنا. سادساً: الماء الذي تشربون وحياتكم متوقفة عليه، أأنتم أنزلتموه من السحاب أم نحن؟ نحن، ولو نشاء لجعلناه ملحاً مرّاً، فهلّا تشكرون هذا الإحسان بالإيمان والطاعة؟ سابعاً: النار التي توقدونها، أأنتم أنشأتم شجرتها أم نحن؟ فالذي يوجد النار في الشجر قادر على أن يبعثكم أحياء ليحاسبكم. نحن جعلناها تذكرة تذكّركم بنار الآخرة، ومتاعاً للمسافرين يتبلّغون بها. ثم بعد إقامة الحجة أمر تعالى رسوله أن يسبّح ربه، أي ينزّهه عن العبث اللازم لخلق الحياة الدنيا على هذا النظام الدقيق ثم إفنائها ولا شيء وراء ذلك، إذ البعث والحياة الآخرة هي الغاية من هذه الحياة الدنيا.", "h": ["تقرير عقيدة البعث والجزاء.", "إقامة الأدلة والبراهين العديدة على صحة البعث وإمكانه عقلاً.", "بيان منن الله تعالى على عباده في طعامهم وشرابهم.", "وجوب شكر الله تعالى على إفضاله وإنعامه.", "في النار التي توقدها عبرة وعظة للمتقين.", "وجوب تسبيح الله وتنزيهه عما لا يليق بجلاله وكماله من العبث والشريك."], "k": "«أفرأيتم الماء الذي تشربون»… أشرب كل يوم ولا أفكّر من أنزله؛ فلأشكره مع كل شربة."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (400, 56, 75, 96, 'سورة الواقعة ٧٥ – ٩٦', 'الواقعة: لا يمسّه إلا المطهّرون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 400) = $j$[{"lbl": "الآيات ٧٥ – ٨٢", "q": "۞فَلَآ أُقۡسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ ﴿٧٥﴾ وَإِنَّهُۥ لَقَسَمٞ لَّوۡ تَعۡلَمُونَ عَظِيمٌ ﴿٧٦﴾ إِنَّهُۥ لَقُرۡءَانٞ كَرِيمٞ ﴿٧٧﴾ فِي كِتَٰبٖ مَّكۡنُونٖ ﴿٧٨﴾ لَّا يَمَسُّهُۥٓ إِلَّا ٱلۡمُطَهَّرُونَ ﴿٧٩﴾ تَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٨٠﴾ أَفَبِهَٰذَا ٱلۡحَدِيثِ أَنتُم مُّدۡهِنُونَ ﴿٨١﴾ وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ ﴿٨٢﴾", "w": [["فلا أقسم", "فأُقسم، و«لا» صلة لتقوية الكلام وتأكيد القسم."], ["بمواقع النجوم", "بمساقطها لغروبها، وبمنازلها ومطالعها."], ["وإنه لقسم لو تعلمون عظيم", "لو كنتم من أهل العلم لعلمتم عِظم هذا القسم."], ["إنه لقرآن كريم", "المتلوّ عليكم قرآن كريم، وهو الذي كذّب به المشركون."], ["في كتاب مكنون", "مصون، وهو المصحف."], ["لا يمسّه إلا المطهّرون", "من الملائكة والأنبياء، وكل طاهر غير محدث حدثاً أكبر أو أصغر."], ["تنزيل من رب العالمين", "منزّل من رب العالمين، وهو الله جل جلاله."], ["أفبهذا الحديث", "أي القرآن."], ["أنتم مدهنون", "تُلينون القول للمكذّبين به ممالأةً منكم لهم على التكذيب."], ["وتجعلون رزقكم", "شكر الله على رزقكم."], ["أنكم تكذّبون", "تكذيبكم بسقيا الله، وتقولون: مُطرنا بنوء كذا وكذا."]], "m": "أقسم تعالى بمواقع النجوم، وهي مطالعها ومغاربها، وإن قسمي هذا لقسم عظيم لو كنتم من أهل العلم، لأن النجوم ومنازلها ومطالعها ومغاربها أمور عظيمة في خلقها وتدبير الله فيها. والمقسم عليه: إن هذا المكذَّب به لقرآن كريم، لا كما قال المبطلون شعر وسحر واختلاق، في كتاب مصون، لا يمسّه إلا المطهّرون، سواء ما كان في اللوح المحفوظ أو في مصاحفنا؛ فلا ينبغي أن يمسّه إلا المطهّرون من الأحداث الصغرى والكبرى، ولذا وجب تقديسه وتعظيمه، فلا يمسّه إلا طاهر من الشرك والكفر وسائر الأحداث. أفبهذا القرآن أنتم تلينون القول للمكذّبين به ممالأةً لهم على التكذيب والكفر، وتجعلون شكر الله على رزقه لكم أنكم تكذّبون بسقيا الله لكم بالأمطار، وتقولون: مُطرنا بنوء كذا ونوء كذا؟", "h": ["بيان أن الله تعالى يقسم بما شاء من مخلوقاته، وأن العبد لا يقسم إلا بربه تعالى.", "تقرير الوحي الإلهي وإثبات النبوة المحمدية، وأن القرآن الكريم منزّل من عند الله تعالى.", "وجوب صيانة القرآن الكريم، وحرمة مسّه على غير طهارة.", "حرمة المداهنة في دين الله تعالى، وهي أن يتنازل عن شيء من الدين ليحفظ شيئاً من دنياه، والمداراة جائزة، وهي أن يتنازل عن شيء من دنياه ليحفظ شيئاً من دينه."], "k": "«وتجعلون رزقكم أنكم تكذّبون»… كم نعمة نسبتها لغيره؛ فلأقل: هذا من فضل الله."}, {"lbl": "الآيات ٨٣ – ٩٦", "q": "فَلَوۡلَآ إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ ﴿٨٣﴾ وَأَنتُمۡ حِينَئِذٖ تَنظُرُونَ ﴿٨٤﴾ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنكُمۡ وَلَٰكِن لَّا تُبۡصِرُونَ ﴿٨٥﴾ فَلَوۡلَآ إِن كُنتُمۡ غَيۡرَ مَدِينِينَ ﴿٨٦﴾ تَرۡجِعُونَهَآ إِن كُنتُمۡ صَٰدِقِينَ ﴿٨٧﴾ فَأَمَّآ إِن كَانَ مِنَ ٱلۡمُقَرَّبِينَ ﴿٨٨﴾ فَرَوۡحٞ وَرَيۡحَانٞ وَجَنَّتُ نَعِيمٖ ﴿٨٩﴾ وَأَمَّآ إِن كَانَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ ﴿٩٠﴾ فَسَلَٰمٞ لَّكَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ ﴿٩١﴾ وَأَمَّآ إِن كَانَ مِنَ ٱلۡمُكَذِّبِينَ ٱلضَّآلِّينَ ﴿٩٢﴾ فَنُزُلٞ مِّنۡ حَمِيمٖ ﴿٩٣﴾ وَتَصۡلِيَةُ جَحِيمٍ ﴿٩٤﴾ إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلۡيَقِينِ ﴿٩٥﴾ فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ ﴿٩٦﴾", "w": [["فلولا", "فهلّا، وهي للحضّ على العمل والحثّ عليه."], ["إذا بلغت الحلقوم", "بلغت الروح مجرى الطعام، وذلك وقت النزع."], ["وأنتم حينئذ تنظرون", "وأنتم أيها المُمرّضون والعوّاد تنظرون إليه."], ["ونحن أقرب إليه منكم", "ورسلنا ملك الموت وأعوانه أقرب إلى المحتضر منكم."], ["ولكن لا تبصرون", "لا تبصرون الملائكة."], ["فلولا إن كنتم غير مدينين", "فهلّا إن كنتم غير محاسبين بعد الموت."], ["ترجعونها إن كنتم صادقين", "ترجعون الروح إلى الجسم بعد وشوك مفارقتها له، إن كنتم صادقين في أنكم لا تُبعثون ولا تحاسبون."], ["فأما إن كان من المقرّبين", "إن كان الميت من السابقين، وهم الصنف الأول من الأصناف الثلاثة."], ["فرَوح وريحان", "استراحة، ورزق حسن، وجنة نعيم."], ["وأما إن كان من أصحاب اليمين", "من الصنف الثاني."], ["فسلام لك من أصحاب اليمين", "فسلام لك يا صاحب اليمين من إخوانك أصحاب اليمين يسلّمون عليك."], ["فنُزُل من حميم", "فله نزل من ماء حار شديد الحرارة."], ["وتصلية جحيم", "احتراق بها."], ["إن هذا لهو حق اليقين", "إن هذا الذي قصصناه عليك في هذه السورة لهو حق اليقين."], ["فسبّح باسم ربك العظيم", "نزّه وقدّس اسم ربك العظيم."]], "m": "بعد تقرير النبوة المحمدية وأن القرآن كلام الله وتنزيله، عاد السياق إلى تقرير البعث والجزاء: فهلّا إذا بلغت الروح الحلقوم، وأنتم في ذلك الوقت تنظرون مريضكم وهو يعاني من سكرات الموت، ونحن أي رسلنا أقرب إليه منكم ولكن لا تبصرون، إذ لا قدرة لكم على رؤية الملائكة ما لم يتشكّلوا في صورة إنسان، فهلّا إن كنتم غير محاسبين بعد الموت ومجزيين بأعمالكم ترجعون الروح بعد ما بلغت الحلقوم، إن كنتم صادقين في أنكم غير مدينين لله بأعمالكم؟ فأما إن كان المحتضر من المقرّبين، وهم السابقون، فإن له الاستراحة التامة من عناء تعب الدنيا وتكاليفها، والرزق الحسن وجنة نعيم. وأما إن كان من أصحاب اليمين فسلام لك يا صاحب اليمين من إخوانك أصحاب اليمين الذين سبقوك إلى دار السلام. وأما إن كان المحتضر من المكذّبين لله ورسوله المنكرين للبعث الضالّين عن الهدى، فله ضيافة من الماء الحار، واحتراق بالجحيم. إن هذا الذي حدّثناك به عن المحتضرين الثلاثة وما لهم لهو حق اليقين. فسبّح باسم ربك العظيم: يأمر تعالى رسوله بالتسبيح باسم ربه العظيم، وصحّ أنه لما نزلت هذه الآية قال ﷺ لأصحابه: «اجعلوها في ركوعكم»، والتسبيح التقديس والتنزيه لله تعالى عما لا يليق بجلاله وكماله.", "h": ["تقرير البعث والجزاء.", "بيان عجز كل الناس أمام قدرة الله تعالى.", "إن في عجز الإنسان عن ردّ روح المحتضر ليعيش بعد ذلك ولو ساعة دليلاً على أنه لا إله إلا الله.", "بيان فضل السابقين على أصحاب اليمين.", "القرآن الكريم أحكامه كلها عدل، وأخباره كلها صدق.", "مشروعية قول العبد: سبحان الله وبحمده، سبحان الله العظيم، وهما من الكلم الطيب، وكذا: سبحان ربي العظيم حال الركوع."], "k": "«فلولا إذا بلغت الحلقوم»… ستأتي هذه اللحظة لا محالة؛ فمن أي الثلاثة أريد أن أكون حينها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 400;
insert into public.tdb_cards(topic, i, body) select 400, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٥ – ٨٢", "q": "۞فَلَآ أُقۡسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ ﴿٧٥﴾ وَإِنَّهُۥ لَقَسَمٞ لَّوۡ تَعۡلَمُونَ عَظِيمٌ ﴿٧٦﴾ إِنَّهُۥ لَقُرۡءَانٞ كَرِيمٞ ﴿٧٧﴾ فِي كِتَٰبٖ مَّكۡنُونٖ ﴿٧٨﴾ لَّا يَمَسُّهُۥٓ إِلَّا ٱلۡمُطَهَّرُونَ ﴿٧٩﴾ تَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٨٠﴾ أَفَبِهَٰذَا ٱلۡحَدِيثِ أَنتُم مُّدۡهِنُونَ ﴿٨١﴾ وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ ﴿٨٢﴾", "w": [["فلا أقسم", "فأُقسم، و«لا» صلة لتقوية الكلام وتأكيد القسم."], ["بمواقع النجوم", "بمساقطها لغروبها، وبمنازلها ومطالعها."], ["وإنه لقسم لو تعلمون عظيم", "لو كنتم من أهل العلم لعلمتم عِظم هذا القسم."], ["إنه لقرآن كريم", "المتلوّ عليكم قرآن كريم، وهو الذي كذّب به المشركون."], ["في كتاب مكنون", "مصون، وهو المصحف."], ["لا يمسّه إلا المطهّرون", "من الملائكة والأنبياء، وكل طاهر غير محدث حدثاً أكبر أو أصغر."], ["تنزيل من رب العالمين", "منزّل من رب العالمين، وهو الله جل جلاله."], ["أفبهذا الحديث", "أي القرآن."], ["أنتم مدهنون", "تُلينون القول للمكذّبين به ممالأةً منكم لهم على التكذيب."], ["وتجعلون رزقكم", "شكر الله على رزقكم."], ["أنكم تكذّبون", "تكذيبكم بسقيا الله، وتقولون: مُطرنا بنوء كذا وكذا."]], "m": "أقسم تعالى بمواقع النجوم، وهي مطالعها ومغاربها، وإن قسمي هذا لقسم عظيم لو كنتم من أهل العلم، لأن النجوم ومنازلها ومطالعها ومغاربها أمور عظيمة في خلقها وتدبير الله فيها. والمقسم عليه: إن هذا المكذَّب به لقرآن كريم، لا كما قال المبطلون شعر وسحر واختلاق، في كتاب مصون، لا يمسّه إلا المطهّرون، سواء ما كان في اللوح المحفوظ أو في مصاحفنا؛ فلا ينبغي أن يمسّه إلا المطهّرون من الأحداث الصغرى والكبرى، ولذا وجب تقديسه وتعظيمه، فلا يمسّه إلا طاهر من الشرك والكفر وسائر الأحداث. أفبهذا القرآن أنتم تلينون القول للمكذّبين به ممالأةً لهم على التكذيب والكفر، وتجعلون شكر الله على رزقه لكم أنكم تكذّبون بسقيا الله لكم بالأمطار، وتقولون: مُطرنا بنوء كذا ونوء كذا؟", "h": ["بيان أن الله تعالى يقسم بما شاء من مخلوقاته، وأن العبد لا يقسم إلا بربه تعالى.", "تقرير الوحي الإلهي وإثبات النبوة المحمدية، وأن القرآن الكريم منزّل من عند الله تعالى.", "وجوب صيانة القرآن الكريم، وحرمة مسّه على غير طهارة.", "حرمة المداهنة في دين الله تعالى، وهي أن يتنازل عن شيء من الدين ليحفظ شيئاً من دنياه، والمداراة جائزة، وهي أن يتنازل عن شيء من دنياه ليحفظ شيئاً من دينه."], "k": "«وتجعلون رزقكم أنكم تكذّبون»… كم نعمة نسبتها لغيره؛ فلأقل: هذا من فضل الله."}, {"lbl": "الآيات ٨٣ – ٩٦", "q": "فَلَوۡلَآ إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ ﴿٨٣﴾ وَأَنتُمۡ حِينَئِذٖ تَنظُرُونَ ﴿٨٤﴾ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنكُمۡ وَلَٰكِن لَّا تُبۡصِرُونَ ﴿٨٥﴾ فَلَوۡلَآ إِن كُنتُمۡ غَيۡرَ مَدِينِينَ ﴿٨٦﴾ تَرۡجِعُونَهَآ إِن كُنتُمۡ صَٰدِقِينَ ﴿٨٧﴾ فَأَمَّآ إِن كَانَ مِنَ ٱلۡمُقَرَّبِينَ ﴿٨٨﴾ فَرَوۡحٞ وَرَيۡحَانٞ وَجَنَّتُ نَعِيمٖ ﴿٨٩﴾ وَأَمَّآ إِن كَانَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ ﴿٩٠﴾ فَسَلَٰمٞ لَّكَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ ﴿٩١﴾ وَأَمَّآ إِن كَانَ مِنَ ٱلۡمُكَذِّبِينَ ٱلضَّآلِّينَ ﴿٩٢﴾ فَنُزُلٞ مِّنۡ حَمِيمٖ ﴿٩٣﴾ وَتَصۡلِيَةُ جَحِيمٍ ﴿٩٤﴾ إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلۡيَقِينِ ﴿٩٥﴾ فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ ﴿٩٦﴾", "w": [["فلولا", "فهلّا، وهي للحضّ على العمل والحثّ عليه."], ["إذا بلغت الحلقوم", "بلغت الروح مجرى الطعام، وذلك وقت النزع."], ["وأنتم حينئذ تنظرون", "وأنتم أيها المُمرّضون والعوّاد تنظرون إليه."], ["ونحن أقرب إليه منكم", "ورسلنا ملك الموت وأعوانه أقرب إلى المحتضر منكم."], ["ولكن لا تبصرون", "لا تبصرون الملائكة."], ["فلولا إن كنتم غير مدينين", "فهلّا إن كنتم غير محاسبين بعد الموت."], ["ترجعونها إن كنتم صادقين", "ترجعون الروح إلى الجسم بعد وشوك مفارقتها له، إن كنتم صادقين في أنكم لا تُبعثون ولا تحاسبون."], ["فأما إن كان من المقرّبين", "إن كان الميت من السابقين، وهم الصنف الأول من الأصناف الثلاثة."], ["فرَوح وريحان", "استراحة، ورزق حسن، وجنة نعيم."], ["وأما إن كان من أصحاب اليمين", "من الصنف الثاني."], ["فسلام لك من أصحاب اليمين", "فسلام لك يا صاحب اليمين من إخوانك أصحاب اليمين يسلّمون عليك."], ["فنُزُل من حميم", "فله نزل من ماء حار شديد الحرارة."], ["وتصلية جحيم", "احتراق بها."], ["إن هذا لهو حق اليقين", "إن هذا الذي قصصناه عليك في هذه السورة لهو حق اليقين."], ["فسبّح باسم ربك العظيم", "نزّه وقدّس اسم ربك العظيم."]], "m": "بعد تقرير النبوة المحمدية وأن القرآن كلام الله وتنزيله، عاد السياق إلى تقرير البعث والجزاء: فهلّا إذا بلغت الروح الحلقوم، وأنتم في ذلك الوقت تنظرون مريضكم وهو يعاني من سكرات الموت، ونحن أي رسلنا أقرب إليه منكم ولكن لا تبصرون، إذ لا قدرة لكم على رؤية الملائكة ما لم يتشكّلوا في صورة إنسان، فهلّا إن كنتم غير محاسبين بعد الموت ومجزيين بأعمالكم ترجعون الروح بعد ما بلغت الحلقوم، إن كنتم صادقين في أنكم غير مدينين لله بأعمالكم؟ فأما إن كان المحتضر من المقرّبين، وهم السابقون، فإن له الاستراحة التامة من عناء تعب الدنيا وتكاليفها، والرزق الحسن وجنة نعيم. وأما إن كان من أصحاب اليمين فسلام لك يا صاحب اليمين من إخوانك أصحاب اليمين الذين سبقوك إلى دار السلام. وأما إن كان المحتضر من المكذّبين لله ورسوله المنكرين للبعث الضالّين عن الهدى، فله ضيافة من الماء الحار، واحتراق بالجحيم. إن هذا الذي حدّثناك به عن المحتضرين الثلاثة وما لهم لهو حق اليقين. فسبّح باسم ربك العظيم: يأمر تعالى رسوله بالتسبيح باسم ربه العظيم، وصحّ أنه لما نزلت هذه الآية قال ﷺ لأصحابه: «اجعلوها في ركوعكم»، والتسبيح التقديس والتنزيه لله تعالى عما لا يليق بجلاله وكماله.", "h": ["تقرير البعث والجزاء.", "بيان عجز كل الناس أمام قدرة الله تعالى.", "إن في عجز الإنسان عن ردّ روح المحتضر ليعيش بعد ذلك ولو ساعة دليلاً على أنه لا إله إلا الله.", "بيان فضل السابقين على أصحاب اليمين.", "القرآن الكريم أحكامه كلها عدل، وأخباره كلها صدق.", "مشروعية قول العبد: سبحان الله وبحمده، سبحان الله العظيم، وهما من الكلم الطيب، وكذا: سبحان ربي العظيم حال الركوع."], "k": "«فلولا إذا بلغت الحلقوم»… ستأتي هذه اللحظة لا محالة؛ فمن أي الثلاثة أريد أن أكون حينها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (401, 57, 1, 11, 'سورة الحديد ١ – ١١', 'الحديد: وهو معكم أين ما كنتم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 401) = $j$[{"lbl": "الآيات ١ – ٦", "q": "سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١﴾ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٢﴾ هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّـٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿٣﴾ هُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۖ وَهُوَ مَعَكُمۡ أَيۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٤﴾ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٥﴾ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۚ وَهُوَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٦﴾", "w": [["سبّح لله ما في السماوات والأرض", "نزّه الله تعالى جميع ما في السماوات والأرض بلسان الحال والمقال."], ["وهو العزيز الحكيم", "العزيز في ملكه، الحكيم في صنعه وتدبيره."], ["له ملك السماوات والأرض", "يملك جميع ما في السماوات والأرض، يتصرّف كيف يشاء."], ["يحيي ويميت", "يحيي بعد العدم، ويميت بعد الإيجاد والإحياء."], ["وهو على كل شيء قدير", "على فعل كل ما يشاء قدير، لا يعجزه شيء."], ["هو الأول والآخر", "الأول الذي ليس قبله شيء، والآخر الذي ليس بعده شيء."], ["والظاهر والباطن", "الظاهر الذي ليس فوقه شيء، والباطن الذي ليس دونه شيء."], ["وهو بكل شيء عليم", "لا يغيب عن علمه شيء ولو كان مثقال ذرة في السماوات والأرض."], ["في ستة أيام", "من أيام الدنيا، أولها الأحد وآخرها الجمعة."], ["ثم استوى على العرش", "ارتفع عليه وعلا."], ["يعلم ما يلج في الأرض", "ما يدخل في الأرض من مطر وأموات وغيرهما."], ["وما يخرج منها", "من نبات ومعادن."], ["وما ينزل من السماء", "من رحمة وعذاب."], ["وما يعرج فيها", "ما يصعد فيها من الأعمال الصالحة والسيئة."], ["وهو معكم أين ما كنتم", "بعلمه بكم وقدرته عليكم أينما كنتم."], ["والله بما تعملون بصير", "لا يخفى عليه شيء من أعمال عباده الظاهرة والباطنة."], ["وإلى الله تُرجع الأمور", "مردّ كل شيء إلى الله خالقه ومدبّره، يحكم فيه بما يشاء."], ["يولج الليل في النهار", "يُدخل جزءاً من الليل في النهار، وذلك في الصيف."], ["ويولج النهار في الليل", "ويُدخل جزءاً من النهار في الليل، وذلك في الشتاء."], ["وهو عليم بذات الصدور", "بما في الصدور من المعتقدات والأسرار والنيات."]], "m": "يخبر تعالى في هذه الآيات الست عن وجوده وعظمته من قدرة وعلم وحكمة ورحمة وتدبير وملك، ومردّ الأمور إليه، وكلها مظاهر الربوبية الموجبة للألوهية: أولاً تسبيح كل شيء في السماوات والأرض له، أي تنزيهه عن كل نقص كالزوجة والولد والشريك والعجز والجهل. ثانياً: أنه العزيز ذو العزة التي لا تُرام، الحكيم في تدبير ملكه، فلا شيء في خلقه عبث أو باطل. ثالثاً: له ملك السماوات والأرض، يهب من شاء ويمنع من شاء. رابعاً: يحيي من العدم ويميت الحيّ الموجود. خامساً: هو على كل شيء قدير، متى أراد الشيء قال له كن فيكون. سادساً: هو الأول الذي ليس قبله شيء، والآخر الذي ليس بعده شيء. سابعاً: علمه محيط بكل شيء. ثامناً: خلقه السماوات والأرض في ستة أيام، وما مسّه من تعب، ثم استوى على العرش يدبّر ملكه بالحكمة والعدل والرحمة. تاسعاً: مع علوّه فالخلق كله بين يديه، يعلم ما يدخل في الأرض من أمطار وأموات، وما يخرج منها، وما ينزل من السماء من مطر ورحمة وعذاب، وما يصعد فيها من ملك وعمل صالح ودعاء، وخاصة دعوة المظلوم فإنها لا تُحجب عن الله أبداً. عاشراً: معيّته تعالى؛ فالخاصة بنصره لأوليائه، والعامة بعلمه بكل عباده وقدرته عليهم. الحادي عشر: بصره بكل أعمال عباده ليحاسبهم بها. الثاني عشر: له ملك السماوات والأرض وحده لا شريك له. الثالث عشر: ردّ كل الأمور إليه، فلا يقضي فيها غيره. الرابع عشر: إيلاجه الليل في النهار والنهار في الليل لمصلحة عباده، إذ لولا هذا التدبير لما صلح أمر الحياة. الخامس عشر: علمه بما في الصدور من وسواس وهمّ وعزم ونية وإرادة؛ فسبحانه من إله لا إله غيره، بهذه الكمالات استحق العبادة فلا تصح العبادة لغيره.", "h": ["فضل التسبيح، وأفضله: سبحان الله وبحمده، سبحان الله العظيم.", "مظاهر القدرة والعلم والحكمة في هذه الآيات هي موجبات ربوبية الله تعالى وألوهيته، وهي مقتضية للبعث الآخر والجزاء فيه.", "في خلقه تعالى السماوات والأرض في ستة أيام، وهو القادر على خلقهما بكلمة التكوين، تعليم لعباده التأنّي في الأمور وعدم العجلة فيها لتخرج متقنة صالحة نافعة.", "بطلان دعاء غير الله تعالى ورجاء غيره، إذ له ملك السماوات والأرض.", "وجوب مراقبة الله تعالى والحياء منه وتقواه، وذلك لعلمه بظواهرنا وبواطننا وقدرته على مجازاتنا."], "k": "«وهو معكم أين ما كنتم»… معي في الخلوة كما في الجماعة؛ فهل أستحيي منه كما أستحيي من الناس؟"}, {"lbl": "الآيات ٧ – ١١", "q": "ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرٞ كَبِيرٞ ﴿٧﴾ وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدۡعُوكُمۡ لِتُؤۡمِنُواْ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِيثَٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٨﴾ هُوَ ٱلَّذِي يُنَزِّلُ عَلَىٰ عَبۡدِهِۦٓ ءَايَٰتِۭ بَيِّنَٰتٖ لِّيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفٞ رَّحِيمٞ ﴿٩﴾ وَمَا لَكُمۡ أَلَّا تُنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا يَسۡتَوِي مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَٰتَلَۚ أُوْلَـٰٓئِكَ أَعۡظَمُ دَرَجَةٗ مِّنَ ٱلَّذِينَ أَنفَقُواْ مِنۢ بَعۡدُ وَقَٰتَلُواْۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿١٠﴾ مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرٞ كَرِيمٞ ﴿١١﴾", "w": [["آمنوا بالله ورسوله", "صدّقوا بالله ورسوله يا من لم تؤمنوا بعد، واثبتوا على إيمانكم يا من آمنتم."], ["وأنفقوا", "وتصدّقوا في سبيل الله."], ["مما جعلكم مستخلفين فيه", "من المال الذي استخلفكم الله فيه، إذ هو مال من قبلكم وسيكون لمن بعدكم."], ["لهم أجر كبير", "ثواب عظيم عند الله، وهو الجنة."], ["وما لكم لا تؤمنون بالله", "أي شيء يمنعكم من الإيمان؟"], ["والرسول يدعوكم لتؤمنوا بربكم", "والحال أن الرسول بنفسه يدعوكم لتؤمنوا بربكم."], ["وقد أخذ ميثاقكم", "على الإيمان به وأنتم في عالم الذرّ حيث أشهدكم على أنفسكم."], ["إن كنتم مؤمنين", "مريدين الإيمان، فلا تتردّدوا، وآمنوا وأسلموا تنجوا."], ["هو الذي ينزّل على عبده آيات بيّنات", "آيات القرآن الواضحات المعاني البيّنات الدلائل."], ["ليخرجكم من الظلمات إلى النور", "من ظلمات الكفر والجهل إلى نور الإيمان والعلم."], ["وإن الله بكم لرؤوف رحيم", "ويدلّكم على ذلك إرسال رسوله إليكم وإنزال كتابه."], ["وما لكم ألا تنفقوا في سبيل الله", "أي شيء لكم في عدم الإنفاق في سبيل الله؟"], ["ولله ميراث السماوات والأرض", "ومن ذلك المال الذي بين أيديكم، فهو عائد إلى الله، فأنفقوه في سبيله يؤجركم عليه."], ["لا يستوي منكم من أنفق من قبل الفتح وقاتل", "لا يستوي مع من أنفق وقاتل بعد صلح الحديبية حيث عزّ الإسلام وكثر مال المسلمين."], ["وكلّاً وعد الله الحسنى", "الجنة، والجنة درجات."], ["من ذا الذي يقرض الله قرضاً حسناً", "بإنفاقه ماله في سبيل الله، لا يريد به غير وجه الله تعالى."], ["فيضاعفه له", "الدرهم بسبعمائة درهم."], ["وله أجر كريم", "يوم القيامة، وهو الجنة دار النعيم المقيم."]], "m": "بعد ذكر الأدلة على وجود الله وقدرته وعلمه ووجوب عبادته وتوحيده، وتقرير البعث والجزاء، أمر تعالى عباده جميعاً، مؤمنيهم وكافريهم، بالإيمان به وبرسوله محمد ﷺ؛ فالمؤمنون مأمورون بزيادة الإيمان والثبات عليه، والكافرون مأمورون بالإيمان والمبادرة إليه، وبما أن الآيات نزلت بالمدينة فإن هذه الأوامر تشمل المؤمنين الصادقين والمنافقين الكاذبين والمتردّدين: آمنوا بالله ورسوله، وأنفقوا مما جعلكم مستخلفين فيه من الأموال، ووجه الاستخلاف أن العبد يرث المال عمّن سبقه ويموت ويتركه لمن بعده، فلا يُدفن معه في قبره. فالذين آمنوا منكم وأنفقوا لهم ثواب عظيم، وهذا الإخبار ينشّط الهمم الفاترة والعزائم المتردّدة. وأي شيء يجعلكم لا تؤمنون وفرص الإيمان كلها متاحة لكم: فإيمانكم الفطري صارخ في نفوسكم، إذ لو سُئلتم من خلقكم لقلتم: الله، والرسول بين أيديكم يدعوكم صباح مساء، وقد أخذ الله ميثاقكم يوم أخرجكم في صورة الذرّ من صلب آدم وأشهدكم على أنفسكم فشهدتم؟ فإن كنتم تريدون الإيمان فآمنوا قبل فوات الأوان. هو الذي ينزّل على عبده آيات واضحات ليخرجكم من ظلمات الكفر والجهل إلى نور الإيمان والعلم، وإن الله بكم لرؤوف رحيم. وما لكم ألا تنفقوا في سبيل الله، التي هي سبيل إسعادكم وإكمالكم، مع العلم أن لله ميراث السماوات والأرض، إذ ما بأيديكم هو واهبه لكم ومسترده منكم؟ لا يستوي منكم من أنفق من قبل الفتح، وهو صلح الحديبية، وقاتل، مع من أنفق وقاتل بعده، أولئك أعظم درجة، وكلّاً من الفريقين وعد الله الجنة، والله بما تعملون خبير لا يخفى عليه إنفاقكم ونياتكم. من ذا الذي يقرض الله قرضاً حسناً مخلصاً فيه، طيبة به نفسه، فيضاعفه له ربه في الدرهم سبعمائة درهم، وله أجر كريم، ألا وهو الجنة.", "h": ["وجوب الإيمان بالله ورسوله وتقويته.", "وجوب الإنفاق في سبيل الله من زكاة وجهاد وصدقة على الفقراء والمساكين.", "بيان لطف الله ورأفته ورحمته بعباده، مما يستلزم محبته وطاعته وشكره.", "الإنفاق في المجاعات والشدائد والحروب أفضل منه في اليسر والعافية.", "الترغيب في الإنفاق في سبيل الله بمضاعفة الأجر، وما عند الله خير وأبقى، وللآخرة خير من الأولى."], "k": "«مما جعلكم مستخلفين فيه»… المال في يدي أمانة مؤقتة؛ فماذا قدّمت منه قبل أن ينتقل لغيري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 401;
insert into public.tdb_cards(topic, i, body) select 401, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١﴾ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٢﴾ هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّـٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿٣﴾ هُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۖ وَهُوَ مَعَكُمۡ أَيۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٤﴾ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٥﴾ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۚ وَهُوَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٦﴾", "w": [["سبّح لله ما في السماوات والأرض", "نزّه الله تعالى جميع ما في السماوات والأرض بلسان الحال والمقال."], ["وهو العزيز الحكيم", "العزيز في ملكه، الحكيم في صنعه وتدبيره."], ["له ملك السماوات والأرض", "يملك جميع ما في السماوات والأرض، يتصرّف كيف يشاء."], ["يحيي ويميت", "يحيي بعد العدم، ويميت بعد الإيجاد والإحياء."], ["وهو على كل شيء قدير", "على فعل كل ما يشاء قدير، لا يعجزه شيء."], ["هو الأول والآخر", "الأول الذي ليس قبله شيء، والآخر الذي ليس بعده شيء."], ["والظاهر والباطن", "الظاهر الذي ليس فوقه شيء، والباطن الذي ليس دونه شيء."], ["وهو بكل شيء عليم", "لا يغيب عن علمه شيء ولو كان مثقال ذرة في السماوات والأرض."], ["في ستة أيام", "من أيام الدنيا، أولها الأحد وآخرها الجمعة."], ["ثم استوى على العرش", "ارتفع عليه وعلا."], ["يعلم ما يلج في الأرض", "ما يدخل في الأرض من مطر وأموات وغيرهما."], ["وما يخرج منها", "من نبات ومعادن."], ["وما ينزل من السماء", "من رحمة وعذاب."], ["وما يعرج فيها", "ما يصعد فيها من الأعمال الصالحة والسيئة."], ["وهو معكم أين ما كنتم", "بعلمه بكم وقدرته عليكم أينما كنتم."], ["والله بما تعملون بصير", "لا يخفى عليه شيء من أعمال عباده الظاهرة والباطنة."], ["وإلى الله تُرجع الأمور", "مردّ كل شيء إلى الله خالقه ومدبّره، يحكم فيه بما يشاء."], ["يولج الليل في النهار", "يُدخل جزءاً من الليل في النهار، وذلك في الصيف."], ["ويولج النهار في الليل", "ويُدخل جزءاً من النهار في الليل، وذلك في الشتاء."], ["وهو عليم بذات الصدور", "بما في الصدور من المعتقدات والأسرار والنيات."]], "m": "يخبر تعالى في هذه الآيات الست عن وجوده وعظمته من قدرة وعلم وحكمة ورحمة وتدبير وملك، ومردّ الأمور إليه، وكلها مظاهر الربوبية الموجبة للألوهية: أولاً تسبيح كل شيء في السماوات والأرض له، أي تنزيهه عن كل نقص كالزوجة والولد والشريك والعجز والجهل. ثانياً: أنه العزيز ذو العزة التي لا تُرام، الحكيم في تدبير ملكه، فلا شيء في خلقه عبث أو باطل. ثالثاً: له ملك السماوات والأرض، يهب من شاء ويمنع من شاء. رابعاً: يحيي من العدم ويميت الحيّ الموجود. خامساً: هو على كل شيء قدير، متى أراد الشيء قال له كن فيكون. سادساً: هو الأول الذي ليس قبله شيء، والآخر الذي ليس بعده شيء. سابعاً: علمه محيط بكل شيء. ثامناً: خلقه السماوات والأرض في ستة أيام، وما مسّه من تعب، ثم استوى على العرش يدبّر ملكه بالحكمة والعدل والرحمة. تاسعاً: مع علوّه فالخلق كله بين يديه، يعلم ما يدخل في الأرض من أمطار وأموات، وما يخرج منها، وما ينزل من السماء من مطر ورحمة وعذاب، وما يصعد فيها من ملك وعمل صالح ودعاء، وخاصة دعوة المظلوم فإنها لا تُحجب عن الله أبداً. عاشراً: معيّته تعالى؛ فالخاصة بنصره لأوليائه، والعامة بعلمه بكل عباده وقدرته عليهم. الحادي عشر: بصره بكل أعمال عباده ليحاسبهم بها. الثاني عشر: له ملك السماوات والأرض وحده لا شريك له. الثالث عشر: ردّ كل الأمور إليه، فلا يقضي فيها غيره. الرابع عشر: إيلاجه الليل في النهار والنهار في الليل لمصلحة عباده، إذ لولا هذا التدبير لما صلح أمر الحياة. الخامس عشر: علمه بما في الصدور من وسواس وهمّ وعزم ونية وإرادة؛ فسبحانه من إله لا إله غيره، بهذه الكمالات استحق العبادة فلا تصح العبادة لغيره.", "h": ["فضل التسبيح، وأفضله: سبحان الله وبحمده، سبحان الله العظيم.", "مظاهر القدرة والعلم والحكمة في هذه الآيات هي موجبات ربوبية الله تعالى وألوهيته، وهي مقتضية للبعث الآخر والجزاء فيه.", "في خلقه تعالى السماوات والأرض في ستة أيام، وهو القادر على خلقهما بكلمة التكوين، تعليم لعباده التأنّي في الأمور وعدم العجلة فيها لتخرج متقنة صالحة نافعة.", "بطلان دعاء غير الله تعالى ورجاء غيره، إذ له ملك السماوات والأرض.", "وجوب مراقبة الله تعالى والحياء منه وتقواه، وذلك لعلمه بظواهرنا وبواطننا وقدرته على مجازاتنا."], "k": "«وهو معكم أين ما كنتم»… معي في الخلوة كما في الجماعة؛ فهل أستحيي منه كما أستحيي من الناس؟"}, {"lbl": "الآيات ٧ – ١١", "q": "ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرٞ كَبِيرٞ ﴿٧﴾ وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدۡعُوكُمۡ لِتُؤۡمِنُواْ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِيثَٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٨﴾ هُوَ ٱلَّذِي يُنَزِّلُ عَلَىٰ عَبۡدِهِۦٓ ءَايَٰتِۭ بَيِّنَٰتٖ لِّيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفٞ رَّحِيمٞ ﴿٩﴾ وَمَا لَكُمۡ أَلَّا تُنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا يَسۡتَوِي مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَٰتَلَۚ أُوْلَـٰٓئِكَ أَعۡظَمُ دَرَجَةٗ مِّنَ ٱلَّذِينَ أَنفَقُواْ مِنۢ بَعۡدُ وَقَٰتَلُواْۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿١٠﴾ مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرٞ كَرِيمٞ ﴿١١﴾", "w": [["آمنوا بالله ورسوله", "صدّقوا بالله ورسوله يا من لم تؤمنوا بعد، واثبتوا على إيمانكم يا من آمنتم."], ["وأنفقوا", "وتصدّقوا في سبيل الله."], ["مما جعلكم مستخلفين فيه", "من المال الذي استخلفكم الله فيه، إذ هو مال من قبلكم وسيكون لمن بعدكم."], ["لهم أجر كبير", "ثواب عظيم عند الله، وهو الجنة."], ["وما لكم لا تؤمنون بالله", "أي شيء يمنعكم من الإيمان؟"], ["والرسول يدعوكم لتؤمنوا بربكم", "والحال أن الرسول بنفسه يدعوكم لتؤمنوا بربكم."], ["وقد أخذ ميثاقكم", "على الإيمان به وأنتم في عالم الذرّ حيث أشهدكم على أنفسكم."], ["إن كنتم مؤمنين", "مريدين الإيمان، فلا تتردّدوا، وآمنوا وأسلموا تنجوا."], ["هو الذي ينزّل على عبده آيات بيّنات", "آيات القرآن الواضحات المعاني البيّنات الدلائل."], ["ليخرجكم من الظلمات إلى النور", "من ظلمات الكفر والجهل إلى نور الإيمان والعلم."], ["وإن الله بكم لرؤوف رحيم", "ويدلّكم على ذلك إرسال رسوله إليكم وإنزال كتابه."], ["وما لكم ألا تنفقوا في سبيل الله", "أي شيء لكم في عدم الإنفاق في سبيل الله؟"], ["ولله ميراث السماوات والأرض", "ومن ذلك المال الذي بين أيديكم، فهو عائد إلى الله، فأنفقوه في سبيله يؤجركم عليه."], ["لا يستوي منكم من أنفق من قبل الفتح وقاتل", "لا يستوي مع من أنفق وقاتل بعد صلح الحديبية حيث عزّ الإسلام وكثر مال المسلمين."], ["وكلّاً وعد الله الحسنى", "الجنة، والجنة درجات."], ["من ذا الذي يقرض الله قرضاً حسناً", "بإنفاقه ماله في سبيل الله، لا يريد به غير وجه الله تعالى."], ["فيضاعفه له", "الدرهم بسبعمائة درهم."], ["وله أجر كريم", "يوم القيامة، وهو الجنة دار النعيم المقيم."]], "m": "بعد ذكر الأدلة على وجود الله وقدرته وعلمه ووجوب عبادته وتوحيده، وتقرير البعث والجزاء، أمر تعالى عباده جميعاً، مؤمنيهم وكافريهم، بالإيمان به وبرسوله محمد ﷺ؛ فالمؤمنون مأمورون بزيادة الإيمان والثبات عليه، والكافرون مأمورون بالإيمان والمبادرة إليه، وبما أن الآيات نزلت بالمدينة فإن هذه الأوامر تشمل المؤمنين الصادقين والمنافقين الكاذبين والمتردّدين: آمنوا بالله ورسوله، وأنفقوا مما جعلكم مستخلفين فيه من الأموال، ووجه الاستخلاف أن العبد يرث المال عمّن سبقه ويموت ويتركه لمن بعده، فلا يُدفن معه في قبره. فالذين آمنوا منكم وأنفقوا لهم ثواب عظيم، وهذا الإخبار ينشّط الهمم الفاترة والعزائم المتردّدة. وأي شيء يجعلكم لا تؤمنون وفرص الإيمان كلها متاحة لكم: فإيمانكم الفطري صارخ في نفوسكم، إذ لو سُئلتم من خلقكم لقلتم: الله، والرسول بين أيديكم يدعوكم صباح مساء، وقد أخذ الله ميثاقكم يوم أخرجكم في صورة الذرّ من صلب آدم وأشهدكم على أنفسكم فشهدتم؟ فإن كنتم تريدون الإيمان فآمنوا قبل فوات الأوان. هو الذي ينزّل على عبده آيات واضحات ليخرجكم من ظلمات الكفر والجهل إلى نور الإيمان والعلم، وإن الله بكم لرؤوف رحيم. وما لكم ألا تنفقوا في سبيل الله، التي هي سبيل إسعادكم وإكمالكم، مع العلم أن لله ميراث السماوات والأرض، إذ ما بأيديكم هو واهبه لكم ومسترده منكم؟ لا يستوي منكم من أنفق من قبل الفتح، وهو صلح الحديبية، وقاتل، مع من أنفق وقاتل بعده، أولئك أعظم درجة، وكلّاً من الفريقين وعد الله الجنة، والله بما تعملون خبير لا يخفى عليه إنفاقكم ونياتكم. من ذا الذي يقرض الله قرضاً حسناً مخلصاً فيه، طيبة به نفسه، فيضاعفه له ربه في الدرهم سبعمائة درهم، وله أجر كريم، ألا وهو الجنة.", "h": ["وجوب الإيمان بالله ورسوله وتقويته.", "وجوب الإنفاق في سبيل الله من زكاة وجهاد وصدقة على الفقراء والمساكين.", "بيان لطف الله ورأفته ورحمته بعباده، مما يستلزم محبته وطاعته وشكره.", "الإنفاق في المجاعات والشدائد والحروب أفضل منه في اليسر والعافية.", "الترغيب في الإنفاق في سبيل الله بمضاعفة الأجر، وما عند الله خير وأبقى، وللآخرة خير من الأولى."], "k": "«مما جعلكم مستخلفين فيه»… المال في يدي أمانة مؤقتة؛ فماذا قدّمت منه قبل أن ينتقل لغيري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (402, 57, 12, 19, 'سورة الحديد ١٢ – ١٩', 'الحديد: ألم يأنِ للذين آمنوا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 402) = $j$[{"lbl": "الآيات ١٢ – ١٥", "q": "يَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡيَوۡمَ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٢﴾ يَوۡمَ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُواْ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِيلَ ٱرۡجِعُواْ وَرَآءَكُمۡ فَٱلۡتَمِسُواْ نُورٗاۖ فَضُرِبَ بَيۡنَهُم بِسُورٖ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ٱلرَّحۡمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ ﴿١٣﴾ يُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُواْ بَلَىٰ وَلَٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِيُّ حَتَّىٰ جَآءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ ﴿١٤﴾ فَٱلۡيَوۡمَ لَا يُؤۡخَذُ مِنكُمۡ فِدۡيَةٞ وَلَا مِنَ ٱلَّذِينَ كَفَرُواْۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِيَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٥﴾", "w": [["يسعى نورهم بين أيديهم وبأيمانهم", "يتقدّمهم نورهم الذي اكتسبوه بالإيمان والعمل الصالح بمسافات بعيدة، يضيء لهم الصراط الذي يجتازونه."], ["بشراكم اليوم جنات", "تقول لهم الملائكة الذين أُعدّوا لاستقبالهم: بشراكم اليوم جنات تجري من تحتها الأنهار."], ["ذلك هو الفوز العظيم", "النجاة من النار ودخول الجنة هو الفوز العظيم."], ["المنافقون والمنافقات", "الذين كانوا يخفون الكفر في نفوسهم ويظهرون الإيمان والإسلام بألسنتهم."], ["انظرونا نقتبس من نوركم", "انظروا إلينا بوجوهكم نأخذ من نوركم ما يضيء لنا."], ["قيل ارجعوا وراءكم فالتمسوا نوراً", "يقال لهم استهزاءً بهم: ارجعوا وراءكم إلى الدنيا، حيث يُطلب النور هناك بالإيمان وصالح الأعمال."], ["فضُرب بينهم بسور له باب باطنه فيه الرحمة", "فضُرب بينهم وبين المؤمنين بسور عالٍ له باب، باطنه الذي من جهة المؤمنين فيه الرحمة."], ["وظاهره من قِبله العذاب", "الذي من جهة المنافقين في عرصات القيامة فيه العذاب."], ["ينادونهم ألم نكن معكم", "ينادي المنافقون المؤمنين: ألم نكن معكم في الدنيا على الطاعات، نصلّي كما تصلّون ونجاهد كما تجاهدون؟"], ["قالوا بلى", "كنتم معنا على الطاعات."], ["ولكنكم فتنتم أنفسكم", "بالنفاق، وهو كفر الباطن وبغض الإسلام والمسلمين."], ["وتربّصتم", "الدوائر بالمسلمين، تنتظرون متى يُهزم المؤمنون فتعلنون كفركم."], ["وغرّكم بالله الغَرور", "غرّكم الشيطان حيث زيّن لكم الكفر وكرّه إليكم الإيمان."], ["فاليوم لا يؤخذ منكم فدية", "مال تفدون به أنفسكم، إذ لا مال يومئذ ينفع ولا ولد."], ["مأواكم النار هي مولاكم", "مستقرّكم ومكان إيوائكم النار، وهي أولى بكم."], ["وبئس المصير", "مصيركم الذي صرتم إليه، وهو النار."]], "m": "لهم أجر كريم يوم ترى المؤمنين والمؤمنات في عرصات القيامة يسعى نورهم الذي اكتسبوه بإيمانهم وصالح أعمالهم في الدنيا، يمشي أمامهم يهديهم إلى طريق الجنة، وقد أُعطوا كتبهم بأيمانهم، وتقول لهم الملائكة الذين أُعدّوا لاستقبالهم: بشراكم اليوم جنات تجري من خلال أشجارها وقصورها أنهار الماء واللبن والخمر والعسل، خالدين فيها، ذلك هو الفوز العظيم، إذ هو نجاة من النار ودخول الجنان في جوار الرحمن. يوم يقول المنافقون والمنافقات، الذين كانوا في الدنيا يخفون الكفر ويظهرون الإيمان، للذين آمنوا: أقبلوا علينا بوجوهكم ذات الأنوار نأخذ من نوركم ما يضيء لنا الطريق، فيقال لهم استهزاءً بهم: ارجعوا وراءكم فالتمسوا نوراً، إشارة إلى أن هذا النور يُطلب في الدنيا بالإيمان وصالح الأعمال، فيرجعون إلى الوراء، وفوراً يُضرب بينهم وبين المؤمنين بسور عالٍ له باب، باطنه وهو يلي المؤمنين فيه الرحمة، وظاهره وهو يلي المنافقين من قبله العذاب، فيأخذون في ندائهم: ألم نكن معكم على الطاعات أيها المؤمنون؟ فقد كنا نصلّي معكم ونجاهد وننفق كما تنفقون. فيقول المؤمنون: بلى، كنتم معنا في الظاهر، ولكنكم فتنتم أنفسكم بالنفاق، وتربّصتم بنا الدوائر لتعلنوا عن كفركم، وشككتم في صحة الإسلام وعقائده ومنها البعث، وغرّتكم الأماني الكاذبة في أن محمداً لن ينتصر ودينه لن يظهر، حتى جاء أمر الله بنصر رسوله وإظهار دينه، وغرّكم بالله الشيطان، إذ زيّن لكم الكفر وذكّركم بعفو الله وعدم مؤاخذته لكم. فاليوم لا يؤخذ منكم فداء مهما كان، ولا من الذين كفروا كذلك، مأواكم النار، هي التي تتولّاكم وتضمّكم، وهي أولى بكم لخبث نفوسكم من جرّاء النفاق والكفر، وبئس المصير.", "h": ["تقرير البعث بذكر أحداثه وما يجري فيه.", "تقرير أن الفوز ليس ربح الشاة والبعير ولا الدار ولا البستان في الدنيا، وإنما هو الزحزحة عن النار ودخول الجنان يوم القيامة، هذا هو الفوز العظيم.", "من بشائر السعادة لأهل الإيمان قبل دخول الجنة تلقّي الملائكة لهم، وإعطاؤهم كتبهم بأيمانهم، ووجود نور عالٍ يسعى بين أيديهم وبأيمانهم يتقدّمهم على الصراط إلى الجنة.", "نور يوم القيامة في وجوه المؤمنين أخذوه من الدنيا، وفي الحديث: «بشّر المشّائين في الظُّلَم إلى المساجد بالنور التام يوم القيامة».", "بيان صفات المنافقين في الدنيا، وهي إبطان الكفر في نفوسهم، والتربّص بالمؤمنين للانقضاض عليهم متى ضعفوا أو هُزموا، وأمانيهم في عدم نصرة الإسلام، وشكّهم الملازم لهم حتى ماتوا شاكّين في صحة الإسلام وما جاء به."], "k": "«ارجعوا وراءكم فالتمسوا نوراً»… النور يُصنع هنا لا هناك؛ فكم خطوة إلى المسجد في الظلمة صنعت لي نوراً؟"}, {"lbl": "الآيات ١٦ – ١٩", "q": "۞أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ ﴿١٦﴾ ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿١٧﴾ إِنَّ ٱلۡمُصَّدِّقِينَ وَٱلۡمُصَّدِّقَٰتِ وَأَقۡرَضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرٞ كَرِيمٞ ﴿١٨﴾ وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦٓ أُوْلَـٰٓئِكَ هُمُ ٱلصِّدِّيقُونَۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿١٩﴾", "w": [["ألم يأنِ للذين آمنوا", "ألم يحن الوقت للذين أكثروا من المزاح…"], ["أن تخشع قلوبهم لذكر الله", "أن تلين وتسكن وتخضع وتطمئن لذكر الله ووعده ووعيده."], ["وما نزل من الحق", "القرآن وما يحويه من وعد ووعيد."], ["ولا يكونوا كالذين أوتوا الكتاب من قبل", "ولا يكونوا كاليهود والنصارى في الإعراض والغفلة."], ["فطال عليهم الأمد", "الزمن بينهم وبين أنبيائهم."], ["فقست قلوبهم", "لعدم وجود من يذكّرهم ويرشدهم، فلم تلن لذكر الله."], ["وكثير منهم فاسقون", "نتيجة لقسوة القلوب المترتبة على ترك التذكير، ففسق أكثرهم فخرج عن دين الله."], ["اعلموا أن الله يحيي الأرض بعد موتها", "بالغيث ينزل بها، وكذلك يحيي القلوب بالذكر والتذكير فتلين وتخشع."], ["قد بيّنا لكم الآيات لعلكم تعقلون", "بيّنا الآيات الدالة على قدرتنا وعلمنا ورحمتنا، رجاء أن تعقلوا فتحفظوا أنفسكم مما يرديها."], ["إن المصّدّقين والمصّدّقات", "المتصدّقين بفضول أموالهم، والمتصدّقات كذلك."], ["وأقرضوا الله قرضاً حسناً", "وكانت صدقاتهم كالقرض الحسن الذي لا منّة معه، والنفس طيبة به راجية جزاءه."], ["يُضاعف لهم", "الحسنة بعشر أمثالها إلى سبعمائة، إلى ألف ألف."], ["والذين آمنوا بالله ورسله", "صدّقوا بالله رباً وإلهاً، وبرسله هداة ودعاة صادقين."], ["أولئك هم الصدّيقون", "الذين كُتبوا عند الله صدّيقين، وهي مرتبة شرف عالية."], ["والشهداء عند ربهم لهم أجرهم ونورهم", "وشهداء المعارك في سبيل الله عند ربهم لهم أجرهم العظيم ونورهم التام يوم القيامة."], ["والذين كفروا وكذّبوا بآياتنا", "كفروا بالله وتوحيده، وكذّبوا بالقرآن وما حواه من الشرائع."], ["أولئك أصحاب الجحيم", "أهل النار الذين لا يفارقونها أبداً."]], "m": "ألم يحن الوقت للذين آمنوا بالله رباً وإلهاً وبمحمد ﷺ نبياً، وبوعد الله ووعيده صدقاً وحقاً، أن تخشع قلوبهم فتلين وتطمئن لذكر الله، ولما نزل من الحق في الكتاب الكريم، فيعرفون المعروف ويأمرون به، ويعرفون المنكر وينهون عنه؟ إنها لموعظة إلهية عظيمة، وزادها عظمة أن تنزل في أصحاب رسول الله ﷺ تستبطئ قلوبهم. ولا يكونوا كاليهود والنصارى الذين أوتوا الكتاب من قبل البعثة المحمدية، فطال عليهم الزمان بينهم وبين أنبيائهم فلم يُذكَّروا ولم يُرشَدوا، فقست قلوبهم من أجل ذلك، وأصبح أكثرهم فاسقين عن دين الله، لا يعرفون معروفاً ولا ينكرون منكراً. اعلموا أيها المؤمنون المصابون ببعض الغفلة أن الله يحيي الأرض بعد موتها بالغيث فتنبت وتزدهر، فكذلك القلوب تموت بترك التذكير والإرشاد وتحيا بهما. قد وضّحنا لكم الآيات في هذا الكتاب لتعقلوا عنّا ما نخاطبكم به وننصح لكم فيه، فاذكروا هذا ولا تنسوه، وراجعوا قلوبكم وتعهّدوها بذكر الله والدار الآخرة. إن المتصدّقين بفضول أموالهم في سبيل الله والمتصدّقات، وأقرضوا الله قرضاً حسناً بما أنفقوه طيبة به نفوسهم، لا منّة فيه ولا رياء ولا سمعة، يضاعف لهم ثواب صدقاتهم إلى عشرة أضعاف إلى سبعمائة ضعف إلى ألف ألف، ولهم أجر كريم وهو الجنة. والذين آمنوا بالله ورسله فصدّقوا بالله رباً وإلهاً وبرسله المصطفين، هؤلاء هم الصدّيقون، فازوا بمرتبة الصدّيقية، والشهداء الذين استُشهدوا في معارك الجهاد هم الآن عند ربهم لهم أجرهم ونورهم، أرواحهم في حواصل طير خضر ترعى في الجنة. والذين كفروا بالله ورسله وكذّبوا بآيات ربهم الحاوية لشرائعه فلم يعبدوه بها، هؤلاء هم أصحاب الجحيم الذين يلازمونها وتلازمهم أبداً.", "h": ["التحذير من الغفلة ونسيان ذكر الله وما عنده من نعيم وما لديه من نكال وعذاب.", "وجوب التذكير للمؤمنين والوعظ والإرشاد والتعليم، خشية أن تقسو قلوبهم فيفسقوا كما فسق أهل الكتاب، ويكفروا كما كفروا.", "تقرير حقيقة، وهي أن الأرض تحيا بالغيث، والقلوب تحيا بالعلم والمواعظ والتذكير بالله.", "بيان أصناف المؤمنين ورتبهم، وهم المتصدّقون والمقرضون في سبيل الله أموالهم، والمؤمنون بالله ورسله حق الإيمان، والصدّيقون، وشهداء الجهاد في سبيل الله."], "k": "«ألم يأنِ للذين آمنوا أن تخشع قلوبهم»… السؤال موجّه لي أنا أيضاً؛ متى آن آخر مرة أن خشع قلبي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 402;
insert into public.tdb_cards(topic, i, body) select 402, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢ – ١٥", "q": "يَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡيَوۡمَ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٢﴾ يَوۡمَ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُواْ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِيلَ ٱرۡجِعُواْ وَرَآءَكُمۡ فَٱلۡتَمِسُواْ نُورٗاۖ فَضُرِبَ بَيۡنَهُم بِسُورٖ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ٱلرَّحۡمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ ﴿١٣﴾ يُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُواْ بَلَىٰ وَلَٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِيُّ حَتَّىٰ جَآءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ ﴿١٤﴾ فَٱلۡيَوۡمَ لَا يُؤۡخَذُ مِنكُمۡ فِدۡيَةٞ وَلَا مِنَ ٱلَّذِينَ كَفَرُواْۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِيَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٥﴾", "w": [["يسعى نورهم بين أيديهم وبأيمانهم", "يتقدّمهم نورهم الذي اكتسبوه بالإيمان والعمل الصالح بمسافات بعيدة، يضيء لهم الصراط الذي يجتازونه."], ["بشراكم اليوم جنات", "تقول لهم الملائكة الذين أُعدّوا لاستقبالهم: بشراكم اليوم جنات تجري من تحتها الأنهار."], ["ذلك هو الفوز العظيم", "النجاة من النار ودخول الجنة هو الفوز العظيم."], ["المنافقون والمنافقات", "الذين كانوا يخفون الكفر في نفوسهم ويظهرون الإيمان والإسلام بألسنتهم."], ["انظرونا نقتبس من نوركم", "انظروا إلينا بوجوهكم نأخذ من نوركم ما يضيء لنا."], ["قيل ارجعوا وراءكم فالتمسوا نوراً", "يقال لهم استهزاءً بهم: ارجعوا وراءكم إلى الدنيا، حيث يُطلب النور هناك بالإيمان وصالح الأعمال."], ["فضُرب بينهم بسور له باب باطنه فيه الرحمة", "فضُرب بينهم وبين المؤمنين بسور عالٍ له باب، باطنه الذي من جهة المؤمنين فيه الرحمة."], ["وظاهره من قِبله العذاب", "الذي من جهة المنافقين في عرصات القيامة فيه العذاب."], ["ينادونهم ألم نكن معكم", "ينادي المنافقون المؤمنين: ألم نكن معكم في الدنيا على الطاعات، نصلّي كما تصلّون ونجاهد كما تجاهدون؟"], ["قالوا بلى", "كنتم معنا على الطاعات."], ["ولكنكم فتنتم أنفسكم", "بالنفاق، وهو كفر الباطن وبغض الإسلام والمسلمين."], ["وتربّصتم", "الدوائر بالمسلمين، تنتظرون متى يُهزم المؤمنون فتعلنون كفركم."], ["وغرّكم بالله الغَرور", "غرّكم الشيطان حيث زيّن لكم الكفر وكرّه إليكم الإيمان."], ["فاليوم لا يؤخذ منكم فدية", "مال تفدون به أنفسكم، إذ لا مال يومئذ ينفع ولا ولد."], ["مأواكم النار هي مولاكم", "مستقرّكم ومكان إيوائكم النار، وهي أولى بكم."], ["وبئس المصير", "مصيركم الذي صرتم إليه، وهو النار."]], "m": "لهم أجر كريم يوم ترى المؤمنين والمؤمنات في عرصات القيامة يسعى نورهم الذي اكتسبوه بإيمانهم وصالح أعمالهم في الدنيا، يمشي أمامهم يهديهم إلى طريق الجنة، وقد أُعطوا كتبهم بأيمانهم، وتقول لهم الملائكة الذين أُعدّوا لاستقبالهم: بشراكم اليوم جنات تجري من خلال أشجارها وقصورها أنهار الماء واللبن والخمر والعسل، خالدين فيها، ذلك هو الفوز العظيم، إذ هو نجاة من النار ودخول الجنان في جوار الرحمن. يوم يقول المنافقون والمنافقات، الذين كانوا في الدنيا يخفون الكفر ويظهرون الإيمان، للذين آمنوا: أقبلوا علينا بوجوهكم ذات الأنوار نأخذ من نوركم ما يضيء لنا الطريق، فيقال لهم استهزاءً بهم: ارجعوا وراءكم فالتمسوا نوراً، إشارة إلى أن هذا النور يُطلب في الدنيا بالإيمان وصالح الأعمال، فيرجعون إلى الوراء، وفوراً يُضرب بينهم وبين المؤمنين بسور عالٍ له باب، باطنه وهو يلي المؤمنين فيه الرحمة، وظاهره وهو يلي المنافقين من قبله العذاب، فيأخذون في ندائهم: ألم نكن معكم على الطاعات أيها المؤمنون؟ فقد كنا نصلّي معكم ونجاهد وننفق كما تنفقون. فيقول المؤمنون: بلى، كنتم معنا في الظاهر، ولكنكم فتنتم أنفسكم بالنفاق، وتربّصتم بنا الدوائر لتعلنوا عن كفركم، وشككتم في صحة الإسلام وعقائده ومنها البعث، وغرّتكم الأماني الكاذبة في أن محمداً لن ينتصر ودينه لن يظهر، حتى جاء أمر الله بنصر رسوله وإظهار دينه، وغرّكم بالله الشيطان، إذ زيّن لكم الكفر وذكّركم بعفو الله وعدم مؤاخذته لكم. فاليوم لا يؤخذ منكم فداء مهما كان، ولا من الذين كفروا كذلك، مأواكم النار، هي التي تتولّاكم وتضمّكم، وهي أولى بكم لخبث نفوسكم من جرّاء النفاق والكفر، وبئس المصير.", "h": ["تقرير البعث بذكر أحداثه وما يجري فيه.", "تقرير أن الفوز ليس ربح الشاة والبعير ولا الدار ولا البستان في الدنيا، وإنما هو الزحزحة عن النار ودخول الجنان يوم القيامة، هذا هو الفوز العظيم.", "من بشائر السعادة لأهل الإيمان قبل دخول الجنة تلقّي الملائكة لهم، وإعطاؤهم كتبهم بأيمانهم، ووجود نور عالٍ يسعى بين أيديهم وبأيمانهم يتقدّمهم على الصراط إلى الجنة.", "نور يوم القيامة في وجوه المؤمنين أخذوه من الدنيا، وفي الحديث: «بشّر المشّائين في الظُّلَم إلى المساجد بالنور التام يوم القيامة».", "بيان صفات المنافقين في الدنيا، وهي إبطان الكفر في نفوسهم، والتربّص بالمؤمنين للانقضاض عليهم متى ضعفوا أو هُزموا، وأمانيهم في عدم نصرة الإسلام، وشكّهم الملازم لهم حتى ماتوا شاكّين في صحة الإسلام وما جاء به."], "k": "«ارجعوا وراءكم فالتمسوا نوراً»… النور يُصنع هنا لا هناك؛ فكم خطوة إلى المسجد في الظلمة صنعت لي نوراً؟"}, {"lbl": "الآيات ١٦ – ١٩", "q": "۞أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ ﴿١٦﴾ ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿١٧﴾ إِنَّ ٱلۡمُصَّدِّقِينَ وَٱلۡمُصَّدِّقَٰتِ وَأَقۡرَضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرٞ كَرِيمٞ ﴿١٨﴾ وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦٓ أُوْلَـٰٓئِكَ هُمُ ٱلصِّدِّيقُونَۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿١٩﴾", "w": [["ألم يأنِ للذين آمنوا", "ألم يحن الوقت للذين أكثروا من المزاح…"], ["أن تخشع قلوبهم لذكر الله", "أن تلين وتسكن وتخضع وتطمئن لذكر الله ووعده ووعيده."], ["وما نزل من الحق", "القرآن وما يحويه من وعد ووعيد."], ["ولا يكونوا كالذين أوتوا الكتاب من قبل", "ولا يكونوا كاليهود والنصارى في الإعراض والغفلة."], ["فطال عليهم الأمد", "الزمن بينهم وبين أنبيائهم."], ["فقست قلوبهم", "لعدم وجود من يذكّرهم ويرشدهم، فلم تلن لذكر الله."], ["وكثير منهم فاسقون", "نتيجة لقسوة القلوب المترتبة على ترك التذكير، ففسق أكثرهم فخرج عن دين الله."], ["اعلموا أن الله يحيي الأرض بعد موتها", "بالغيث ينزل بها، وكذلك يحيي القلوب بالذكر والتذكير فتلين وتخشع."], ["قد بيّنا لكم الآيات لعلكم تعقلون", "بيّنا الآيات الدالة على قدرتنا وعلمنا ورحمتنا، رجاء أن تعقلوا فتحفظوا أنفسكم مما يرديها."], ["إن المصّدّقين والمصّدّقات", "المتصدّقين بفضول أموالهم، والمتصدّقات كذلك."], ["وأقرضوا الله قرضاً حسناً", "وكانت صدقاتهم كالقرض الحسن الذي لا منّة معه، والنفس طيبة به راجية جزاءه."], ["يُضاعف لهم", "الحسنة بعشر أمثالها إلى سبعمائة، إلى ألف ألف."], ["والذين آمنوا بالله ورسله", "صدّقوا بالله رباً وإلهاً، وبرسله هداة ودعاة صادقين."], ["أولئك هم الصدّيقون", "الذين كُتبوا عند الله صدّيقين، وهي مرتبة شرف عالية."], ["والشهداء عند ربهم لهم أجرهم ونورهم", "وشهداء المعارك في سبيل الله عند ربهم لهم أجرهم العظيم ونورهم التام يوم القيامة."], ["والذين كفروا وكذّبوا بآياتنا", "كفروا بالله وتوحيده، وكذّبوا بالقرآن وما حواه من الشرائع."], ["أولئك أصحاب الجحيم", "أهل النار الذين لا يفارقونها أبداً."]], "m": "ألم يحن الوقت للذين آمنوا بالله رباً وإلهاً وبمحمد ﷺ نبياً، وبوعد الله ووعيده صدقاً وحقاً، أن تخشع قلوبهم فتلين وتطمئن لذكر الله، ولما نزل من الحق في الكتاب الكريم، فيعرفون المعروف ويأمرون به، ويعرفون المنكر وينهون عنه؟ إنها لموعظة إلهية عظيمة، وزادها عظمة أن تنزل في أصحاب رسول الله ﷺ تستبطئ قلوبهم. ولا يكونوا كاليهود والنصارى الذين أوتوا الكتاب من قبل البعثة المحمدية، فطال عليهم الزمان بينهم وبين أنبيائهم فلم يُذكَّروا ولم يُرشَدوا، فقست قلوبهم من أجل ذلك، وأصبح أكثرهم فاسقين عن دين الله، لا يعرفون معروفاً ولا ينكرون منكراً. اعلموا أيها المؤمنون المصابون ببعض الغفلة أن الله يحيي الأرض بعد موتها بالغيث فتنبت وتزدهر، فكذلك القلوب تموت بترك التذكير والإرشاد وتحيا بهما. قد وضّحنا لكم الآيات في هذا الكتاب لتعقلوا عنّا ما نخاطبكم به وننصح لكم فيه، فاذكروا هذا ولا تنسوه، وراجعوا قلوبكم وتعهّدوها بذكر الله والدار الآخرة. إن المتصدّقين بفضول أموالهم في سبيل الله والمتصدّقات، وأقرضوا الله قرضاً حسناً بما أنفقوه طيبة به نفوسهم، لا منّة فيه ولا رياء ولا سمعة، يضاعف لهم ثواب صدقاتهم إلى عشرة أضعاف إلى سبعمائة ضعف إلى ألف ألف، ولهم أجر كريم وهو الجنة. والذين آمنوا بالله ورسله فصدّقوا بالله رباً وإلهاً وبرسله المصطفين، هؤلاء هم الصدّيقون، فازوا بمرتبة الصدّيقية، والشهداء الذين استُشهدوا في معارك الجهاد هم الآن عند ربهم لهم أجرهم ونورهم، أرواحهم في حواصل طير خضر ترعى في الجنة. والذين كفروا بالله ورسله وكذّبوا بآيات ربهم الحاوية لشرائعه فلم يعبدوه بها، هؤلاء هم أصحاب الجحيم الذين يلازمونها وتلازمهم أبداً.", "h": ["التحذير من الغفلة ونسيان ذكر الله وما عنده من نعيم وما لديه من نكال وعذاب.", "وجوب التذكير للمؤمنين والوعظ والإرشاد والتعليم، خشية أن تقسو قلوبهم فيفسقوا كما فسق أهل الكتاب، ويكفروا كما كفروا.", "تقرير حقيقة، وهي أن الأرض تحيا بالغيث، والقلوب تحيا بالعلم والمواعظ والتذكير بالله.", "بيان أصناف المؤمنين ورتبهم، وهم المتصدّقون والمقرضون في سبيل الله أموالهم، والمؤمنون بالله ورسله حق الإيمان، والصدّيقون، وشهداء الجهاد في سبيل الله."], "k": "«ألم يأنِ للذين آمنوا أن تخشع قلوبهم»… السؤال موجّه لي أنا أيضاً؛ متى آن آخر مرة أن خشع قلبي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (403, 57, 20, 29, 'سورة الحديد ٢٠ – ٢٩', 'الحديد: سابقوا إلى مغفرة من ربكم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 403) = $j$[{"lbl": "الآيتان ٢٠ – ٢١", "q": "ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞ وَزِينَةٞ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرٞ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِۖ كَمَثَلِ غَيۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَكُونُ حُطَٰمٗاۖ وَفِي ٱلۡأٓخِرَةِ عَذَابٞ شَدِيدٞ وَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرِضۡوَٰنٞۚ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ ﴿٢٠﴾ سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٢١﴾", "w": [["إنما الحياة الدنيا لعب ولهو", "إن الحياة الدنيا أشبه بالأمور الخيالية، قليلة النفع، سريعة الزوال."], ["وزينة", "ما يتزيّن به المرء من أنواع الزينة، والزينة سريعة التغيّر."], ["وتفاخر بينكم وتكاثر في الأموال والأولاد", "إنها لا تخرج عن كونها لهواً ولعباً وزينة وتفاخراً وتكاثراً في الأموال والأولاد."], ["كمثل غيث أعجب الكفار نباته", "مثلها في سرعة زوالها كمثل مطر أعجب الزرّاع ما نبت به من الزرع."], ["ثم يهيج فتراه مصفرّاً", "ييبس فتراه مصفرّاً آن أوان حصاده."], ["ثم يكون حطاماً", "ثم يتحوّل بسرعة إلى حطام يابس يتفتّت."], ["وما الحياة الدنيا إلا متاع الغرور", "وما الحياة الدنيا في التمتع بها إلا غرور لا حقيقة له."], ["سابقوا إلى مغفرة من ربكم", "سارعوا بالتوبة مسابقين غيركم لتُغفر لكم ذنوبكم وتدخلوا الجنة."], ["ذلك فضل الله يؤتيه من يشاء", "الموعود به من المغفرة والجنة."], ["والله ذو الفضل العظيم", "فلا يبعد تفضّله بذلك الموعود به وإن كان عظيماً."]], "m": "ما زال السياق في توجيه المؤمنين وإرشادهم إلى ما يزيد في كمالهم وسعادتهم: اعلموا أيها المؤمنون الذين استبطأ الله خشوع قلوبهم، إذ الإقبال على الدنيا هو سبب الغفلة عن الآخرة، أنما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الأموال والأولاد؛ هذه حقيقتها، أمور خيالية قليلة النفع سريعة الزوال، فلا تغترّوا بها ولا تُقبلوا بكلّكم عليها. فاللهو كاللعب لا يُخلّفان منفعة، والزينة سرعان ما تتغيّر وتزول، والتفاخر مجرد كلام ما وراءه طائل، والتكاثر لا ينتهي إلى حد ولا يُجمع إلا بالشقاء والتعب ثم يذهب، وله تبعات لا ينجو منها صاحبها إلا برحمة من الله. ومثل الحياة الدنيا كمثل مطر أعجب الفلاحين الذين ستروا البذر بالتربة نباته، ثم ييبس فتراه مصفرّاً، ثم يكون حطاماً يتفتّت؛ هذه هي الدنيا من بدايتها إلى نهايتها المؤلمة. أما الآخرة ففيها عذاب شديد لأهل الشرك والمعاصي، ومغفرة من الله ورضوان لأهل التوحيد وصالح الأعمال. وما الحياة الدنيا إلا متاع الغرور، أي لا حقيقة لها، وكل ما فيها من المتع غرور باطل. وعليه فسابقوا إلى مغفرة من ربكم، سارعوا بالتوبة مسابقين بعضكم بعضاً لتُغفر ذنوبكم وتدخلوا جنة ربكم التي عرضها كعرض السماء والأرض، أُعدّت للذين آمنوا بالله ورسله. ذلك فضل الله يؤتيه من يشاء، ومن سارع إلى التوبة فآمن وعمل صالحاً فهو ممن شاء له فضله، والله ذو الفضل العظيم.", "h": ["التحذير من الاغترار بالحياة الدنيا.", "الدعوة إلى المسابقة في طلب مغفرة الذنب ودخول الجنة.", "بيان الجنة، وبيان ما يُكسبها، وهو الإيمان بالله ورسله ومستلزماته من التوحيد والعمل الصالح."], "k": "«سابقوا إلى مغفرة من ربكم»… أسابق الناس في الدنيا كثيراً؛ فهل سابقتهم يوماً إلى المغفرة؟"}, {"lbl": "الآيات ٢٢ – ٢٥", "q": "مَآ أَصَابَ مِن مُّصِيبَةٖ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبٖ مِّن قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿٢٢﴾ لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ ﴿٢٣﴾ ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿٢٤﴾ لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ﴿٢٥﴾", "w": [["ما أصاب من مصيبة في الأرض", "بالجدب وذهاب المال."], ["ولا في أنفسكم", "بالمرض وفقد الولد."], ["إلا في كتاب من قبل أن نبرأها", "في اللوح المحفوظ قبل أن نخلقها."], ["إن ذلك على الله يسير", "سهل ليس بالصعب."], ["لكيلا تأسوا على ما فاتكم", "لكيلا تحزنوا على ما فاتكم مما تحبون من الخير."], ["ولا تفرحوا بما آتاكم", "بما أعطاكم فرح البطر، أما فرح الشكر فهو مشروع."], ["والله لا يحب كل مختال فخور", "مختال بتكبّره بما أُعطي، فخور به على الناس."], ["الذين يبخلون ويأمرون الناس بالبخل", "الذين يمنعون الواجب ويدعون غيرهم إلى منعه."], ["فإن الله هو الغني", "غني عن سائر خلقه، لأن غناه ذاتي له لا يستمدّه من غيره."], ["الحميد", "المحمود بجلاله وجماله وآلائه ونعمه على عباده."], ["لقد أرسلنا رسلنا بالبيّنات", "بالحجج والبراهين القاطعة على صدق دعوتهم."], ["وأنزلنا معهم الكتاب", "الكتب الحاوية للشرائع والأحكام."], ["والميزان", "العدل الذي نزلت الكتب بالأمر به وتقريره."], ["ليقوم الناس بالقسط", "لتقوم حياتهم فيما بينهم على أساس العدل."], ["فيه بأس شديد", "في الحديد بأس شديد، والمراد آلات القتال."], ["ومنافع للناس", "ينتفع به الناس، إذ ما من صنعة إلا والحديد آلتها."], ["وليعلم الله من ينصره ورسله بالغيب", "ليعلم الله من ينصر دينه وأولياءه ورسله المبلّغين عنه، وهم لا يشاهدونه بأبصارهم."], ["إن الله قوي عزيز", "لا حاجة به إلى نصرة أحد."]], "m": "ما زال السياق في إرشاد المؤمنين وتوجيههم إلى ما يكمّلهم ويسعدهم: ما أصابكم أيها المؤمنون من مصيبة في الأرض بالجدب والقحط أو الجوائح تصيب الزرع، ولا في أنفسكم بالمرض وفقد الولد، إلا وهي في كتاب المقادير مكتوبة بكميتها وكيفيتها وزمانها ومكانها من قبل أن يخلقها الله، وإن ذلك على الله يسير. أعلمناكم بذلك من أجل ألا تحزنوا على ما فاتكم مما تحبون في دنياكم، ولا تفرحوا بما آتاكم فرح الأشر والبطر فإنه مضر، أما فرح الشكر فلا بأس به، فقد ينعم الله على العبد ليشكره. والله لا يحب كل مختال فخور: يحذّر أولياءه من خصلتين ذميمتين لا تنبغيان للمؤمن، وهما الاختيال أي التكبر، والفخر على الناس بما أعطاه الله وحرمهم. ثم بيّن صفتين قبيحتين لأهل الكبر والفخر: البخل الذي هو منع الواجب، والأمر بالبخل والدعوة إليه. ومن يتولّ عن الإيمان والطاعة وعدم قبول وعظ الله فإن الله هو الغني عن سائر خلقه، الحميد بجلاله وجماله وإنعامه. لقد أرسلنا رسلنا بالحجج القواطع، وأنزلنا معهم الكتاب الحاوي للشرائع والأحكام التي يكمل عليها الناس ويسعدون، وأنزلنا الميزان ليقوم الناس بالعدل. وكما أنزلنا الكتاب للدين والعدل للدنيا أنزلنا الحديد لهما معاً: فيه بأس شديد في الحروب لإقامة الدين بالجهاد، ومنافع للناس إذ سائر الصناعات متوقفة عليه. ومن الحكمة في إنزاله أن يعلم الله من ينصر دينه ورسله بالجهاد معهم والوقوف إلى جانبهم، وهم لا يشاهدون الله تعالى بأعينهم وإن عرفوه بقلوبهم. إن الله قوي عزيز، لا حاجة به إلى نصرة أحد من خلقه، لقوته الذاتية وعزته التي لا تُرام، وإنما كلّف عباده بنصرة دينه ورسله تشريفاً لهم وتكريماً، وليرفعهم بذلك إلى مقام الشهداء.", "h": ["تقرير عقيدة القضاء والقدر.", "بيان الحكمة في معرفة القضاء والقدر والإيمان بهما.", "حرمة الاختيال والفخر والبخل والأمر بالبخل.", "بيان إفضال الله وإنعامه على الناس بإرسال الرسل وإنزال الكتب والميزان، وإنزال الحديد بما فيه من منافع للناس وبأس شديد."], "k": "«لكيلا تأسوا على ما فاتكم ولا تفرحوا بما آتاكم»… كله مكتوب قبل أن يكون؛ فلماذا يطير قلبي فرحاً أو ينكسر حزناً؟"}, {"lbl": "الآيتان ٢٦ – ٢٧", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحٗا وَإِبۡرَٰهِيمَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَۖ فَمِنۡهُم مُّهۡتَدٖۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ ﴿٢٦﴾ ثُمَّ قَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى ٱبۡنِ مَرۡيَمَ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَۖ وَجَعَلۡنَا فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةٗ وَرَحۡمَةٗۚ وَرَهۡبَانِيَّةً ٱبۡتَدَعُوهَا مَا كَتَبۡنَٰهَا عَلَيۡهِمۡ إِلَّا ٱبۡتِغَآءَ رِضۡوَٰنِ ٱللَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَايَتِهَاۖ فَـَٔاتَيۡنَا ٱلَّذِينَ ءَامَنُواْ مِنۡهُمۡ أَجۡرَهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ ﴿٢٧﴾", "w": [["ولقد أرسلنا نوحاً وإبراهيم", "وتالله لقد أرسلنا نوحاً، وهو الأب الثاني للبشر، وإبراهيم أبا الأنبياء."], ["وجعلنا في ذريتهما النبوة والكتاب", "النبوة، والكتاب: التوراة والزبور والإنجيل والفرقان."], ["وكثير منهم فاسقون", "عن طاعة الله ورسله، ضالّون في طريقهم."], ["ثم قفّينا على آثارهم برسلنا", "أرسلنا رسولاً بعد رسول حتى انتهينا إلى عيسى."], ["وقفّينا بعيسى ابن مريم", "أتبعناهم بعيسى ابن مريم لتأخّره عنهم في الزمان."], ["وجعلنا في قلوب الذين اتبعوه", "على دينه، وهم الحواريون وأتباعهم."], ["رأفة ورحمة", "ليناً وشفقة."], ["ورهبانية ابتدعوها", "وابتدعوا رهبانية لم يكتبها الله عليهم، وهي اعتزال النساء والانقطاع في الأديرة والصوامع للتعبّد."], ["إلا ابتغاء رضوان الله", "إلا طلباً لرضوان الله عز وجل."], ["فما رعوها حق رعايتها", "لم يلتزموا بما نذروه على أنفسهم من الطاعات."], ["فآتينا الذين آمنوا منهم أجرهم", "فأعطينا الذين ثبتوا على إيمانهم وتقواهم أجرهم."], ["وكثير منهم فاسقون", "لا أجر لهم ولا ثواب إلا العقاب."]], "m": "يخبر تعالى أنه كما أرسل رسله وأنزل معهم الكتاب والميزان، أرسل كذلك نوحاً وإبراهيم؛ فنوح أبو البشر الثاني، وإبراهيم أبو الأنبياء من بعده، ذكرهما لمزيد شرفهما، وجعل في ذريتهما النبوة والكتاب: فهود وصالح وشعيب وإبراهيم ولوط من ذرية نوح، وإسماعيل وإسحاق وباقي الأنبياء من ذرية إبراهيم. فمن أولئك الذرية المهتدي، وأكثرهم فاسقون. ثم أرسلنا رسولاً بعد رسول إلى عيسى ابن مريم، وآتيناه الإنجيل، وجعلنا في قلوب الذين اتبعوه رأفة، وهي اللين وأشد الرحمة، ورحمة. ورهبانية ابتدعوها من التشديد ما كتبناها عليهم، ولكن ما ابتدعوها إلا طلباً لرضوان الله، فما رعوها حق رعايتها، حيث لم يوفوا بما التزموا به من ترك الدنيا والإقبال على الآخرة. ولهذه الرهبانية سبب مروي عن ابن عباس رضي الله عنهما، نذكره باختصار: كان بعد عيسى ملوك بدّلوا التوراة وحرّفوا الإنجيل وألزموا العامة بذلك، وكان بينهم جماعة رفضوا ذلك التحريف ففرّوا بدينهم والتحقوا بالجبال وانقطعوا عن الناس مخافة قتلهم أو تعذيبهم، فهذا الانقطاع بداية الرهبانية، وعاش أولئك المؤمنون وماتوا، وجاء جيل من أبناء الدين المحرّف فذكروا سيرة الصالحين الأولين فأرادوا أن يفعلوا فعلهم فانقطعوا إلى الصوامع والأديرة، ولكنهم جهال وعلى دين محرّف، فما انتفعوا بالرهبانية المبتدعة، وفسق أكثرهم. وهو ما دلّ عليه قوله: فآتينا الذين آمنوا منهم أجرهم، وهم الأولون الذين فرّوا من الكفر والتعذيب وعبدوا الله بما شرع، وكثير منهم فاسقون، وهم الذين أتوا من بعدهم، إذ يعبدون الله بدين محرّف باطل.", "h": ["بيان منّة الله على عباده بإرسال الرسل.", "بيان سنة الله في الناس، وهي أنه إذا أرسل الرسل لهداية الناس يهتدي بعض ويضل بعض.", "ثناء الله على عيسى ابن مريم وأتباعه بحق من الحواريين وغيرهم، إلى أن غيّرت الملوك دين المسيح وضلّ الناس وأصبحوا فاسقين عن دين الله تعالى.", "تحريم البدع والابتداع، ولا رهبانية في الإسلام، ولكن يُعبد الله بما شرع."], "k": "«فما رعوها حق رعايتها»… قد أبدأ عبادة بحماس ثم أتركها؛ فهل أرعى ما ألزمت به نفسي؟"}, {"lbl": "الآيتان ٢٨ – ٢٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ وَيَجۡعَل لَّكُمۡ نُورٗا تَمۡشُونَ بِهِۦ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٢٨﴾ لِّئَلَّا يَعۡلَمَ أَهۡلُ ٱلۡكِتَٰبِ أَلَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٢٩﴾", "w": [["يا أيها الذين آمنوا", "بعيسى ابن مريم، وموسى من قبله."], ["اتقوا الله وآمنوا برسوله", "خافوا عقاب الله، وآمنوا بمحمد ﷺ واتبعوه."], ["يؤتكم كفلين من رحمته", "يعطكم الله نصيبين من الأجر مقابل إيمانكم بنبيكم وإيمانكم بمحمد ﷺ."], ["ويجعل لكم نوراً تمشون به", "في الدنيا إذ تعيشون على هداية الله، وفي الآخرة تمشون به على الصراط."], ["لئلا يعلم أهل الكتاب", "لكي يعلم أهل الكتاب أنهم لا يقدرون على شيء من فضل الله، واللام في «لئلا» مزيدة لتقوية الكلام."]], "m": "هذا نداء الله لأهل الكتاب بعد أن ذكر نبذة عن رسلهم وأتباعهم، نادى الموجودين منهم بعنوان الإيمان، أي يا من آمنتم بالرسل السابقين حسب ادعائكم: اتقوا الله فلا تفرّقوا بين رسل الله، وآمنوا برسوله محمد ﷺ يعطكم حظين ونصيبين من رحمته ومثوبته، ويجعل لكم نوراً تمشون به في الدنيا، وهو الهداية الإسلامية، إذ الإسلام صراط مستقيم صاحبه لا يضل ولا يشقى، وتمشون به في الآخرة على الصراط إلى دار السلام، ويغفر لكم ذنوبكم، والله غفور رحيم. وذلك ليعلم أهل الكتاب من اليهود والنصارى الذين رفضوا الإيمان بمحمد ﷺ والدخول في الإسلام أنهم لا يقدرون على الحصول على شيء من فضل الله، وأن الفضل بيد الله يؤتيه من يشاء، والله ذو الفضل العظيم.", "h": ["أعظم نصيحة تُقدَّم لأهل الكتاب لو أخذوا بها تضمّنها نداء الله لهم وما وعدهم به في هذه الآية الكريمة.", "فضل الإيمان والتقوى، إذ هما سبيل الولاية والكرامة في الدنيا والآخرة.", "إبطال مزاعم أهل الكتاب في احتكار الجنة لهم، وإعلامهم بأنهم محرومون منها ما لم يؤمنوا برسول الله ﷺ ويتقوا الله بفعل أوامره واجتناب نواهيه."], "k": "«ويجعل لكم نوراً تمشون به»… التقوى نور في طريقي اليوم وعلى الصراط غداً؛ فهل يكفيني نوري الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 403;
insert into public.tdb_cards(topic, i, body) select 403, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٠ – ٢١", "q": "ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞ وَزِينَةٞ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرٞ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِۖ كَمَثَلِ غَيۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَكُونُ حُطَٰمٗاۖ وَفِي ٱلۡأٓخِرَةِ عَذَابٞ شَدِيدٞ وَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرِضۡوَٰنٞۚ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ ﴿٢٠﴾ سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٢١﴾", "w": [["إنما الحياة الدنيا لعب ولهو", "إن الحياة الدنيا أشبه بالأمور الخيالية، قليلة النفع، سريعة الزوال."], ["وزينة", "ما يتزيّن به المرء من أنواع الزينة، والزينة سريعة التغيّر."], ["وتفاخر بينكم وتكاثر في الأموال والأولاد", "إنها لا تخرج عن كونها لهواً ولعباً وزينة وتفاخراً وتكاثراً في الأموال والأولاد."], ["كمثل غيث أعجب الكفار نباته", "مثلها في سرعة زوالها كمثل مطر أعجب الزرّاع ما نبت به من الزرع."], ["ثم يهيج فتراه مصفرّاً", "ييبس فتراه مصفرّاً آن أوان حصاده."], ["ثم يكون حطاماً", "ثم يتحوّل بسرعة إلى حطام يابس يتفتّت."], ["وما الحياة الدنيا إلا متاع الغرور", "وما الحياة الدنيا في التمتع بها إلا غرور لا حقيقة له."], ["سابقوا إلى مغفرة من ربكم", "سارعوا بالتوبة مسابقين غيركم لتُغفر لكم ذنوبكم وتدخلوا الجنة."], ["ذلك فضل الله يؤتيه من يشاء", "الموعود به من المغفرة والجنة."], ["والله ذو الفضل العظيم", "فلا يبعد تفضّله بذلك الموعود به وإن كان عظيماً."]], "m": "ما زال السياق في توجيه المؤمنين وإرشادهم إلى ما يزيد في كمالهم وسعادتهم: اعلموا أيها المؤمنون الذين استبطأ الله خشوع قلوبهم، إذ الإقبال على الدنيا هو سبب الغفلة عن الآخرة، أنما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الأموال والأولاد؛ هذه حقيقتها، أمور خيالية قليلة النفع سريعة الزوال، فلا تغترّوا بها ولا تُقبلوا بكلّكم عليها. فاللهو كاللعب لا يُخلّفان منفعة، والزينة سرعان ما تتغيّر وتزول، والتفاخر مجرد كلام ما وراءه طائل، والتكاثر لا ينتهي إلى حد ولا يُجمع إلا بالشقاء والتعب ثم يذهب، وله تبعات لا ينجو منها صاحبها إلا برحمة من الله. ومثل الحياة الدنيا كمثل مطر أعجب الفلاحين الذين ستروا البذر بالتربة نباته، ثم ييبس فتراه مصفرّاً، ثم يكون حطاماً يتفتّت؛ هذه هي الدنيا من بدايتها إلى نهايتها المؤلمة. أما الآخرة ففيها عذاب شديد لأهل الشرك والمعاصي، ومغفرة من الله ورضوان لأهل التوحيد وصالح الأعمال. وما الحياة الدنيا إلا متاع الغرور، أي لا حقيقة لها، وكل ما فيها من المتع غرور باطل. وعليه فسابقوا إلى مغفرة من ربكم، سارعوا بالتوبة مسابقين بعضكم بعضاً لتُغفر ذنوبكم وتدخلوا جنة ربكم التي عرضها كعرض السماء والأرض، أُعدّت للذين آمنوا بالله ورسله. ذلك فضل الله يؤتيه من يشاء، ومن سارع إلى التوبة فآمن وعمل صالحاً فهو ممن شاء له فضله، والله ذو الفضل العظيم.", "h": ["التحذير من الاغترار بالحياة الدنيا.", "الدعوة إلى المسابقة في طلب مغفرة الذنب ودخول الجنة.", "بيان الجنة، وبيان ما يُكسبها، وهو الإيمان بالله ورسله ومستلزماته من التوحيد والعمل الصالح."], "k": "«سابقوا إلى مغفرة من ربكم»… أسابق الناس في الدنيا كثيراً؛ فهل سابقتهم يوماً إلى المغفرة؟"}, {"lbl": "الآيات ٢٢ – ٢٥", "q": "مَآ أَصَابَ مِن مُّصِيبَةٖ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبٖ مِّن قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿٢٢﴾ لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ ﴿٢٣﴾ ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿٢٤﴾ لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ﴿٢٥﴾", "w": [["ما أصاب من مصيبة في الأرض", "بالجدب وذهاب المال."], ["ولا في أنفسكم", "بالمرض وفقد الولد."], ["إلا في كتاب من قبل أن نبرأها", "في اللوح المحفوظ قبل أن نخلقها."], ["إن ذلك على الله يسير", "سهل ليس بالصعب."], ["لكيلا تأسوا على ما فاتكم", "لكيلا تحزنوا على ما فاتكم مما تحبون من الخير."], ["ولا تفرحوا بما آتاكم", "بما أعطاكم فرح البطر، أما فرح الشكر فهو مشروع."], ["والله لا يحب كل مختال فخور", "مختال بتكبّره بما أُعطي، فخور به على الناس."], ["الذين يبخلون ويأمرون الناس بالبخل", "الذين يمنعون الواجب ويدعون غيرهم إلى منعه."], ["فإن الله هو الغني", "غني عن سائر خلقه، لأن غناه ذاتي له لا يستمدّه من غيره."], ["الحميد", "المحمود بجلاله وجماله وآلائه ونعمه على عباده."], ["لقد أرسلنا رسلنا بالبيّنات", "بالحجج والبراهين القاطعة على صدق دعوتهم."], ["وأنزلنا معهم الكتاب", "الكتب الحاوية للشرائع والأحكام."], ["والميزان", "العدل الذي نزلت الكتب بالأمر به وتقريره."], ["ليقوم الناس بالقسط", "لتقوم حياتهم فيما بينهم على أساس العدل."], ["فيه بأس شديد", "في الحديد بأس شديد، والمراد آلات القتال."], ["ومنافع للناس", "ينتفع به الناس، إذ ما من صنعة إلا والحديد آلتها."], ["وليعلم الله من ينصره ورسله بالغيب", "ليعلم الله من ينصر دينه وأولياءه ورسله المبلّغين عنه، وهم لا يشاهدونه بأبصارهم."], ["إن الله قوي عزيز", "لا حاجة به إلى نصرة أحد."]], "m": "ما زال السياق في إرشاد المؤمنين وتوجيههم إلى ما يكمّلهم ويسعدهم: ما أصابكم أيها المؤمنون من مصيبة في الأرض بالجدب والقحط أو الجوائح تصيب الزرع، ولا في أنفسكم بالمرض وفقد الولد، إلا وهي في كتاب المقادير مكتوبة بكميتها وكيفيتها وزمانها ومكانها من قبل أن يخلقها الله، وإن ذلك على الله يسير. أعلمناكم بذلك من أجل ألا تحزنوا على ما فاتكم مما تحبون في دنياكم، ولا تفرحوا بما آتاكم فرح الأشر والبطر فإنه مضر، أما فرح الشكر فلا بأس به، فقد ينعم الله على العبد ليشكره. والله لا يحب كل مختال فخور: يحذّر أولياءه من خصلتين ذميمتين لا تنبغيان للمؤمن، وهما الاختيال أي التكبر، والفخر على الناس بما أعطاه الله وحرمهم. ثم بيّن صفتين قبيحتين لأهل الكبر والفخر: البخل الذي هو منع الواجب، والأمر بالبخل والدعوة إليه. ومن يتولّ عن الإيمان والطاعة وعدم قبول وعظ الله فإن الله هو الغني عن سائر خلقه، الحميد بجلاله وجماله وإنعامه. لقد أرسلنا رسلنا بالحجج القواطع، وأنزلنا معهم الكتاب الحاوي للشرائع والأحكام التي يكمل عليها الناس ويسعدون، وأنزلنا الميزان ليقوم الناس بالعدل. وكما أنزلنا الكتاب للدين والعدل للدنيا أنزلنا الحديد لهما معاً: فيه بأس شديد في الحروب لإقامة الدين بالجهاد، ومنافع للناس إذ سائر الصناعات متوقفة عليه. ومن الحكمة في إنزاله أن يعلم الله من ينصر دينه ورسله بالجهاد معهم والوقوف إلى جانبهم، وهم لا يشاهدون الله تعالى بأعينهم وإن عرفوه بقلوبهم. إن الله قوي عزيز، لا حاجة به إلى نصرة أحد من خلقه، لقوته الذاتية وعزته التي لا تُرام، وإنما كلّف عباده بنصرة دينه ورسله تشريفاً لهم وتكريماً، وليرفعهم بذلك إلى مقام الشهداء.", "h": ["تقرير عقيدة القضاء والقدر.", "بيان الحكمة في معرفة القضاء والقدر والإيمان بهما.", "حرمة الاختيال والفخر والبخل والأمر بالبخل.", "بيان إفضال الله وإنعامه على الناس بإرسال الرسل وإنزال الكتب والميزان، وإنزال الحديد بما فيه من منافع للناس وبأس شديد."], "k": "«لكيلا تأسوا على ما فاتكم ولا تفرحوا بما آتاكم»… كله مكتوب قبل أن يكون؛ فلماذا يطير قلبي فرحاً أو ينكسر حزناً؟"}, {"lbl": "الآيتان ٢٦ – ٢٧", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحٗا وَإِبۡرَٰهِيمَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَۖ فَمِنۡهُم مُّهۡتَدٖۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ ﴿٢٦﴾ ثُمَّ قَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى ٱبۡنِ مَرۡيَمَ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَۖ وَجَعَلۡنَا فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةٗ وَرَحۡمَةٗۚ وَرَهۡبَانِيَّةً ٱبۡتَدَعُوهَا مَا كَتَبۡنَٰهَا عَلَيۡهِمۡ إِلَّا ٱبۡتِغَآءَ رِضۡوَٰنِ ٱللَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَايَتِهَاۖ فَـَٔاتَيۡنَا ٱلَّذِينَ ءَامَنُواْ مِنۡهُمۡ أَجۡرَهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ ﴿٢٧﴾", "w": [["ولقد أرسلنا نوحاً وإبراهيم", "وتالله لقد أرسلنا نوحاً، وهو الأب الثاني للبشر، وإبراهيم أبا الأنبياء."], ["وجعلنا في ذريتهما النبوة والكتاب", "النبوة، والكتاب: التوراة والزبور والإنجيل والفرقان."], ["وكثير منهم فاسقون", "عن طاعة الله ورسله، ضالّون في طريقهم."], ["ثم قفّينا على آثارهم برسلنا", "أرسلنا رسولاً بعد رسول حتى انتهينا إلى عيسى."], ["وقفّينا بعيسى ابن مريم", "أتبعناهم بعيسى ابن مريم لتأخّره عنهم في الزمان."], ["وجعلنا في قلوب الذين اتبعوه", "على دينه، وهم الحواريون وأتباعهم."], ["رأفة ورحمة", "ليناً وشفقة."], ["ورهبانية ابتدعوها", "وابتدعوا رهبانية لم يكتبها الله عليهم، وهي اعتزال النساء والانقطاع في الأديرة والصوامع للتعبّد."], ["إلا ابتغاء رضوان الله", "إلا طلباً لرضوان الله عز وجل."], ["فما رعوها حق رعايتها", "لم يلتزموا بما نذروه على أنفسهم من الطاعات."], ["فآتينا الذين آمنوا منهم أجرهم", "فأعطينا الذين ثبتوا على إيمانهم وتقواهم أجرهم."], ["وكثير منهم فاسقون", "لا أجر لهم ولا ثواب إلا العقاب."]], "m": "يخبر تعالى أنه كما أرسل رسله وأنزل معهم الكتاب والميزان، أرسل كذلك نوحاً وإبراهيم؛ فنوح أبو البشر الثاني، وإبراهيم أبو الأنبياء من بعده، ذكرهما لمزيد شرفهما، وجعل في ذريتهما النبوة والكتاب: فهود وصالح وشعيب وإبراهيم ولوط من ذرية نوح، وإسماعيل وإسحاق وباقي الأنبياء من ذرية إبراهيم. فمن أولئك الذرية المهتدي، وأكثرهم فاسقون. ثم أرسلنا رسولاً بعد رسول إلى عيسى ابن مريم، وآتيناه الإنجيل، وجعلنا في قلوب الذين اتبعوه رأفة، وهي اللين وأشد الرحمة، ورحمة. ورهبانية ابتدعوها من التشديد ما كتبناها عليهم، ولكن ما ابتدعوها إلا طلباً لرضوان الله، فما رعوها حق رعايتها، حيث لم يوفوا بما التزموا به من ترك الدنيا والإقبال على الآخرة. ولهذه الرهبانية سبب مروي عن ابن عباس رضي الله عنهما، نذكره باختصار: كان بعد عيسى ملوك بدّلوا التوراة وحرّفوا الإنجيل وألزموا العامة بذلك، وكان بينهم جماعة رفضوا ذلك التحريف ففرّوا بدينهم والتحقوا بالجبال وانقطعوا عن الناس مخافة قتلهم أو تعذيبهم، فهذا الانقطاع بداية الرهبانية، وعاش أولئك المؤمنون وماتوا، وجاء جيل من أبناء الدين المحرّف فذكروا سيرة الصالحين الأولين فأرادوا أن يفعلوا فعلهم فانقطعوا إلى الصوامع والأديرة، ولكنهم جهال وعلى دين محرّف، فما انتفعوا بالرهبانية المبتدعة، وفسق أكثرهم. وهو ما دلّ عليه قوله: فآتينا الذين آمنوا منهم أجرهم، وهم الأولون الذين فرّوا من الكفر والتعذيب وعبدوا الله بما شرع، وكثير منهم فاسقون، وهم الذين أتوا من بعدهم، إذ يعبدون الله بدين محرّف باطل.", "h": ["بيان منّة الله على عباده بإرسال الرسل.", "بيان سنة الله في الناس، وهي أنه إذا أرسل الرسل لهداية الناس يهتدي بعض ويضل بعض.", "ثناء الله على عيسى ابن مريم وأتباعه بحق من الحواريين وغيرهم، إلى أن غيّرت الملوك دين المسيح وضلّ الناس وأصبحوا فاسقين عن دين الله تعالى.", "تحريم البدع والابتداع، ولا رهبانية في الإسلام، ولكن يُعبد الله بما شرع."], "k": "«فما رعوها حق رعايتها»… قد أبدأ عبادة بحماس ثم أتركها؛ فهل أرعى ما ألزمت به نفسي؟"}, {"lbl": "الآيتان ٢٨ – ٢٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ وَيَجۡعَل لَّكُمۡ نُورٗا تَمۡشُونَ بِهِۦ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٢٨﴾ لِّئَلَّا يَعۡلَمَ أَهۡلُ ٱلۡكِتَٰبِ أَلَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٢٩﴾", "w": [["يا أيها الذين آمنوا", "بعيسى ابن مريم، وموسى من قبله."], ["اتقوا الله وآمنوا برسوله", "خافوا عقاب الله، وآمنوا بمحمد ﷺ واتبعوه."], ["يؤتكم كفلين من رحمته", "يعطكم الله نصيبين من الأجر مقابل إيمانكم بنبيكم وإيمانكم بمحمد ﷺ."], ["ويجعل لكم نوراً تمشون به", "في الدنيا إذ تعيشون على هداية الله، وفي الآخرة تمشون به على الصراط."], ["لئلا يعلم أهل الكتاب", "لكي يعلم أهل الكتاب أنهم لا يقدرون على شيء من فضل الله، واللام في «لئلا» مزيدة لتقوية الكلام."]], "m": "هذا نداء الله لأهل الكتاب بعد أن ذكر نبذة عن رسلهم وأتباعهم، نادى الموجودين منهم بعنوان الإيمان، أي يا من آمنتم بالرسل السابقين حسب ادعائكم: اتقوا الله فلا تفرّقوا بين رسل الله، وآمنوا برسوله محمد ﷺ يعطكم حظين ونصيبين من رحمته ومثوبته، ويجعل لكم نوراً تمشون به في الدنيا، وهو الهداية الإسلامية، إذ الإسلام صراط مستقيم صاحبه لا يضل ولا يشقى، وتمشون به في الآخرة على الصراط إلى دار السلام، ويغفر لكم ذنوبكم، والله غفور رحيم. وذلك ليعلم أهل الكتاب من اليهود والنصارى الذين رفضوا الإيمان بمحمد ﷺ والدخول في الإسلام أنهم لا يقدرون على الحصول على شيء من فضل الله، وأن الفضل بيد الله يؤتيه من يشاء، والله ذو الفضل العظيم.", "h": ["أعظم نصيحة تُقدَّم لأهل الكتاب لو أخذوا بها تضمّنها نداء الله لهم وما وعدهم به في هذه الآية الكريمة.", "فضل الإيمان والتقوى، إذ هما سبيل الولاية والكرامة في الدنيا والآخرة.", "إبطال مزاعم أهل الكتاب في احتكار الجنة لهم، وإعلامهم بأنهم محرومون منها ما لم يؤمنوا برسول الله ﷺ ويتقوا الله بفعل أوامره واجتناب نواهيه."], "k": "«ويجعل لكم نوراً تمشون به»… التقوى نور في طريقي اليوم وعلى الصراط غداً؛ فهل يكفيني نوري الآن؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;